/* Lamplight: question banks built from Anna's own study notes (T1 and T2 2026). */
window.LAMPLIGHT_UNITS = window.LAMPLIGHT_UNITS || {};
window.LAMPLIGHT_UNITS["HPS121"] = {"code":"HPS121","name":"Introduction to Psychology","term":"T2 2026","weeks":11,"weekList":[{"week":1,"topic":"Human Development: Theories of Development","summary":"Major lifespan theories (Erikson, behaviourism, social learning, ethology, Bronfenbrenner, Life Course Theory) and the classic studies behind them.","skills":[{"id":"HPS121-1.1","name":"Match Erikson's psychosocial stages to their crises","summary":"Given an age or scenario, you can name the Erikson stage, its crisis and the likely outcome of success or failure.","questions":[{"type":"mc","prompt":"A 45-year-old feels their career, family and volunteering make a real contribution to others. Which Erikson crisis are they successfully resolving?","options":["Integrity vs Despair","Generativity vs Stagnation","Intimacy vs Isolation","Industry vs Inferiority"],"answer":1,"explanation":"Generativity vs Stagnation (40 to 60 years) is about contributing through career, family or community. Failing to feel useful leads to stagnation.","lvl":3},{"type":"case","passage":"Mia is 4. She loves inventing games with other children and asking to help cook dinner. Her father often scolds her for making a mess and stops her play before she can finish.","prompt":"Which crisis is Mia facing, and what outcome is her father's response likely to foster?","options":["Autonomy vs Shame; shame","Industry vs Inferiority; inferiority","Initiative vs Guilt; guilt","Trust vs Mistrust; mistrust"],"answer":2,"explanation":"Ages 3 to 6 are Initiative vs Guilt. Encouraging safe exploration and cooperative play builds initiative, while being held back or punished fosters guilt.","lvl":3},{"type":"order","prompt":"Put these Erikson crises in order from infancy to adolescence.","items":["Trust vs Mistrust","Autonomy vs Shame","Initiative vs Guilt","Industry vs Inferiority","Identity vs Identity Diffusion"],"explanation":"Erikson's first five stages run from birth to 2, 2 to 3, 3 to 6, 6 to 10 and 10 to 20 years."},{"type":"match","prompt":"Match each age band to its Erikson crisis.","pairs":[["Birth to 2 years","Trust vs Mistrust"],["10 to 20 years","Identity vs Identity Diffusion"],["20 to 40 years","Intimacy vs Isolation"],["60+ years","Integrity vs Despair"]],"explanation":"Each of Erikson's eight stages combines internal and external influences and centres on one crisis."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In Erikson's theory, success at each stage depends on the individual's characteristics and how punitive their social environment is.","wrong":"punitive","correct":"supportive","explanation":"Erikson held that success depends on the person's characteristics and how supportive their social environment is."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In Erikson's fifth stage, over-control by others can lead to role confusion, also called identity ___.","answers":["diffusion"],"explanation":"Stage 5 is Identity vs Identity Diffusion. Over-control during adolescence leads to role confusion or diffusion.","lvl":3}]},{"id":"HPS121-1.2","name":"Identify stimuli, responses and consequences in conditioning","summary":"You can label UCS, UCR, CS and CR in a classical example and classify operant consequences as reinforcement or punishment.","questions":[{"type":"case","passage":"In Watson and Rayner's (1920) study, a white rat was paired with a loud noise made by striking a steel bar behind Albert. After about six pairings, Albert showed fear when he saw the rat alone.","prompt":"After conditioning, what was the white rat?","options":["Unconditioned stimulus","Unconditioned response","Conditioned stimulus","Conditioned response"],"answer":2,"explanation":"The rat began as a neutral stimulus and, after pairing with the loud noise (UCS), became a conditioned stimulus that produced fear (CR).","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Positive reinforcement","Negative reinforcement","Punishment"],"items":[{"text":"Getting a present for waking early","cat":0},{"text":"Getting up to turn off the alarm","cat":1},{"text":"Receiving a speeding fine","cat":2},{"text":"Losing a driver's licence","cat":2},{"text":"A rat presses a lever to receive a food pellet","cat":0},{"text":"A rat presses a lever to stop a mild shock","cat":1}],"explanation":"Reinforcement increases behaviour by adding something pleasant (positive) or removing something unpleasant (negative). Fines and licence loss are punishments that decrease behaviour."},{"type":"mc","prompt":"Which description best defines negative reinforcement?","options":["Removing a pleasant stimulus to decrease a behaviour","Adding an unpleasant stimulus to decrease a behaviour","Removing an unpleasant stimulus to increase a behaviour","Adding a pleasant stimulus to increase a behaviour"],"answer":2,"explanation":"Negative reinforcement removes something unpleasant, which makes the behaviour more likely. Removing a pleasant stimulus is negative punishment.","lvl":2},{"type":"analogy","prompt":"Food is to salivation as a loud noise is to ___","options":["the white rat","fear","extinction","a rabbit"],"answer":1,"explanation":"Food (UCS) naturally produces salivation (UCR); the loud noise (UCS) naturally produced fear (UCR) in Little Albert.","lvl":2},{"type":"type_answer","prompt":"Albert's conditioned fear spread to a rabbit, a dog, a furry object and a white mask. What is this process called?","answers":["generalisation","stimulus generalisation","generalization","stimulus generalization"],"explanation":"Generalisation occurs when a conditioned response spreads to stimuli similar to the original conditioned stimulus.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Extinction occurs when the conditioned stimulus is repeatedly presented with the unconditioned stimulus, so the conditioned response weakens.","wrong":"with","correct":"without","explanation":"Extinction is the weakening of a conditioned response when the CS is repeatedly presented without the UCS."}]},{"id":"HPS121-1.3","name":"Evaluate Bandura's and Watson's classic learning studies","summary":"You can explain what the Bobo doll and Little Albert studies showed, their key critiques and how behaviourism's core concepts apply.","questions":[{"type":"mc","prompt":"In the Bobo doll study (Bandura, Ross & Ross, 1961), which finding best shows that children did more than copy exact actions?","options":["Children who saw the aggressive model produced novel aggressive acts the adult had not modelled","A control group saw no model at all","Children were observed through one-way glass","Seventy-two children aged 3 to 6 took part"],"answer":0,"explanation":"Children exposed to the aggressive model showed more physical and verbal aggression, including new acts not shown by the adult.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Critique of the Bobo doll study","Critique of the Little Albert study"],"items":[{"text":"A doll is not a person, so results may not transfer to aggression toward humans","cat":0},{"text":"He was never de-conditioned","cat":1},{"text":"Participants' history of violence was unknown","cat":0},{"text":"The researcher's masked appearance may itself have been frightening","cat":1},{"text":"Instructions may have been read as what they were supposed to do","cat":0},{"text":"The single infant's health may limit generalisability","cat":1}],"explanation":"Bobo critiques centre on imitation versus real aggression and demand effects; Little Albert critiques centre on ethics, the lack of de-conditioning and a single child's characteristics."},{"type":"case","passage":"A parent notices her children re-enact fights from a cartoon, even though they have never been rewarded for fighting. She wonders why they learn it at all.","prompt":"Which theory best explains this learning?","options":["Social learning theory (Bandura)","Classical conditioning (Pavlov)","Ethological theory (Lorenz)","Psychosocial theory (Erikson)"],"answer":0,"explanation":"Social learning theory holds that learning occurs through observation, imitation and modelling, not only through direct reinforcement or punishment.","lvl":1},{"type":"match","prompt":"Match each core concept of behaviourism to its meaning.","pairs":[["Blank slate","Born with no pre-existing mental content but a capacity to learn"],["Behavioural focus","Studies observable behaviour, not unobservable internal processes"],["Environmental determinism","All behaviour is learned through interaction with the environment"],["Conditioning","Behaviour is shaped by associations or consequences"]],"explanation":"These four concepts define behaviourism as an approach focused on observable, learned behaviour."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Before being observed with the Bobo doll, children were mildly ___ by being stopped from playing with attractive toys.","answers":["frustrated"],"explanation":"Children were mildly frustrated and then observed for 20 minutes through one-way glass with the Bobo doll present.","lvl":4},{"type":"mc","prompt":"What is the main overall limitation of behaviourism noted in the unit?","options":["It cannot explain how fears and phobias develop","It relies too heavily on unconscious drives","It ignores the role of the environment","It rejects the role of complex cognitive processes"],"answer":3,"explanation":"Behaviourism is useful for explaining learning but is criticised for rejecting complex cognitive processes.","lvl":2}]},{"id":"HPS121-1.4","name":"Distinguish imprinting, critical periods and sensitive periods","summary":"You can explain imprinting, ethograms and the difference between critical and sensitive periods with examples.","questions":[{"type":"case","passage":"Goslings hatched in an incubator saw Lorenz before any other moving object. From then on they followed him everywhere and would not switch to following their mother.","prompt":"Which concept does this demonstrate?","options":["Operant conditioning","A sensitive period for language","Secure attachment","Imprinting"],"answer":3,"explanation":"Imprinting is a rapid, enduring, largely irreversible attachment to the first moving object seen after hatching, requiring no reinforcement.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Critical period","Sensitive period"],"items":[{"text":"Untreated congenital cataracts cause permanent visual deficits","cat":0},{"text":"Language acquisition in early childhood","cat":1},{"text":"Attachment formation in early childhood","cat":1},{"text":"The absence of an experience has irreversible effects","cat":0},{"text":"Learning can still occur later, just less efficiently","cat":1}],"explanation":"Critical periods are narrow windows with irreversible effects (rare in humans). Sensitive periods (Bornstein, 1989) are more flexible."},{"type":"mc","prompt":"Which of the following is NOT a feature of imprinting as described by Lorenz (1937)?","options":["It happens rapidly","It requires reinforcement","It is largely irreversible","It is adaptive for survival"],"answer":1,"explanation":"Imprinting needs no reinforcement. It is rapid, enduring and adaptive because following the caregiver aids survival.","lvl":2},{"type":"type_answer","prompt":"What is the name for a systematic, objective catalogue of a species' observable behaviours?","answers":["ethogram","an ethogram"],"explanation":"An ethogram catalogues observable behaviours, an approach paralleled in observational child research such as Ainsworth's coding.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Ramey and Ramey (1998) argued that critical periods may be too flexible, proposing relative timing effects instead.","wrong":"flexible","correct":"rigid","explanation":"The criticism is that critical or sensitive periods may be too rigid; relative timing effects allow more flexibility."},{"type":"analogy","prompt":"An ethogram is to ethology as coding proximity seeking in the Strange Situation is to ___","options":["behaviourism","attachment research","psychosocial theory","Life Course Theory"],"answer":1,"explanation":"Ainsworth's Strange Situation codes behaviours such as proximity seeking and distress signalling, much like an ethogram.","lvl":4}]},{"id":"HPS121-1.5","name":"Apply Bronfenbrenner's systems and Life Course Theory","summary":"You can place an influence in the correct ecological system, name Life Course Theory concepts and contrast it with the Bioecological Model.","questions":[{"type":"match","prompt":"Match each ecological system to an example.","pairs":[["Microsystem","A child's family and school"],["Mesosystem","Parents' relationship with the child's teachers"],["Exosystem","A parent's workplace"],["Chronosystem","Growing up during COVID-19"]],"explanation":"Systems range from direct interaction (micro) and links between settings (meso) to indirect settings (exo), culture (macro) and time (chrono)."},{"type":"case","passage":"Jai's mother has been moved onto long night shifts by her employer. She is exhausted and less available at home. Jai has never visited her workplace.","prompt":"In which of Bronfenbrenner's systems does the employer's decision sit for Jai?","options":["Microsystem","Mesosystem","Exosystem","Macrosystem"],"answer":2,"explanation":"The exosystem contains settings that affect the person indirectly, such as a parent's workplace.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Life Course Theory","Bioecological Model"],"items":[{"text":"Looks outward to historical events and their timing","cat":0},{"text":"Places the individual at the centre of layered environments","cat":1},{"text":"Emphasises linked lives across relationships","cat":0},{"text":"Explains development through nested systems around the person","cat":1},{"text":"Stresses human agency in changing one's trajectory","cat":0}],"explanation":"Both stress context and time, but Life Course Theory looks outward to history, timing and connections, while the Bioecological Model centres the individual."},{"type":"case","passage":"Two sisters lost their jobs in the same recession. The 22-year-old retrained and built a new career; the 55-year-old struggled to re-enter the workforce.","prompt":"Which Life Course Theory concept best explains the different outcomes?","options":["Timing of lives","Linked lives","Human agency","Historical time and place"],"answer":0,"explanation":"Timing of lives holds that the impact of an event depends on when it occurs, so the same event can be disruptive or adaptive.","lvl":3},{"type":"mc","prompt":"What did Lehman, David and Gruber (2017) propose?","options":["Replacing biological factors in the Biopsychosocial Model with social ones","A Dynamic Biopsychosocial Model in which biological, psychological, interpersonal and contextual systems constantly reshape each other","That each influence on health has a fixed importance across the lifespan","That social factors matter only in childhood"],"answer":1,"explanation":"They integrated Bronfenbrenner's systems into the Biopsychosocial Model, using a mobile metaphor where the salience of each influence rises and falls.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The Life Course Theory concept of ___ lives holds that one person's experiences can alter the trajectories of others.","answers":["linked"],"explanation":"Linked lives means lives are interdependent, with stress, support and resources flowing across relationships.","lvl":3}]}]},{"week":2,"topic":"Human Development: Cognitive, Moral and Social Development","summary":"Piaget, Vygotsky and information-processing theories, three theories of moral development, and Bowlby's and Ainsworth's work on attachment.","skills":[{"id":"HPS121-2.1","name":"Classify children's thinking using Piaget's four stages","summary":"You can place a child's reasoning in the correct Piagetian stage and explain assimilation, accommodation and equilibration.","questions":[{"type":"order","prompt":"Put Piaget's stages in order from birth to adolescence.","items":["Sensorimotor","Preoperational","Concrete operational","Formal operational"],"explanation":"Sensorimotor (0 to 2), preoperational (2 to 7), concrete operational (7 to 11), formal operational (12+)."},{"type":"case","passage":"A 5-year-old watches juice poured from a short, wide glass into a tall, thin glass. She insists the tall glass now has more juice.","prompt":"Which stage is she most likely in?","options":["Sensorimotor","Preoperational","Concrete operational","Formal operational"],"answer":1,"explanation":"Preoperational children think symbolically but lack conservation, so they judge amount by appearance.","lvl":2},{"type":"match","prompt":"Match each Piagetian term to its meaning.","pairs":[["Assimilation","Fitting new information into existing schemes"],["Accommodation","Adjusting schemes to take in new information"],["Equilibration","The balancing process that drives learning"],["Object permanence","Knowing objects exist when out of sight"]],"explanation":"Children reorganise schemes through assimilation and accommodation, driven by equilibration."},{"type":"case","passage":"A 14-year-old wants to know what makes a pendulum swing faster. She changes only the string length while holding weight and height constant, then repeats with each factor.","prompt":"Which stage does this reasoning reflect?","options":["Sensorimotor","Preoperational","Concrete operational","Formal operational"],"answer":3,"explanation":"Formal operational thinking is abstract, hypothetical and systematic, such as designing an experiment that isolates variables.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A toddler who searches for a toy hidden under a blanket has developed object conservation.","wrong":"conservation","correct":"permanence","explanation":"Searching for a hidden toy shows object permanence, a sensorimotor achievement. Conservation develops in the concrete operational stage."},{"type":"type_answer","prompt":"In Piaget's theory, what term describes a child changing an existing scheme because new information does not fit it?","answers":["accommodation"],"explanation":"Accommodation adjusts cognitive structures to fit new information, whereas assimilation fits information into existing ones.","lvl":3}]},{"id":"HPS121-2.2","name":"Contrast Piaget, Vygotsky and information-processing theories","summary":"You can say which theory a claim belongs to and explain how the three differ on stages, social input and mechanisms.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Piaget","Vygotsky","Information-processing"],"items":[{"text":"Development occurs in discrete stages","cat":0},{"text":"Zone of Proximal Development","cat":1},{"text":"Scaffolding by more knowledgeable others","cat":1},{"text":"Gradual gains in processing speed and executive function","cat":2},{"text":"Maturational readiness limits which concepts can be grasped","cat":0},{"text":"The mind compared to a computer","cat":2}],"explanation":"Piaget: individual construction through stages. Vygotsky: continuous growth through social interaction. Information-processing: gradual mechanistic improvement."},{"type":"case","passage":"A tutor breaks a new maths task into small steps and gives hints. As the student improves, the tutor gradually withdraws the hints until the student works alone.","prompt":"Which concept is the tutor using?","options":["Assimilation","Equilibration","Scaffolding","Automatisation"],"answer":2,"explanation":"Scaffolding is Vygotsky's idea of adults structuring tasks to build new skills within the Zone of Proximal Development.","lvl":1},{"type":"mc","prompt":"Which statement correctly contrasts Vygotsky with Piaget?","options":["Vygotsky saw growth as continuous and socially driven, rather than staged","Vygotsky proposed four stages, Piaget proposed none","Vygotsky focused on processing speed and memory","Vygotsky argued children cannot learn beyond their stage"],"answer":0,"explanation":"Vygotsky saw cognitive development as continuous and driven by social interaction, unlike Piaget's discrete, individually constructed stages.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Vygotsky's Zone of ___ Development is the gap between what a child can do alone and what they can do with guided support.","answers":["Proximal"],"explanation":"The ZPD is where learning happens with support from more knowledgeable others.","lvl":2},{"type":"analogy","prompt":"Piaget is to discrete stages as information-processing theory is to ___","options":["scaffolding","gradual mechanistic improvement","immanent justice","the Zone of Proximal Development"],"answer":1,"explanation":"Information-processing theory rejects broad stages in favour of gradual improvement in attention, memory, speed and strategies.","lvl":4},{"type":"type_answer","prompt":"Which researcher (1996) is cited for the information-processing view of cognitive development?","answers":["Siegler","Robert Siegler","R. S. Siegler"],"explanation":"Siegler (1996) focused on the mechanisms of thinking rather than broad stages.","lvl":5}]},{"id":"HPS121-2.3","name":"Compare Piaget's, Kohlberg's and Eisenberg's moral theories","summary":"You can classify moral reasoning into the correct theory, level or stage and explain what each theory adds.","questions":[{"type":"case","passage":"A 6-year-old hears two stories. John broke 15 cups by accident while coming to dinner. Henry broke 1 cup while sneaking jam. She says John is naughtier because he broke more cups.","prompt":"Which kind of moral reasoning is she showing?","options":["Heteronomous morality (moral realism)","Autonomous morality","Kohlberg's social contract stage","Eisenberg's empathic stage"],"answer":0,"explanation":"In heteronomous morality (about 5 to 8 years), actions are judged by consequences rather than intentions.","lvl":3},{"type":"order","prompt":"Put Eisenberg's levels of prosocial reasoning in order from earliest to most mature.","items":["Hedonistic","Needs-based","Approval-oriented","Empathic and internalised"],"explanation":"Eisenberg (1986) described a progression from self-interest to empathy and internalised values by adolescence."},{"type":"match","prompt":"Match each Kohlberg stage to its typical reasoning.","pairs":[["Obedience and punishment","Do the right thing to avoid being punished"],["Self-interest","What's in it for me?"],["Law and order","Obey laws and fulfil duties to maintain social order"],["Universal ethical principles","Follow self-chosen principles even against the law"]],"explanation":"Stages 1 and 2 are pre-conventional, 3 and 4 conventional, and 5 and 6 post-conventional."},{"type":"case","passage":"Asked about the Heinz dilemma, Tara says: \"He should steal the drug, because a human life matters more than property laws, even if he is punished for it.\"","prompt":"At which of Kohlberg's levels is Tara reasoning?","options":["Pre-conventional","Conventional","Post-conventional","Premoral"],"answer":2,"explanation":"Post-conventional reasoning separates personal principles from social norms and may conflict with the law.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Kohlberg's original sample included only females, which later fuelled contested claims about sex differences in moral reasoning.","wrong":"females","correct":"males","explanation":"Kohlberg's original sample was male-only, and later claims that women stopped at stage 3 are contested."},{"type":"mc","prompt":"What is Eisenberg's key contribution relative to Piaget and Kohlberg?","options":["She showed moral reasoning develops in fixed, identical stages across situations","She focused on obedience to authority","She studied reasoning about stealing and justice","She highlighted emotion, empathy and relationships in reasoning about helping"],"answer":3,"explanation":"Eisenberg used prosocial dilemmas and highlighted empathy and relationships, which were underrepresented in the earlier justice-based theories.","lvl":2}]},{"id":"HPS121-2.4","name":"Identify Bowlby's attachment stages and Ainsworth's attachment types","summary":"You can sequence Bowlby's stages, classify Strange Situation behaviour and link each type to its caregiving history.","questions":[{"type":"case","passage":"In the Strange Situation, 14-month-old Leo barely reacts when his mother leaves. When she returns, he turns away and keeps playing with the toys.","prompt":"Which attachment type does this suggest?","options":["Secure","Insecure-avoidant","Insecure-resistant (ambivalent)","Disorganised"],"answer":1,"explanation":"Avoidant infants are unfazed by separation and avoid or ignore the caregiver on reunion, minimising attachment behaviour.","lvl":2},{"type":"order","prompt":"Put Bowlby's stages of attachment development in order.","items":["Orientation to social stimuli","Emerging selectivity","Active proximity maintenance","Goal-corrected partnership"],"explanation":"Birth to about 3 months, about 5 to 7 months, about 7 to 9 months, then about 2 to 3 years."},{"type":"match","prompt":"Match each attachment type to its typical caregiving history.","pairs":[["Secure","Consistent, sensitive, responsive care"],["Insecure-avoidant","Rejection and emotional unavailability"],["Insecure-resistant","Inconsistent, unpredictable care"],["Disorganised","Frightening or frightened caregiving"]],"explanation":"Caregiving patterns shape the internal working models that underlie each attachment type."},{"type":"mc","prompt":"What did Harlow's surrogate-mother studies suggest about attachment?","options":["Infants bond mainly with whoever feeds them","Attachment is formed only through reinforcement","Attachment rests on the need for emotional security and comfort, not just feeding","Isolation has no lasting effect on monkeys"],"answer":2,"explanation":"Monkeys preferred the cloth mother and ran to her when frightened, going to the wire mother only to feed.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Across development, children build internal ___ models of self, caregiver and relationships.","answers":["working"],"explanation":"Internal working models formed from early experience shape later relationships, emotion regulation and mental health.","lvl":3},{"type":"case","passage":"On reunion in the Strange Situation, an infant starts to crawl toward her father, then freezes mid-approach and appears fearful of him.","prompt":"Which attachment type best fits this behaviour?","options":["Secure","Insecure-avoidant","Insecure-resistant","Disorganised"],"answer":3,"explanation":"Disorganised attachment (Main & Solomon, 1986) involves confused or contradictory behaviour such as approaching then freezing.","lvl":3}]}]},{"week":3,"topic":"Personality: The Psychodynamic Perspective","summary":"Freud's assumptions and models of mind, psychosexual stages, ego defence mechanisms, and modern evidence-informed psychodynamic ideas.","skills":[{"id":"HPS121-3.1","name":"Explain Freud's three core assumptions and their modern echoes","summary":"You can name each assumption, recognise it in an example and pair it with a modern research finding.","questions":[{"type":"match","prompt":"Match each Freudian assumption to its claim.","pairs":[["Primacy of the unconscious","Much of mental life occurs outside awareness and drives behaviour"],["Psychic determinism","Slips of the tongue and dreams are meaningful, not random"],["Importance of early experience","Early caregiver experiences shape personality long afterward"]],"explanation":"Remember them as unconscious, meaning and early experience."},{"type":"case","passage":"During dinner Sam accidentally calls his new partner by his ex-partner's name. His friend, a psychology student, says it was \"no accident\".","prompt":"Which Freudian assumption is the friend drawing on?","options":["Psychic determinism","The reality principle","Importance of early experience","Aggregation"],"answer":0,"explanation":"Psychic determinism holds that apparent accidents such as slips are meaningful expressions of underlying forces.","lvl":3},{"type":"mc","prompt":"Which modern finding best echoes Freud's assumption about the importance of early experience?","options":["People often lack insight into what guides their judgements","Behaviour has psychological or biological causes","The early-childhood environment can shape the life strategy a person adopts (harshness-unpredictability model)","Traits predict aggregated behaviour well"],"answer":2,"explanation":"Ellis et al. (2009) showed the environment in the first 5 years can shape life strategy, and adverse childhood experiences relate to later psychopathology.","lvl":4},{"type":"type_answer","prompt":"What is the technical term for a Freudian slip, a verbal error thought to reveal an unconscious wish?","answers":["parapraxis"],"explanation":"A parapraxis feels accidental precisely because its meaning is hidden in the unconscious.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Modern research suggests the unconscious is more extensive than Freud proposed, though it still influences motivation, emotion and memory.","wrong":"extensive","correct":"limited","explanation":"Research supports nonconscious influence, but the modern unconscious is seen as more limited than Freud's."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Freud's assumption of psychic ___ holds that thoughts, feelings and behaviours are not random.","answers":["determinism"],"explanation":"Psychic determinism means mental events have psychological meaning.","lvl":3}]},{"id":"HPS121-3.2","name":"Distinguish the topographic and structural models of mind","summary":"You can place mental content in the conscious, preconscious or unconscious, and explain how the id, ego and superego interact.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Conscious","Preconscious","Unconscious"],"items":[{"text":"Feeling hungry right now","cat":0},{"text":"Recalling a friend's birthday when prompted","cat":1},{"text":"A forbidden wish surfacing in a dream","cat":2},{"text":"Concentrating on the words you are reading","cat":0},{"text":"Remembering a familiar route home","cat":1},{"text":"An unresolved childhood fear behind an irrational reaction","cat":2}],"explanation":"Conscious content is in awareness now, preconscious content is easily retrieved, and unconscious content is kept out of awareness and surfaces only indirectly."},{"type":"match","prompt":"Match each structure of the mind to its operating principle.","pairs":[["Id","Pleasure principle"],["Ego","Reality principle"],["Superego","Strives for perfection and moral ideals"]],"explanation":"The ego mediates between the id's desires, the superego's constraints and external reality."},{"type":"case","passage":"Lena badly wants to skip her shift for a beach day. She then feels guilty imagining her team struggling without her. In the end she works the shift and goes to the beach afterwards.","prompt":"Which structure produced Lena's final, realistic compromise?","options":["Ego","Id","Superego","Preconscious"],"answer":0,"explanation":"The ego satisfies drives realistically and safely, negotiating between wanting (id), forbidding (superego) and reality.","lvl":2},{"type":"mc","prompt":"According to Freud, when and how does the superego develop?","options":["At birth, as a reservoir of instinctual drives","In early infancy, to manage reality","In the latency stage, through schooling","In the phallic (oedipal) stage, through identification with caregivers"],"answer":3,"explanation":"The superego develops in the phallic or oedipal stage and represents internalised moral values that can produce guilt and shame.","lvl":3},{"type":"analogy","prompt":"The topographic model is to where mental content sits as the structural model is to ___","options":["which stage causes fixation","how parts of the mind operate and come into conflict","how traits are measured","when crises occur"],"answer":1,"explanation":"The topographic model maps levels of awareness; the structural model explains how id, ego and superego operate and conflict.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Freud described the id, ego and superego as physical systems that operate at different levels of awareness.","wrong":"physical","correct":"functional","explanation":"They are functional systems, not physical brain regions."}]},{"id":"HPS121-3.3","name":"Sequence Freud's psychosexual stages and fixation traits","summary":"You can order the psychosexual stages, give their age bands and link fixation to adult traits.","questions":[{"type":"order","prompt":"Put Freud's psychosexual stages in order.","items":["Oral","Anal","Oedipal (phallic)","Latency","Genital"],"explanation":"Oral (0 to 18 months), anal (18 to 36 months), oedipal (5 to 6 years), latency (6 years to puberty), genital (puberty onward)."},{"type":"match","prompt":"Match each stage to its associated adult personality trait.","pairs":[["Oral","Dependency"],["Anal","Obsessiveness"],["Oedipal (phallic)","Competitiveness"],["Latency","No associated trait"]],"explanation":"A memory hook for the first three: dependency, obsessiveness, competitiveness."},{"type":"case","passage":"A psychodynamic therapist describes a client as rigid, preoccupied with order and driven to control people around him.","prompt":"Fixation at which stage would classical theory propose?","options":["Oral","Anal","Oedipal","Genital"],"answer":1,"explanation":"The anal stage task is controlling one's body, impulses and others; fixation is linked to obsessiveness.","lvl":2},{"type":"mc","prompt":"Why do the latency and genital stages have no associated character trait?","options":["In classical theory, fixation in these later periods plays no role in shaping personality","Freud never studied children older than 6","These stages were added by Erikson","Everyone passes through them without conflict"],"answer":0,"explanation":"The character-forming action happens in the first three stages, which is why psychodynamic theory emphasises early childhood.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When too little or too much gratification occurs at a stage, psychic energy stays invested there, a process called ___.","answers":["fixation"],"explanation":"Fixation links an early stage's concerns to an adult character trait.","lvl":2},{"type":"type_answer","prompt":"Name the psychosexual stage (18 to 36 months) whose task is learning to control one's body, impulses and others.","answers":["anal","anal stage","the anal stage"],"explanation":"The anal stage task is control; fixation is associated with obsessiveness.","lvl":3}]},{"id":"HPS121-3.4","name":"Identify ego defence mechanisms in scenarios","summary":"Given a scenario, you can name the defence mechanism and avoid the classic confusions (repression vs denial, displacement vs projection).","questions":[{"type":"case","passage":"After being criticised by his supervisor, Tom says nothing at work but snaps at his children as soon as he gets home.","prompt":"Which defence mechanism is Tom using?","options":["Displacement","Projection","Sublimation","Regression"],"answer":0,"explanation":"Displacement redirects the same feeling from a threatening target (the supervisor) to a safer substitute (family).","lvl":2},{"type":"case","passage":"Kim feels strong hostility toward a colleague but tells everyone that the colleague is the aggressive one.","prompt":"Which defence mechanism is Kim using?","options":["Displacement","Reaction formation","Projection","Denial"],"answer":2,"explanation":"Projection attributes one's own unacceptable feelings to another person.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Repression","Denial"],"items":[{"text":"Has no memory of a childhood trauma but feels anxious in related situations","cat":0},{"text":"Insists a serious diagnosis is wrong despite clear evidence","cat":1},{"text":"Refuses to accept that their business has failed despite closure notices","cat":1},{"text":"Keeps a forbidden impulse entirely out of awareness","cat":0}],"explanation":"Repression buries an internal memory or impulse; denial rejects an external fact."},{"type":"match","prompt":"Match each defence mechanism to its example.","pairs":[["Reaction formation","Being overly kind to a resented sibling"],["Regression","Thumb-sucking again after a new sibling arrives"],["Sublimation","Channelling aggressive impulses into competitive sport"],["Intellectualisation","Discussing a diagnosis only in technical terms"]],"explanation":"Sublimation is the most mature defence because it redirects impulses into socially acceptable activity."},{"type":"mc","prompt":"Which statement about defence mechanisms is accurate?","options":["They resolve the underlying conflict","Only people with psychological disorders use them","Sublimation is the least mature defence","They manage the feeling, not its cause"],"answer":3,"explanation":"Defences are normal and universal, but they manage the feeling rather than resolve the conflict. Heavy reliance on immature defences relates to poorer adjustment.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A student who blames a poor exam result on an unfair test rather than poor preparation is using sublimation.","wrong":"sublimation","correct":"rationalisation","explanation":"Rationalisation gives a seemingly logical explanation to justify unacceptable behaviour or feelings."}]},{"id":"HPS121-3.5","name":"Evaluate modern psychodynamic concepts and projective tests","summary":"You can identify which psychodynamic ideas have empirical support, explain projective testing and weigh strengths against criticisms.","questions":[{"type":"mc","prompt":"Which psychodynamic concept gains empirical support from research on the therapeutic alliance (Horvath et al., 2011)?","options":["The psychosexual stages","Transference and countertransference","The Oedipal conflict","Classical drive theory"],"answer":1,"explanation":"Alliance quality consistently predicts outcomes, supporting concepts such as transference and countertransference.","lvl":4},{"type":"type_answer","prompt":"What is the capacity to understand one's own and others' behaviour in terms of underlying mental states (also called reflective functioning)?","answers":["mentalisation","mentalization"],"explanation":"Contemporary psychodynamic approaches aim to strengthen mentalisation, especially with families and people exposed to trauma.","lvl":4},{"type":"case","passage":"A clinician shows a client a series of inkblots. She is less interested in what the client sees than in how the client approaches the perceptual task.","prompt":"What type of test is this, and which theory underpins it?","options":["An implicit test grounded in behaviourism","A projective test grounded in psychoanalytic theory","An objective test grounded in trait theory","A behavioural assessment grounded in social learning"],"answer":1,"explanation":"The Rorschach (1921) is a projective test: people are assumed to project unconscious material onto an ambiguous stimulus.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Strength of the psychodynamic perspective","Criticism of the psychodynamic perspective"],"items":[{"text":"Built largely from case studies of a narrow clinical sample","cat":1},{"text":"Foregrounded the therapeutic relationship","cat":0},{"text":"Concepts were framed in ways that are hard to falsify","cat":1},{"text":"Defence mechanisms can now be reliably measured","cat":0},{"text":"Reflects the cultural and gender assumptions of Freud's era","cat":1},{"text":"Highlighted the lasting importance of early relationships","cat":0}],"explanation":"A balanced evaluation credits unconscious influence, early relationships, defences and the alliance, while noting testability and sampling problems."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Neuropsychoanalysis uses a dual-aspect ___ framework that treats mind and brain as two descriptions of the same processes.","answers":["monist"],"explanation":"The dual-aspect monist framework lets concepts such as defence and affect regulation be examined alongside neuroscience (Solms & Turnbull, 2011).","lvl":5},{"type":"analogy","prompt":"A projective test is to unconscious motivations as an implicit test is to ___","options":["automatic attitudes and biases","consciously reported traits","defence mechanisms","psychosexual stages"],"answer":0,"explanation":"Implicit tests also target unconscious material but focus on automatic attitudes, often via reaction times.","lvl":3}]}]},{"week":4,"topic":"Personality: Traits and Assessment","summary":"What traits are, the Big Five and facets, Mischel's person-situation critique, personality assessment methods, and writing the Method section.","skills":[{"id":"HPS121-4.1","name":"Explain the defining features of a personality trait","summary":"You can define a trait as consistent, stable and individually varying, and trace how the Big Five were derived.","questions":[{"type":"match","prompt":"Match each defining feature of a trait to its meaning.","pairs":[["Consistency","Similar patterns across different situations"],["Stability","Relative standing is similar across time"],["Individual differences","People vary meaningfully on the tendency"]],"explanation":"Traits summarise consistent patterns, show continuity over time and capture differences between people."},{"type":"mc","prompt":"Why is needing oxygen NOT considered a personality trait?","options":["It is not stable across time","It cannot be measured by self-report","People do not meaningfully differ on it, so there is no individual-differences variance","It is only consistent within one situation"],"answer":2,"explanation":"Without variance between individuals a trait has no explanatory use; needing oxygen is shared human nature.","lvl":3},{"type":"order","prompt":"Put the steps that produced the Big Five in order.","items":["Lexical hypothesis","Allport and Odbert's dictionary search","Factor analysis of trait words","The Five-Factor Model"],"explanation":"Important differences are encoded in language, collected from the dictionary, then reduced by factor analysis into five broad factors."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"At a population level, most traits form a bimodal distribution, which is why thinking in types is misleading.","wrong":"bimodal","correct":"normal","explanation":"Most traits form a normal (bell-shaped) distribution with most people near the middle."},{"type":"type_answer","prompt":"Which statistical process groups highly correlated descriptors into a smaller set of broad factors?","answers":["factor analysis"],"explanation":"Factor analysis reduces many overlapping descriptors to a few underlying concepts.","lvl":3},{"type":"case","passage":"A friend says: \"I'm an introvert, so I'm a completely different kind of person from extraverts, and I'll never enjoy parties.\"","prompt":"Which response best reflects the trait approach taught in the unit?","options":["Correct: introversion is a fixed type","Correct: traits are absolute, not probabilistic","Incorrect only because introversion is not a Big Five trait","Incorrect: traits are dimensions, most people sit between extremes, and traits are probabilistic tendencies"],"answer":3,"explanation":"Traits vary by degree and describe tendencies, not destiny; labels like introvert are convenient shortcuts.","lvl":2}]},{"id":"HPS121-4.2","name":"Match Big Five factors and facets to behaviour","summary":"You can identify high and low poles of each OCEAN factor and name facets that explain different expressions of the same factor.","questions":[{"type":"case","passage":"A colleague keeps a detailed task list, never misses a deadline, keeps regular routines and thinks carefully before acting.","prompt":"Which Big Five factor is she high on?","options":["Conscientiousness","Openness to Experience","Agreeableness","Extraversion"],"answer":0,"explanation":"Conscientiousness is self-regulation in the service of goals and strongly predicts follow-through.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["High neuroticism","Low extraversion (introversion)","High openness"],"items":[{"text":"Ruminates and needs longer to settle after stress","cat":0},{"text":"Prefers small gatherings and needs solitude to recharge","cat":1},{"text":"Tries new foods, reads widely and is comfortable with ambiguity","cat":2},{"text":"Anticipates problems and feels easily overwhelmed","cat":0},{"text":"Speaks in groups only when they have something specific to add","cat":1},{"text":"Enjoys playing with abstract ideas","cat":2}],"explanation":"Learn both poles of each factor, for example low extraversion is introversion."},{"type":"match","prompt":"Match each NEO PI-3 facet to its Big Five factor.","pairs":[["Gregariousness","Extraversion"],["Order","Conscientiousness"],["Altruism","Agreeableness"],["Vulnerability","Neuroticism"]],"explanation":"Facets divide each broad domain into narrower, more specific components."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The low end of neuroticism is called emotional introversion and shows as recovering quickly after conflict.","wrong":"introversion","correct":"stability","explanation":"Low neuroticism is emotional stability. Introversion is the low end of extraversion."},{"type":"case","passage":"Two people have identical Extraversion scores. One dominates meetings but is not especially warm; the other is very warm and friendly but rarely takes charge.","prompt":"What best explains the difference?","options":["They have different Conscientiousness scores","One score must be invalid","They differ at the facet level (assertiveness versus warmth)","Extraversion is not a normal-range trait"],"answer":2,"explanation":"Facets explain why the same broad score can look very different in behaviour.","lvl":3},{"type":"analogy","prompt":"Low extraversion is to introversion as low neuroticism is to ___","options":["agreeableness","conscientiousness","emotional stability","closedness"],"answer":2,"explanation":"Each factor has two named poles; high neuroticism is also a normal-range trait, not a mental health condition.","lvl":2}]},{"id":"HPS121-4.3","name":"Explain Mischel's person-situation critique and CAPS","summary":"You can explain Mischel's critique, behavioural signatures, aggregation and the CAPS units without framing it as traits versus situations.","questions":[{"type":"mc","prompt":"What was the central point of Mischel's (1968) critique?","options":["People have no general dispositions","Single traits often fail to predict specific behaviours when the situation changes","Situations always outweigh traits","Traits cannot be measured reliably"],"answer":1,"explanation":"Mischel showed trait-behaviour correlations in specific situations were modest, but he did not reject dispositions.","lvl":3},{"type":"case","passage":"Over many years Priya reliably withdraws when criticised by her boss, but argues back whenever friends challenge her opinions.","prompt":"Which concept captures this consistent pattern?","options":["Aggregation","Reference group effect","Self-enhancement","A behavioural signature"],"answer":3,"explanation":"Behavioural signatures are stable if-then regularities of person-by-situation interaction (Mischel & Shoda, 1995).","lvl":4},{"type":"match","prompt":"Match each CAPS cognitive-affective unit to its meaning.","pairs":[["Encodings","How a person categorises self, others and events"],["Expectancies and beliefs","What a person anticipates will happen"],["Affects","Emotional responses activated in a context"],["Competencies and self-regulatory plans","Skills used to translate goals into action"]],"explanation":"CAPS treats personality as an organised network of processes activated by situations."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Trait measures predict behaviour better when behaviour is averaged across many observations, a principle called ___.","answers":["aggregation"],"explanation":"Averaging cancels out random situational influences so the underlying tendency becomes clearer.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Mischel argued that situations always outweigh traits in predicting behaviour.","wrong":"always","correct":"can","explanation":"The debate is a corrective, not a claim that situations always beat traits; both matter."},{"type":"type_answer","prompt":"What is the acronym for the model that treats personality as a stable network of cognitive and affective units activated by situations?","answers":["CAPS"],"explanation":"The Cognitive-Affective Personality System (Mischel & Shoda, 1995).","lvl":4}]},{"id":"HPS121-4.4","name":"Compare strengths and biases of personality assessment methods","summary":"You can name the logic, strengths and main biases of self-report, informant, projective and behavioural methods and argue for triangulation.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Self-report limitation","Informant report limitation"],"items":[{"text":"Self-enhancement","cat":0},{"text":"Letter of recommendation effect","cat":1},{"text":"Sibling contrast effect","cat":1},{"text":"Faking responses on a job application","cat":0},{"text":"Depends on how much of the target's behaviour the rater has seen","cat":1}],"explanation":"Self-report is threatened by motivated distortion; informants are limited by knowledge of the target and favourable rater selection."},{"type":"case","passage":"Sam rates himself as highly conscientious on a survey. He is tidier than his housemates, who are extremely messy, but his routines would be average in most other households.","prompt":"Which bias is most likely inflating Sam's score?","options":["Self-enhancement","Reference group effect","Sibling contrast effect","Letter of recommendation effect"],"answer":1,"explanation":"The reference group effect occurs when people compare themselves with their own social context rather than a universal standard.","lvl":4},{"type":"mc","prompt":"What did Gosling et al. (2012) find?","options":["Smartphone app use predicted extraversion","Projective tests showed strong validity","Observers' Big Five ratings from bedroom cues were consistent with students' self-ratings","Informant reports were more valid than self-reports"],"answer":2,"explanation":"Orderly bedrooms linked to conscientiousness and varied reading materials to openness. The smartphone finding was Chittaranjan et al. (2011).","lvl":3},{"type":"match","prompt":"Match each projective method to its task.","pairs":[["Rorschach","Describe what inkblots could be"],["Thematic Apperception Test","Tell stories about ambiguous pictures"],["Sentence completion","Complete stems such as 'I regret...'"],["Drawing tasks","Draw a person, house or tree"]],"explanation":"Validity varies by test and is strongest with structured coding of narrow constructs; drawing tasks show weak validity."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Behavioural assessments are more vulnerable to self-enhancement than self-report measures, but they are costly and time-intensive.","wrong":"more","correct":"less","explanation":"Behavioural measures sample what people actually do, so they are less vulnerable to response biases."},{"type":"mc","prompt":"Why does the unit recommend using multiple assessment methods together?","options":["Projective tests are always the most valid","Self-report cannot predict life outcomes","Behavioural assessments are cheap and quick","Each method has distinct biases and captures partly unique variance"],"answer":3,"explanation":"Triangulating self-report, informant and behavioural data reduces the biases of each method.","lvl":1}]},{"id":"HPS121-4.5","name":"Place details correctly in a Method section and interpret alpha","summary":"You can sort report details into Participants, Measures and Procedure and interpret Cronbach's alpha values.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Participants","Measures","Procedure"],"items":[{"text":"Accessed the online survey via a link and took 20 minutes on average","cat":2},{"text":"Measured with four items on a 5-point scale","cat":1},{"text":"A sample of 1132 Australian adults, 59.5% female","cat":0},{"text":"Received ethics approval from the Deakin HREC","cat":2},{"text":"Cronbach's alpha for this scale was .82","cat":1},{"text":"Recruited using convenience sampling","cat":0}],"explanation":"Participants covers who and how sampled; Measures covers each measure and its reliability; Procedure covers ethics, consent and what participants did."},{"type":"case","passage":"A student reports that a scale in her study had a Cronbach's alpha of 0.62.","prompt":"How should she describe its internal consistency?","options":["Questionable","Acceptable","Poor","Good"],"answer":0,"explanation":"Alpha of 0.6 to 0.69 is questionable; 0.7 to 0.79 is acceptable.","lvl":4},{"type":"order","prompt":"Put these Cronbach's alpha labels in order from highest to lowest internal consistency.","items":["Excellent","Good","Acceptable","Questionable","Poor"],"explanation":"0.9+ excellent, 0.8 to 0.89 good, 0.7 to 0.79 acceptable, 0.6 to 0.69 questionable, 0.5 to 0.59 poor, below 0.5 unacceptable."},{"type":"mc","prompt":"Researchers advertise their study only to first-year psychology students because they are easy to reach and belong to the population of interest. What sampling method is this?","options":["Random sampling","Stratified sampling","Convenience sampling","Snowball sampling"],"answer":2,"explanation":"Convenience sampling uses easy access to a reasonably large group from the population; random sampling gives everyone an equal chance.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The purpose of the Method section is to describe the study in enough detail to allow ___.","answers":["replication"],"explanation":"Transparent, logically placed information lets others replicate the study.","lvl":2},{"type":"type_answer","prompt":"Which statistic indicates how internally consistent (how well hung together) a scale's items are?","answers":["Cronbach's alpha","Cronbachs alpha","alpha","Cronbach alpha"],"explanation":"Cronbach's alpha ranges from 0 to 1, with higher values meaning higher internal consistency.","lvl":3}]}]},{"week":5,"topic":"Psychological Disorders: Frameworks, Anxiety and Mood","summary":"How disorders are defined, classified and explained (biopsychosocial and vulnerability-stress models), plus anxiety and mood disorders.","skills":[{"id":"HPS121-5.1","name":"Judge clinical significance using distress, impairment and context","summary":"You can decide whether a pattern is clinically significant using distress, impairment, context and risk, and compare the DSM and ICD.","questions":[{"type":"case","passage":"Jess spends every weekend collecting and cataloguing old bus tickets. Her friends think it is odd, but Jess enjoys it, works full-time without problems and has a close social circle.","prompt":"How would a psychologist most likely view Jess's behaviour?","options":["As a disorder, because it is unusual","As a disorder, because it deviates from social norms","Not a disorder: it is unusual but neither distressing nor impairing","Not assessable without the ICD-11"],"answer":2,"explanation":"Psychologists focus on clinical significance, not difference; unusual behaviour alone does not define a disorder.","lvl":1},{"type":"match","prompt":"Match each of the four Ds to what it captures.","pairs":[["Deviance","Departs from what the person's context expects"],["Distress","Subjectively painful or troubling"],["Dysfunction","Impairs work, study, home or relationships"],["Danger","Risk of harm to self or others"]],"explanation":"The four Ds are a flexible aid to thinking, not a rigid test."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["DSM","ICD"],"items":[{"text":"Published by the American Psychiatric Association","cat":0},{"text":"Published by the World Health Organisation","cat":1},{"text":"Covers both physical and mental health conditions","cat":1},{"text":"Current edition is the fifth, text revision","cat":0},{"text":"Current edition is the eleventh","cat":1}],"explanation":"The DSM-5-TR (APA, 2022) and ICD-11 (WHO, 2019) are the two main manuals used in Australia."},{"type":"mc","prompt":"What does the removal of homosexuality from the DSM in the 1970s illustrate?","options":["Diagnostic manuals are fully objective","Definitions of disorder are shaped by culture and history, so diagnosis requires care and humility","The ICD is more accurate than the DSM","Distress alone defines a disorder"],"answer":1,"explanation":"Shifting attitudes, evidence and advocacy changed the classification, showing definitions cannot be fixed or universal.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Most psychologists understand mental health and mental illness as existing on a binary.","wrong":"binary","correct":"continuum","explanation":"Thoughts, emotions and behaviours range from typical to severe, so the line is a matter of degree."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Psychologists focus on clinical ___, not difference, when judging whether a pattern is a disorder.","answers":["significance"],"explanation":"Clinical significance means the pattern causes real distress or impairment in context.","lvl":3}]},{"id":"HPS121-5.2","name":"Apply vulnerability-stress and biopsychosocial models to disorders","summary":"You can separate vulnerabilities from stressors, classify factors as biological, psychological or social, and explain their interaction.","questions":[{"type":"case","passage":"Ben has a family history of alcohol problems, is highly impulsive, and grew up watching his parents drink to cope. He began drinking heavily after a painful relationship breakup.","prompt":"Which of these is the stressor in a vulnerability-stress account?","options":["His genetic family history","His high impulsivity","His parents modelling drinking as coping","The relationship breakup"],"answer":3,"explanation":"Genetics, impulsivity and family modelling are vulnerabilities; the breakup is a social stressor that interacts with them to trigger onset.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Biological","Psychological","Social"],"items":[{"text":"Heightened autonomic nervous system reactivity","cat":0},{"text":"Catastrophic thinking","cat":1},{"text":"Academic or workplace pressure","cat":2},{"text":"Genetic vulnerability","cat":0},{"text":"Attentional bias towards threat","cat":1},{"text":"Interpersonal conflict","cat":2}],"explanation":"These are the contributing factors to anxiety listed in the notes, grouped by biopsychosocial domain."},{"type":"type_answer","prompt":"The vulnerability-stress model is also called the ___-stress model. What is the missing Ancient Greek-derived word meaning predisposition?","answers":["diathesis"],"explanation":"Diathesis refers to a predisposition or vulnerability toward developing a condition.","lvl":4},{"type":"mc","prompt":"Which statement is consistent with the vulnerability-stress model?","options":["Vulnerability does not make onset inevitable","A single factor best predicts onset","Stressors are always one-off events","People with low vulnerability cannot develop a disorder"],"answer":0,"explanation":"Onset depends on the interaction of vulnerability and stress over time; support and coping can change outcomes.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The biopsychosocial model was proposed by Bowlby in 1977.","wrong":"Bowlby","correct":"Engel","explanation":"Engel (1977) proposed that disorders reflect interacting biological, psychological and social factors."},{"type":"case","passage":"After childbirth, Anh experiences hormonal changes and broken sleep, worries about her parenting, and has little practical help because her family live overseas.","prompt":"In a biopsychosocial account of her postnatal depression, what domain does the lack of practical help belong to?","options":["Biological","Psychological","Social","It is not a contributing factor"],"answer":2,"explanation":"Reduced support, isolation and limited practical help are social factors that increase vulnerability.","lvl":1}]},{"id":"HPS121-5.3","name":"Describe features and maintenance of anxiety disorders","summary":"You can describe the features and course of anxiety disorders and explain how avoidance maintains anxiety.","questions":[{"type":"mc","prompt":"Why does avoidance maintain anxiety over time?","options":["It increases physiological arousal immediately","It is a culturally bound response","It causes genetic changes in threat detection","It reduces anxiety short-term, reinforcing avoidance and preventing learning that the situation is manageable"],"answer":3,"explanation":"Avoidance is reinforced by relief, which blocks new learning and makes untreated anxiety self-maintaining.","lvl":2},{"type":"case","passage":"A man in Japan experiences intense fear that his appearance and body odour cause embarrassment and discomfort to the people around him.","prompt":"What does this experience best illustrate?","options":["Generalised Anxiety Disorder","A culturally bound anxiety (Taijin Kyofusho)","Hypomania","A trauma- and stressor-related disorder"],"answer":1,"explanation":"Culturally bound anxieties show how social norms shape how distress is experienced and expressed.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"PTSD is now classified separately as a trauma- and ___-related disorder.","answers":["stressor"],"explanation":"PTSD shares threat sensitivity and avoidance with anxiety disorders but is now classified separately.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Physiological arousal","Cognitive feature","Behavioural tendency"],"items":[{"text":"Increased heart rate","cat":0},{"text":"Muscle tension","cat":0},{"text":"Persistent worry","cat":1},{"text":"Catastrophic thinking","cat":1},{"text":"Escaping feared situations","cat":2},{"text":"Avoiding feared stimuli","cat":2}],"explanation":"Anxiety disorders involve arousal, worry and escape or avoidance, which interact to maintain anxiety."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Anxiety disorders often develop suddenly and fluctuate over time with changes in stress.","wrong":"suddenly","correct":"gradually","explanation":"Anxiety disorders often develop gradually and fluctuate, with periods of improvement and worsening."},{"type":"analogy","prompt":"Nerves before an exam are to typical anxiety as persistent, disproportionate anxiety that disrupts study is to ___","options":["an anxiety disorder","a culturally bound syndrome","hypomania","anhedonia"],"answer":0,"explanation":"Anxiety becomes a possible disorder when it is excessive, persistent, hard to manage and interferes with functioning.","lvl":1}]},{"id":"HPS121-5.4","name":"Apply DSM-5-TR criteria to depressive and bipolar disorders","summary":"You can apply MDD criteria and exclusions and distinguish Bipolar I, Bipolar II and Cyclothymic Disorder.","questions":[{"type":"case","passage":"For three weeks Lina has felt depressed most of the day, nearly every day. She has insomnia, fatigue, feelings of worthlessness and poor concentration. There is no substance use, medical cause or history of mania or hypomania.","prompt":"Based on the DSM-5-TR overview, what is the most accurate conclusion?","options":["Criteria for a major depressive episode appear to be met","Criteria are not met because anhedonia is absent","This pattern indicates Bipolar II Disorder","This pattern indicates Cyclothymic Disorder"],"answer":0,"explanation":"Five symptoms over at least two weeks, including depressed mood, with no exclusions applying, fits a major depressive episode.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Bipolar I","Bipolar II","Cyclothymic Disorder"],"items":[{"text":"At least one full manic episode","cat":0},{"text":"Hypomanic and major depressive episodes, never full mania","cat":1},{"text":"Chronic subthreshold mood fluctuations for at least two years","cat":2},{"text":"May involve psychosis or hospitalisation","cat":0},{"text":"Depression is often the more impairing, enduring part","cat":1}],"explanation":"Bipolar I needs full mania; Bipolar II involves hypomania plus major depression; cyclothymia is chronic and below full criteria."},{"type":"mc","prompt":"Which of the following would rule out a diagnosis of Major Depressive Disorder?","options":["Symptoms lasting longer than two weeks","Changes in sleep and appetite","Symptoms that include episodes of hypomania","Loss of interest in most activities"],"answer":2,"explanation":"Hypomania or mania suggests a bipolar disorder rather than MDD.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Loss of interest or pleasure in previously enjoyable activities is called ___.","answers":["anhedonia"],"explanation":"Either depressed mood or anhedonia must be one of the five symptoms for a major depressive episode.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A major depressive episode requires five or more symptoms during the same month.","wrong":"month","correct":"fortnight","explanation":"The DSM-5-TR requires five or more symptoms during the same two-week period."},{"type":"match","prompt":"Match each mood disorder to its defining description.","pairs":[["Persistent Depressive Disorder","Also known as dysthymia"],["Major Depressive Disorder","Discrete episodes, often an episodic course"],["Cyclothymic Disorder","Chronic, persistent mood fluctuations"],["Bipolar I Disorder","Depressive episodes common but not required"]],"explanation":"Mood disorders are defined by how persistent and impairing mood changes are, not simply by sad or elevated mood."}]}]},{"week":6,"topic":"Psychological Disorders: Psychosis, Personality, Neurodevelopment and Labels","summary":"Schizophrenia spectrum, personality and neurodevelopmental disorders, the role of culture, diagnostic labels, and interpreting correlations for the Results section.","skills":[{"id":"HPS121-6.1","name":"Classify positive, negative and cognitive symptoms of psychosis","summary":"You can sort schizophrenia symptoms into positive, negative and cognitive and explain course and risk using the vulnerability-stress model.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Positive","Negative","Cognitive"],"items":[{"text":"Hearing voices","cat":0},{"text":"Fixed beliefs not shared by others","cat":0},{"text":"Avolition","cat":1},{"text":"Reduced emotional expression","cat":1},{"text":"Difficulty planning and making decisions","cat":2},{"text":"Poor attention and concentration","cat":2}],"explanation":"Positive symptoms are added experiences, negative symptoms are reductions, and cognitive symptoms are thinking difficulties."},{"type":"case","passage":"Daniel, 20, has a family history of schizophrenia. During a period of heavy cannabis use, severe sleep disruption and social isolation, he begins hearing voices.","prompt":"Which framework best explains why psychosis emerged now?","options":["Categorical personality model","The four Ds","The vulnerability-stress model","The Stereotype Content Model"],"answer":2,"explanation":"Psychotic symptoms emerge from the interaction of an underlying vulnerability with stressors, not from either alone.","lvl":1},{"type":"mc","prompt":"Which statement about schizophrenia is accurate according to the unit?","options":["It usually begins in middle age","People with psychotic symptoms can never recover","Negative symptoms are more visible than positive symptoms","Most people with schizophrenia are not violent; the absolute risk is low"],"answer":3,"explanation":"Relative risk is elevated but absolute risk remains low (Fazel et al., 2021), so challenging the stereotype matters.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Negative and cognitive symptoms are often subtler than positive symptoms, but frequently less impairing over the longer term.","wrong":"less","correct":"more","explanation":"Negative and cognitive symptoms are less visible but frequently more persistent and more impairing (McCutcheon et al., 2020)."},{"type":"type_answer","prompt":"What term describes reduced motivation or goal-directed behaviour, a negative symptom?","answers":["avolition"],"explanation":"Avolition, reduced emotional expression and social withdrawal are negative symptoms.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Schizophrenia spectrum disorders typically emerge in late adolescence or early ___.","answers":["adulthood"],"explanation":"Onset timing varies, and the course ranges from episodic to persistent (Owen et al., 2016).","lvl":2}]},{"id":"HPS121-6.2","name":"Contrast categorical and dimensional (AMPD) personality diagnosis","summary":"You can sort disorders into clusters, identify BPD, ASPD and AvPD patterns, and apply AMPD Criteria A and B.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Cluster A (odd or eccentric)","Cluster B (dramatic, emotional or erratic)","Cluster C (anxious or fearful)"],"items":[{"text":"Paranoid","cat":0},{"text":"Schizotypal","cat":0},{"text":"Borderline","cat":1},{"text":"Narcissistic","cat":1},{"text":"Avoidant","cat":2},{"text":"Dependent","cat":2}],"explanation":"The categorical model groups 10 personality disorders into three clusters by shared characteristics."},{"type":"case","passage":"Karl, a psychologist, assesses each client's sense of self and personal goals, their ability to understand another person's experience, and their capacity for close relationships. He rates the degree of impairment in each area rather than assigning a category.","prompt":"Which approach is Karl using?","options":["The categorical approach","The dimensional approach (AMPD Criterion A)","The four Ds","Behavioural assessment"],"answer":1,"explanation":"Criterion A rates impairment across identity, self-direction, empathy and intimacy on a continuum.","lvl":4},{"type":"match","prompt":"Match each AMPD Criterion B trait domain to its description.","pairs":[["Negative affectivity","Frequent, intense negative emotions"],["Detachment","Emotional or social withdrawal"],["Antagonism","Disregard for others' needs, hostility or manipulation"],["Disinhibition","Impulsivity, especially under stress"]],"explanation":"Criterion B describes how difficulties show up; the fifth domain is psychoticism."},{"type":"case","passage":"Tom badly wants close friendships but declines most invitations because he is sure people will judge him negatively. He often feels inadequate and ashamed.","prompt":"Which personality disorder pattern does this illustrate?","options":["Borderline","Antisocial","Avoidant","Schizoid"],"answer":2,"explanation":"Avoidant Personality Disorder involves desire for connection alongside intense fear of criticism or rejection.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The dimensional approach offers yes/no diagnoses with a high likelihood of diagnostic overlap.","wrong":"dimensional","correct":"categorical","explanation":"The categorical approach uses discrete, yes/no labels; the dimensional approach describes degree and pattern of traits."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Personality disorders are estimated to affect approximately ___ of the global population.","answers":["7.8%","7.8 percent","7.8"],"explanation":"Winsper et al. (2020) estimated about 7.8%; patterns are stable but not unchangeable.","lvl":5}]},{"id":"HPS121-6.3","name":"Explain neurodevelopmental disorders as difference versus disorder","summary":"You can describe ASD, ADHD and Specific Learning Disorders and explain how context determines clinically significant impairment.","questions":[{"type":"match","prompt":"Match each neurodevelopmental disorder to its key features.","pairs":[["Autism Spectrum Disorder","Social communication differences plus restricted or repetitive patterns"],["ADHD","Persistent inattention and/or hyperactivity-impulsivity"],["Specific Learning Disorder","Academic skills well below expectations despite appropriate opportunities"]],"explanation":"These disorders emerge early and affect functioning across settings."},{"type":"case","passage":"Ari's attention difficulties went unnoticed in a play-based kindergarten. In a structured Year 2 classroom with long seated tasks, they began to seriously affect his learning.","prompt":"What best explains why the difficulties became more noticeable?","options":["He developed a new illness in Year 2","Impact grows when environmental demands exceed current capacities","Neurodevelopmental disorders begin in middle childhood","His kindergarten caused the difficulties"],"answer":1,"explanation":"The impact of a neurodevelopmental disorder often becomes noticeable when expectations such as school structure exceed capacities.","lvl":1},{"type":"mc","prompt":"How do neurodevelopmental disorders differ from many other psychological disorders?","options":["They always resolve by adulthood","They are caused only by the environment","They reflect developmental variation rather than episodes of illness","They are rarely heritable"],"answer":2,"explanation":"They reflect developmental pathways that unfold over time, not a sudden change from previous functioning.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Biological","Psychological","Social"],"items":[{"text":"Prenatal and perinatal factors","cat":0},{"text":"Differences in neural connectivity","cat":0},{"text":"Cognitive processing styles","cat":1},{"text":"Adaptive and coping skills","cat":1},{"text":"Educational contexts and supports","cat":2},{"text":"Cultural expectations and social inclusion","cat":2}],"explanation":"Genetic vulnerability and environmental influences interact across development."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Twin and sibling studies suggest low familial income remains linked to ASD after controlling for shared family risk.","wrong":"ASD","correct":"ADHD","explanation":"Low familial income was linked to ADHD; gestational age and perinatal hypoxia were linked to ASD (Carlsson et al., 2020)."},{"type":"type_answer","prompt":"Hyperactive behaviour in early childhood may present in adulthood as difficulties with organisation or with what?","answers":["attention"],"explanation":"Neurodevelopmental conditions are lifelong, but their expression changes with development.","lvl":3}]},{"id":"HPS121-6.4","name":"Weigh the benefits and risks of diagnostic labels in context","summary":"You can explain how culture shapes distress and diagnosis and balance scientific, clinical, social and administrative benefits and risks.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Potential benefit","Potential risk"],"items":[{"text":"Supports access to funding and accommodations","cat":0},{"text":"A label may be treated as an identity","cat":1},{"text":"Enables consistent classification across studies","cat":0},{"text":"Narrows focus to symptoms rather than the whole person","cat":1},{"text":"Can validate experiences and reduce self-blame","cat":0},{"text":"Access to services becomes dependent on a label","cat":1}],"explanation":"Workhoven et al. (2021) outline benefits and risks across scientific, clinical, social and administrative domains."},{"type":"match","prompt":"Match each domain to a potential benefit of diagnostic labels.","pairs":[["Scientific","Consistent classification and comparison across studies"],["Clinical","Guides assessment and treatment planning"],["Social","Validates experience and builds community"],["Administrative","Access to services, funding and legal recognition"]],"explanation":"Each domain also carries a matching risk, so labels must be used with care."},{"type":"case","passage":"A client from a cultural background where distress is usually described physically presents with headaches, fatigue and stomach pain. A clinician relying only on Western criteria finds \"nothing psychological\".","prompt":"Which idea from the unit best explains the risk here?","options":["Diagnosis is purely objective","Only Western cultures experience distress","Physical symptoms rule out psychological distress","Culture shapes which symptoms are emphasised, and manuals may miss culturally specific expressions"],"answer":3,"explanation":"Diagnostic systems may reflect Western norms and overlook culturally specific expressions of distress.","lvl":1},{"type":"mc","prompt":"Social withdrawal may be protective in an unsafe setting but impairing in a supportive one. What does this illustrate?","options":["What counts as impairment depends on situational demands","Withdrawal is never clinically significant","Context is irrelevant to diagnosis","Diagnostic labels are fixed"],"answer":0,"explanation":"Functional impairment, a key criterion, depends on context (Batstra & Frances, 2024/2025).","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Diagnostic labels are tools, not definitions of ___.","answers":["identity"],"explanation":"Their impact depends on how they are communicated, understood and supported.","lvl":2},{"type":"analogy","prompt":"A scientific benefit is to consistent classification as a social risk is to ___","options":["stigma and stereotyping","access to funding","treatment planning","research comparison"],"answer":0,"explanation":"Socially, labels can validate experience but also risk stigma, stereotyping and discrimination.","lvl":2}]},{"id":"HPS121-6.5","name":"Interpret correlations using p and r values","summary":"You can check significance first, then describe the strength and direction of r, and report results correctly.","questions":[{"type":"case","passage":"A study finds a correlation between optimism and life satisfaction of r = .527, p = .038.","prompt":"How should this result be interpreted?","options":["Not significant, so do not interpret r","Significant, weak and negative","Significant, moderate and positive","Significant, strong and positive"],"answer":2,"explanation":"p < .05 so it is significant; r between .30 and .59 is moderate, and positive r means both variables rise together.","lvl":3},{"type":"case","passage":"A study finds a correlation between extraversion and stress of r = -.291, p = .066.","prompt":"How should this result be interpreted?","options":["Not significant, so strength and direction are not interpreted","Significant, weak and negative","Significant, moderate and negative","Not significant, but a weak negative trend should be reported as the main finding"],"answer":0,"explanation":"p is above .05, so the result is non-significant and r is not interpreted.","lvl":3},{"type":"order","prompt":"Put the steps for interpreting a correlation in order.","items":["Check whether p is below .05","If significant, judge the strength of r","State the direction of the relationship"],"explanation":"Always check the p-value first; only interpret r for significant correlations."},{"type":"match","prompt":"Match each significant correlation to its strength.","pairs":[["r = .75","Strong"],["r = .45","Moderate"],["r = -.17","Weak"]],"explanation":"Plus or minus .60 to 1 is strong, .30 to .59 moderate, and below .30 weak; the sign does not affect strength."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A negative correlation means that as scores on one variable increase, scores on the other variable rise.","wrong":"rise","correct":"fall","explanation":"In a negative correlation, as one variable increases the other decreases."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When reporting a mean scale score you must also report the ___.","answers":["standard deviation","SD"],"explanation":"Without the SD the mean is meaningless, because the SD shows the spread of scores.","lvl":2}]}]},{"week":7,"topic":"Psychological Treatment: Therapeutic Traditions","summary":"Psychodynamic, behavioural, humanistic, cognitive, CBT and third wave therapies, plus writing the Discussion and Abstract.","skills":[{"id":"HPS121-7.1","name":"Explain key features of modern psychodynamic therapy","summary":"You can describe how modern psychodynamic therapy works, name example therapies and weigh its strengths and limitations.","questions":[{"type":"match","prompt":"Match each psychodynamic therapy to its key figure(s).","pairs":[["Mentalisation-based therapy","Bateman and Fonagy"],["Transference-focused psychotherapy","Kernberg, Yeomans and Clarkin"],["Supportive-expressive therapy","Luborsky"],["Short-term psychodynamic psychotherapy","Malan and Davanloo"]],"explanation":"These therapies keep core psychodynamic ideas but are more structured and evidence-informed."},{"type":"case","passage":"Ella keeps expecting her therapist to criticise her, just as her father did. Her therapist gently explores this pattern with her as it happens in their sessions.","prompt":"Which psychodynamic concept is being worked with?","options":["Sublimation","Transference","Systematic desensitisation","Cognitive restructuring"],"answer":1,"explanation":"Transference is unconsciously repeating earlier relational patterns with the therapist; examining it safely produces insight.","lvl":2},{"type":"mc","prompt":"What are the 'sleeper effects' reported for psychodynamic therapy?","options":["Clients feel drowsy after sessions","Gains disappear once therapy ends","Improvements occur only during sleep","Gains continue or increase after therapy ends"],"answer":3,"explanation":"Sleeper effects are often read as evidence that therapy strengthens reflective capacity and insight.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In psychodynamic therapy, homework is assumed to be the mechanism of change.","wrong":"homework","correct":"insight","explanation":"Insight into emotional patterns, defences and relational themes is assumed to produce change."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Strength","Limitation"],"items":[{"text":"Emphasis on depth and long-term personality change","cat":0},{"text":"Sleeper effects after therapy ends","cat":0},{"text":"Traditionally time-intensive and costly","cat":1},{"text":"Early constructs lacked experimental validation","cat":1},{"text":"Risk of inconsistency between practitioners","cat":1}],"explanation":"Contemporary versions respond to these limitations by being more time-limited, manualised and outcome-focused."},{"type":"type_answer","prompt":"Contemporary psychodynamic therapists describe the therapeutic relationship as what kind of environment?","answers":["holding","holding environment","a holding environment"],"explanation":"The relationship is a holding environment and an active tool for change, not a neutral observation post.","lvl":4}]},{"id":"HPS121-7.2","name":"Apply behavioural therapy principles such as exposure","summary":"You can explain how classical conditioning, operant conditioning and modelling are used in behavioural therapies.","questions":[{"type":"case","passage":"Nadia developed a fear of spiders after a frightening experience. Her therapist arranges gradual, repeated contact with spiders in a safe setting where nothing bad happens.","prompt":"According to the research described, what happens to Nadia's original fear association?","options":["It is permanently erased","It is strengthened by the exposure","It remains, but a new association forms that inhibits the fear response","It is replaced by a conditioned relaxation response only"],"answer":2,"explanation":"Exposure works through extinction; the original association is not erased but a new inhibitory association develops.","lvl":4},{"type":"match","prompt":"Match each behavioural therapy to its central focus.","pairs":[["Systematic desensitisation","Pairing relaxation with feared stimuli"],["Contingency management","Structured rewards for adaptive behaviour"],["Applied behaviour analysis","Shaping behaviour through reinforcement and consequences"],["Behavioural skills training","Teaching and reinforcing new skills through practice"]],"explanation":"These therapies apply learning principles to observable, measurable behaviour."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Classical conditioning","Operant conditioning","Modelling"],"items":[{"text":"A spider becomes feared after being paired with distress","cat":0},{"text":"Food poisoning makes a food aversive after one pairing","cat":0},{"text":"Leaving a feared situation reduces anxiety, strengthening avoidance","cat":1},{"text":"An app unlocks new content after a module is completed","cat":1},{"text":"A therapist demonstrates a coping skill for the client to copy","cat":2},{"text":"Learning a social behaviour by watching a peer be rewarded","cat":2}],"explanation":"Behaviours are shaped by associations, consequences and observation."},{"type":"mc","prompt":"Which is a recognised limitation of behavioural approaches?","options":["They cannot be tested experimentally","Behaviour change does not always generalise, and relapse can occur if supports are removed","They focus too heavily on unconscious conflict","They have no evidence for anxiety disorders"],"answer":1,"explanation":"Skills may need ongoing reinforcement across contexts (Babulal et al., 2016); early models also neglected internal experience.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Behavioural approaches emerged in the mid-twentieth century as a reaction against theories focused on observable processes.","wrong":"observable","correct":"unconscious","explanation":"They reacted against theories focused on unconscious processes, favouring observable behaviour and learning."},{"type":"analogy","prompt":"The bell is to a neutral stimulus before pairing as the bell is to ___ after pairing","options":["a conditioned stimulus","an unconditioned stimulus","a conditioned response","an unconditioned response"],"answer":0,"explanation":"After repeated pairing with food, the formerly neutral bell becomes a conditioned stimulus.","lvl":1}]},{"id":"HPS121-7.3","name":"Identify humanistic therapy features and examples","summary":"You can recognise humanistic assumptions and skills, match therapies to founders and weigh the evidence.","questions":[{"type":"mc","prompt":"How does humanistic therapy understand psychological distress?","options":["As a disruption in the ability to experience oneself authentically and move toward growth","As unconscious conflict from early childhood","As learned behaviour maintained by reinforcement","As distorted automatic thoughts"],"answer":0,"explanation":"Humanistic therapy assumes growth emerges from the right relational conditions.","lvl":2},{"type":"match","prompt":"Match each humanistic therapy to its key figure.","pairs":[["Person-centred therapy","Rogers"],["Emotion-focused therapy","Greenberg, Rice and Elliott"],["Focusing-oriented therapy","Gendlin"],["Gestalt therapy","Perls, Hefferline and Goodman"]],"explanation":"Each shares a focus on the relationship and present experience."},{"type":"case","passage":"During a session the therapist says: \"I notice you went quiet just now when I mentioned your brother. What's happening for you right now, between us?\"","prompt":"Which empathic skill is the therapist using?","options":["Cognitive restructuring","Free association","Immediacy","Contingency management"],"answer":2,"explanation":"Immediacy means gently commenting on what is happening in the relationship right now.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Empathy and the therapeutic ___ are among the most reliable predictors of positive outcomes across therapies.","answers":["alliance"],"explanation":"Norcross and Lambert (2019) found these relational qualities are measurable and clinically important.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Strength","Limitation"],"items":[{"text":"Improvements comparable to other major traditions","cat":0},{"text":"EFT is evidence-supported for depression and relationship distress","cat":0},{"text":"Less efficient for highly specific symptom problems","cat":1},{"text":"Empathy is hard to standardise, making RCTs difficult","cat":1},{"text":"Clients wanting step-by-step techniques may prefer directive models","cat":1}],"explanation":"Earlier criticisms of its scientific basis have largely been addressed, though outdated perceptions linger."},{"type":"type_answer","prompt":"Which humanistic therapy, associated with Axline (1947), supports emotional expression through play?","answers":["child-centred play therapy","play therapy","child-centered play therapy"],"explanation":"Child-centred play therapy provides a safe relational environment for children's emotional expression.","lvl":4}]},{"id":"HPS121-7.4","name":"Distinguish cognitive therapy, CBT and third wave approaches","summary":"You can identify cognitive distortions, contrast disputing thoughts with changing one's relationship to them, and match therapies to founders.","questions":[{"type":"case","passage":"After a friend does not reply to a message, Jordan immediately thinks: \"They must hate me.\"","prompt":"Which automatic thought distortion is this?","options":["Overgeneralising","Catastrophising","Mind-reading","Rationalisation"],"answer":2,"explanation":"Mind-reading assumes knowledge of others' thoughts without evidence; cognitive therapy helps examine such thoughts.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Traditional CBT","Third wave"],"items":[{"text":"Disputing the content of unhelpful thoughts","cat":0},{"text":"Noticing thoughts without automatically believing them","cat":1},{"text":"Acting on values even with uncomfortable feelings","cat":1},{"text":"Behavioural experiments to test the accuracy of beliefs","cat":0},{"text":"Mindfulness and acceptance","cat":1},{"text":"Replacing safety behaviours with adaptive actions","cat":0}],"explanation":"The third wave shifts from disputing thought content to changing how people relate to inner experience (psychological flexibility)."},{"type":"match","prompt":"Match each therapy to its founder.","pairs":[["Acceptance and commitment therapy","Hayes"],["Dialectical behaviour therapy","Linehan"],["Rational emotive behaviour therapy","Ellis"],["Metacognitive therapy","Wells"]],"explanation":"ACT and DBT are third wave; REBT and metacognitive therapy are cognitive approaches."},{"type":"mc","prompt":"What is considered the 'second wave' of behavioural therapy?","options":["Classical psychoanalysis","Mindfulness-based approaches","Humanistic person-centred therapy","The integration of cognitive models with behavioural learning principles (traditional CBT)"],"answer":3,"explanation":"Traditional CBT combined the C with the B, treating thoughts and behaviour as an interacting system (Schefft et al., 2023).","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Comparative trials generally show that third wave therapies are superior to traditional CBT.","wrong":"superior","correct":"equivalent","explanation":"Trials generally show equivalence rather than superiority, fuelling debate over whether the third wave is a paradigm shift."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Aaron Beck, who developed cognitive therapy, originally trained in ___.","answers":["psychoanalysis"],"explanation":"Cognitive therapy grew as a response to both the psychodynamic and behavioural traditions.","lvl":4}]},{"id":"HPS121-7.5","name":"Structure a Discussion paragraph and an Abstract","summary":"You can order the parts of a findings paragraph and an abstract, and write limitations and future directions correctly.","questions":[{"type":"order","prompt":"Put the parts of a paragraph that interprets a finding in order.","items":["Restate the finding","Interpret the finding","Explain the finding","Research implications","Real-world implications"],"explanation":"The seminar example moves through restate, interpret, explain, then research and real-world implications."},{"type":"order","prompt":"Put the content of an Abstract in the correct order.","items":["Introduction","Method","Results","Discussion"],"explanation":"The Abstract summarises the most critical points from each section in the same order as the report."},{"type":"mc","prompt":"What should you do with a statistically non-significant result in your Discussion?","options":["Leave it out, since it does not support the hypothesis","Discuss why you think it was non-significant","Interpret its r value for strength and direction","Report it only in the Abstract"],"answer":1,"explanation":"Non-significant results should be discussed, not ignored.","lvl":2},{"type":"case","passage":"A student lists a limitation: \"Most participants were female.\" Their only future research suggestion is: \"Future studies should recruit more males.\"","prompt":"What is the main problem with this approach?","options":["Limitations should never mention the sample","Future research must be a personal interest","Limitations belong in the Results section","A future research suggestion should not simply be the fix for a limitation"],"answer":3,"explanation":"You need two limitations and two distinct future directions that ask the next question given your findings.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A significant correlation provides sufficient evidence of causation between two variables.","wrong":"causation","correct":"association","explanation":"Correlation shows association, not causation; a causal relationship may exist but the analysis cannot show it."},{"type":"type_answer","prompt":"Besides real-world implications, what other type of implication should accompany each finding in the Discussion?","answers":["research","research implications","research implication"],"explanation":"Research implications ask whether the finding is consistent with past literature and what it adds.","lvl":3}]}]},{"week":8,"topic":"Psychological Treatment: Delivery Systems and Evaluation","summary":"Group therapy, self-help, community mental health services, digital mental health and methods for evaluating interventions.","skills":[{"id":"HPS121-8.1","name":"Identify mechanisms of group therapy and self-help groups","summary":"You can explain the treatment gap and name the mechanisms that make group and peer-led formats work.","questions":[{"type":"match","prompt":"Match each group therapy mechanism to what it does.","pairs":[["Universality","Recognising others share similar struggles"],["Instillation of hope","Seeing improvement in others further along"],["Group cohesion","Belonging and trust, the group analogue of the alliance"],["Interpersonal learning","Learning about one's own relational patterns through the group"]],"explanation":"Yalom and Leszcz (2020) describe these as mechanisms of change in group formats."},{"type":"case","passage":"In her first group session, Rosa says with visible relief: \"I honestly thought I was the only person who felt like this.\"","prompt":"Which group mechanism is Rosa experiencing?","options":["Instillation of hope","Universality","Modelling adaptive coping","Giving and receiving feedback"],"answer":1,"explanation":"Universality reduces isolation and shame by showing others share similar struggles.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Group therapy","Self-help group"],"items":[{"text":"Clinician-led","cat":0},{"text":"Peer-led","cat":1},{"text":"Emphasises mutual aid rather than formal psychotherapy","cat":1},{"text":"Alcoholics Anonymous","cat":1},{"text":"Professional guidance of corrective interpersonal experiences","cat":0}],"explanation":"Both leverage social processes, but self-help groups are peer-led and draw on shared lived experience."},{"type":"mc","prompt":"What is the 'treatment gap'?","options":["The time between sessions in group therapy","The difference between RCT and pragmatic trial results","The mismatch between the number of people who need psychological support and those who receive effective treatment","The gap between telehealth and in-person outcomes"],"answer":2,"explanation":"Kazdin (2023) argues even highly effective therapies have limited public health impact if they cannot be scaled.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Yalom and Leszcz describe group cohesion as the group analogue of the therapeutic ___.","answers":["alliance"],"explanation":"Cohesion lets members take interpersonal risks and disclose vulnerability.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Kazdin (2023) argues that one-to-one therapy can meet population demand on its own if it is efficacious enough.","wrong":"can","correct":"cannot","explanation":"Traditional one-to-one therapy cannot meet population demand on its own, no matter how efficacious."}]},{"id":"HPS121-8.2","name":"Match community mental health goals to practice","summary":"You can link each goal of community mental health services to concrete practices, including culturally safe care.","questions":[{"type":"case","passage":"A regional health network struggles with workforce shortages and long travel distances, despite high need in remote towns. It funds locally based clinicians and community-controlled Aboriginal services.","prompt":"Which community mental health goal is this mainly addressing?","options":["Promote recovery and partnership","Prevent crisis after hospital discharge","Address social determinants such as housing","Reduce inequities in access to care"],"answer":3,"explanation":"Equitable delivery is a persistent challenge in rural and remote Australia, and culturally safe, community-controlled services are essential.","lvl":3},{"type":"mc","prompt":"How do recovery-oriented community frameworks define recovery?","options":["The ability to live a meaningful, self-directed life in one's community","The complete absence of symptoms","Discharge from hospital","Completing an RCT-validated treatment"],"answer":0,"explanation":"Recovery emphasises hope, dignity and partnership, not only symptom control.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Address social determinants","Prevent crisis and support long-term recovery"],"items":[{"text":"Case management to secure stable housing","cat":0},{"text":"Employment and education support","cat":0},{"text":"Relapse prevention beyond the acute phase","cat":1},{"text":"Continuity from hospital to community care to reduce readmission","cat":1},{"text":"Treating social isolation as a core part of recovery","cat":0}],"explanation":"Social determinants are treated as core to recovery, while crisis prevention focuses on continuity and relapse prevention."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Community services aim to deliver support in the least ___ and most accessible environments possible.","answers":["restrictive"],"explanation":"Locally embedded services reduce geographic, financial and social barriers.","lvl":3},{"type":"analogy","prompt":"Peer workforces are to promoting partnership as community-controlled services are to ___","options":["culturally safe care for Aboriginal and Torres Strait Islander communities","hospital-centred treatment","symptom control only","randomised controlled trials"],"answer":0,"explanation":"Community-controlled services and investment in local capacity support culturally safe care.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Recovery-oriented frameworks treat lived experience as a form of bias.","wrong":"bias","correct":"expertise","explanation":"Lived experience is treated as expertise, supported by shared decision-making and peer workforces."}]},{"id":"HPS121-8.3","name":"Evaluate evidence for digital mental health and telehealth","summary":"You can summarise evidence for each digital modality and name the main limitations, including the digital divide.","questions":[{"type":"match","prompt":"Match each digital modality to its evidence.","pairs":[["Telehealth","Equivalent to in-person care for adult anxiety and mood disorders"],["Digital CBT for anxiety","Large gains versus usual care; similar to face-to-face"],["Digital CBT for depression","Comparable to face-to-face once moderators are accounted for"],["Blended care","Combines clinician contact with digital resources"]],"explanation":"Shaker et al. (2023), Pauley et al. (2023), Kambeitz-Ilankovic et al. (2022) and Nunes-Zlotkowski et al. (2024)."},{"type":"case","passage":"George, 72, lives on a remote property with unreliable internet and limited experience with smartphones. His local clinic offers mental health support only through an app.","prompt":"Which limitation of digital mental health does George's situation illustrate?","options":["High attrition","Underdeveloped implementation research","The digital divide","Privacy and data security"],"answer":2,"explanation":"Unequal access to technology can exclude people with lower digital literacy or poor connectivity.","lvl":1},{"type":"mc","prompt":"For which kind of approach is the digital mental health evidence base currently strongest?","options":["Psychodynamic approaches","Cognitive behavioural approaches","Humanistic approaches","AI-assisted support"],"answer":1,"explanation":"The module notes the strongest evidence exists for cognitive behavioural approaches.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Benefit","Limitation"],"items":[{"text":"Supports continuity during travel restrictions, illness or relocation","cat":0},{"text":"High attrition and disengagement","cat":1},{"text":"Privacy and data security concerns","cat":1},{"text":"Expands access for people facing barriers to care","cat":0},{"text":"Limited long-term evidence for newer tools","cat":1}],"explanation":"Digital tools extend reach, but evidence gaps, dropout and privacy remain concerns."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Once moderators such as guidance and adherence are accounted for, digital and face-to-face CBT for depression show different effectiveness.","wrong":"different","correct":"comparable","explanation":"Face-to-face looks stronger in unadjusted comparisons, but adjusted comparisons show comparable effectiveness."},{"type":"type_answer","prompt":"What term describes unequal access to technology that may exclude people with lower income or poor connectivity from care?","answers":["digital divide","the digital divide"],"explanation":"The digital divide is a key equity limitation of digital mental health.","lvl":2}]},{"id":"HPS121-8.4","name":"Compare methods for evaluating psychological interventions","summary":"You can identify each evaluation approach from a description and state its strength and limitation.","questions":[{"type":"match","prompt":"Match each evaluation approach to its main limitation.","pairs":[["Randomised controlled trial","Ideal conditions limit generalisability to routine practice"],["Pragmatic trial","Less experimental control"],["Meta-analysis","Inherits the limitations of the underlying studies"],["Routine outcome monitoring","Depends on consistent completion and good measure choice"]],"explanation":"No single method gives a complete picture; strong evidence comes from converging methods."},{"type":"case","passage":"Roberge et al. (2022) tested transdiagnostic group CBT plus usual care in community settings with broad participant criteria, comparing it with usual care alone.","prompt":"What type of evaluation is this?","options":["Randomised controlled trial under ideal conditions","Effectiveness (pragmatic) trial","Systematic review","Routine outcome monitoring"],"answer":1,"explanation":"Pragmatic trials test performance in real-world settings with typical services, giving high ecological validity.","lvl":4},{"type":"mc","prompt":"According to the Week 10 revision quiz, which approach does NOT allow assessment of the effectiveness of interventions?","options":["Routine outcome monitoring","A randomised controlled trial","A pragmatic trial","Implementation evaluation"],"answer":3,"explanation":"Implementation evaluation examines integration into services, but cannot always isolate treatment effects.","lvl":4},{"type":"case","passage":"At the start of each session, a psychologist asks her client to complete a brief standardised questionnaire. When scores plateau for three weeks, she adjusts the treatment plan.","prompt":"Which evaluation approach is she using?","options":["Routine outcome monitoring","Meta-analysis","Implementation evaluation","Randomised controlled trial"],"answer":0,"explanation":"Routine outcome monitoring turns evaluation into an ongoing feature of practice (Barkham et al., 2023).","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"RCTs are the gold standard for efficacy because random assignment gives strong ___ validity.","answers":["internal"],"explanation":"Random assignment isolates causal effects, although generalisability may be limited.","lvl":3},{"type":"analogy","prompt":"A randomised controlled trial is to internal validity as a pragmatic trial is to ___","options":["ecological validity","treatment fidelity","base rates","attrition"],"answer":0,"explanation":"RCTs maximise control; pragmatic trials trade some control for real-world relevance.","lvl":4}]}]},{"week":9,"topic":"Social Psychology: Foundations, Reasoning and Attitudes","summary":"What social psychology studies, its major areas, stereotypes versus prejudice versus discrimination, social reasoning shortcuts, and explicit versus implicit attitudes.","skills":[{"id":"HPS121-9.1","name":"Define social psychology, its levels of analysis and methods","summary":"You can apply Allport's definition, order levels of analysis and explain why social psychologists use naturalistic observation.","questions":[{"type":"fill_gap","prompt":"Complete the sentence.","text":"Allport (1954) defined social psychology as the study of how individuals are influenced by the actual, imagined or ___ presence of others.","answers":["implied"],"explanation":"Others need not be physically present; imagining an audience or knowing a rule exists can change behaviour.","lvl":4},{"type":"order","prompt":"Put these levels of analysis in order from broadest to most specific.","items":["Culture and environment","Relationships and groups","Behaviour","Thoughts, feelings and perceptions","Physiology (hormones, brain)"],"explanation":"The toddler example runs from culture down to chemistry and DNA; social psychology emphasises the higher levels."},{"type":"case","passage":"A researcher wants to study how strangers negotiate queue-jumping. Instead of a lab task, she watches shoppers at supermarket checkouts over several weeks.","prompt":"Which method is she using, and what bias does it help reduce?","options":["Laboratory experiment; demand characteristics","Implicit Association Test; self-presentation","Naturalistic observation; social desirability bias","Self-report survey; reference group effect"],"answer":2,"explanation":"Naturalistic observation studies real settings without relying on self-report, reducing social desirability bias (Krumpal, 2011).","lvl":3},{"type":"match","prompt":"Match each area of social psychology to a question it studies.","pairs":[["Attraction","What shapes who we are drawn to"],["Peace and conflict","Why people fight and how reconciliation happens"],["Social influence","How others shape our attitudes and behaviour"],["Social cognition","How we interpret others' motives and behaviour"]],"explanation":"The fifth area is attitudes. The categories overlap, and one researcher may work across several."},{"type":"mc","prompt":"In Wirtz et al. (2011), what most influenced perceived attractiveness?","options":["The viewer's cultural group","Facial symmetry","The photographed person's age","Whether the viewer was friends with the person"],"answer":3,"explanation":"Knowing someone's non-physical qualities such as warmth raised perceived attractiveness, the friendship effect.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Social psychologists typically emphasise the lower levels of analysis, such as chemistry and DNA.","wrong":"lower","correct":"higher","explanation":"They are interested in every level but typically emphasise relationships, groups, environment and culture."}]},{"id":"HPS121-9.2","name":"Distinguish stereotypes, prejudice and discrimination","summary":"Given a scenario, you can identify the thought (stereotype), feeling (prejudice) and action (discrimination).","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Stereotype","Prejudice","Discrimination"],"items":[{"text":"Believing all tattooed people are aggressive","cat":0},{"text":"Feeling uncomfortable sitting beside a tattooed man","cat":1},{"text":"Declining to hire a qualified candidate because of a tattoo","cat":2},{"text":"Assuming older people are bad with technology","cat":0},{"text":"Feeling contempt for a group before meeting any members","cat":1},{"text":"Refusing service to someone because of their religion","cat":2}],"explanation":"Stereotype is cognitive, prejudice is affective and discrimination is behavioural."},{"type":"analogy","prompt":"A stereotype is to thought as discrimination is to ___","options":["action","feeling","attitude","category"],"answer":0,"explanation":"Discrimination is prejudice or stereotyping put into behaviour.","lvl":1},{"type":"mc","prompt":"Which statement about stereotypes is accurate?","options":["They are always negative","They are emotional responses to group members","They can be positive or negative, accurate or inaccurate, and never apply to every group member","They are always inaccurate"],"answer":2,"explanation":"Stereotypes are information shortcuts; even broadly accurate ones do not fit every individual.","lvl":2},{"type":"case","passage":"A manager feels uneasy whenever a new graduate from a particular suburb speaks in meetings, but he gives her the same tasks, feedback and opportunities as everyone else.","prompt":"What is present in this scenario?","options":["Discrimination only","Prejudice, without discrimination","Discrimination based on a stereotype","No bias at all"],"answer":1,"explanation":"The uneasy feeling based on group membership is prejudice; because his behaviour is unchanged, there is no discrimination.","lvl":3},{"type":"type_answer","prompt":"What term describes how someone feels about a person based on their group membership?","answers":["prejudice"],"explanation":"Prejudice is pre-judging by group membership rather than getting to know the individual.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Discrimination is a cognitive structure that helps us navigate social situations efficiently by making judgements about others.","wrong":"Discrimination","correct":"Stereotyping","explanation":"Stereotypes are the cognitive structure; discrimination is the behavioural response."}]},{"id":"HPS121-9.3","name":"Identify social influence forms and the attribution error","summary":"You can classify conformity, obedience, reciprocity and persuasion, recognise the FAE and the two drivers of conformity.","questions":[{"type":"match","prompt":"Match each form of social influence to its definition.","pairs":[["Conformity","Acting and thinking like the people around us"],["Obedience","Following instructions from someone in authority"],["Reciprocity","Feeling obliged to return favours"],["Persuasion","Messages designed to change behaviour"]],"explanation":"Social influence is often subtle and occurs without us realising."},{"type":"case","passage":"When a colleague arrives late to a meeting, Hana thinks, \"She is so disorganised and careless.\" When Hana is late the next week, she blames the traffic.","prompt":"What is Hana showing?","options":["The fundamental attribution error","The availability heuristic","The planning fallacy","Reciprocity"],"answer":0,"explanation":"The FAE attributes others' actions to personality while overlooking situational influences, and excuses our own as situational.","lvl":2},{"type":"case","passage":"At the supermarket, a staff member hands Leo a free sample of cheese. Leo doesn't much like it but feels he should buy a packet anyway.","prompt":"Which form of social influence is at work?","options":["Obedience","Informational influence","Persuasion","Reciprocity"],"answer":3,"explanation":"Reciprocity is the felt obligation to return favours, gifts and kind gestures.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Normative influence","Informational influence"],"items":[{"text":"Laughing at a joke you don't find funny so the group accepts you","cat":0},{"text":"Following the crowd to an exit in an unfamiliar building","cat":1},{"text":"Wearing the same brand as friends to avoid being teased","cat":0},{"text":"Copying other diners' cutlery use at your first formal dinner","cat":1}],"explanation":"Normative influence seeks approval; informational influence uses others as a source of accurate information when uncertain."},{"type":"mc","prompt":"Which finding does the lecture use to challenge the Stanford Prison Experiment's conclusions?","options":["Guards were chosen for aggressive personalities","A partial replication (Haslam & Reicher, 2006) found guards were unwilling to take on the role without explicit instructions","Prisoners became aggressive rather than docile","The study ran for the full two weeks"],"answer":1,"explanation":"Along with anecdotal evidence and demand characteristics, this suggests people do not blindly conform to roles.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Making educated guesses about the motives and efforts of others is called social ___.","answers":["attribution"],"explanation":"Because we lack direct insight into others' minds, social attributions are prone to systematic errors.","lvl":3}]},{"id":"HPS121-9.4","name":"Recognise schemas, heuristics and reasoning biases","summary":"You can identify schemas, the representativeness and availability heuristics, forecasting errors, motivated reasoning and mood effects.","questions":[{"type":"case","passage":"On a train, you see a quiet person in glasses reading poetry. You guess they are a literature professor rather than a truck driver.","prompt":"Which heuristic are you using, and what are you ignoring?","options":["Representativeness heuristic; base-rate information","Availability heuristic; how easily examples come to mind","Representativeness heuristic; durability bias","Availability heuristic; mood-congruent memory"],"answer":0,"explanation":"Judging by similarity to a prototype neglects base rates: there are far more truck drivers than literature professors.","lvl":4},{"type":"case","passage":"After weeks of heavy news coverage of a rare plane crash, Maya decides to drive interstate because flying \"seems so dangerous now\".","prompt":"Which heuristic best explains her decision?","options":["Representativeness heuristic","Planning fallacy","Need for closure","Availability heuristic"],"answer":3,"explanation":"Vivid, heavily televised events come to mind easily, so their frequency is overestimated.","lvl":2},{"type":"match","prompt":"Match each reasoning error to its definition.","pairs":[["Planning fallacy","Underestimating how long a task will take"],["Impact bias","Overestimating the intensity of future feelings"],["Durability bias","Overestimating how long future feelings will last"],["Need for closure","Wanting a firm decision quickly to reduce uncertainty"]],"explanation":"Impact and durability biases are errors in affective forecasting."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Person schema","Self-schema","Event schema (script)"],"items":[{"text":"Expecting your best friend to be late, as usual","cat":0},{"text":"Knowing you get nervous before presentations and planning for it","cat":1},{"text":"Knowing to queue, order, then pay at a cafe","cat":2},{"text":"Anticipating how your grandmother will react to news","cat":0},{"text":"Knowing the usual sequence of a wedding ceremony","cat":2},{"text":"Seeing yourself as a morning person and scheduling study early","cat":1}],"explanation":"Schemas are mental blueprints about people, ourselves and recurring events."},{"type":"mc","prompt":"What did Schwarz and Clore (1983) show about mood and judgement?","options":["Mood has no effect on important judgements","Sad people recall happy memories more easily","People used their weather-related mood as evidence about their overall life satisfaction","Sunny weather lowered life-satisfaction ratings"],"answer":2,"explanation":"Lower mood on rainy days reduced life-satisfaction ratings, showing irrelevant mood can distort judgement.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Dismissing strong evidence that contradicts a preferred belief is called motivated closure.","wrong":"closure","correct":"scepticism","explanation":"Motivated scepticism, like Ahmed questioning the marker's fairness, arises from directional goals."}]},{"id":"HPS121-9.5","name":"Contrast explicit and implicit attitudes and the IAT","summary":"You can distinguish explicit from implicit attitudes, explain the IAT's logic and predict which attitude guides a behaviour.","questions":[{"type":"case","passage":"Priya rates \"I like my job\" as strongly agree. On an IAT she is slow to select 'positive' when shown her company logo, perhaps reflecting her long commute and a condescending coworker.","prompt":"What is the best interpretation?","options":["Both attitudes are positive","Positive explicit attitude, less positive implicit attitude","Negative explicit attitude, positive implicit attitude","The IAT result shows she is lying"],"answer":1,"explanation":"Implicit attitudes can differ from, or contradict, explicit attitudes; slower 'positive' pairing implies a less positive association.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Explicit attitude","Implicit attitude"],"items":[{"text":"Rating agreement with 'I like my job' on a Likert scale","cat":0},{"text":"Reaction time when pairing a logo with 'positive'","cat":1},{"text":"Guides deliberate decisions like choosing a university major","cat":0},{"text":"Shapes split-second behaviour when cognitive resources are limited","cat":1},{"text":"Consciously held and easily reported","cat":0},{"text":"Operates outside conscious awareness","cat":1}],"explanation":"Explicit attitudes are measured directly and guide deliberate choices; implicit attitudes are measured indirectly and shape automatic behaviour."},{"type":"mc","prompt":"What are the two main limitations of measuring attitudes by direct self-report?","options":["Reaction times are too slow and scales are too short","Informants are biased and samples are small","It cannot predict any behaviour and is too expensive","Self-presentation concerns, and people not being fully aware of their true attitude"],"answer":3,"explanation":"People may not answer socially undesirable items truthfully, or may be undecided or unaware of their attitude.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In the IAT, faster categorisation implies a ___ mental association between two concepts.","answers":["closer","stronger"],"explanation":"Response time in milliseconds indicates how strongly a concept and an evaluation are linked.","lvl":3},{"type":"type_answer","prompt":"Who is the first author of the 1998 paper introducing the Implicit Association Test?","answers":["Greenwald","Anthony Greenwald","A. G. Greenwald"],"explanation":"Greenwald, McGhee and Schwartz (1998).","lvl":5},{"type":"analogy","prompt":"An explicit attitude is to a considered voting decision as an implicit attitude is to ___","options":["choosing a university major","a split-second reaction","a Likert rating","a survey response"],"answer":1,"explanation":"People may endorse egalitarian views explicitly while implicit attitudes still drive quick, discriminatory actions.","lvl":2}]}]},{"week":10,"topic":"Social Psychology: Conformity, Subtle Bias and Helping","summary":"Why people conform to norms, the Stanford Prison Experiment, automatic, ambiguous and ambivalent bias, and situational and individual factors in helping.","skills":[{"id":"HPS121-10.1","name":"Contrast normative and informational social influence","summary":"You can explain why people conform, link each reason to its classic evidence and describe descriptive-norm misperception.","questions":[{"type":"case","passage":"In Asch's (1956) study, six confederates confidently choose an obviously wrong comparison line. The real participant, answering last, gives the same wrong answer while privately knowing it is incorrect.","prompt":"Why did the participant conform?","options":["Normative influence: concern about what the others would think","Informational influence: to be correct when uncertain","Obedience to the experimenter's orders","Deindividuation from wearing uniforms"],"answer":0,"explanation":"The answer was obvious, so participants knowingly conformed to fit in and avoid disapproval.","lvl":3},{"type":"case","passage":"First-year student Ollie notices the loudest drinkers at every party and assumes most students drink heavily. He starts binge drinking to match what he thinks is normal.","prompt":"What best explains Ollie's behaviour?","options":["Normative influence from an injunctive norm","Reciprocal altruism","Informational influence based on a misperceived descriptive norm","Pluralistic ignorance in an emergency"],"answer":2,"explanation":"Students overestimate peers' drinking (Borsari & Carey, 2003; Perkins et al., 2005), misreading the descriptive norm.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In Asch's study, ___% of participants conformed to the incorrect group answer at least once.","answers":["76"],"explanation":"Overall, participants conformed on about one third of trials.","lvl":5},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Normative influence","Informational influence"],"items":[{"text":"Wanting to be liked by peers","cat":0},{"text":"Wanting to be correct when uncertain","cat":1},{"text":"Avoiding exclusion or disapproval","cat":0},{"text":"Relying on descriptive norms","cat":1},{"text":"Asch line-judgement study","cat":0},{"text":"Overestimating how much peers drink","cat":1}],"explanation":"Normative is about fitting in; informational is about being right."},{"type":"mc","prompt":"What did Burger and Shelton (2011) show about descriptive norms?","options":["They cannot be changed","They only affect people high in agreeableness","Misperceptions increase helping behaviour","Giving accurate norm information can reduce excessive drinking"],"answer":3,"explanation":"Correcting norm misperceptions can be used to change health behaviour.","lvl":2},{"type":"type_answer","prompt":"What term describes the shared expectations about how group members should think, feel and behave?","answers":["social norms","norms","social norm"],"explanation":"Norms are what we actually conform to.","lvl":2}]},{"id":"HPS121-10.2","name":"Evaluate the Stanford Prison Experiment and situational power","summary":"You can explain the design, findings and critiques of the Stanford Prison Experiment and what it suggests about situations.","questions":[{"type":"mc","prompt":"Why was it important that guards and prisoners were statistically indistinguishable at the start?","options":["Later behavioural differences could be attributed to the roles and situation rather than to personality","It ensured prisoners would be docile","It allowed the study to finish early","It removed the need for random assignment"],"answer":0,"explanation":"Random assignment and equivalent groups let Zimbardo argue situation, not disposition, drove behaviour.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Deindividuation technique","Other design feature"],"items":[{"text":"Prisoners identified only by numbers","cat":0},{"text":"Guards wore reflective sunglasses","cat":0},{"text":"Identical khaki uniforms for guards","cat":0},{"text":"Random assignment to roles","cat":1},{"text":"Mock prison built in the psychology building basement","cat":1}],"explanation":"Numbers, smocks, uniforms and sunglasses stripped away individual identity."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The study was planned to run for two weeks but was terminated after just six hours.","wrong":"hours","correct":"days","explanation":"It was ended after six days because of the guards' 'sadistic' behaviour and prisoners' distress."},{"type":"case","passage":"Zimbardo, acting as the prison superintendent, later admitted he was 'startled by the ease' with which he switched off his concern for others.","prompt":"What does this admission suggest?","options":["Only the guards were affected by the situation","The study was a dispassionate scientific test","Even the researchers were pulled in by the situation and its norms","Personality fully explains cruelty"],"answer":2,"explanation":"The team became 'caught up in the passion of the present', reinforcing the claim about situational power.","lvl":2},{"type":"mc","prompt":"Which of these is a criticism of the Stanford Prison Experiment raised in the lecture?","options":["It had too many participants","Results were prone to demand characteristics, and experimenters told participants how to act","Guards were all trained police officers","It used the IAT incorrectly"],"answer":1,"explanation":"Critics also note anecdotal evidence and that not all guards were abusive.","lvl":2},{"type":"type_answer","prompt":"What term describes the loss of individual identity engineered in the study through uniforms and numbers?","answers":["deindividuation"],"explanation":"Deindividuation made it easier for participants to adopt the norms of their roles.","lvl":3}]},{"id":"HPS121-10.3","name":"Classify subtle biases as automatic, ambiguous or ambivalent","summary":"You can match each subtle bias to its theory and mechanism and place groups in the Stereotype Content Model.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Automatic (implicit) bias","Ambiguous bias","Ambivalent bias"],"items":[{"text":"Faster pairing of good words with the ingroup","cat":0},{"text":"Neglecting outgroup members rather than openly attacking them","cat":1},{"text":"Judging a group on warmth and competence","cat":2},{"text":"Measured with the IAT","cat":0},{"text":"Explained by social identity theory","cat":1},{"text":"Explained by the Stereotype Content Model","cat":2}],"explanation":"Automatic bias comes from self-categorisation, ambiguous bias from ingroup favouritism (ostracism) and ambivalent bias from warmth and competence judgements."},{"type":"match","prompt":"Match each Stereotype Content Model quadrant to its typical response.","pairs":[["High warmth, high competence","Admiration"],["High warmth, low competence","Pity or paternalism"],["Low warmth, high competence","Envy or resentment"],["Low warmth, low competence","Contempt or disgust"]],"explanation":"Fiske, Cuddy and Glick (2007): the quadrant predicts the type of discrimination a group is likely to face."},{"type":"case","passage":"A marketing team always invites only their own department to Friday lunches. They are never rude to other staff, but the other departments feel ignored and left out.","prompt":"Which kind of subtle bias does this best illustrate?","options":["Automatic bias measured by the IAT","Ambivalent bias based on competence","Overt discrimination","Ambiguous bias expressed through ostracism"],"answer":3,"explanation":"Ingroup favouritism disfavours outgroups through neglect rather than hostility, which is ostracism.","lvl":4},{"type":"mc","prompt":"On which two dimensions does the Stereotype Content Model judge groups?","options":["Openness and conscientiousness","Warmth (intentions) and competence","Power and status","Similarity and familiarity"],"answer":1,"explanation":"Warmth reflects perceived intentions; competence reflects the ability to act on them.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In-group favouritism is called an ambivalent bias because it disfavours the outgroup through neglect rather than hostility.","wrong":"ambivalent","correct":"ambiguous","explanation":"In-group favouritism is an ambiguous bias; ambivalent bias is described by the Stereotype Content Model."},{"type":"analogy","prompt":"Ambiguous bias is to ostracism as ambivalent bias is to ___","options":["warmth and competence judgements","the IAT","deindividuation","kin selection"],"answer":0,"explanation":"Ambivalent biases categorise groups along warmth and competence.","lvl":4}]},{"id":"HPS121-10.4","name":"Predict bystander helping from situational factors","summary":"You can explain pluralistic ignorance, diffusion of responsibility, level of responsibility and cost-benefit analysis in emergencies.","questions":[{"type":"case","passage":"Smoke starts seeping under a door in a crowded waiting room. Each person glances at the others, sees them sitting calmly, and concludes nothing is really wrong.","prompt":"Which factor best explains why no one acts?","options":["Diffusion of responsibility","Reciprocal altruism","Pluralistic ignorance","Kin selection"],"answer":2,"explanation":"Everyone misreads everyone else's inaction as a sign that help is not needed.","lvl":3},{"type":"case","passage":"A man collapses in a busy shopping centre. Everyone can see he needs help, but each shopper assumes someone else will call an ambulance.","prompt":"Which factor best explains the lack of helping?","options":["Diffusion of responsibility","Pluralistic ignorance","Level of responsibility","Descriptive norm misperception"],"answer":0,"explanation":"The presence of others lets people shift responsibility; this is the main mechanism behind the bystander effect.","lvl":3},{"type":"mc","prompt":"According to Fischer et al.'s (2011) meta-analysis, when is the bystander effect reduced?","options":["When the situation seems harmless","When there are more bystanders","When helping is costly in money","When the situation is perceived as dangerous, perpetrators are present and costs of intervening are physical"],"answer":3,"explanation":"The effect is not simply 'more onlookers, less help'.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Makes helping more likely","Makes helping less likely"],"items":[{"text":"Helping would take a lot of time and money","cat":1},{"text":"The bystander is a trained first aider","cat":0},{"text":"Many other onlookers are present","cat":1},{"text":"Helping brings praise and avoids guilt","cat":0},{"text":"Everyone else appears calm and inactive","cat":1},{"text":"The bystander is the manager of the person in trouble","cat":0}],"explanation":"Level of responsibility and favourable cost-benefit balance increase helping; diffusion and pluralistic ignorance reduce it."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Philpot et al. (2019) found that in nine out of ten public conflicts caught on CCTV, no bystander intervened.","wrong":"no","correct":"a","explanation":"In nine out of ten conflicts at least one bystander, usually several, did something to help."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The 1964 murder of Kitty ___ sparked bystander research, though the '38 witnesses' account was later disputed.","answers":["Genovese"],"explanation":"Later work (Benderly, 2012) claims several witnesses did call police, a reminder to think critically about famous stories.","lvl":4}]},{"id":"HPS121-10.5","name":"Explain individual differences in helping behaviour","summary":"You can explain how sex and gender, agreeableness, prosocial personality, kin selection and reciprocal altruism shape helping.","questions":[{"type":"match","prompt":"Match each individual factor to its description.","pairs":[["Kin selection","Helping genetic relatives (Hamilton, 1964)"],["Reciprocal altruism","Helping those likely to return the favour"],["Prosocial personality orientation","Other-oriented empathy plus helpfulness"],["Agreeableness","A trait marked by generosity, compassion and cooperation"]],"explanation":"These person-level factors combine with situational ones to predict helping."},{"type":"case","passage":"Nora spends a whole weekend helping her neighbour move house. She mentions she is counting on him to help when she renovates next year.","prompt":"Which explanation of helping fits best?","options":["Kin selection","Diffusion of responsibility","Reciprocal altruism","Pluralistic ignorance"],"answer":2,"explanation":"Reciprocal altruism holds that we help more when we expect the help to be returned.","lvl":2},{"type":"mc","prompt":"What does the unit say about sex and gender differences in helping?","options":["Overall helping is similar, but the type of helping differs because of different risks and gender roles","Women help far more than men overall","Men help far more than women overall","Gender has no influence on helping"],"answer":0,"explanation":"Cost-benefit analyses differ with risk, and people help in ways that align with their gender roles.","lvl":3},{"type":"type_answer","prompt":"The prosocial personality orientation has two components: other-oriented empathy and what?","answers":["helpfulness"],"explanation":"Helpfulness refers to a personal history of helping behaviours (Penner et al., 1995).","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Female gender roles tend to emphasise physical strength and chivalry.","wrong":"Female","correct":"Male","explanation":"Male gender roles emphasise physical strength and chivalry; female roles emphasise compassion and nurturing."},{"type":"case","passage":"During a flood, Ravi wades out to rescue his cousin from a stranded car but hesitates to do the same for a stranger in a similar car nearby.","prompt":"Which evolutionary explanation fits Ravi's behaviour?","options":["Reciprocal altruism","Agreeableness","Level of responsibility","Kin selection"],"answer":3,"explanation":"Kin selection suggests we help genetic relatives more, which helps pass on shared genetic material.","lvl":2}]}]},{"week":11,"topic":"Indigenous and Cross-cultural Psychology","summary":"Defining cross-cultural and Indigenous psychology, the history and impact of colonisation, Indigenous health and wellbeing, and levels of racism.","skills":[{"id":"HPS121-11.1","name":"Distinguish cross-cultural psychology from Indigenous psychology","summary":"You can define both fields, explain how their methods differ and critique applying Western tools across cultures.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Cross-cultural psychology","Indigenous psychology"],"items":[{"text":"Aims to test the generalisability of theories across cultures","cat":0},{"text":"Tends to rely on Western methodological approaches","cat":0},{"text":"Emphasises local development and application of psychology","cat":1},{"text":"Requires consultation with local community leaders","cat":1},{"text":"Examines concepts with no English equivalent, such as Country","cat":1},{"text":"Compares behaviour across different cultural contexts","cat":0}],"explanation":"Both study culture's influence on behaviour, but Indigenous psychology uses locally relevant methods and interpretation."},{"type":"mc","prompt":"Why must Indigenous psychology research teams consult with local community leaders?","options":["To obtain funding","So methods and interpretations are culturally relevant and locally meaningful concepts can be examined","To translate Western questionnaires word for word","Because ethics committees require one meeting"],"answer":1,"explanation":"Consultation lets researchers examine concepts that matter locally and may have no Western equivalent.","lvl":1},{"type":"case","passage":"A researcher administers an English-only personality questionnaire developed in the United States to a remote community and concludes the community scores 'low' on a trait.","prompt":"What is the strongest critique of this conclusion?","options":["The sample was too large","Personality cannot be measured at all","The tool was not designed with this culture in mind, so the result may not reflect true functioning","Only ethnography can use questionnaires"],"answer":2,"explanation":"Many tools and norms were built on narrow populations and are not always applicable across cultures or languages.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"One main aim of cross-cultural psychology is to understand the ___ of theories about human behaviour.","answers":["generalisability","generalizability"],"explanation":"It asks whether a theory built in one cultural context holds in others.","lvl":3},{"type":"type_answer","prompt":"Which Japanese concept, cited as having no English equivalent, refers to a form of emotional dependence on others?","answers":["amae"],"explanation":"Amae and Country (for First Nations Australians) show why locally relevant concepts matter.","lvl":5},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Much psychological literature has focused on Anglo-Saxon, English-speaking communities, resulting in the historical inclusion of other cultural groups.","wrong":"inclusion","correct":"exclusion","explanation":"The narrow focus resulted in the historical exclusion of people from other cultural groups."}]},{"id":"HPS121-11.2","name":"Explain culture-general processes and ethnographic methods","summary":"You can separate culture-general from culture-specific aspects of emotion and explain why ethnography suits cultural research.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Culture-general","Culture-specific"],"items":[{"text":"Recognising emotions from facial expressions","cat":0},{"text":"Rules about when it is appropriate to show anger","cat":1},{"text":"Expression of at least some basic emotions","cat":0},{"text":"Japanese participants deeming happiness displays appropriate less often than Canadians","cat":1},{"text":"Cultural display rules","cat":1}],"explanation":"Experiencing and recognising some emotions looks culture-general, while display rules are culture-specific."},{"type":"case","passage":"A researcher lives in a coastal community for 18 months, joins daily activities and holds conversational, open-ended interviews in people's homes and workplaces.","prompt":"Which research method is this?","options":["Laboratory experiment","Implicit Association Test","Randomised controlled trial","Ethnography"],"answer":3,"explanation":"Ethnography is an immersive qualitative method giving an insider perspective through observation and natural-setting interviews.","lvl":1},{"type":"mc","prompt":"Why is ethnography described as crucial in cross-cultural and Indigenous psychology?","options":["It challenges the assumption that Western theories are universal and foregrounds lived experience","It produces the fastest results","It removes the researcher's influence entirely","It relies on external expert perspectives"],"answer":0,"explanation":"It aligns with community-based ways of knowing and shifts focus away from external 'expert' views.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Ethnography is a quantitative research method that immerses the researcher in a culture for extended periods.","wrong":"quantitative","correct":"qualitative","explanation":"Ethnography is qualitative, using observation and less structured interviews."},{"type":"match","prompt":"Match each figure to what it describes about Australia's diversity.","pairs":[["3.8%","Aboriginal and Torres Strait Islander share of the population"],["Over 250","Countries of birth"],["Over 400","Languages spoken"],["8.3%","Share of the Indigenous population identifying as Torres Strait Islander or both"]],"explanation":"ABS (2021) data highlight how diverse Australia is, raising questions about theories built on narrow samples."},{"type":"analogy","prompt":"Emotion recognition is to culture-general as emotional display rules are to ___","options":["universal","ethnographic","culture-specific","implicit"],"answer":2,"explanation":"Norms about when to show emotion vary across cultures (Matsumoto et al., 2008).","lvl":3}]},{"id":"HPS121-11.3","name":"Sequence key events and policies of colonisation in Australia","summary":"You can order key events, describe population impacts, name protection legislation and explain the Stolen Generations.","questions":[{"type":"order","prompt":"Put these events in chronological order.","items":["British arrival","The 'Coming of the Light' in the Torres Strait","Annexation of the Torres Strait to Queensland","Federation and the White Australia policy","The Commonwealth Referendum"],"explanation":"1788, 1871, 1879, 1901 and 1967."},{"type":"mc","prompt":"How did the Aboriginal population change after colonisation?","options":["It remained stable until 1967","It grew because of new trade","It fell from about 75,000 to 30,000 by 1900","It fell from between 300,000 and 950,000 to an estimated 75,000 by 1900"],"answer":3,"explanation":"Violence, introduced disease such as smallpox and dispossession caused a dramatic decline.","lvl":4},{"type":"case","passage":"As land and food sources were destroyed, many Aboriginal people offered labour at European settlements through kinship-based systems, expecting goods for the whole group. Settlers treated it as an individual exchange.","prompt":"What does this episode illustrate?","options":["Aboriginal people rejected all contact","A clash between kinship-based reciprocal systems and European individual exchange","The success of protection legislation","The Mabo decision"],"answer":1,"explanation":"The misunderstanding reflects how Aboriginal society was organised through kinship and group obligations.","lvl":3},{"type":"match","prompt":"Match each piece of legislation to its jurisdiction.","pairs":[["Aborigines Act 1869","Victoria"],["Aborigines Protection Act 1909","New South Wales"],["Aboriginals Protection and Restriction of the Sale of Opium Act 1897","Queensland"],["Cape Barren Island Act 1912","Tasmania"]],"explanation":"These 'protection' laws enabled child removal, surveillance and cultural suppression."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"An estimated one in ___ First Nations children were forcibly removed from their families in the first half of the twentieth century.","answers":["ten","10"],"explanation":"Few families escaped the effects of the Stolen Generations (Dudgeon et al., 2014).","lvl":5},{"type":"type_answer","prompt":"Which 1997 Australian Human Rights Commission report documented the experiences of the Stolen Generations?","answers":["Bringing Them Home","Bringing Them Home Report","the Bringing Them Home report"],"explanation":"The Bringing Them Home Report (1997) documented forced removal and its effects.","lvl":4}]},{"id":"HPS121-11.4","name":"Describe Indigenous health and wellbeing disadvantage and its causes","summary":"You can describe areas of disadvantage, recognise Torres Strait Islander-specific challenges and link outcomes to colonisation.","questions":[{"type":"mc","prompt":"According to Dudgeon et al. (2014), what lies at the core of the disadvantages experienced by Aboriginal and Torres Strait Islander peoples?","options":["Individual lifestyle choices","Geographic remoteness alone","Colonial exploitation and prolonged, systematic attempts to destroy peoples and culture","A lack of interest in education"],"answer":2,"explanation":"Colonisation is the root cause; several outcomes are also linked to mental health.","lvl":2},{"type":"case","passage":"Moana, a Torres Strait Islander woman, seeks support in a mainland city. An Aboriginal service tells her it is not for her, and a mainstream service knows nothing about her culture.","prompt":"Which challenge from the unit does this illustrate?","options":["Torres Strait Islander people are often not recognised as a distinct cultural group","Torres Strait Islander people have better access than others","Cultural renewal has been completed","Ethnography has replaced mainstream services"],"answer":0,"explanation":"Torres Strait Islander people can be excluded from Aboriginal services while met with ignorance from non-Aboriginal Australia.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In 2008, only ___% of Aboriginal students received a year 12 certificate.","answers":["25"],"explanation":"Year 12 completion is now about 50%, still 30% lower than for other students.","lvl":5},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Torres Strait Islander people complete year 12 at lower rates than Aboriginal people.","wrong":"lower","correct":"higher","explanation":"Torres Strait Islander people complete year 12 at higher rates than Aboriginal people, but lower than non-Aboriginal people."},{"type":"match","prompt":"Match each statistic to the outcome it describes.","pairs":[["50%","Aboriginal students completing year 12"],["71%","Aboriginal homicides where victim and offender had consumed alcohol"],["20%","Gap in employment rates"]],"explanation":"These figures come from Dudgeon et al. (2014)."},{"type":"case","passage":"A clinician attributes an Aboriginal client's job insecurity, unstable housing and distress entirely to the client's personal motivation.","prompt":"What does the unit suggest the clinician is missing?","options":["That motivation is the main cause of disadvantage","That housing is unrelated to mental health","That employment has no link to wellbeing","The impacts of colonisation, and links between employment, housing and mental health"],"answer":3,"explanation":"Psychologists must understand colonisation; precarious employment and housing are linked to mental health.","lvl":1}]},{"id":"HPS121-11.5","name":"Classify individual, institutional and cultural racism","summary":"You can classify examples by level of racism, describe its effects and cite evidence of its prevalence.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Individual racism","Institutional racism","Cultural racism"],"items":[{"text":"A shopkeeper follows an Aboriginal teenager around because of her appearance","cat":0},{"text":"A service policy that ignores cultural values, producing unequal outcomes without racist intent","cat":1},{"text":"Public discourse blaming Aboriginal peoples for the disadvantage they experience","cat":2},{"text":"A person believes some races are intellectually inferior","cat":0},{"text":"School rules that systematically disadvantage remote communities","cat":1},{"text":"'Common sense' claims that Aboriginal people get special treatment","cat":2}],"explanation":"Individual racism is personal belief and action, institutional racism works through laws and policies, and cultural racism is embedded in everyday assumptions."},{"type":"case","passage":"A hospital requires all patients to attend alone and complete English-only forms. No staff member intends harm, but Aboriginal patients consistently receive poorer care because family involvement and language needs are ignored.","prompt":"Which type of racism is this?","options":["Individual racism","Cultural racism","Institutional racism","Internalised racism"],"answer":2,"explanation":"Institutional racism occurs through policies and practices that systematically disadvantage groups, even without racist intent.","lvl":2},{"type":"mc","prompt":"Which of the following is listed as an effect of racism on marginalised groups?","options":["Increased trust in the dominant culture","Mistrust of the dominant culture","Higher self-esteem","Reduced internalised racism"],"answer":1,"explanation":"Effects include reduced self-esteem, mistrust of the dominant culture and internalised racism.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In Ferdinand et al. (2013), ___% of Aboriginal respondents reported at least one experience of racism in the past 12 months.","answers":["97"],"explanation":"Most also anticipated racism and avoided situations because of it.","lvl":5},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Individual racism can be overt but is increasingly obvious, making it harder to detect and challenge.","wrong":"obvious","correct":"covert","explanation":"Individual racism is increasingly subtle and covert, which makes it harder to detect, challenge and cope with."},{"type":"type_answer","prompt":"Pedersen et al. (2006) identified a common misconception that Aboriginal peoples receive what from the government?","answers":["special treatment"],"explanation":"This misconception perpetuates negative stereotypes and is an example of cultural racism.","lvl":4}]}]}]};
window.LAMPLIGHT_UNITS["HPS105"] = {"code":"HPS105","name":"Foundations of Psychological Practice","term":"T2 2026","weeks":11,"weekList":[{"week":1,"topic":"Psychology Then and Now","summary":"How psychology grew from philosophy, religion and medicine into a regulated Australian profession, and the lenses used to view it.","skills":[{"id":"HPS105-1.1","name":"Trace the philosophical and scientific roots of psychology","summary":"Links each historical tradition and era to what it contributed to modern psychology and its blind spots.","questions":[{"type":"match","prompt":"Match each tradition to its contribution to modern psychology.","pairs":[["Plato","Inner conflict between reason, spirited emotion and appetite"],["Aristotle","Functional view of mind and habit shaping character"],["Stoics","Emotions arise from judgements about events, not events themselves"],["Early medicine","Distress has natural, observable, treatable causes"]],"explanation":"Plato anticipates self-regulation, Aristotle connects to learning and behaviour change, the Stoics offer an early cognitive approach, and early medicine argued for care rather than blame."},{"type":"order","prompt":"Put these developments in order from earliest to most recent.","items":["Wundt-era laboratories and measurement of reaction time","Competing schools such as structuralism and behaviourism","Post-war growth of clinical psychology and behaviour therapy","The cognitive revolution and integration with neuroscience","Replication and open-science reform"],"explanation":"Psychology became a distinct science in the mid to late 1800s, split into competing schools in the early 1900s, grew post-war, underwent the cognitive revolution from the 1950s, and recently turned to open-science reform."},{"type":"mc","prompt":"Which idea from the Enlightenment is described in the notes as a blind spot psychology still confronts?","options":["The myth of the purely rational individual","Careful measurement and transparent methods","Normalising organised care","Treating the person as capable of agency and choice"],"answer":0,"explanation":"The Enlightenment gave psychology its expectations of measurement and testing, but the myth of the purely rational individual is listed as a blind spot, alongside quantification sidelining meaning and universalism.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The Stoics argued that emotions arise directly from events rather than from our interpretations of them.","wrong":"events","correct":"interpretations","explanation":"The Stoics taught that emotions come from judgements and interpretations, so you pause and examine an impression. This is why they are seen as an early cognitive approach."},{"type":"case","passage":"A tutor argues that because diagnosis and standardisation are 'tools of care', they can only ever help clients.","prompt":"Which Module 1 point best challenges this claim?","options":["Standardised tools were rejected during the cognitive revolution","Diagnosis belongs to psychiatry, not psychology","Tools of care can also cause stigma, exclusion and control if not guided by justice, respect and humility","Standardisation is a product of post-war funding, so it is outdated"],"answer":2,"explanation":"The notes list classification, diagnosis and standardisation as tools of care that can also cause stigma, exclusion and control. Justice, respect and humility are needed to guide them.","lvl":3},{"type":"type_answer","prompt":"What was the key tension at the heart of psychology: is human experience best understood as meaning and interpretation, or as mechanism and ___?","answers":["measurement"],"explanation":"Psychology's enduring tension is between meaning and interpretation versus mechanism and measurement, and the discipline tries to synthesise both.","lvl":3}]},{"id":"HPS105-1.2","name":"Map the Australian pathways to psychologist registration","summary":"Describes each stage and pathway to general registration and area of practice endorsement in Australia.","questions":[{"type":"order","prompt":"Put the stages of the higher-degree pathway in order, from first to last.","items":["Three-year accredited bachelor sequence","Fourth 'screening' year (Honours or Graduate Diploma)","Master of Professional Psychology coursework year","Internship year leading to general registration"],"explanation":"The minimum six-year sequence is a three-year bachelor, a fourth screening year, then a postgraduate degree such as the Master of Professional Psychology (one year coursework plus one year internship)."},{"type":"mc","prompt":"Which pathway closed to new applicants on 30 June 2022?","options":["The Graduate Diploma fourth year","The Doctor of Psychology pathway","The 5+1 internship pathway","The 4+2 internship pathway"],"answer":3,"explanation":"The 4+2 internship pathway closed on 30 June 2022 and was replaced by the 5+1 pathway for consistent training and placement quality.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Before applying for general registration through the 5+1 pathway, you must pass the national psychology ___.","answers":["exam","examination"],"explanation":"The 5+1 internship pathway requires passing the national psychology exam before applying for general registration.","lvl":2},{"type":"case","passage":"Jess is a generally registered psychologist who works mostly with young offenders but has not completed an Area of Practice Endorsement.","prompt":"Which statement about Jess is accurate?","options":["She needs a Doctor of Psychology to keep practising","She is a provisional psychologist until she is endorsed","She must stop forensic work until she is endorsed","She can practise in forensic settings but cannot use the specialist title 'forensic psychologist'"],"answer":3,"explanation":"A general psychologist can practise in specialist areas without the specialist title. An AoPE requires an additional year of supervised practice to gain the title.","lvl":3},{"type":"match","prompt":"Match each fourth-year option or postgraduate stage to its typical entry requirement.","pairs":[["Fourth-year sequence","Around H2A or WAM 70 plus interpersonal skills"],["Master of Psychology (Clinical)","H1 fourth-year outcome, minimum WAM 80"],["Doctor of Psychology (Clinical)","H1 plus research experience such as a thesis or publication"]],"explanation":"Entry is grade-competitive at each stage, and the Doctor of Psychology adds research experience to the H1 requirement."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Honours and the Graduate Diploma are the same fourth-year course, but the Honours year is the dearer option.","wrong":"dearer","correct":"cheaper","explanation":"It is the other way around: Honours is a Commonwealth-supported place and the Graduate Diploma is full fee. Entry to each usually depends on grades."}]},{"id":"HPS105-1.3","name":"Distinguish psychologists from related professions","summary":"Explains how psychologists differ from counsellors and social workers and what clinical, organisational and forensic psychologists do.","questions":[{"type":"case","passage":"A hospital job advertisement says it will accept either a psychologist or a social worker for the same role.","prompt":"According to the lecture, how do the two disciplines differ in perspective?","options":["Social workers diagnose, psychologists refer","Psychologists focus on systems, social workers on the individual","Psychologists take an individualistic mind-body perspective, social workers a sociological systems perspective","They are trained identically but regulated by different boards"],"answer":2,"explanation":"Psychologists work from a more individualistic, mind-body perspective, while social workers look at the systems people operate within. They are complementary and often work side by side.","lvl":3},{"type":"mc","prompt":"What most distinguishes the psychological pathway from counselling training?","options":["Counselling uses no evidence-based approaches at all","Psychology places heavier emphasis on research training and evidence-based assessment, diagnosis and intervention","Counsellors work only with groups","Psychology training has fewer placement hours"],"answer":1,"explanation":"Counselling still uses evidence-based approaches, but the scientist-practitioner pathway emphasises research training and evidence-based assessment, diagnosis and intervention more heavily.","lvl":2},{"type":"match","prompt":"Match each type of psychologist to its focus.","pairs":[["Clinical","Assess, diagnose and treat mental health problems from mild to severe"],["Organisational","Employee wellbeing, productivity, training and leadership coaching"],["Forensic","Psychosocial rehabilitation of offenders to reduce recidivism"]],"explanation":"These are three common APS specialisations; forensic work also balances the justice system as primary client and the offender as secondary client."},{"type":"type_answer","prompt":"In forensic psychology, the justice system is the primary client. Who is the secondary client?","answers":["the offender","offender"],"explanation":"Forensic psychologists balance obligations to the justice system (primary client) and the offender (secondary client).","lvl":4},{"type":"analogy","prompt":"Psychologist is to the individual as social worker is to ___","options":["the medication","the diagnosis","the system","the family doctor"],"answer":2,"explanation":"Psychologists focus on the individual and mind-body connection, while social workers focus on the broader systems that influence people.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The APS recognises general psychologists plus five College specialisations.","wrong":"five","correct":"nine","explanation":"The APS recognises general psychologists plus nine College specialisations, aligned with the Areas of Practice Endorsement."}]},{"id":"HPS105-1.4","name":"Apply the science, health and critical lenses to psychology","summary":"Identifies the values of the science and allied-health lenses and uses critical questions to examine claims.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Science lens","Allied-health lens"],"items":[{"text":"Empiricism: things can be measured and known through the senses","cat":0},{"text":"Scepticism and falsifiability","cat":0},{"text":"Beneficence and non-maleficence","cat":1},{"text":"Respect for human dignity and accreditation standards","cat":1},{"text":"Objectivity: there are facts that can be distinguished","cat":0},{"text":"Professional collaboration","cat":1}],"explanation":"The science lens values objectivity, empiricism, progress, humanism and scepticism. The health lens values doing good, doing no harm, respect and collaboration."},{"type":"mc","prompt":"Which statement best describes what a critical lens does NOT mean?","options":["Asking whose experiences a claim reflects or misses","Holding complexity: a finding can be useful and incomplete","Separating evidence from assumption","Rejecting psychology as a science"],"answer":3,"explanation":"A critical lens does not reject psychology as a science. It separates evidence from assumption and notices the limits of any single explanation.","lvl":3},{"type":"case","passage":"A marketing student learns persuasion techniques in class and plans to use them to push high-interest loans on vulnerable customers.","prompt":"Which Week 1 idea is most relevant to this plan?","options":["General psychologists can work without an AoPE","The 5+1 pathway requires an exam","Psychological knowledge is a tool, and how you use it (to help or to control) matters","Psychology split into competing schools in the early 1900s"],"answer":2,"explanation":"The lecture's 'dark arts' discussion stresses that psychological knowledge can help or control and exploit, so each person must decide what values guide its use.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The allied-health values of 'do good' and 'do no harm' are called beneficence and ___.","answers":["non-maleficence","nonmaleficence"],"explanation":"Beneficence means benefiting others and non-maleficence means avoiding harm; both sit within the health lens.","lvl":3},{"type":"match","prompt":"Match each critical-lens question to what it examines.","pairs":[["What does it assume is normal or good?","Built-in values"],["Who says it is true, and who benefits?","Authority and interests"],["Whose experiences does it miss?","Representation and exclusion"]],"explanation":"The critical lens asks where a claim came from, what it assumes, who benefits and whose experiences it reflects or misses."},{"type":"analogy","prompt":"Science lens is to empiricism as health lens is to ___","options":["objectivity","quantification","beneficence","falsifiability"],"answer":2,"explanation":"Empiricism is a core value of the science lens, just as beneficence is a core value of the allied-health lens.","lvl":3}]}]},{"week":2,"topic":"The Scientist-Practitioner Model and Gap","summary":"How the scientist-practitioner model integrates research and practice, why a gap opens between them, and how it is bridged.","skills":[{"id":"HPS105-2.1","name":"Describe the roles of the scientist-practitioner model","summary":"Explains the model's origins and identifies the researcher, consumer and evaluator roles in practice.","questions":[{"type":"match","prompt":"Match each scientist-practitioner role to what it involves.","pairs":[["Researcher","Conducting or contributing to research and sharing findings"],["Consumer of research","Staying current and translating research into decisions"],["Evaluator","Monitoring outcomes and refining practice"]],"explanation":"The three integrated roles are knowledge contributor, knowledge user and quality assurer."},{"type":"mc","prompt":"The scientist-practitioner model is also known as the Boulder Model. What drove its 1949 development?","options":["The need to regulate pastoral care workers","The need to treat the mental health of WWI and WWII veterans","The closure of the 4+2 pathway","The rise of psychoanalysis in universities"],"answer":1,"explanation":"The Boulder conference, sponsored by the US Veterans Administration and NIMH, was driven by veterans' mental health needs and let psychology become an evidence-based profession distinct from psychiatry and pastoral care.","lvl":3},{"type":"case","passage":"After each block of sessions, Dr Lee compares clients' outcome scores with their baselines and changes her approach when progress stalls.","prompt":"Which scientist-practitioner role is Dr Lee mainly performing?","options":["Researcher","Consumer of research","Evaluator","Pastoral carer"],"answer":2,"explanation":"Monitoring outcomes, checking whether approaches work and refining practice is the evaluator (quality assurer) role.","lvl":2},{"type":"type_answer","prompt":"Undergraduate students learn to interpret literature and become discerning ___ of evidence.","answers":["consumers","consumer"],"explanation":"Training begins in undergraduate study, where students become discerning consumers of evidence before deepening skills in fourth year and postgraduate study.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Skill grows through conceptual learning, where experience helps you notice meaningful differences that once looked the same.","wrong":"conceptual","correct":"perceptual","explanation":"The notes describe perceptual learning, like learning to taste wine: knowledge and experience let you notice differences you could not see before."},{"type":"analogy","prompt":"Researcher is to knowledge contributor as evaluator is to ___","options":["grant reviewer","quality assurer","pastoral carer","knowledge user"],"answer":1,"explanation":"The researcher contributes knowledge, the consumer uses it, and the evaluator assures quality by monitoring outcomes.","lvl":3}]},{"id":"HPS105-2.2","name":"Explain the causes of the scientist-practitioner gap","summary":"Identifies the six causes of the gap and the biases scientific thinking guards against.","questions":[{"type":"case","passage":"A trial shows a therapy reduces depression scores by a statistically significant two points on average, but a client notices no change in daily life.","prompt":"Which cause of the gap does this illustrate?","options":["Competing ideas about evidence","Dual-role pressures","Statistical versus clinical significance","Practical barriers to research in practice"],"answer":2,"explanation":"An effect can be statistically significant without meaningfully changing a client's life, which is the statistical versus clinical significance problem.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Cause of the gap","Not a cause of the gap"],"items":[{"text":"Research asks what helps on average; practice asks what helps this person now","cat":0},{"text":"Group averages hide who benefits and why","cat":0},{"text":"Practice cannot control away housing stress or discrimination","cat":0},{"text":"Clinicians are simply lazy about reading research","cat":1},{"text":"Time, funding and infrastructure limits in services","cat":0},{"text":"Researchers deliberately hide their findings from clinicians","cat":1}],"explanation":"The six causes are different goals, competing ideas about evidence, practical barriers, statistical versus clinical significance, the average client problem, and controlled conditions versus complex lives. The notes stress these are structural, not personal failings."},{"type":"mc","prompt":"According to the notes, neither research nor practice is 'wrong' in the gap. Why?","options":["The gap has been closed by accreditation","Practice is always more accurate than research","Both sides use identical methods","They face different conditions, constraints and incentives"],"answer":3,"explanation":"The gap is an ongoing disconnect because research and practice face different conditions, constraints and incentives, not because either side is at fault.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Scientific thinking is described as a ___ against biases such as confirmation bias and persuasion by anecdotes.","answers":["safeguard"],"explanation":"Lilienfeld and colleagues (2012) describe scientific thinking as a safeguard against reasoning errors like confirmation bias, causal oversimplification and overconfidence.","lvl":3},{"type":"analogy","prompt":"Research is to 'on average, does this help?' as practice is to ___","options":["'what is the effect size?'","'what does the journal accept?'","'what will help this person now?'","'is the sample random?'"],"answer":2,"explanation":"Different goals drive the gap: research asks about average effects under set conditions, while practice asks what will help this person now given their history and preferences.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The less practice is constrained by evidence and bias-awareness, the lower the risk of harm to clients.","wrong":"lower","correct":"greater","explanation":"Less constraint by evidence means greater risk of harm, as shown in the 'memory recovery' controversies."}]},{"id":"HPS105-2.3","name":"Match bridging strategies to the gap they address","summary":"Identifies the six systemic strategies for bridging the gap and how each works.","questions":[{"type":"match","prompt":"Match each bridging strategy to how it works.","pairs":[["Accredited training (APAC)","Teaches levels of evidence, effect sizes and cognitive biases"],["Registration standards and codes","Non-evidence-based practice can bring conditions or suspension"],["Practice-guidance resources","Evidence summaries and graded clinical guidelines"],["Implementation science","Makes efficacious treatments usable in the real world"]],"explanation":"The six strategies also include practice-based evidence in services and professional collaboration."},{"type":"order","prompt":"Put the steps of Routine Outcome Monitoring in order.","items":["Observe","Hypothesis","Intervene","Evaluate","Adjust"],"explanation":"Routine Outcome Monitoring follows Observe, Hypothesis, Intervene, Evaluate, Adjust, building practice-based evidence in services."},{"type":"case","passage":"A service finds a trauma therapy works well in trials but staff cannot deliver it because sessions are too long for their funding model. Researchers and managers work together to adapt delivery.","prompt":"Which bridging strategy is this?","options":["Routine Outcome Monitoring","Accredited training","Implementation science","Registration standards"],"answer":2,"explanation":"Implementation science makes treatments not just efficacious in trials but usable in the real world, addressing the implementation gap.","lvl":3},{"type":"type_answer","prompt":"What is the name for the ongoing learning registered psychologists complete to keep their knowledge current (give the abbreviation or full term)?","answers":["CPD","continuing professional development"],"explanation":"Continuing Professional Development keeps knowledge current and supports reflective practice, as part of registration standards.","lvl":3},{"type":"mc","prompt":"Which bridging strategy includes placement supervision, communities of practice and practitioner-researcher partnerships?","options":["Practice-guidance resources","Implementation science","Accredited training","Professional collaboration"],"answer":3,"explanation":"Professional collaboration bridges the gap through supervision tied to evidence, communities of practice and partnerships between practitioners and researchers.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Routine Outcome Monitoring is an example of practice-based ___ in services.","answers":["evidence"],"explanation":"Practice-based evidence in services includes Routine Outcome Monitoring, de-identified case reports and service evaluations.","lvl":4}]},{"id":"HPS105-2.4","name":"Apply ontology, epistemology and the hypothetico-deductive model","summary":"Defines ontology and epistemology, operationalises constructs and applies the seven hypothetico-deductive steps.","questions":[{"type":"analogy","prompt":"Ontology is to what is real as epistemology is to ___","options":["how we can know it","what is ethical","what is measurable in dollars","who funds research"],"answer":0,"explanation":"Ontology concerns what exists; epistemology concerns how we can know it. Together they shape what counts as evidence.","lvl":2},{"type":"order","prompt":"Put these hypothetico-deductive steps in order.","items":["Observe and define the phenomenon","Generate multiple explanations across levels","Form a testable, falsifiable hypothesis","Gather evidence systematically","Consider disconfirmation"],"explanation":"The first five of the seven steps run from observing to seeking disconfirming evidence; revising and then accumulating and replicating follow."},{"type":"case","passage":"A clinician wants to know whether a client's 'anxiety' is improving, so she tracks self-reported worry, avoidance behaviours and sleep disruption each week.","prompt":"What process is she using?","options":["Operationalisation","Replication","Universalism","Falsification"],"answer":0,"explanation":"Operationalisation defines an internal construct through measurable indicators, answering 'How would we know this is present, changing or improving?'","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The scientific method pairs realism with rationalism to support claims that are testable, measurable and replicable.","wrong":"rationalism","correct":"empiricism","explanation":"Psychology pairs realism (ontology) with empiricism (epistemology), building knowledge from systematic observation and measurement."},{"type":"mc","prompt":"Why is seeking evidence that could prove your hypothesis wrong described as a strength?","options":["It guarantees the hypothesis is true","It guards against confirmation bias and makes practice safer","It replaces clinical judgement","It removes the need for replication"],"answer":1,"explanation":"Considering disconfirmation protects against bias, and revising when evidence does not fit makes practice safer.","lvl":2},{"type":"case","passage":"A 'bioenergy' practitioner uses scientific jargon and client testimonials to promote a treatment. Clients report feeling better after six weeks.","prompt":"Which explanation from the notes should a scientist-practitioner consider before crediting the treatment?","options":["Testimonials are a form of replication","Improvement may be due to time, placebo, regression to the mean or interpersonal kindness","Feeling better proves the ontology is correct","Jargon shows the method is falsifiable"],"answer":1,"explanation":"Pseudoscience imitates jargon and relies on selective stories, and mental-health improvements can come from time, placebo, regression to the mean, life changes or kindness rather than the treatment.","lvl":3}]}]},{"week":3,"topic":"Ethics and Dilemmas","summary":"How to reason about what is good, apply the PsyBA Code of Conduct, resolve ethical dilemmas and understand the consequences of unethical conduct.","skills":[{"id":"HPS105-3.1","name":"Distinguish consequentialist, deontological and virtue ethics","summary":"Classifies ethical reasoning by framework and separates morals, ethics and law.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Consequentialist","Duty-based (deontological)","Virtue ethics"],"items":[{"text":"Choosing the option that produces the greatest good for the greatest number","cat":0},{"text":"Reporting child abuse because it is mandatory, whatever the outcome","cat":1},{"text":"Acting with courage, humility and compassion until it becomes character","cat":2},{"text":"Asking 'what is the best outcome for me?'","cat":0},{"text":"Keeping a rule even when breaking it might feel kinder","cat":1},{"text":"Practising patience and integrity consciously and repeatedly","cat":2}],"explanation":"Consequentialism judges outcomes (utilitarianism, ethical egoism), deontology focuses on duties and rules, and virtue ethics focuses on traits of moral character."},{"type":"match","prompt":"Match each concept to its definition.","pairs":[["Morals","Society-level principles of right and wrong, often felt as gut feelings"],["Ethics","An individual's choice about how conduct reflects their morals"],["Law","A formalised, enforceable contract from a legitimate authority"]],"explanation":"Something can be legal but feel immoral, or moral but not legally enforceable."},{"type":"type_answer","prompt":"What term describes using a mixture of ethical approaches, with one fitting better in some situations and a combination needed for complex problems?","answers":["ethical pluralism","pluralism"],"explanation":"Ethical pluralism recognises multiple valid approaches; because we are emotional and error-prone, this helps us reason transparently rather than assuming pure objectivity.","lvl":4},{"type":"case","passage":"A psychologist realises that keeping a client's disclosure confidential may leave the client at risk of harm, yet protecting clients from harm is also a duty.","prompt":"Which weakness of duty-based ethics does this show?","options":["It ignores rules","It has no clear rules to follow","Duties can conflict","It only considers outcomes for the self"],"answer":2,"explanation":"Deontology is conceptually easy to follow, but duties such as confidentiality and protecting a client from harm can conflict.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Utilitarianism is a form of virtue ethics that seeks the greatest good for the greatest number.","wrong":"virtue","correct":"consequentialist","explanation":"Utilitarianism is consequentialist: it judges actions by their outcomes. Virtue ethics focuses on character."},{"type":"analogy","prompt":"Utilitarianism is to consequentialist ethics as mandatory reporting is to ___","options":["ethical egoism","duty-based ethics","ethical pluralism","virtue ethics"],"answer":1,"explanation":"Mandatory reporting is the notes' example of a duty-based obligation that applies regardless of consequences.","lvl":4}]},{"id":"HPS105-3.2","name":"Identify principles of the PsyBA Code of Conduct","summary":"Recognises the Code's purpose, its 11 principles and the client groups and contexts its guidelines cover.","questions":[{"type":"mc","prompt":"How many principles is the Code of Conduct for Psychologists (PsyBA, 2025) organised around?","options":["Eleven","Eight","Five","Fifteen"],"answer":0,"explanation":"The Code is organised around 11 principles, each stated as imperatives with several sub-principles.","lvl":4},{"type":"match","prompt":"Match each Code principle number to its focus.","pairs":[["Principle 2","Aboriginal and Torres Strait Islander health and cultural safety"],["Principle 7","Client safety and managing risk"],["Principle 9","Health and wellbeing of yourself and other practitioners"],["Principle 11","Ethical, evidence-based research"]],"explanation":"Principle 2 is cultural safety as determined by First Nations people, 7 covers risk, 9 covers practitioner wellbeing and 11 covers research."},{"type":"case","passage":"A psychologist's accurate record keeping and honest financial arrangements are questioned by a client.","prompt":"Which Code principle most directly covers these behaviours?","options":["Principle 8: a standard of practice and behaviour that warrants trust","Principle 6: effectiveness of systems","Principle 5: collaboration with colleagues","Principle 10: teaching and supervising"],"answer":0,"explanation":"Principle 8 covers Board standards, accurate records and honest financial arrangements that warrant community and peer trust.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Cultural safety under Principle 2 is determined by Aboriginal and Torres Strait Islander individuals, families and ___.","answers":["communities","community"],"explanation":"Cultural safety is defined by the recipients of care, not by the practitioner.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Client group guideline","Practice context or issue guideline"],"items":[{"text":"Clients at risk of suicide","cat":0},{"text":"Older adults","cat":0},{"text":"Telehealth and digital communication","cat":1},{"text":"Record keeping","cat":1},{"text":"Children and young people","cat":0},{"text":"Rural and remote practice","cat":1}],"explanation":"The Code's Professional Guidelines cover client groups, particular contexts, and practice-specific issues where ethical compromise is most likely."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The Code's Preamble sets conduct standards across all roles where psychological knowledge is used, to protect the public and maintain profits.","wrong":"profits","correct":"trust","explanation":"The Preamble sets conduct standards across all roles where psychological knowledge is used, not only therapy."}]},{"id":"HPS105-3.3","name":"Apply the ethical decision-making framework to a dilemma","summary":"Recognises when directives conflict and works through the Shaw et al. (2012) steps to a defensible decision.","questions":[{"type":"order","prompt":"Put the steps of the ethical decision-making framework (Shaw et al., 2012) in order.","items":["Recognise the ethical issue","Clarify the ethical issues","Generate and examine options","Choose and implement the preferred option","Reflect and review"],"explanation":"The framework moves from noticing discomfort, to clarifying what is in conflict, weighing options against the Code and law, acting transparently, then reflecting."},{"type":"case","passage":"Liam, a provisional psychologist in a small town, ended therapy with Noah three months ago. Noah messages asking to 'grab a coffee as friends'. Liam worries a blunt no will hurt Noah, who has few supports.","prompt":"What is the best first action for Liam?","options":["Consult his supervisor before replying","Refer Noah to another psychologist immediately","Ignore the message to avoid any contact","Accept, because therapy has ended"],"answer":0,"explanation":"The worked example shows Liam consulting his supervisor before replying, using supervision as a core safeguard against a boundary violation and multiple relationship.","lvl":2},{"type":"mc","prompt":"Which cue does the notes suggest for recognising an ethical issue?","options":["'Is this the fastest option?'","'Has the client complained yet?'","'Would this be profitable?'","'Would I be comfortable if my supervisor read this?'"],"answer":3,"explanation":"Discomfort is a warning sign; asking whether you would be comfortable if your supervisor read it is a signal to pause and consult.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Is an ethical dilemma","Is not an ethical dilemma"],"items":[{"text":"A Code principle conflicts with a law you must follow","cat":0},{"text":"Two Code principles point in opposite directions","cat":0},{"text":"The Code conflicts with your personal morals","cat":0},{"text":"You forgot to return a phone call","cat":1},{"text":"A client prefers morning appointments","cat":1}],"explanation":"An ethical dilemma occurs when two or more ethical directives conflict and you must prioritise one."},{"type":"case","passage":"An organisation hires a psychologist to improve morale. A worker confidentially discloses a drinking problem while operating heavy machinery.","prompt":"What makes this a 'who is the client?' dilemma?","options":["It is not a dilemma because drinking is legal","The worker is not a client because the organisation pays","Only the colleagues are clients","Responsibilities are owed to both the organisation and the worker, and safety competes with confidentiality"],"answer":3,"explanation":"Under the APS Code, clients can include organisations and those commissioning the work, so the psychologist must weigh confidentiality to the worker against safety risks to the worker, colleagues and organisation.","lvl":3},{"type":"type_answer","prompt":"The APA offers 10 strategies to avoid ethical pitfalls. Strategy 7 is to practise only where you hold what?","answers":["expertise","competence"],"explanation":"Strategy 7 is to practise only within your expertise; expertise grows with experience and CPD.","lvl":3}]},{"id":"HPS105-3.4","name":"Explain consequences of unethical conduct and integrity breaches","summary":"Identifies AHPRA's role, possible tribunal findings and sanctions, and academic integrity breaches.","questions":[{"type":"mc","prompt":"Which of these is AHPRA's role alongside the 15 National Boards?","options":["Running the APS Colleges","Writing the DSM-5-TR","Accrediting courses, registering practitioners and investigating complaints","Setting Medicare rebate levels"],"answer":2,"explanation":"AHPRA regulates all health practitioners with the National Boards: it accredits courses, registers and renews practitioners, and investigates complaints.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Tribunal finding","Tribunal sanction"],"items":[{"text":"Unprofessional conduct","cat":0},{"text":"Professional misconduct","cat":0},{"text":"A fine of up to $30,000","cat":1},{"text":"Suspending registration","cat":1},{"text":"The practitioner has an impairment","cat":0},{"text":"A condition on registration","cat":1}],"explanation":"After hearing a matter a tribunal makes findings, then may caution, reprimand, impose conditions, fine, suspend or cancel registration."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Findings of unprofessional conduct are published online by AHPRA as legally binding case law that is sortable by patient.","wrong":"patient","correct":"Board","explanation":"AHPRA's Court and tribunal outcomes are sortable by Board. Findings of unprofessional conduct or professional misconduct are legally binding and, subject to privacy, published online as case law."},{"type":"case","passage":"Two students share their full AT1 answers with each other the night before it is due and each submits a version.","prompt":"Which academic integrity breach is this most likely to be?","options":["Impersonation","Collusion","Falsification of data","Contract cheating"],"answer":1,"explanation":"Collusion crosses the line from ethical collaboration into shared work presented as individual work.","lvl":1},{"type":"type_answer","prompt":"What is the name for outsourcing your assessment to another person or service?","answers":["contract cheating"],"explanation":"Contract cheating is outsourcing work; Deakin lists it among academic integrity breaches.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"To maintain registration, psychologists must complete ___ hours of CPD each year.","answers":["30","thirty"],"explanation":"Psychologists complete 30 hours of Continuing Professional Development each year to maintain registration.","lvl":4}]}]},{"week":4,"topic":"Collaborative Practice","summary":"What interprofessional collaborative practice is, how teams differ from groups, the client's place in the team, and the competencies and education that build it.","skills":[{"id":"HPS105-4.1","name":"Explain the drivers and benefits of collaborative practice","summary":"Defines collaborative practice and links each driver of the shift to why it pushes toward teamwork.","questions":[{"type":"match","prompt":"Match each driver of collaboration to why it pushes toward teamwork.","pairs":[["Complexity of patient care","Chronic disease and ageing need care no single professional can give"],["Advances and specialisation","Professionals depend on each other for complete care"],["Patient safety and quality","Many errors stem from poor communication between professionals"],["Workforce challenges","Shortages, especially rurally, mean scarce resources must be used efficiently"]],"explanation":"The six drivers also include the patient-centred care movement and global health challenges such as pandemics."},{"type":"mc","prompt":"Which organisation endorsed collaborative practice in 2010 to strengthen health systems?","options":["The World Health Organisation","IPEC","The APS","AHPRA"],"answer":0,"explanation":"The WHO endorsed collaborative practice in 2010 and has continued to advocate it for universal health coverage.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Documented benefit of collaboration","Not a documented benefit"],"items":[{"text":"Fewer hospital admissions and shorter stays","cat":0},{"text":"Less redundancy and better coordination","cat":0},{"text":"Enhanced professional satisfaction","cat":0},{"text":"Each professional works fully independently","cat":1},{"text":"More cost-effective care","cat":0},{"text":"Care plans developed separately by each discipline","cat":1}],"explanation":"Benefits include improved outcomes, more efficient care, professional satisfaction and cost-effectiveness. Working independently with separate plans describes the older multidisciplinary model."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Collaborative practice breaks down the ___ that traditionally separated professionals.","answers":["silos"],"explanation":"The WHO (2010) definition frames collaboration as shared decision-making that breaks down professional silos.","lvl":2},{"type":"case","passage":"A rural health service has one psychologist and one dietitian covering a large region. The manager wants them to share case planning and assessments.","prompt":"Which driver of collaboration does this best reflect?","options":["Patient-centred care movement","Advances and specialisation","Global health challenges","Workforce challenges"],"answer":3,"explanation":"Workforce shortages, especially in rural and regional areas, mean collaboration uses scarce resources more efficiently.","lvl":2},{"type":"type_answer","prompt":"The WHO lists five foundational elements of quality care. Which element, and especially how its members work together, is described as pivotal?","answers":["health workers","the health workforce","workforce"],"explanation":"The five elements are health workers, facilities, medicines, devices and technologies, and information systems and financing; health workers are pivotal.","lvl":4}]},{"id":"HPS105-4.2","name":"Distinguish groups, multidisciplinary and interprofessional teams","summary":"Contrasts groups with teams and multidisciplinary with interprofessional collaborative teams.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Group","Team"],"items":[{"text":"Members work independently or in parallel","cat":0},{"text":"Accountability is both individual and mutual","cat":1},{"text":"Outcome is the sum of individual contributions","cat":0},{"text":"Regular, structured interaction focused on collaboration","cat":1},{"text":"Roles may be undefined or flexible","cat":0},{"text":"Decisions made collectively","cat":1}],"explanation":"Teams have a unified purpose, high interdependence, defined roles and mutual accountability, producing outcomes greater than the sum of their parts."},{"type":"case","passage":"At a hospital, the psychologist, physiotherapist and doctor each assess a patient separately, write their own care plans and share only brief notes with the senior doctor.","prompt":"What kind of team is this, and what is the risk?","options":["Interprofessional; risk of role confusion","Interprofessional; risk of over-coordination","Traditional multidisciplinary; risk of fragmented care","A true team; no particular risk"],"answer":2,"explanation":"Working in parallel with separate plans and hierarchical information sharing is the traditional multidisciplinary model, which can fragment care and resembles a group more than a team.","lvl":3},{"type":"analogy","prompt":"Multidisciplinary team is to working in parallel as interprofessional team is to ___","options":["working in silos","working alone","working together","working hierarchically"],"answer":2,"explanation":"The key difference is integration: multidisciplinary teams work in parallel, interprofessional teams work together toward a unified plan.","lvl":1},{"type":"mc","prompt":"Katzenbach and Smith (1993) define a team as a small number of people with complementary skills committed to a common purpose for which they hold themselves what?","options":["Hierarchically ranked","Mutually accountable","Legally liable","Individually rewarded"],"answer":1,"explanation":"Mutual accountability for a common purpose, goals and approach is central to the definition of a team.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In reality most care sits somewhere in between, and 'interprofessional' is still the more common everyday term.","wrong":"interprofessional","correct":"multidisciplinary","explanation":"'Multidisciplinary' remains the common term, sometimes used even when the team is actually interprofessional."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"An interprofessional collaborative team builds a ___ plan of care by sharing responsibilities, knowledge and decision-making.","answers":["unified","single","shared"],"explanation":"Interprofessional teams integrate their work into a unified, holistic and coordinated plan.","lvl":3}]},{"id":"HPS105-4.3","name":"Position the person receiving care as an equal team member","summary":"Explains who belongs on the team, how complexity shapes it, and why clients are experts by experience.","questions":[{"type":"analogy","prompt":"Professionals are to 'experts by profession' as the person receiving care is to ___","options":["passive recipients","experts by referral","experts by experience","secondary clients"],"answer":2,"explanation":"Collaborative patient-centred care treats the person and their care partners as experts by experience whose voices belong at the centre of decisions.","lvl":2},{"type":"case","passage":"A recreational cyclist with a fractured arm needs one or two providers. A single parent of three with the same fracture has several chronic conditions and little support.","prompt":"What does the module say explains the difference in team size?","options":["The patient's preferred terminology","Hospital funding rules","The type of injury","Complexity of care"],"answer":3,"explanation":"Complexity of care strongly shapes team composition, so the parent with chronic conditions and limited support needs a larger, cross-sector team.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Professional team member","Non-professional team member"],"items":[{"text":"A school teacher","cat":0},{"text":"The person receiving care","cat":1},{"text":"A police officer","cat":0},{"text":"A community volunteer providing informal support","cat":1},{"text":"A family member who is a care partner","cat":1},{"text":"A support worker","cat":0}],"explanation":"Professionals are not limited to health disciplines; non-professionals include the person receiving care and their care partners."},{"type":"match","prompt":"Match each term for the person receiving care to the concern the module raises about it.","pairs":[["Patient","Can imply a passive recipient and a power dynamic"],["Client","Can suggest a commodified relationship"],["Consumer or service user","Can sound distanced"]],"explanation":"There is no universally accepted term, but the constant message is that non-professional members are equal participants."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Care must be provided ___, rather than for, patients.","answers":["with"],"explanation":"Collaborative patient-centred care is done with the person, not to or for them.","lvl":2},{"type":"mc","prompt":"Which statement about the interprofessional team is correct?","options":["It can include architects, lawyers and prison officers where relevant","Care partners attend only as observers","The team's size is fixed by the setting","Only health professionals can be members"],"answer":0,"explanation":"Professionals on the team are not limited to health disciplines and can include teachers, police, lawyers, prison officers, support workers and architects.","lvl":3}]},{"id":"HPS105-4.4","name":"Identify WHO competency domains and the role of IPE","summary":"Names the six WHO (2022) competency domains and explains what interprofessional education is and who needs it.","questions":[{"type":"match","prompt":"Match each WHO (2022) competency domain to its focus.","pairs":[["People-centredness","Promotes agency and culturally sensitive, holistic care"],["Communication","Listens actively and manages documentation"],["Collaboration","Builds trusting partnerships and manages conflict"],["Personal conduct","Works within scope, lifelong learning, own wellbeing"]],"explanation":"The six domains are people-centredness, decision-making, communication, collaboration, evidence-informed practice and personal conduct."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The distinguishing feature of interprofessional education is attendance between learners.","wrong":"attendance","correct":"interaction","explanation":"IPE is learning with, from and about each other; its distinguishing feature is interaction, not simply sharing a lecture."},{"type":"case","passage":"A hospital runs a workshop where nursing, psychology and pharmacy students debate how to manage a simulated patient's medication concerns together.","prompt":"Why does this count as interprofessional education?","options":["Students receive a certificate","A lecturer from each profession presents","It is held at a hospital","Learners from different professions interact through dialogue and debate"],"answer":3,"explanation":"IPE requires interaction between learners, such as case studies, simulations and debate, not just co-location.","lvl":2},{"type":"mc","prompt":"Why does the module say IPE is not only for university students?","options":["Students no longer need discipline-specific learning","IPE replaces supervision","Much of the current workforce did not experience IPE and needs to upskill","Registration requires annual IPE exams"],"answer":2,"explanation":"Collaborative practice is relatively new, so many current practitioners need IPE to refine teamwork and understand colleagues' evolving roles.","lvl":2},{"type":"type_answer","prompt":"Competencies integrate knowledge, skills and what third element, demonstrated through behaviours?","answers":["attitudes","attitude"],"explanation":"The WHO defines competencies as the ability to integrate knowledge, skills and attitudes, demonstrated through behaviours in context.","lvl":3},{"type":"analogy","prompt":"WHO domain 'Collaboration' is to managing conflict as WHO domain 'Evidence-informed practice' is to ___","options":["listening actively","contributing to a culture of safety","managing own wellbeing","promoting agency"],"answer":1,"explanation":"Evidence-informed practice applies evidence-informed principles, assesses data from many sources and contributes to a culture of safety and improvement.","lvl":5}]}]},{"week":5,"topic":"Case Formulation: the 4Ps and Biopsychosocial Model","summary":"How to define a client's problem, organise evidence with the biopsychosocial model and the 4Ps, and synthesise a formulation that guides intervention.","skills":[{"id":"HPS105-5.1","name":"Define the presenting problem and distinguish it from diagnosis","summary":"Describes the presenting problem accurately, explains why formulation is needed beyond diagnosis, and knows evidence-collection methods.","questions":[{"type":"mc","prompt":"What does a case formulation tell you that a diagnosis alone does not?","options":["Which DSM-5-TR code to bill","Whether the person meets 5 of 9 criteria","How the person came to have the problem and why it persists","The population prevalence of the disorder"],"answer":2,"explanation":"A diagnosis labels a consistent symptom pattern; a formulation explains how the problem developed, why it persists and which factors contribute.","lvl":2},{"type":"case","passage":"A client presents with fainting, panic and avoidance of places where spiders live, but does not quite meet diagnostic threshold for a specific phobia.","prompt":"How should the psychologist treat this presentation?","options":["Wait until full criteria are met","Decline treatment because there is no disorder","Refer to a psychiatrist for diagnosis first","Treat it as the presenting problem, since the symptoms still cause distress"],"answer":3,"explanation":"The lecture stressed that a presenting problem may not meet threshold for any psychopathology and you still treat it.","lvl":2},{"type":"match","prompt":"Match each evidence-collection method to its description.","pairs":[["Interview","Usually first; open-ended questions such as 'When did this begin?'"],["Observation","Watching presentation in session or discreetly in the waiting room"],["Psychometric screening","Standardised tests normed on populations to set a baseline"],["Case history","Archival reports and referrals showing how things progressed"]],"explanation":"Systematic assessment with structured tools is a fifth method. Together these build the case evidence the formulation organises."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Screening tests alone let you determine whether a person meets criteria for a specific disorder.","wrong":"Screening","correct":"Diagnostic","explanation":"Screeners indicate distress or symptom frequency and point toward labels to consider; only a diagnostic manual (DSM-5-TR or ICD-11) determines whether criteria are met."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"At the first stage of formulation the goal is to ___ the problem accurately, not explain its causes.","answers":["describe"],"explanation":"Clients explain the problem in their own words (onset, development, frequency, severity, impact), and the clinician describes before explaining.","lvl":3},{"type":"type_answer","prompt":"A presenting problem answers what key question about the client's timing?","answers":["why now","why are they coming now","why is the person coming to see you now"],"explanation":"The presenting problem answers 'why is the person coming to see you now?', because it has exceeded their capacity to cope.","lvl":3}]},{"id":"HPS105-5.2","name":"Classify factors across biopsychosocial domains","summary":"Allocates client factors to biological, psychological and social domains and explains how domains interact.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Biological","Psychological","Social"],"items":[{"text":"Poor sleep and headaches","cat":0},{"text":"Negative self-talk ('I'm going to fail')","cat":1},{"text":"Moving away from home","cat":2},{"text":"Chronic inflammation","cat":0},{"text":"Avoidant coping style","cat":1},{"text":"Limited financial resources","cat":2}],"explanation":"Biological covers physiology and genetics, psychological covers internal processes like thoughts and coping, and social covers relationships, resources and institutions."},{"type":"case","passage":"Jordan, 21, has a family history of anxiety.","prompt":"Why did the lecture say this factor sits across more than one domain?","options":["It can be a genetic vulnerability and also reflect modelling of how family respond to anxiety","It is irrelevant to Jordan's presenting problem","Family history only counts as social","It is purely genetic"],"answer":0,"explanation":"Family history can be biological (genetic vulnerability), social (modelling) and psychological, which shows why the model is integrative.","lvl":3},{"type":"mc","prompt":"Engel (1977) introduced the biopsychosocial model as a response to which dominant model?","options":["The social model of disability","The psychodynamic model","The biomedical model","The behavioural model"],"answer":2,"explanation":"The biomedical model focused on biological causes of disease and overlooked mental and social context.","lvl":2},{"type":"order","prompt":"Put this worked chain from the module in causal order.","items":["Financial hardship creates chronic stress","Cortisol levels change","Mood and immune functioning are affected"],"explanation":"Social stress (financial hardship) alters cortisol (biological), affecting mood and immunity; coping and support can buffer this chain."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In the biopsychosocial model, the biological domain includes exposure to chemicals, and also behavioural exposure therapy.","wrong":"also","correct":"not","explanation":"Biological 'exposure' means things that happen to you, such as chemicals and environment, not behavioural exposure."},{"type":"type_answer","prompt":"Which school of thought, popular from the 1930s to 1950s, focused only on what can be seen and measured, as with Pavlov and Skinner?","answers":["behavioural","behaviourism","behaviorism"],"explanation":"Behavioural approaches explain problems through learning history and environmental contingencies, which shape how formulations and interventions target behaviour.","lvl":2}]},{"id":"HPS105-5.3","name":"Apply the 4Ps to classify case factors","summary":"Sorts client factors into predisposing, precipitating, perpetuating and protective, recognising factors with multiple roles.","questions":[{"type":"sort","prompt":"Sort each factor into the right 'P'.","categories":["Predisposing","Precipitating","Perpetuating"],"items":[{"text":"Brent's father was addicted to alcohol","cat":0},{"text":"Brent's recent relationship breakdown","cat":1},{"text":"Brent's denial and false confidence in his 'safe' use","cat":2},{"text":"Toby being moved 18 times across placements","cat":0},{"text":"Toby's delinquent peer group in his current unit","cat":2}],"explanation":"Predisposing factors create vulnerability, the precipitating factor is the proximal trigger, and perpetuating factors keep the problem going."},{"type":"mc","prompt":"Which of these is NOT one of the 4Ps?","options":["Protective","Predisposing","Perpetuating","Preventative"],"answer":3,"explanation":"'Preventative' is the exam trap from the lecture; the four are predisposing, precipitating, perpetuating and protective.","lvl":1},{"type":"case","passage":"Brent, 37, was deregistered as a pharmacist for working under the influence. Since deregistration his misuse has increased, but he badly wants to regain registration.","prompt":"How can deregistration be both perpetuating and protective?","options":["It increases stress and self-medication now, but the wish to re-register can motivate change","It cannot fit two categories","It is predisposing because it happened in adolescence","It is only a precipitating factor"],"answer":0,"explanation":"The lecture used deregistration to show one factor playing two roles: worsening things now but acting as a 'carrot' for change.","lvl":3},{"type":"analogy","prompt":"Predisposing is to vulnerability as precipitating is to ___","options":["diagnosis","trigger","maintenance","strength"],"answer":1,"explanation":"Predisposing factors make someone vulnerable; precipitating factors are the proximal trigger, often the straw that breaks the camel's back.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A disagreeable personality style can be predisposing and then perpetuating, which is why formulation is described as cyclical, not ___.","answers":["linear"],"explanation":"The same characteristic can create isolation and then prevent skill development that would reduce it, so formulation is cyclical.","lvl":3},{"type":"match","prompt":"Match each of Toby's factors to its 'P'.","pairs":[["Removal from family care at age 9","Predisposing"],["Friendships with peers involved in burglary","Perpetuating"],["Enjoyment of team sports and dry humour","Protective"]],"explanation":"Early removal and instability are vulnerabilities, the delinquent peer group maintains offending, and his engagement and humour are strengths."}]},{"id":"HPS105-5.4","name":"Synthesise a formulation into a coherent narrative","summary":"Writes a parsimonious, causally linked formulation that uses a timeline and guides intervention choices.","questions":[{"type":"order","prompt":"Put the parts of a strong formulation synthesis in the order the Brent example uses.","items":["Context about the client","The presenting problem and diagnosis","A timeline of how factors interact","A balanced prognosis with strengths"],"explanation":"The synthesis moves from context to problem to the interacting factors and ends with a prognosis that becomes the baseline for future sessions."},{"type":"mc","prompt":"Which sentence best shows the linking language the module recommends?","options":["Predisposing: anxiety. Precipitating: move.","Her vulnerability to anxiety, combined with a recent move, led to distress; in response she avoided lectures, which gave short-term relief but reinforced the problem.","She has anxiety. She moved. She avoids lectures.","Factors: anxiety, move, avoidance."],"answer":1,"explanation":"A formulation should be a flowing explanation using 'because', 'which led to', 'in response' and 'over time', not a segmented list.","lvl":2},{"type":"case","passage":"A client's anxiety is being maintained by avoiding feared situations.","prompt":"According to the module, which target should intervention usually prioritise first?","options":["The precipitating event, by revisiting it repeatedly","Perpetuating factors, such as avoidance, using approaches like exposure","Only protective factors","Predisposing factors, to explain childhood"],"answer":1,"explanation":"Perpetuating factors are often the most immediate and effective targets; if avoidance maintains anxiety, exposure may be indicated.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A good formulation is exhaustive, listing every factor rather than highlighting the most relevant ones.","wrong":"exhaustive","correct":"parsimonious","explanation":"A good formulation is parsimonious: concise and focused on the most relevant factors and how they interact."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"On Dr Hayley's timeline tool, the ___ event is marked as the closest trigger in time before the presenting problem.","answers":["precipitating"],"explanation":"The timeline places predisposing factors early, the precipitating event just before the problem, and perpetuating factors after.","lvl":3},{"type":"case","passage":"Two clinicians disagree about whether Brent's precipitating factor is the relationship breakdown or the deregistration.","prompt":"What does the lecture recommend?","options":["Choose one, justify it clearly, and check the formulation in supervision","Always choose the most recent event","List both as precipitating","Leave the precipitating factor blank"],"answer":0,"explanation":"Identify one precipitating factor and justify it; supervision guards against bias and rigid thinking because clinicians can be unreliable narrators.","lvl":3}]}]},{"week":6,"topic":"Evidence and Tools","summary":"The types of evidence psychologists use, the skills and tools that collect it, healthy scepticism, and the levels of evidence pyramid.","skills":[{"id":"HPS105-6.1","name":"Distinguish case evidence from research evidence in EBP","summary":"Separates case from research evidence and names the components of evidence-based practice.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Case evidence","Research evidence"],"items":[{"text":"A client's DASS-21 score from this week","cat":0},{"text":"A meta-analysis of CBT for depression","cat":1},{"text":"A teacher's observations of a student client","cat":0},{"text":"Average effects across a representative sample","cat":1},{"text":"The client's account of when the problem began","cat":0},{"text":"Factors shown to be associated with a problem in a population","cat":1}],"explanation":"Case evidence comes from and about the individual client; research evidence describes the group or population the client belongs to."},{"type":"match","prompt":"Match each EBP component to what it means.","pairs":[["Research evidence","The best available research about problems and interventions"],["Clinical expertise","The psychologist's training, skills and experience"],["Client values and preferences","The client's goals, beliefs, culture and lived experience"],["Practice context","The setting and professional boundaries that limit scope"]],"explanation":"EBP integrates the first three components within a practice context."},{"type":"analogy","prompt":"Case evidence is to individualising as research evidence is to ___","options":["diagnosing","generalising","personalising","observing"],"answer":1,"explanation":"Case evidence individualises and research evidence generalises; neither is sufficient alone.","lvl":3},{"type":"case","passage":"A client's main goal is to 'attend a party without feeling anxious'. The psychologist uses this goal to shape therapy.","prompt":"Which EBP component is most directly guiding the psychologist?","options":["Clinical expertise","Research evidence","Client values and preferences","Practice context"],"answer":2,"explanation":"Client goals become the goals of therapy, and client values set boundaries on how the psychologist works.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When citing the DASS in AT1, cite its authors, Lovibond and Lovibond, not the ___ platform that hosts it.","answers":["NovoPsych"],"explanation":"The lecturer's hint: cite the tool's developers (1995), not the hosting platform.","lvl":5},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A screener such as the DASS-21 is a full diagnosis of the client's condition over the past seven days.","wrong":"diagnosis","correct":"snapshot","explanation":"A screener is a little bit of evidence, a snapshot over a set timeframe, not a diagnosis."}]},{"id":"HPS105-6.2","name":"Select tools and skills for collecting evidence","summary":"Distinguishes tools from skills and chooses the right one for a given information need.","questions":[{"type":"analogy","prompt":"A tool is to an instrument you use as a skill is to ___","options":["a case history","a questionnaire","a diagnostic manual","a capacity you develop"],"answer":3,"explanation":"Tools are instruments for gathering information; skills are capacities, often built experientially, for using tools well and interpreting results.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Tool","Skill"],"items":[{"text":"Self-report questionnaire","cat":0},{"text":"Active listening","cat":1},{"text":"DSM-5-TR","cat":0},{"text":"Clinical reasoning and judgement","cat":1},{"text":"Collateral information from a teacher","cat":0},{"text":"Integrating multiple evidence sources","cat":1}],"explanation":"Tools include interviews, observation, psychometric tests, diagnostic systems, records, collateral sources, self-report and literature. Skills include listening, reasoning and integration."},{"type":"case","passage":"A psychologist is assessing a 7-year-old who has little awareness of his inner experience.","prompt":"Which tool does the module say is especially important here?","options":["Behavioural observation and reports from teachers or parents","Diagnostic classification alone","Published literature","Self-report measures"],"answer":0,"explanation":"Behavioural observation, including information from reliable sources like teachers and parents, is especially important with children.","lvl":2},{"type":"mc","prompt":"A client says 'I'm fine' but looks away, speaks slowly and slumps. Which skill lets the psychologist use this mismatch?","options":["Ethical and professional judgement","Evidence-based decision-making","Ability to observe and interpret interactions","Use of psychometric tools"],"answer":2,"explanation":"Reading non-verbal cues that nuance or contrast with spoken words is the skill of observing and interpreting interactions.","lvl":2},{"type":"type_answer","prompt":"Which diagnostic classification system is published internationally as an alternative to the DSM-5-TR?","answers":["ICD-11","ICD 11","ICD"],"explanation":"Diagnostic guides include the DSM-5-TR (APA, 2022) and the ICD-11.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Psychometric tests are developed from psychological theory and assessed for validity and popularity.","wrong":"popularity","correct":"reliability","explanation":"Psychometric assessments are standardised against population norms and assessed for validity and reliability."}]},{"id":"HPS105-6.3","name":"Apply healthy scepticism to evaluate claims","summary":"Uses scepticism, critical thinking and the scientific method to judge a claim, and names common reasoning errors.","questions":[{"type":"mc","prompt":"How does scepticism differ from cynicism?","options":["Scepticism rejects all claims; cynicism accepts them","Scepticism believes a claim when there is credible and sufficient evidence; cynicism doubts everything regardless of evidence","They are the same thing","Cynicism relies on replication"],"answer":1,"explanation":"Healthy scepticism reserves judgement until evidence is evaluated; cynicism rejects everything no matter how much evidence is presented.","lvl":1},{"type":"case","passage":"On Instagram, 'Dr Jenny' in scrubs claims a study found 60% of vaccinated children later developed mental health conditions.","prompt":"Which is the most useful first question?","options":["How many followers does she have?","What kind of doctor is she, and is the claim within her expertise?","Did the reel get many comments?","Does the video look professional?"],"answer":1,"explanation":"Checking whether the presenter has relevant expertise (a paediatrician or immunologist, not a dentist) guards against misplaced authority.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Letting too much in","Keeping too much out"],"items":[{"text":"Accepting surface-level content without verification","cat":0},{"text":"Refusing to update 'best practice' when new evidence emerges","cat":1},{"text":"Information overload from unverified sources","cat":0},{"text":"Rigidly rejecting new ideas","cat":1}],"explanation":"The scepticism filter can misfire both ways: passive acceptance of low-quality sources, or rigid rejection of evidence-based advances."},{"type":"case","passage":"Marshall, 22, dreads speaking in seminars. The psychologist lists H1 social anxiety disorder, H2 another condition, and H3 an appropriate response to context such as English as a second language.","prompt":"Why list three hypotheses?","options":["To maximise billing","To apply the scientific method with falsifiable alternatives before concluding","To delay treatment","Because the DSM requires three"],"answer":1,"explanation":"Proposing competing falsifiable hypotheses and collecting evidence to test them avoids jumping to a conclusion.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Believing what you want to be true rather than what is true is called ___ reasoning.","answers":["motivated"],"explanation":"Motivated reasoning is a logical fallacy to watch for, alongside missing assumptions and appeals to emotion.","lvl":3},{"type":"match","prompt":"Match each reasoning error to its guard.","pairs":[["Correlation mistaken for causation","Reserve causal claims for randomised, controlled evidence"],["Over-trusting a single study","Look for replication and filtered evidence"],["Authority misplaced","Check the claim is within the expert's field"]],"explanation":"Naming and catching these errors in yourself and in sources is a core professional skill under ULO4."}]},{"id":"HPS105-6.4","name":"Rank evidence on the levels of evidence pyramid","summary":"Orders study designs, distinguishes filtered from unfiltered and quantitative from qualitative, and separates efficacy from utility.","questions":[{"type":"order","prompt":"Put these on the psychology levels of evidence pyramid from strongest to weakest.","items":["Systematic reviews and meta-analyses","Randomised controlled trials","Cohort studies","Cross-sectional single studies","Expert opinion and anecdote"],"explanation":"Level 1 is filtered syntheses, then RCTs (Level 4), cohort studies (5), single cross-sectional studies (6) and expert opinion (7)."},{"type":"case","passage":"Emma, 16, has depressive symptoms linked to social media. Options: an RCT of iCBT with 70 adolescents, a correlational study of mindfulness, and a blog by a 'doctor' on digital detox.","prompt":"Which option has the strongest and most relevant evidence?","options":["Digital detox blog","All are equal","iCBT RCT","Mindfulness correlational study"],"answer":2,"explanation":"The iCBT RCT is Level 4 with a relevant adolescent sample; the correlational study cannot show causation and the blog is bottom-tier opinion.","lvl":1},{"type":"match","prompt":"Match each term to its definition.","pairs":[["Efficacy","How well an intervention works under controlled study conditions"],["Utility","How useful it is when clinicians apply it in everyday life"],["Grey literature","Non-peer-reviewed reports from reputable bodies such as the ABS"],["White literature","For-profit material that looks like research but sells an agenda"]],"explanation":"The efficacy and utility gap is a face of the scientist-practitioner gap; grey, black and white literature describe source types."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Filtered evidence","Unfiltered evidence"],"items":[{"text":"A systematic review of CBT trials","cat":0},{"text":"A single RCT of 1039 adolescents","cat":1},{"text":"A meta-analysis of 13 studies","cat":0},{"text":"A case report of one client","cat":1},{"text":"A cohort study tracking stress over time","cat":1}],"explanation":"Filtered evidence has systematically evaluated and synthesised primary studies; unfiltered evidence is original single studies."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The levels of evidence pyramid rates the quality of qualitative studies only.","wrong":"qualitative","correct":"quantitative","explanation":"The pyramid rates quantitative studies only; qualitative research does not even rate a mention, though it is evaluated for rigour in other ways."},{"type":"mc","prompt":"A meta-analysis differs from a systematic review because it:","options":["Includes only qualitative studies","Is written by a single expert","Is always unfiltered","Uses statistics to combine data into a single effect size estimate"],"answer":3,"explanation":"A systematic review identifies themes across retained studies; a meta-analysis goes further and statistically combines the data.","lvl":3}]}]},{"week":7,"topic":"Treatment","summary":"Practice contexts, distress versus disorder, families of psychotherapy, the clinician's toolkit, client-centred practice and Australian treatment access.","skills":[{"id":"HPS105-7.1","name":"Distinguish normal distress from psychological disorder","summary":"Judges whether a response is understandable distress or disorder using severity, duration, impairment, context and pattern.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Normative life event","Non-normative life event"],"items":[{"text":"Starting school","cat":0},{"text":"Retirement","cat":0},{"text":"A natural disaster","cat":1},{"text":"Sudden bereavement in childhood","cat":1},{"text":"Becoming a parent","cat":0},{"text":"Major illness at a young age","cat":1}],"explanation":"Normative events are common or developmentally typical; non-normative events are less predictable or occur outside expected timing. Neither is inherently pathological."},{"type":"case","passage":"Six weeks after her mother's death, Kim has insomnia, low appetite, crying spells and poor concentration.","prompt":"What is the most appropriate interpretation at this point?","options":["No support is warranted","Prolonged Grief Disorder, because the symptoms are intense","Expected grief, while monitoring severity, duration, impairment and cultural context over time","Major depressive disorder, because she cannot concentrate"],"answer":2,"explanation":"Early grief responses are expected; Prolonged Grief Disorder may be hypothesised only when intense, persistent, culturally atypical grief lasts beyond 12 months.","lvl":3},{"type":"mc","prompt":"According to the module, the line between distress and disorder is NOT drawn by which of these?","options":["Duration","Functional impairment","Severity","The mere presence of symptoms"],"answer":3,"explanation":"Symptoms alone do not make a disorder; severity, duration, functional impairment, context and pattern do.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Intense, persistent, culturally atypical grief lasting beyond ___ months may lead a clinician to hypothesise Prolonged Grief Disorder.","answers":["12","twelve"],"explanation":"The bereavement worked example uses a 12-month threshold alongside cultural context and impairment.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Only psychologists holding an Area of Practice Endorsement can conduct a diagnostic assessment and give a diagnosis.","wrong":"Only","correct":"Any","explanation":"Any psychologist with appropriate training, experience and competence can diagnose, including those with only General registration (APS, 2023)."},{"type":"match","prompt":"Match each practice context to one of its distinctive demands.","pairs":[["Clinical psychology","Intensive therapeutic work for mild to severe disorders"],["Organisational psychology","Understanding hierarchy; may be embedded in HR or a consultant"],["Forensic psychology","Balancing the justice system and offender as primary and secondary clients"]],"explanation":"Each context has different problems and demands, and general psychologists often work alongside specialists across them."}]},{"id":"HPS105-7.2","name":"Match therapy families and waves to their theory of change","summary":"Identifies the three waves and main therapy families, and selects best-supported approaches for a case.","questions":[{"type":"match","prompt":"Match each wave of therapy to its theory of change.","pairs":[["First wave: behaviour therapies","Problems are learned behaviours shaped by reinforcement"],["Second wave: cognitive and CBT","Maladaptive beliefs and distortions drive distress"],["Third wave: contextual","Change the relationship with inner experience through acceptance and values"]],"explanation":"The waves move from behaviour, to thought content, to one's relationship with thoughts (ACT, DBT, MBCT)."},{"type":"case","passage":"Leah, 29, has longstanding relationship instability, self-image disturbance, emotional dysregulation and recurrent self-harm, consistent with borderline personality disorder.","prompt":"Which approaches does the APS (2024) review best support?","options":["CBT or interpersonal psychotherapy","Dialectical behaviour therapy or schema therapy","Play-based therapy","Solution-focused brief therapy"],"answer":1,"explanation":"DBT and schema therapy have Level I support for BPD; CBT and IPT had inconclusive evidence, showing that 'studied' is not the same as 'best supported'.","lvl":4},{"type":"analogy","prompt":"DBT is to chain analysis as narrative therapy is to ___","options":["exposure hierarchies","Socratic questioning","externalising conversations","sand trays"],"answer":2,"explanation":"Narrative therapy uses externalising conversations and re-authoring, and is specifically recognised under Better Access for Aboriginal and Torres Strait Islander peoples.","lvl":4},{"type":"mc","prompt":"What separates good integrative practice from eclecticism?","options":["Following a single manual strictly","Using as many techniques as possible","The clinician is still guided by formulation, evidence, client preference, culture and outcome monitoring","Always starting with psychodynamic therapy"],"answer":2,"explanation":"Integrative practice combines approaches such as CBT, ERP and schema therapy (as with Sophie) but stays anchored in formulation and evidence.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Third-wave (contextual) method","First or second-wave method"],"items":[{"text":"Values clarification","cat":0},{"text":"Cognitive restructuring","cat":1},{"text":"Cognitive defusion","cat":0},{"text":"Contingency management","cat":1},{"text":"Mindfulness and acceptance","cat":0},{"text":"Thought records","cat":1}],"explanation":"Third-wave methods target the relationship with inner experience; first and second-wave methods change behaviour or the content of thoughts."},{"type":"type_answer","prompt":"For Marcus, 38, with PTSD after an assault, which approach does the APS (2024) review best support (give the name)?","answers":["trauma-focused CBT","trauma focused CBT","TF-CBT","trauma-focused cognitive behaviour therapy"],"explanation":"Trauma-focused CBT has Level I support for PTSD, though many studies excluded people with substance dependence or psychosis, which limits generalisability.","lvl":4}]},{"id":"HPS105-7.3","name":"Select clinician tools for a treatment purpose","summary":"Chooses conceptual, monitoring, cognitive, behavioural, experiential, skills and relational tools to fit a clinical aim.","questions":[{"type":"match","prompt":"Match each tool to its category.","pairs":[["Thought record","Cognitive tool"],["Graded exposure hierarchy","Behavioural tool"],["Chair work","Experiential tool"],["Sleep diary","Idiographic monitoring"]],"explanation":"Tools are the practical mechanisms through which theory becomes therapeutic action."},{"type":"case","passage":"A client with depression has stopped seeing friends and says she will go out again 'once I feel motivated'.","prompt":"Which tool best fits the principle that action often needs to come before motivation?","options":["Behavioural activation","Socratic questioning","A PHQ-9 at intake","Imagery rescripting"],"answer":0,"explanation":"Behavioural activation reverses the withdrawal cycle with activity schedules and graded tasks, on the principle that action precedes motivation.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The aim of a thought record is simply to replace negative thoughts with positive ones.","wrong":"positive","correct":"balanced","explanation":"The thought record aims for accuracy, flexibility and emotional tolerability, moving to a more balanced alternative, not just positive thinking."},{"type":"mc","prompt":"A therapist says, 'Given how much uncertainty you were dealing with, it makes sense that you felt overwhelmed.' Which relational tool is this?","options":["Guided discovery","Validation","Psychoeducation","Exposure"],"answer":1,"explanation":"Validation communicates that reactions make sense given circumstances, without necessarily agreeing with everything the client says.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Distress tolerance","Emotion regulation"],"items":[{"text":"Urge surfing during a crisis","cat":0},{"text":"Distinguishing primary from secondary emotions","cat":1},{"text":"A crisis survival plan","cat":0},{"text":"Opposite action planning","cat":1},{"text":"Grounding to get through intense moments","cat":0}],"explanation":"Distress tolerance helps a client survive crises without making them worse; emotion regulation builds accurate identification and management of emotions."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A PHQ-9 at intake establishes a ___, and repeating it during treatment provides evidence of change.","answers":["baseline"],"explanation":"Standardised measures give severity and change over time; a worsening score signals a need to review the formulation.","lvl":2}]},{"id":"HPS105-7.4","name":"Apply client-centred practice principles","summary":"Explains why the therapeutic alliance matters and identifies barriers, facilitators and practical steps of client-centred care.","questions":[{"type":"mc","prompt":"What does the module identify as the deeper reason client-centred practice matters?","options":["It reduces session length","It removes the need for evidence","The therapeutic alliance predicts adherence and outcomes across diagnoses and settings","It makes the clinician the sole decision-maker"],"answer":2,"explanation":"Trust in the relationship affects outcomes, and a good working alliance lets therapist and client agree on tasks and goals.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Barrier to client-centred practice","Facilitator of client-centred practice"],"items":[{"text":"Time-poor staff and institutional protocols","cat":0},{"text":"Organisational support for the approach","cat":1},{"text":"Professionals feeling disempowered as they are no longer the sole expert","cat":0},{"text":"Training and education in the approach","cat":1},{"text":"Apparent compliance that reflects a communication barrier","cat":0},{"text":"A respectful and trusting care environment","cat":1}],"explanation":"Barriers include time, disempowerment, low autonomy and communication difficulties; facilitators include skilled professionals, self-reflection, training and supportive environments."},{"type":"order","prompt":"Put these practical client-centred steps in the order the lecture lists them.","items":["Smile, introduce yourself and explain your role","Ask how the client is feeling physically and emotionally","See the client as a person with a life outside treatment","Make sure the client has the information to make informed choices"],"explanation":"The steps build rapport first, then partnership, and end with informed choice."},{"type":"case","passage":"A psychologist explains the CBT approach and its likely timeline to a new client before starting.","prompt":"According to the module, why is this important?","options":["It is a courtesy only","It is part of informed consent","It is required only under Better Access","It replaces the need for goals"],"answer":1,"explanation":"Explaining treatment principles as you go is informed consent, not a courtesy.","lvl":2},{"type":"type_answer","prompt":"What term describes the feelings and attitudes client and therapist hold toward each other and how these are expressed?","answers":["therapeutic alliance","therapeutic relationship","alliance"],"explanation":"The therapeutic relationship, or alliance, predicts adherence and outcomes.","lvl":3},{"type":"analogy","prompt":"Historical medical model is to professional as expert as client-centred practice is to ___","options":["the client as expert in their lived experience","the GP as referrer","the diagnosis as focus","the manual as authority"],"answer":0,"explanation":"Client-centred practice recognises each person as an expert in their own lived experience, correcting the historical power imbalance.","lvl":2}]},{"id":"HPS105-7.5","name":"Explain Australian treatment access pathways and Better Access","summary":"Compares private, Better Access and public pathways and applies the Better Access rules to a case.","questions":[{"type":"mc","prompt":"Under Better Access, how many individual and group rebated services are available each calendar year?","options":["20 individual and no group","10 individual and 10 group","Unlimited individual sessions","6 individual and 6 group"],"answer":1,"explanation":"Better Access allows up to 10 individual and 10 group services per calendar year, counted separately.","lvl":4},{"type":"order","prompt":"Put the Better Access referral steps in order.","items":["GP prepares a Mental Health Treatment Plan","Client attends up to 6 individual sessions","Client returns to the GP for review","GP refers for remaining sessions up to the annual cap"],"explanation":"Referral is usually for up to 6 sessions first, then review with the referring practitioner before the remaining sessions."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Treatable under Better Access","Not regarded as a mental disorder for Better Access"],"items":[{"text":"Panic disorder","cat":0},{"text":"Dementia","cat":1},{"text":"Adjustment disorder","cat":0},{"text":"Tobacco use disorder","cat":1},{"text":"Eating disorders","cat":0},{"text":"Intellectual disability","cat":1}],"explanation":"Dementia, delirium, tobacco use disorder and intellectual disability are excluded; people who do not qualify may use digital services or Medicare Mental Health Centres."},{"type":"case","passage":"Andy, 47, has a Mental Health Treatment Plan but faces a one-month wait. His sleep, alcohol use and distress have worsened, and he says 'I do not know how long I can keep doing this.'","prompt":"Which is the best immediate step?","options":["Increase alcohol to help sleep","Cancel the referral and self-refer to a private coach","Return to the GP for earlier review, including risk assessment and safety planning","Wait quietly for the appointment"],"answer":2,"explanation":"Increasing severity makes waiting harmful, so returning to the GP for reassessment of risk, sleep, alcohol and coping, with safety planning, comes first.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The principal limitation of private self-referral is clinical: without Better Access rebates, treatment is fully fee paying.","wrong":"clinical","correct":"financial","explanation":"Private self-referral is flexible but does not by itself provide the medical oversight of a GP-initiated pathway, and it is fully fee paying without rebates."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Psychologists treating under Better Access must use evidence-based and time-___ treatment approaches.","answers":["limited"],"explanation":"Better Access funds finite, evidence-based, time-limited treatment, not open-ended psychotherapy.","lvl":4}]}]},{"week":8,"topic":"Evaluation and Outcomes","summary":"Setting client-led goals, turning them into indicators, evaluating outcomes and trajectories, critical self-reflection, and the 5As.","skills":[{"id":"HPS105-8.1","name":"Translate broad hopes into client-led measurable goals","summary":"Turns vague hopes into specific, observable goals developed with the client and linked to measurement.","questions":[{"type":"mc","prompt":"Which is the best-formed treatment goal?","options":["'I want to attend one social activity each week without leaving early because of anxiety.'","'I want to be less anxious.'","'I want to feel better.'","'I want to be normal again.'"],"answer":0,"explanation":"Good goals are specific, observable and measurable; broad hopes like 'feel better' cannot guide treatment.","lvl":1},{"type":"order","prompt":"Put the goal-creation steps in order.","items":["Start with the client's presenting concern","Ask what change would look like in everyday life","Translate broad hopes into observable, realistic goals","Link goals to the formulation and treatment plan","Review goals regularly and revise when needed"],"explanation":"Goal setting moves from the concern, to everyday change, to concrete goals tied to the plan, with ongoing review."},{"type":"case","passage":"A psychologist wants to 'reduce anxiety symptoms'. The client says what really matters is attending her daughter's school concert without leaving early.","prompt":"What does the module say about these two goals?","options":["Only the psychologist's goal is valid","The client's goal is too specific","Goals should be set by the GP","Both are relevant, but the client's version gives the goal lived meaning"],"answer":3,"explanation":"Goals should be developed with the client; the client's version connects treatment to their values and reduces the risk of defining progress too narrowly.","lvl":2},{"type":"match","prompt":"Match each problem to a goal-linked measurement from the module's table.","pairs":[["Daily panic attacks","Number of panic attacks and strategy use over two weeks"],["Depression","Activity type, duration and satisfaction in the past week"],["Poor sleep","Time to bed and sleep quality over two weeks"]],"explanation":"Each goal pairs a strategy with a measurement and a subjective check-in."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In goal setting, the psychologist brings lived expertise about the client's life, values, culture and priorities.","wrong":"psychologist","correct":"client","explanation":"The client brings lived expertise about their life, values and constraints, while the psychologist brings professional knowledge; goals are developed together, not imposed."},{"type":"type_answer","prompt":"Treatment goals give client and clinician a common objective and let both recalibrate when what gets derailed?","answers":["the therapeutic alliance","therapeutic alliance","alliance","the alliance"],"explanation":"Goals keep both parties focused on the core problem and help them recalibrate when the therapeutic alliance is derailed.","lvl":4}]},{"id":"HPS105-8.2","name":"Classify indicators and types of improvement","summary":"Distinguishes symptom, behavioural, functional, process, relational and personally meaningful indicators, and three kinds of improvement.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Symptom indicator","Behavioural indicator","Functional indicator"],"items":[{"text":"Lower GAD-7 score","cat":0},{"text":"Approaching rather than avoiding feared situations","cat":1},{"text":"Returning to work three days a week","cat":2},{"text":"Fewer intrusive thoughts","cat":0},{"text":"Reducing reassurance seeking","cat":1},{"text":"Attending university classes again","cat":2}],"explanation":"Symptom indicators show symptom change, behavioural indicators show acting differently, and functional indicators show daily life improving."},{"type":"match","prompt":"Match each type of improvement to an example.","pairs":[["Improvement","A person with depression now showers daily"],["Clinically meaningful improvement","Moving from the severe to the mild symptom range"],["Personally meaningful improvement","Being able to sleep through the night and parent confidently"]],"explanation":"Improvement is any helpful change, clinical meaningfulness is large enough to matter clinically, and personal meaningfulness matters in the client's real life."},{"type":"case","passage":"After eight sessions Liam still gets angry quickly, but he has not punched walls or threatened anyone in a month and has used time-out three times.","prompt":"What is the best evaluation?","options":["Treatment is producing important change: it changed what he does with anger, not the emotion itself","He should be discharged immediately","Treatment failed because he still feels anger","Only his symptom score matters"],"answer":0,"explanation":"Evaluation should distinguish emotional experience from behavioural response; fewer aggressive incidents and safer choices are meaningful change.","lvl":2},{"type":"mc","prompt":"Increased cognitive flexibility and improved distress tolerance are examples of which indicator type?","options":["Symptom","Process","Relational","Functional"],"answer":1,"explanation":"Process indicators show whether the mechanisms targeted in treatment are changing.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Evaluation compares the client's current presentation with earlier information, so you need a ___.","answers":["baseline"],"explanation":"Without a baseline it is difficult to know whether meaningful change has occurred.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A client who still has symptoms cannot show functional improvement.","wrong":"cannot","correct":"can","explanation":"Symptom and functional change overlap but are not identical; a client can improve functionally while still symptomatic."}]},{"id":"HPS105-8.3","name":"Interpret treatment trajectories and respond appropriately","summary":"Reads a trajectory of change, identifies what it may signal and chooses the right professional response.","questions":[{"type":"match","prompt":"Match each trajectory to the professional response.","pairs":[["Quick improvement then plateau","Revise goals and target maintaining factors"],["Little or no improvement","Review formulation, plan, alliance and supervision"],["Deterioration","Reassess risk, revisit formulation, consider referral"],["Strong early improvement","Keep monitoring whether gains are sustained"]],"explanation":"Each trajectory signals something different, so the response is tailored rather than assuming the chosen approach is working."},{"type":"case","passage":"At session 6 Robin's panic attacks have dropped from four or five a week to one, but his PADIS score is still high and he still avoids busy shopping centres.","prompt":"What should the psychologist conclude?","options":["This is partial improvement; review the plan and target remaining avoidance","Treatment has worked; discharge him","Wait until session 10 before reviewing","Treatment has failed; switch to psychodynamic therapy"],"answer":0,"explanation":"The psychologist neither declares success nor failure; they review at session 6 and Robin requests four more sessions for graded exposure.","lvl":3},{"type":"order","prompt":"Put the stages of a typical treatment timeline in order.","items":["Initial engagement and consent","Assessment and formulation","Treatment planning","Active intervention and progress monitoring","Relapse prevention and ending or referral"],"explanation":"The timeline is not always linear; if symptoms worsen the psychologist may revisit assessment or refer on."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Shapes the treatment timeline","Does not shape the timeline"],"items":[{"text":"Referral under a Mental Health Plan with a session cap","cat":0},{"text":"Attendance compelled under a Community Based Order","cat":0},{"text":"The evidence-based structure of the chosen treatment","cat":0},{"text":"The psychologist's favourite colour","cat":1},{"text":"Access through WorkSafe or the NDIA","cat":0}],"explanation":"Problem type, assessment purpose, funding system limits, voluntary or compelled attendance and the treatment's evidence-based structure all shape timelines."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"At session 10, because Robin was referred through a Mental Health Plan, the psychologist sends a final report to the ___.","answers":["GP","general practitioner","referring GP"],"explanation":"Better Access requires the referrer and psychologist to communicate about treatment and outcomes.","lvl":3},{"type":"analogy","prompt":"Steady improvement is to continue and monitor as deterioration is to ___","options":["stop measuring","discharge the client","extend the same plan unchanged","reassess risk and consider referral"],"answer":3,"explanation":"Deterioration may mean increased risk, an unsuitable intervention or a weakened alliance, so risk and formulation are reassessed.","lvl":2}]},{"id":"HPS105-8.4","name":"Distinguish reflective and reflexive practice using Driscoll","summary":"Applies Driscoll's What? So what? Now what? model and separates event-focused reflection from self-focused reflexivity.","questions":[{"type":"order","prompt":"Put Driscoll's model of reflection in order.","items":["What? (Describe)","So what? (Interpret)","Now what? (Outcome)"],"explanation":"Driscoll's model moves from an objective account, to analysing meaning, to planning future action."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Reflective question","Reflexive question"],"items":[{"text":"Did I explain the homework task clearly?","cat":0},{"text":"Am I assuming non-completion means low motivation?","cat":1},{"text":"What went well in the session?","cat":0},{"text":"How might my culture or training shape how I understood this client?","cat":1},{"text":"What did the client appear to need?","cat":0},{"text":"Was I more comfortable with some client emotions than others?","cat":1}],"explanation":"Reflective practice examines the event; reflexive practice examines the self who is practising, including assumptions and power."},{"type":"case","passage":"Priya asks Elena, who is distressed and fears abandonment, 'What evidence do you have that everyone leaves?' Elena says 'You don't get it' and leaves early.","prompt":"What did Priya's reflection identify?","options":["She moved to cognitive questioning too quickly; Elena needed validation and grounding first","Elena was resistant to therapy","The question was inconsistent with CBT","She should never use cognitive work with Elena"],"answer":0,"explanation":"The question was technically consistent with CBT but did not match Elena's emotional state; Priya plans to repair the rupture and lead with validation.","lvl":3},{"type":"mc","prompt":"Which bias involves attributing your successes to internal factors and your failures to external ones?","options":["Self-serving bias","Confirmation bias","Fundamental attribution error","Anchoring"],"answer":0,"explanation":"Self-serving bias ('I lost weight through willpower; I gained it because of Christmas') blocks genuine self-reflection.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The fundamental attribution error over-emphasises situational factors when explaining other people's behaviour.","wrong":"situational","correct":"dispositional","explanation":"It over-emphasises dispositional factors for others ('he is disorganised') and situational ones for ourselves ('traffic')."},{"type":"type_answer","prompt":"Which Psychology Board competency includes professional reflexivity, deliberate practice and self-care (give the number)?","answers":["3","Competency 3","three"],"explanation":"Competency 3 covers reflexivity, purposeful practice and self-care; the lecture calls critical self-reflection a meta-competency.","lvl":5}]},{"id":"HPS105-8.5","name":"Apply the 5As of evidence-based practice","summary":"Works through Ask, Access, Appraise, Apply and Audit for a client, including auditing your own role.","questions":[{"type":"order","prompt":"Put the 5As of evidence-based practice in order.","items":["Ask","Access (Acquire)","Appraise","Apply","Audit"],"explanation":"The cycle converts a problem into a question, finds and appraises evidence, applies it, then audits the outcome."},{"type":"match","prompt":"Match each PICO element to Maya's case.","pairs":[["Population and problem","A young adult with major depressive disorder"],["Intervention","Evidence-informed psychological strategies"],["Outcome","Reduced depression and increased functional participation"]],"explanation":"PICO specifies population and problem, intervention, comparison and outcome to make a question answerable."},{"type":"case","passage":"A psychologist asks a clear question, applies an evidence-informed intervention for Maya, but never checks whether her tutorial attendance or depression ratings changed.","prompt":"What is wrong?","options":["Nothing; applying evidence is enough","Maya should have chosen the intervention alone","The EBP cycle is incomplete because the outcome was never audited","The question should have been broader"],"answer":2,"explanation":"Auditing outcomes is not optional; without it the evidence-based practice cycle is incomplete.","lvl":2},{"type":"case","passage":"For Alex, an Autistic adult with sleep difficulties, one source is a meta-analysis of CBT in Autistic children by non-Autistic researchers showing reduced anxiety at 3 months but increased anxiety at 12 months.","prompt":"At the Appraise step, what is the key concern?","options":["It is qualitative so it cannot be used","It was published too recently","Its relevance: it studied children, not adults, and longer-term anxiety rose","It is too high on the pyramid to question"],"answer":2,"explanation":"Appraisal asks whether evidence applies to this client's age, needs and preferences; high-level evidence can still be a poor fit.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The lecture adds a second half to the Audit step: assess your own ___ in the outcome through critical self-reflection.","answers":["role","contribution"],"explanation":"Auditing includes evaluating the client's outcomes and your own contribution, for better or worse.","lvl":4},{"type":"analogy","prompt":"Ask is to PICO question as Audit is to ___","options":["comparing outcome measures before and after","writing a referral","searching guidelines","choosing a therapy"],"answer":0,"explanation":"Ask forms the PICO question; Audit evaluates whether the approach helped by comparing outcomes before and after.","lvl":3}]}]},{"week":9,"topic":"Popular Psychology and the Critical Consumer","summary":"How psychological ideas circulate through history and social media, what is gained and lost, and how to consume psychology content critically.","skills":[{"id":"HPS105-9.1","name":"Link historical explanations of difference to modern media","summary":"Connects phrenology, hysteria, changeling folklore and the mad genius myth to contemporary social media patterns.","questions":[{"type":"match","prompt":"Match each historical pattern to its contemporary parallel.","pairs":[["Phrenology","Reducing behaviour to biology, as in reductive evolutionary psychology"],["Hysteria","Gendered dismissal of women's distress as 'too emotional'"],["Changeling folklore","Othering people on the basis of developmental difference"],["Mad genius myth","Romanticising distress while neglecting care and treatment"]],"explanation":"Each historical example maps onto a modern pattern, so old ideas can reappear in new forms."},{"type":"mc","prompt":"Why does the module say it is misleading to read the history of explaining difference as a tidy progression from superstition to science?","options":["Psychiatry arrived fully formed in 1650","Many societies held several explanations at once, and categories reflected the power of their time","Religion was always more accurate","Science has never changed"],"answer":1,"explanation":"A person could be seen as spiritually troubled, morally suspect, medically unwell and dangerous at once, and labels like hysteria were never neutral.","lvl":3},{"type":"case","passage":"A post claims that great artists must suffer, and that treating depression will 'kill your creativity'.","prompt":"What does the research reviewed in the module suggest?","options":["There is no link at all between any disorder and creativity","Madness causes creativity","Some links exist, but creativity is more conducive with milder or controlled symptoms, so the myth wrongly romanticises distress","Treatment always increases creativity"],"answer":2,"explanation":"Reddy and colleagues found some links but concluded creativity is more conducive with milder or controlled symptoms; the myth discourages help-seeking.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Phrenology claimed that character and mental faculties could be read from the shape of the hand.","wrong":"hand","correct":"skull","explanation":"Phrenology (Gall and Spurzheim) inferred mental faculties from skull shape; it is now called a pseudoscience."},{"type":"type_answer","prompt":"Which neurologist made hysteria a major topic at the Salpetriere in Paris in the nineteenth century?","answers":["Charcot","Jean-Martin Charcot"],"explanation":"Charcot's work on hysteria, and Freud's after him, fed the development of psychoanalysis.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"How a society explains mental illness matters because the explanation shapes the ___.","answers":["response"],"explanation":"A person seen as possessed may be treated with ritual, while one seen as criminally defective may be punished or surveilled.","lvl":3}]},{"id":"HPS105-9.2","name":"Distinguish dark traits from clinical diagnoses","summary":"Separates Dark Triad and Tetrad traits from personality disorder diagnoses and critiques red flag content.","questions":[{"type":"match","prompt":"Match each dark trait to its core description.","pairs":[["Narcissism","Grandiosity, entitlement and desire for admiration"],["Machiavellianism","Strategic manipulation and using others for gain"],["Psychopathy","Callousness, impulsivity and low remorse"],["Sadism","Enjoyment of cruelty or others' suffering"]],"explanation":"The Dark Triad (Paulhus and Williams) is narcissism, Machiavellianism and psychopathy; adding sadism makes the Dark Tetrad."},{"type":"case","passage":"A friend says her ex 'refused to apologise, so he's definitely a narcissist'.","prompt":"What is the most accurate response, based on the module?","options":["She is right; refusing to apologise is diagnostic","Difficulty apologising can reflect shame, trauma, immaturity or cultural norms; describing the behaviour and its impact is more accurate than a label","She should post the diagnosis online","Only a psychopath refuses to apologise"],"answer":1,"explanation":"A red flag list is not an assessment; naming the behaviour keeps the focus on impact and safety without misusing a clinical construct.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Research trait construct","Formal DSM-5-TR diagnosis"],"items":[{"text":"Machiavellianism","cat":0},{"text":"Narcissistic Personality Disorder","cat":1},{"text":"Sadism in the Dark Tetrad","cat":0},{"text":"Antisocial Personality Disorder","cat":1},{"text":"Scoring high on a trait measure in a community sample","cat":0}],"explanation":"Dark traits are spectrum tendencies measured in non-clinical populations; NPD and ASPD are diagnoses requiring pervasive patterns with impairment."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Antisocial Personality Disorder is identical to psychopathy.","wrong":"identical","correct":"different","explanation":"ASPD focuses on enduring patterns of violating others' rights and is not identical to psychopathy, which is a contested construct."},{"type":"mc","prompt":"Why does dark personality content perform so well on social media?","options":["It is always peer reviewed","It is emotionally charged, identity-relevant and algorithmically efficient","It avoids moral drama","Platforms remove it quickly"],"answer":1,"explanation":"Viewers comment, tag and keep watching, so algorithms serve more, creating a distorted sense of how common narcissists and psychopaths are.","lvl":2},{"type":"analogy","prompt":"Dark Triad is to three traits as Dark Tetrad is to ___","options":["three traits plus sadism","a personality disorder","a diagnostic manual","two traits"],"answer":0,"explanation":"The Dark Tetrad extends the Triad by adding sadism.","lvl":2}]},{"id":"HPS105-9.3","name":"Critique reductive evolutionary psychology claims","summary":"Explains what evolutionary findings actually show and how looksmaxxing, mewing and mate value distort them.","questions":[{"type":"case","passage":"A viral TikTok says women are biologically wired to only want tall men, so shorter men are 'doomed'.","prompt":"What does evolutionary research actually suggest?","options":["Height fully determines attraction","There is no research on mate preferences","Findings are probabilistic, context-dependent and modest group tendencies, not rules for individuals","Only culture affects attraction, never biology"],"answer":2,"explanation":"Studies such as Buss show broad statistical trends with modest effects; reductive versions turn them into fatalistic laws.","lvl":2},{"type":"mc","prompt":"What is the evidence for mewing changing adult facial structure?","options":["Strong RCT support","It is endorsed as an alternative to braces","Proven in meta-analyses","Very thin; little robust support that tongue posture changes adult faces"],"answer":3,"explanation":"The American Association of Orthodontists said the evidence is 'as thin as dental floss', and John Mew lost his dental licence for misconduct.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Looksmaxxing spaces operate through bro-___, where harsh critique and reinforcement normalise extreme behaviour.","answers":["pedagogy"],"explanation":"Bro-pedagogy can escalate self-improvement into self-harm, disordered eating and body dysmorphia.","lvl":5},{"type":"match","prompt":"Match each term to its meaning in the module.","pairs":[["Mate value","Ranking people by perceived desirability as if attraction were a marketplace"],["Objectification theory","Women's value tied mainly to appearance, increasing self-surveillance"],["Neoteny","Baby-faced features theorised as cues to reproductive fitness"]],"explanation":"These ideas are often presented online without their conjectural, probabilistic nature."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Evolutionary findings about mate preference are deterministic and large in effect size.","wrong":"deterministic","correct":"probabilistic","explanation":"The findings are probabilistic, context-dependent and often modest, a nuance usually lost online."},{"type":"analogy","prompt":"Mewing is to unproven self-optimisation as bonesmashing is to ___","options":["a peer-reviewed technique","orthodontic treatment","dangerous self-harm","evidence-based surgery"],"answer":2,"explanation":"Looksmaxxing practices range from unproven (mewing) to dangerous behaviours like bonesmashing.","lvl":1}]},{"id":"HPS105-9.4","name":"Evaluate neurodiversity self-diagnosis content","summary":"Weighs the benefits and risks of neurodivergent self-identification and responds in a validating, evidence-based way.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Benefit of self-identification","Risk of social media self-diagnosis"],"items":[{"text":"Community and belonging","cat":0},{"text":"Diagnostic overshadowing between ADHD and anxiety","cat":1},{"text":"Echo chambers from personalised algorithms","cat":1},{"text":"Language to articulate long-standing difference","cat":0},{"text":"Misinformation in 41 to 52 percent of TikToks on autism and ADHD","cat":1},{"text":"Lived experience helping correct male-based diagnostic criteria","cat":0}],"explanation":"The module presents four advantages (knowledge, validation, community, reconceptualising) and risks including misinformation, echo chambers, user bias, overshadowing and identity development."},{"type":"type_answer","prompt":"What hypothesis describes broad lived experiences being over-interpreted as clinical concerns after exposure to content?","answers":["prevalence inflation hypothesis","prevalence inflation"],"explanation":"The prevalence inflation hypothesis (Jansen et al., 2025) helps explain rising self-identification after exposure to broad portrayals.","lvl":4},{"type":"case","passage":"A client tells you she has self-diagnosed ADHD from TikTok and wants to discuss it.","prompt":"What is best practice according to the module?","options":["Dismiss the self-diagnosis as misinformation","Accept it without assessment","Validate her perspective and experience while providing evidence-based psychoeducation and clinically informed assessment","Refer her to TikTok creators"],"answer":2,"explanation":"Best practice balances validating identity with evidence-based decisions, and also addresses the systemic barriers (waitlists, cost, past invalidation) behind self-diagnosis.","lvl":1},{"type":"mc","prompt":"Which group more commonly reports self-diagnosis of neurodivergence, often because it was missed in childhood?","options":["Psychiatrists","Children under 10","Men over 60","Adults assigned female at birth"],"answer":3,"explanation":"Self-diagnosis is more commonly reported by adults assigned female at birth, whose neurodivergence was often missed.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Selective exposure from personalised algorithms makes users more passive and less likely to accept misinformation.","wrong":"less","correct":"more","explanation":"Selective exposure makes users more passive and more likely to accept misinformation that fits what they are motivated to believe."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A neurodiversity perspective shifts the focus from fixing the person to ___ difference, the heart of the social model of disability.","answers":["accommodating"],"explanation":"It asks whether difficulty comes from the person or from environments not designed for different ways of thinking and sensing.","lvl":3}]},{"id":"HPS105-9.5","name":"Identify heuristics and apply science literacy to content","summary":"Names the cognitive heuristic at work in a scenario and uses science literacy and the consumption checklist.","questions":[{"type":"match","prompt":"Match each heuristic to how it works.","pairs":[["Availability","Judging frequency by how easily examples come to mind"],["Illusory truth effect","Repeated claims feel more true"],["Social proof","Using likes and shares as a cue for what to believe"],["Anchoring","The first explanation you meet shapes later judgements"]],"explanation":"Heuristics are efficient but produce predictable errors, especially in fast, emotional, algorithm-driven feeds."},{"type":"case","passage":"Sam trusts a mental health influencer mainly because she has a blue tick and two million followers.","prompt":"Which heuristic is most likely at work?","options":["Anchoring","Source credibility","Representativeness","Affect"],"answer":1,"explanation":"Source credibility judges information by who appears to present it (titles, branding, followers) rather than the evidence.","lvl":2},{"type":"type_answer","prompt":"What is the bias of believing media influences other people more than yourself?","answers":["third-person effect","third person effect"],"explanation":"Psychology students are especially at risk of over-confidence, mistaking recognition of a term for understanding.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Conceptual understanding","Methodological understanding","Epistemic humility"],"items":[{"text":"Knowing narcissistic traits are not Narcissistic Personality Disorder","cat":0},{"text":"Asking whether a study was correlational or experimental","cat":1},{"text":"Matching your confidence to the strength of the evidence","cat":2},{"text":"Knowing a group finding does not determine any individual","cat":0},{"text":"Checking whether the sample was large and diverse","cat":1}],"explanation":"Science literacy combines conceptual and methodological understanding, epistemic humility, and ethical and social awareness."},{"type":"mc","prompt":"When sharing psychology content, which practice does the module recommend?","options":["Separate evidence from opinion with signals like 'research suggests' or 'in my experience'","Hide commercial interests","Diagnose public figures to raise awareness","Use sensational phrases to increase reach"],"answer":0,"explanation":"Responsible sharing defines terms, separates evidence from opinion, acknowledges uncertainty, avoids diagnosing online and discloses commercial interests.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Platforms amplify psychology content mainly because it is accurate.","wrong":"accurate","correct":"engaging","explanation":"Recommendation systems amplify content that holds attention, so nuance loses to emotional, identity-based or sensational content."}]}]},{"week":10,"topic":"Diversity in Psychological Practice","summary":"How social identity, stigma, norms and privilege shape mental health, and how to practise safely with six diverse populations in Australia.","skills":[{"id":"HPS105-10.1","name":"Explain social identity, intersectionality and stereotypes","summary":"Defines social identity, ingroups and outgroups, intersectionality and stereotypes, and links each to practice.","questions":[{"type":"match","prompt":"Match each concept to its originator.","pairs":[["Social identity theory","Tajfel and Turner (1979)"],["Intersectionality","Crenshaw (1989)"],["Minority stress theory","Meyer (2003)"]],"explanation":"Knowing who to attribute each named framework to is an exam tip for this module."},{"type":"case","passage":"An older Aboriginal woman with disability describes difficulties accessing a service.","prompt":"Why does the module say her experience cannot be understood by considering each identity separately?","options":["Because disability outweighs all other factors","Because her identities interact with ageism, racism, ableism and historical mistrust to create a distinct experience","Because only her age matters","Because intersectionality is a checklist of identities"],"answer":1,"explanation":"Intersectionality describes how multiple identities combine with systems of power to produce distinct experiences.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Positive stereotypes, such as being 'naturally resilient', are harmless because they are flattering.","wrong":"harmless","correct":"restrictive","explanation":"Even positive stereotypes simplify people into categories and can shape assessment, formulation and risk judgements."},{"type":"mc","prompt":"A clinician feels more at ease with clients who speak and dress like her. Which process does this reflect?","options":["Identity integration","Masking","Ingroup and outgroup dynamics","Moral expansiveness"],"answer":2,"explanation":"Ingroup comfort can lead clinicians to misread unfamiliar behaviour as resistance or poor insight.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Social identity provides context but never replaces curiosity about the individual's ___ identity.","answers":["personal"],"explanation":"Personal identity covers the unique characteristics, experiences and histories that make a person distinct.","lvl":3},{"type":"analogy","prompt":"Ingroup is to 'us' as outgroup is to ___","options":["'no one'","'me'","'everyone'","'them'"],"answer":3,"explanation":"Tajfel and Turner describe ingroups as 'us' and outgroups as 'them', shaping belonging, trust and prejudice.","lvl":1}]},{"id":"HPS105-10.2","name":"Classify forms of stigma, norms and privilege in practice","summary":"Identifies social, self, associative and structural stigma and reinterprets 'non-compliance' through norms and privilege.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Social stigma","Self-stigma","Structural stigma"],"items":[{"text":"A person with depression believing they are weak","cat":1},{"text":"Intake forms that do not allow for gender diversity","cat":2},{"text":"A same-sex attracted young person feeling shame","cat":1},{"text":"A person with schizophrenia unfairly perceived as dangerous","cat":0},{"text":"Services unavailable in a client's language","cat":2},{"text":"An Aboriginal client anticipating racism based on past experiences","cat":0}],"explanation":"Social stigma comes from others, self-stigma is internalised, and structural stigma is built into laws, policies and service design. The fourth form, stigma by association, affects families and carers."},{"type":"case","passage":"A client is labelled 'non-compliant' after missing two appointments.","prompt":"What does a social-identity-informed perspective ask instead?","options":["Whether to raise the fee","How to discharge the client","Whether the client is lazy","What conditions make engagement difficult, such as caring duties, transport, language or past racism"],"answer":3,"explanation":"The shift is from 'Why has the client not engaged?' to 'What conditions are making engagement difficult?'","lvl":1},{"type":"mc","prompt":"A psychologist suggests mindfulness to a client facing eviction. Why might this feel invalidating?","options":["It ignores that the main source of distress is unsafe housing, a social condition","The client did not ask for homework","Mindfulness is only for older adults","Mindfulness has no evidence base"],"answer":0,"explanation":"A privilege-informed response keeps psychological strategies but places them within the reality of social conditions, possibly adding referral or advocacy.","lvl":2},{"type":"type_answer","prompt":"What term describes treating people as less fully human by denying their complexity, agency or moral worth (Haslam, 2006)?","answers":["dehumanisation","dehumanization"],"explanation":"Reducing people to labels like 'a borderline' or 'non-compliant' is a care-context example of dehumanisation.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Social privilege means some aspects of identity make life harder in particular contexts.","wrong":"harder","correct":"easier","explanation":"Privilege does not mean an easy life; it means some aspects of identity make life easier or safer in particular contexts."},{"type":"case","passage":"A refugee client gives short answers and avoids eye contact in a first session.","prompt":"Which adaptation does the module recommend?","options":["End the session early","Record the client as disengaged","Slow the pace, explain confidentiality, ask permission before sensitive questions and use an interpreter where appropriate","Insist on direct eye contact"],"answer":2,"explanation":"A social norms perspective considers respect, shame, feeling unsafe with authority, limited English or trauma before assuming disengagement.","lvl":2}]},{"id":"HPS105-10.3","name":"Apply SEWB and cultural safety with First Nations clients","summary":"Uses the social and emotional wellbeing model, historical context and strengths-based framing with Aboriginal and Torres Strait Islander clients.","questions":[{"type":"mc","prompt":"What does social and emotional wellbeing (SEWB) connect that Western models of mental health often do not?","options":["Income and employment only","Body, mind and emotions with family, kinship, community, culture, Country, spirituality and ancestry","Genetics and neurotransmitters","Only symptoms and diagnosis"],"answer":1,"explanation":"SEWB is a holistic framework shaped by cultural, historical, political and social determinants.","lvl":2},{"type":"case","passage":"An Aboriginal client is reluctant to engage with a hospital-based service.","prompt":"What should a historically informed psychologist consider first?","options":["Whether the client, family or community has experienced institutional harm, racism, child removal or culturally unsafe care","That the client needs an Elder present","That all Aboriginal people live remotely","That the client lacks motivation"],"answer":0,"explanation":"Reluctance may reflect histories of institutional harm; the psychologist should also ask, not assume, about family or Elder involvement.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The 1992 Mabo decision confirmed terra nullius.","wrong":"confirmed","correct":"overturned","explanation":"Mabo overturned terra nullius and recognised the land rights of the Meriam people, inserting native title into Australian law."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Deficit framing","Strengths-based framing"],"items":[{"text":"Describing a community mainly by its disadvantage and risk","cat":0},{"text":"Treating kinship, Elders and connection to Country as foundational to wellbeing","cat":1},{"text":"Positioning peoples as problems to be fixed","cat":0},{"text":"Supporting Aboriginal Community Controlled Health Organisations","cat":1}],"explanation":"Inequities must be named, but a deficit-only account reinforces stigma and obscures strengths."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Aboriginal people have occupied mainland Australia for at least ___ years.","answers":["65,000","65000","sixty-five thousand"],"explanation":"British colonisation from 1788 brought dispossession, violence and later forced child removal documented in Bringing them home (1997).","lvl":4},{"type":"analogy","prompt":"Mabo decision is to native title as Bringing them home report is to ___","options":["marriage equality","the White Australia policy","the NDIS","the Stolen Generations"],"answer":3,"explanation":"Bringing them home (1997) documented the forced removal of children and made recommendations for healing and reconciliation.","lvl":2}]},{"id":"HPS105-10.4","name":"Respond to barriers for CALD and older adult clients","summary":"Recognises barriers such as language, stigma, ageism and underdiagnosis, and adapts practice for CALD and older clients.","questions":[{"type":"case","passage":"A client who manages everyday English well needs to discuss a trauma history and suicidal thoughts. Her teenage son offers to interpret.","prompt":"What is the best approach?","options":["Proceed in English, since she manages daily conversation","Postpone discussing risk","Use a trained interpreter, considering confidentiality, client preference and community ties","Use the son, since he is available"],"answer":2,"explanation":"Everyday English does not mean a client can discuss trauma or risk in English, and relying on family interpreters creates ethical and clinical risks.","lvl":2},{"type":"mc","prompt":"Why are depression and anxiety in older adults often under-recognised?","options":["Symptoms are wrongly attributed to 'normal ageing'","Older adults cannot be assessed","Better Access excludes people over 65","They are always caused by dementia"],"answer":0,"explanation":"Poor mental health is not an inevitable part of ageing, and many older adults benefit from intervention and social support.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["CALD-specific consideration","Older adult-specific consideration"],"items":[{"text":"Interpreter use and language access","cat":0},{"text":"Allowing processing time for age-related cognitive slowing","cat":1},{"text":"Unfamiliarity with Medicare and referral pathways after migration","cat":0},{"text":"Elder abuse and carer burden","cat":1},{"text":"Racism as part of the presenting problem","cat":0},{"text":"Digital exclusion affecting telehealth suitability","cat":1}],"explanation":"Each population has distinct barriers, although intersectionality means many clients face several at once."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Lower recorded rates of diagnosed mental health conditions among humanitarian entrants may reflect overdiagnosis, stigma or lack of culturally appropriate assessment.","wrong":"overdiagnosis","correct":"underdiagnosis","explanation":"Lower recorded rates may reflect underdiagnosis, stigma, different expressions of distress or lack of culturally appropriate assessment."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Approximately one in ___ Australians is aged 65 or older.","answers":["six","6"],"explanation":"About one in six Australians is 65 or older, rising to about one in four by 2066.","lvl":4},{"type":"type_answer","prompt":"Which 1901 Act was central to the White Australia policy, using mechanisms such as the dictation test?","answers":["Immigration Restriction Act","the Immigration Restriction Act","Immigration Restriction Act 1901"],"explanation":"The Racial Discrimination Act 1975 later made race-based discrimination unlawful and removed the last traces of the policy.","lvl":4}]},{"id":"HPS105-10.5","name":"Apply minority stress, social model and neuro-affirming lenses","summary":"Uses minority stress theory, the social model of disability and neuro-affirming practice to formulate and respond.","questions":[{"type":"order","prompt":"Put the minority stress process in order.","items":["Distal stressors: experiences of stigma and discrimination","Proximal stressors: internalised stigma and concealment","Cumulative long-term impacts on mental health"],"explanation":"Meyer (2003) explains disparities as resulting from repeated exposure to stigma, not from LGBTQ+ identity itself."},{"type":"case","passage":"Mary, 42, has a chronic physical disability and depression. The nearest psychologist is three hours away, public transport is limited and her internet is unreliable.","prompt":"How does the social model of disability explain her difficulty accessing care?","options":["Barriers in the environment, such as distance, transport and connectivity, create the disability","Her impairment alone prevents access","She lacks motivation","Rural people do not need psychologists"],"answer":0,"explanation":"The social model says disability results from the interaction between impairment and inaccessible environments: 'not the inability to walk, but the inaccessible stairs'.","lvl":2},{"type":"match","prompt":"Match each term to its definition.","pairs":[["Diagnostic overshadowing","Attributing psychological symptoms to a person's disability"],["Masking","Modifying neurodivergent traits to avoid exclusion"],["Identity concealment","Hiding a stigmatised identity; protective short-term but harmful when persistent"],["Neuro-affirming practice","Prioritising acceptance and autonomy over normalisation"]],"explanation":"Each concept links a population's experience to a practice implication."},{"type":"mc","prompt":"A psychologist asks a new client, 'What does your husband do?' Why does the module caution against this?","options":["It is too informal","It is not relevant to formulation","It breaches confidentiality","It assumes heterosexuality and a partner's gender, which can be invalidating"],"answer":3,"explanation":"Affirming care avoids assumptions about identity or partners and uses neutral language such as 'partner'.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Neuro-affirming practice encourages clinicians to reduce natural traits such as stimming.","wrong":"reduce","correct":"respect","explanation":"Psychologists should avoid pathologising stimming, monotropism or divergent communication, and support safe unmasking."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Neuro-affirming","Deficit-based"],"items":[{"text":"Co-developing goals that reflect the client's values","cat":0},{"text":"Using identity-first language when the client prefers it","cat":0},{"text":"Training a child to eliminate autistic traits for compliance","cat":1},{"text":"Accommodating sensory needs in the therapy room","cat":0},{"text":"Treating neurotypical behaviour as the standard to reach","cat":1}],"explanation":"Neuro-affirming practice prioritises acceptance, autonomy and collaboration, unlike historical approaches such as ABA aimed at normalisation."}]}]},{"week":11,"topic":"The Wounded Healer, Privilege and Power","summary":"Lived experience in practice, the privilege and power of psychology, and critical self-reflection on your own learning.","skills":[{"id":"HPS105-11.1","name":"Distinguish the wounded healer from the impaired practitioner","summary":"Separates the wounded healer from the impaired practitioner and names the benefits and risks of lived experience.","questions":[{"type":"match","prompt":"Match each term to its definition.","pairs":[["Wounded healer","Suffering reflected on and integrated so it informs compassionate practice"],["Impaired practitioner","Distress or circumstances adversely affect judgement or safe service"],["Countertransference","Emotional responses to a client shaped by the practitioner's own history"]],"explanation":"Confusing the wounded healer with the impaired practitioner can lead to unfair judgement or to missing genuine risk."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Benefit of lived experience","Risk of lived experience"],"items":[{"text":"Empathy","cat":0},{"text":"Overidentification","cat":1},{"text":"Hope","cat":0},{"text":"Boundary confusion","cat":1},{"text":"Humility","cat":0},{"text":"Avoidance of help-seeking","cat":1}],"explanation":"The four benefits are empathy, humility, hope and advocacy; the four risks are overidentification, countertransference, boundary confusion and avoidance of help-seeking."},{"type":"case","passage":"A psychologist who recovered from panic attacks assumes a new client's panic will respond to exactly the strategies that helped her.","prompt":"Which risk does this illustrate?","options":["Overidentification","Humility","Avoidance of help-seeking","Advocacy"],"answer":0,"explanation":"Overidentification means seeing too much of yourself in the client and losing sight of their distinct experience and needs.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Zerubavel and Wright describe woundedness as existing on a binary.","wrong":"binary","correct":"continuum","explanation":"Zerubavel and Wright stress that woundedness is on a continuum; the question is whether suffering is drawn on in service of healing."},{"type":"type_answer","prompt":"Which idea describes serious misconduct beginning with small boundary crossings and rationalisations, then moving gradually toward serious breaches?","answers":["slippery slope","the slippery slope"],"explanation":"Kremer and colleagues (2018) found misconduct often involved externalising responsibility and lack of objectivity.","lvl":3},{"type":"mc","prompt":"According to the key reframe, when does professional risk increase?","options":["When a practitioner discusses wellbeing in supervision","When a practitioner attends personal therapy","Whenever a practitioner has any lived experience","When a practitioner denies or hides a problem, refuses consultation or uses clients to meet personal needs"],"answer":3,"explanation":"Having a problem is not necessarily the problem; denial, secrecy and refusing consultation increase risk.","lvl":2}]},{"id":"HPS105-11.2","name":"Judge when practitioner self-disclosure is appropriate","summary":"Applies the principle that disclosure must serve the client, and chooses boundaried responses.","questions":[{"type":"case","passage":"Rebeka, a provisional psychologist with a history of adolescent depression, is asked by a young client, 'Have you ever felt like this?'","prompt":"Which response is most boundaried and client-centred?","options":["Refuse to answer and change the subject","Tell the client to ask her supervisor","Describe her own history in detail to build trust","'I have worked with many people who have felt overwhelmed and alone. What feels most important for me to understand about what it is like for you?'"],"answer":3,"explanation":"The boundaried response communicates understanding and returns to the client's experience, avoiding both over-disclosure and avoidance.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Helpful disclosure","Less helpful disclosure"],"items":[{"text":"Brief and purposeful","cat":0},{"text":"Lengthy and emotionally intense","cat":1},{"text":"Followed by a return to the client's experience","cat":0},{"text":"Used to seek reassurance or admiration from the client","cat":1},{"text":"Clinically relevant","cat":0},{"text":"Triggered by the practitioner's own activated memories","cat":1}],"explanation":"Disclosure should be brief, relevant and client-focused; disclosure that shifts attention to the practitioner can burden the client."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The key principle is that disclosure should be in the ___ best interests, not the practitioner's.","answers":["client's","clients","client"],"explanation":"Disclosure may model hope or reduce power differences, but only when it serves the client.","lvl":2},{"type":"mc","prompt":"After the session, what should Rebeka do about how strongly the client affected her?","options":["Transfer the client immediately","Nothing, as strong feelings show empathy","Reflect on why and discuss it in supervision","Contact the client's parents"],"answer":2,"explanation":"Without reflection and supervision, her empathy could slide into overidentification or overprotection.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Before self-disclosing, ask whether you have discussed this kind of disclosure with your partner.","wrong":"partner","correct":"supervisor","explanation":"The checklist asks whether you have discussed this kind of disclosure in supervision."},{"type":"analogy","prompt":"Over-disclosure is to shifting focus onto the practitioner as avoidance is to ___","options":["sharing too much detail","returning to the client","refusing the question out of shame","consulting a supervisor"],"answer":2,"explanation":"Rebeka's two unhelpful options were over-disclosing her history or avoiding the question, perhaps from shame.","lvl":3}]},{"id":"HPS105-11.3","name":"Analyse privilege and power in psychological practice","summary":"Explains how psychology perpetuates privilege through norms, access and research design, and how power operates through framing.","questions":[{"type":"case","passage":"Dr Taylor frames Amina's distress as poor boundaries and suggests she move out of home and reduce family involvement. Amina, a first-in-family student who helps care for siblings, nods politely and does not return.","prompt":"What went wrong?","options":["Dr Taylor should have set more goals","Dr Taylor treated Western independence as psychological health without exploring Amina's culture, finances and caregiving","Dr Taylor should have diagnosed her faster","Amina was resistant to therapy"],"answer":1,"explanation":"Power was exercised through framing: an individualistic model made some options seem healthy and others pathological.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Through norms","Through access","Through research design"],"items":[{"text":"Assuming direct eye contact always signals engagement","cat":0},{"text":"People with money obtaining timely private therapy","cat":1},{"text":"Relying on university student samples and English-language measures","cat":2},{"text":"Treating paid employment as the central marker of recovery","cat":0},{"text":"Flexible work hours making appointments easier to attend","cat":1}],"explanation":"Practice can perpetuate privilege by treating dominant norms as universal, through unequal access, and by generalising partial research."},{"type":"type_answer","prompt":"Which philosopher described knowledge and power as deeply connected, so that a profession's authority to classify and assess gives it influence over how people are treated?","answers":["Foucault","Michel Foucault"],"explanation":"Foucault's point applies to diagnosis, psychometric testing, risk assessment and treatment planning.","lvl":4},{"type":"mc","prompt":"Louis and colleagues (2014) describe a neutrality paradox. What is it?","options":["Fear of appearing biased can lead psychologists to avoid challenging the status quo, producing implicitly political work that presents as neutral","Psychologists must never discuss values","Psychology is openly political at all times","Neutral research is always unbiased"],"answer":0,"explanation":"Psychology can be an agent of social justice or of oppression depending on context, values and use of power.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Checking privilege means examining how your social position affects what you notice, and whether your decisions reproduce equal access, credibility or care.","wrong":"equal","correct":"unequal","explanation":"Checking privilege means examining how your social position affects what you notice and assume, and whether decisions reproduce unequal access or care."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Tang and colleagues stress that intersectionality should be used as a lens, not a ___ of identities.","answers":["checklist"],"explanation":"Intersectionality investigates complexity rather than listing identities.","lvl":3}]},{"id":"HPS105-11.4","name":"Apply critical self-reflection to your own learning","summary":"Uses critical self-reflection to identify barriers and facilitators, active engagement and appropriate use of generative AI.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Helpful use of generative AI","Riskier use of generative AI"],"items":[{"text":"Generating practice quiz questions, then checking answers","cat":0},{"text":"Asking it to write assessment responses","cat":1},{"text":"Explaining a difficult concept in simpler language","cat":0},{"text":"Using AI-generated references without checking them","cat":1},{"text":"Comparing two theories after your own attempt","cat":0},{"text":"Letting AI decide your argument","cat":1}],"explanation":"The reflective question is whether AI helped you learn or helped you avoid learning."},{"type":"case","passage":"A student can recognise every term on the lecture slides but cannot explain case formulation to a classmate without reading them.","prompt":"What does this suggest?","options":["Her engagement has been passive, producing a false sense of familiarity","She has mastered the content","The slides are inaccurate","She needs to highlight more"],"answer":0,"explanation":"The explain-it-to-a-peer test separates recognising content from understanding it; active engagement means doing something with the content.","lvl":2},{"type":"mc","prompt":"Which statement is a plan rather than a hope?","options":["'I will try harder.'","'I will be more organised next trimester.'","'Every Monday at 10am I will check my unit sites, update my task list and schedule two study blocks.'","'I will stop procrastinating.'"],"answer":2,"explanation":"A strong plan is specific and realistic; vague intentions are hopes.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The module recommends reading the rubric after drafting an assessment, as a final check.","wrong":"after","correct":"before","explanation":"Many students open the rubric too late; using it as a planning tool from the beginning avoids a mismatch with the task."},{"type":"type_answer","prompt":"What test asks whether you can explain and defend every sentence in your assessment, to check AI has not moved into substitution?","answers":["defensibility test","the defensibility test"],"explanation":"If you cannot defend a sentence, AI may have replaced rather than supported your learning.","lvl":4},{"type":"match","prompt":"Match each reflection to whether it is useful or unhelpful.","pairs":[["'I am lazy.'","Too global and judgemental to act on"],["'I avoided starting because I did not understand the task and felt embarrassed to ask.'","Identifies a barrier and points to a strategy"],["'These experiences are data, not failures.'","Reframes setbacks as information about how you learn"]],"explanation":"Critical self-reflection should be honest but not self-punishing, turning discomfort into information and information into action."}]}]}]};
window.LAMPLIGHT_UNITS["MMK266"] = {"code":"MMK266","name":"Consumer Behaviour","term":"T2 2026","weeks":10,"weekList":[{"week":1,"topic":"Motivation","summary":"Motivation as direction (goals and goal hierarchies) plus drive (need discrepancies and the compensatory strategies consumers use to handle them).","skills":[{"id":"MMK266-1.1","name":"Distinguish motivational direction from motivational drive","summary":"You can tell whether a message or behaviour reflects what a consumer wants (direction) or how strongly they pursue it (drive).","questions":[{"type":"mc","prompt":"In the lecture's car analogy, motivation that has drive but no direction is most like which situation?","options":["A car with no steering wheel","A car parked in the wrong garage","A car with an empty fuel tank but working steering","A car with the engine switched off"],"answer":0,"explanation":"Direction is the steering: without goals, drive has nowhere to go. A car with the engine off is the opposite case, direction without drive.","lvl":2},{"type":"case","passage":"A phone brand's ad opens with a commuter whose battery dies at 3pm, leaving her stranded and anxious. Only in the final seconds does it show the new phone lasting two days.","prompt":"Which part of 'make 'em sick, make 'em well' is the opening scene doing?","options":["Highlighting a need discrepancy to create drive","Demonstrating direction by showing the offering","Activating a subordinate goal through priming","Showing need satisfaction to build loyalty"],"answer":0,"explanation":"The opening highlights the gap between current and desired states, which is the source of motivational drive. The closing shot supplies direction by showing the offering resolves it.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Motivational drive arises from need ___, the gap between a consumer's actual and ideal level of fulfilment for a need.","answers":["discrepancies","discrepancy"],"explanation":"A need discrepancy is the gap between the current state and the desired state, and it is aversive, which is why it energises behaviour.","lvl":3},{"type":"type_answer","prompt":"What term describes the state in which a consumer's actual level of need fulfilment matches their ideal level?","answers":["need satisfaction","satisfaction"],"explanation":"When current and desired states match there is no discrepancy, so there is need satisfaction and no drive to act.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Direction","Drive"],"items":[{"text":"A commitment to approach getting a good job","cat":0},{"text":"Anxiety about falling behind smarter colleagues","cat":1},{"text":"Choosing a streaming service as a way to relax","cat":0},{"text":"Rumination and discomfort caused by an unmet need","cat":1},{"text":"A cognitive representation of a future state to avoid, such as getting fired","cat":0},{"text":"The gap between current and ideal fulfilment of a need","cat":1}],"explanation":"Goals and their hierarchies give motivation direction. Need discrepancies, and the aversive thoughts, feelings and physiology they produce, give it drive."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Elliot and Niesta (2009) define a goal as an emotional representation of a future object that an organism is committed to approach or avoid.","wrong":"emotional","correct":"cognitive","explanation":"A goal is a cognitive representation of a future object. It also requires conscious commitment, otherwise it is only a wish or fantasy."}]},{"id":"MMK266-1.2","name":"Classify goals as superordinate, focal or subordinate","summary":"You can place any goal in a hierarchy and explain what WHY, WHAT and HOW questions each level answers.","questions":[{"type":"match","prompt":"Match each goal level to the question it answers.","pairs":[["Superordinate goal","WHY we pursue focal goals"],["Focal goal","WHAT we plan to achieve"],["Subordinate goal","HOW we pursue focal goals"]],"explanation":"Superordinate goals fulfil fundamental needs (why), focal goals are what we are trying to achieve now, and subordinate goals are the means (how)."},{"type":"order","prompt":"Put the lecture's goal hierarchy in order from most abstract to most concrete.","items":["Hedonism","Relax","Watch a movie","Streaming service"],"explanation":"Hedonism is the superordinate goal, relaxing is focal, and watching a movie via a streaming service are progressively more concrete subordinate means."},{"type":"mc","prompt":"At which level of a goal hierarchy do market offerings usually appear?","options":["Subordinate goals","Superordinate goals","Focal goals","Outside the hierarchy entirely"],"answer":0,"explanation":"Market offerings are usually the means to higher-level ends, so they sit at the subordinate (HOW) level.","lvl":3},{"type":"case","passage":"Mia has committed to 'getting fit this year'. She is deciding between a gym membership and a road bike. Underneath it all she wants others to see her as successful.","prompt":"Which of these is Mia's focal goal?","options":["Buying a road bike","Getting fit this year","Joining a gym","Being recognised as successful"],"answer":1,"explanation":"Getting fit is WHAT she plans to achieve (focal). Being seen as successful is the superordinate WHY (achievement), and the gym or bike are subordinate means.","lvl":3},{"type":"mc","prompt":"Which statement about superordinate goals is consistent with the Week 1 notes?","options":["Everyone holds the same mix, so they are useless for segmentation","Consumers are usually fully aware of their superordinate goals","Marketers cannot change them but can activate latent ones and align offerings with them","Marketers can readily change a consumer's superordinate goals"],"answer":2,"explanation":"Superordinate goals fulfil fundamental needs and are often hidden from us. Because everyone's mix differs they support segmentation, and marketers work by activating and aligning with them.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Symons (1992) argued that human behaviour is flexible, but this flexibility is of means, not ___.","answers":["ends"],"explanation":"Lower-level goals (means) are interchangeable, while the higher-level ends they serve are relatively fixed.","lvl":4}]},{"id":"MMK266-1.3","name":"Apply means-ends analysis to laddering chains","summary":"You can code interview answers as attributes, consequences or values and read what aligned or misaligned chains mean for strategy.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Attribute","Consequence","Value"],"items":[{"text":"Freedom to choose what to watch","cat":0},{"text":"Suits my mood","cat":1},{"text":"Hedonism","cat":2},{"text":"Large back catalogue","cat":0},{"text":"Can't decide what to watch","cat":1},{"text":"Achievement","cat":2}],"explanation":"Attributes are tangible or intangible features (Level 1), consequences are perceived outcomes (Level 2), and values are the underlying needs or Schwartz values (Level 3)."},{"type":"order","prompt":"Put the levels of a laddering chain in order from Level 1 to Level 3.","items":["Attribute","Consequence","Value"],"explanation":"Means-ends analysis links attributes of an offering to their consequences, and those consequences to the values (superordinate goals) they satisfy."},{"type":"case","passage":"In a laddering interview a Netflix user says: 'There's a huge back catalogue, so I can never decide what to watch, and I end up stressed.'","prompt":"According to the notes, what kind of opportunity does this misaligned chain reveal?","options":["A reason to classify 'stressed' as an attribute","Evidence that the consumer's superordinate goal is achievement","A positioning opportunity to advertise the catalogue size","A competitive-advantage opportunity, such as better recommendation algorithms"],"answer":3,"explanation":"Misalignment between an attribute and a consumer's goals reveals competitive-advantage opportunities, which is why streaming firms invest billions in recommendation algorithms. Aligned chains reveal positioning opportunities.","lvl":4},{"type":"type_answer","prompt":"What name is given to the connections between attributes, consequences and values in means-ends analysis?","answers":["laddering chains","laddering chain","ladders"],"explanation":"Each attribute to consequence to value link is a laddering chain, and mapping many chains produces a hierarchical value map.","lvl":4},{"type":"order","prompt":"Put the three components of Assignment 1's means-ends analysis in the order they are completed.","items":["Laddering interviews","Content analysis","Hierarchical value map construction"],"explanation":"You first interview (repeated 'why is that important to you?' questions), then code the data, then map the chains into a hierarchical value map."},{"type":"analogy","prompt":"'Freedom to choose' is to attribute as 'suits my mood' is to ___","options":["focal goal","superordinate goal","consequence","value"],"answer":2,"explanation":"'Suits my mood' is a perceived outcome of the attribute, so it is a Level 2 consequence that then links to the value of hedonism.","lvl":3}]},{"id":"MMK266-1.4","name":"Explain equifinality, multifinality and dynamic goals","summary":"You can recognise each feature of goal hierarchies and state its implication for commitment, messaging and change over time.","questions":[{"type":"case","passage":"Ella's focal goal tonight is to relax. When the movie she planned to stream will not load, she simply runs a bath instead, and she knows reading or a walk would also work.","prompt":"Which feature of goal hierarchies does this illustrate?","options":["Multifinality","Dynamic goals","Symbolic self-completion","Equifinality"],"answer":3,"explanation":"Equifinality means several interchangeable means connect to the same end, so a failed means can be substituted. The trade-off is lower commitment to any single means.","lvl":4},{"type":"mc","prompt":"The aerobic-exercise study found that exercise promoted with one benefit was seen as more effective than exercise promoted with two. What is the marketing implication?","options":["Always list as many benefits as possible","Benefits do not matter once a goal is dynamic","Firms often 'hero' a single benefit because multifinality dilutes each connection","Link the offering to many ends to boost equifinality"],"answer":2,"explanation":"Multifinality gives a bigger bang for your buck, but linking a means to many ends weakens each link, so brands often lead with one hero benefit.","lvl":3},{"type":"match","prompt":"Match each feature of goal hierarchies to its definition.","pairs":[["Equifinality","Several interchangeable means connect to the same end"],["Multifinality","One means satisfies multiple goals"],["Dynamic","Goals change over time"]],"explanation":"These are the three further features of goal hierarchies. Dynamic change is driven by success or failure, technology, social influence, economic conditions, life stage and marketing."},{"type":"order","prompt":"Put the lawn case study's goal meanings in chronological order.","items":["Wealth status symbol in 17th to 18th century England","Accessible middle-class status with push mowers","'Good neighbour' conformity with motor mowers","'Weed-free equals houseproud' achievement in the 1950s","Eco-conscious lawn replacement from the 1970s"],"explanation":"The lawn shows goals are dynamic: the same feature has served power, status, conformity, achievement and then universalism (nature) goals over time."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"As equifinality rises, the higher goal is more likely to be achieved, but commitment to any single means grows.","wrong":"grows","correct":"falls","explanation":"Having many substitutable means protects the higher goal but reduces commitment to each individual means."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"One means satisfying several goals at once, giving 'a bigger bang for your buck', is called ___.","answers":["multifinality"],"explanation":"Multifinality is the reverse of equifinality: one means to many ends rather than many means to one end.","lvl":3}]},{"id":"MMK266-1.5","name":"Identify compensatory strategies for need discrepancies","summary":"You can classify a consumer's response to a threatened need into the five strategies and predict its effect on consumption.","questions":[{"type":"match","prompt":"Match each compensatory strategy to what the persona Roger does.","pairs":[["Direct resolution","Reads and studies to become more intelligent"],["Symbolic self-completion","Hangs his degree in his office"],["Dissociation","Cancels his Economist subscription"],["Fluid compensation","Buys a Rolex to affirm his success"]],"explanation":"Direct resolution tackles the source, symbolic self-completion signals mastery, dissociation avoids domain purchases, and fluid compensation reaffirms worth in a different domain."},{"type":"case","passage":"After an awkward dinner party where her cooking was criticised, Priya stops buying cookbooks and cancels her subscription to a food magazine.","prompt":"Which compensatory strategy is Priya using?","options":["Escapism","Symbolic self-completion","Direct resolution","Dissociation"],"answer":3,"explanation":"Dissociation means avoiding purchases tied to the threatened domain so the discrepancy is not activated. It is the one strategy that decreases consumption.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Tends to increase consumption","Tends to decrease consumption"],"items":[{"text":"Direct resolution","cat":0},{"text":"Symbolic self-completion","cat":0},{"text":"Dissociation","cat":1},{"text":"Escapism (short-lived)","cat":0},{"text":"Fluid compensation","cat":0}],"explanation":"Four of the five strategies increase consumption (escapism only briefly). Dissociation decreases it because the consumer avoids the domain altogether."},{"type":"mc","prompt":"Some drivers respond to confronting TAC road-safety ads by switching channels and binge-watching comedy. Which strategy interferes with the TAC's goals here?","options":["Fluid compensation","Escapism","Symbolic self-completion","Direct resolution"],"answer":1,"explanation":"Escapism distracts attention from the source of the discrepancy, so the threat is ignored rather than resolved, undermining the campaign.","lvl":2},{"type":"type_answer","prompt":"Which compensatory strategy can marketers most reliably leverage, by showing their offering resolves the discrepancy?","answers":["direct resolution"],"explanation":"Direct resolution is the strategy marketers lean on most, although they must understand all five because some work against strategic goals.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In dissociation, the consumer avoids purchases tied to the threatened domain, which increases consumption in that domain.","wrong":"increases","correct":"decreases","explanation":"Dissociation keeps the need discrepancy from being activated by avoiding the domain, so consumption there falls."}]}]},{"week":2,"topic":"Superordinate Goals","summary":"The 19 Schwartz values as types of superordinate goals, and three ways to leverage them: demonstrating need discrepancy, aligning offerings, and priming.","skills":[{"id":"MMK266-2.1","name":"Classify Schwartz values by type and dimension","summary":"You can name the value behind a consumer's motive and place it on the growth versus self-protection and personal versus social dimensions.","questions":[{"type":"match","prompt":"Match each Simpsons character to the Schwartz value the lecture used them to illustrate.","pairs":[["Bart","Stimulation"],["Mr Burns","Power (resources)"],["Principal Skinner","Face"],["Marge","Benevolence (caring)"]],"explanation":"Stimulation is excitement and novelty, power (resources) is control via wealth, face is maintaining public image, and benevolence (caring) is protecting the in-group's welfare."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Growth","Self-protection"],"items":[{"text":"Stimulation","cat":0},{"text":"Hedonism","cat":0},{"text":"Face","cat":1},{"text":"Security (personal)","cat":1},{"text":"Benevolence (caring)","cat":0},{"text":"Tradition","cat":1}],"explanation":"Growth values motivate when people are anxiety-free, while self-protection values guard against anxiety. Achievement and humility straddle both, so they are left out here."},{"type":"case","passage":"When choosing a car, Leanne's main concern is avoiding anything that might make her look foolish in front of neighbours or colleagues. She wants to maintain her public image.","prompt":"Which Schwartz value is most implicated?","options":["Conformity (interpersonal)","Face","Power (dominance)","Humility"],"answer":1,"explanation":"Face is the desire to maintain one's public image and avoid humiliation. Conformity (interpersonal) is about not upsetting others, which is a different motive.","lvl":3},{"type":"mc","prompt":"Which of these Schwartz values has a social rather than personal focus?","options":["Power (resources)","Hedonism","Conformity (rules)","Achievement"],"answer":2,"explanation":"Conformity (rules) concerns complying with rules and obligations owed to others and institutions, so it is social focus. The other three concern outcomes for the self.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Everyone weights the Schwartz values identically, which is why the values are a useful basis for segmentation.","wrong":"identically","correct":"differently","explanation":"People weight the values differently because of genetics, upbringing, class and culture, and that variation is what makes them useful for segmentation."},{"type":"type_answer","prompt":"Which Schwartz value describes the desire to protect and preserve the natural environment?","answers":["universalism (nature)","universalism nature","universalism-nature","universalism"],"explanation":"Universalism (nature) is a social-focus growth value, illustrated by Lisa Simpson.","lvl":3}]},{"id":"MMK266-2.2","name":"Demonstrate need discrepancy to activate superordinate goals","summary":"You can design or critique a message that brings a specific discrepancy into focus, and spot when it will fail.","questions":[{"type":"mc","prompt":"Why does demonstrating a specific need discrepancy increase the chance a consumer acts?","options":["It changes the consumer's superordinate goals","It removes the need for the offering to show direction","It works regardless of which goals the consumer holds","Consumers hold more discrepancies than they can focus on, so it brings one into focal attention"],"answer":3,"explanation":"We cannot attend to every discrepancy at once, so showing the gap between current and desired states brings one to focal attention and drives action.","lvl":3},{"type":"case","passage":"A conservation charity runs two ads. Ad A shows a river choked with plastic. Ad B shows a pristine rainforest with the line 'Keep it this way'.","prompt":"Which statement best describes the two ads?","options":["Ad A emphasises the current state and Ad B emphasises the desired state","Both ads are examples of semantic priming only","Only Ad B demonstrates a need discrepancy","Ad A targets hedonism and Ad B targets power"],"answer":0,"explanation":"Ads can demonstrate a discrepancy by emphasising either side of the gap, for example 'harming nature' (current) versus 'protecting nature' (desired).","lvl":2},{"type":"case","passage":"A fitness brand's campaign shows elite athletes with physiques most viewers feel they could never achieve. Sales fall and research shows viewers now avoid fitness content.","prompt":"What is the most likely explanation from the notes?","options":["The desired state seemed unattainable, so consumers used non-purchase compensatory strategies","The ad failed to create any need discrepancy","The consumers did not hold any superordinate goals","Priming effects are always long-lived"],"answer":0,"explanation":"If the desired state seems unattainable, consumers may turn to dissociation, escapism or fluid compensation rather than buying the offering.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Demonstrating a need discrepancy only works if the consumer already holds the overarching ___ goal.","answers":["superordinate"],"explanation":"Marketers cannot create superordinate goals, so the message must connect to one the consumer already holds.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Emphasises current state","Emphasises desired state"],"items":[{"text":"Images of a polluted, lifeless river","cat":0},{"text":"A child breathing clean mountain air","cat":1},{"text":"A stressed worker still at their desk at 2am","cat":0},{"text":"A relaxed family laughing on holiday","cat":1},{"text":"A cracked, dry lawn in drought","cat":0}],"explanation":"Both sides of the gap can demonstrate a discrepancy: showing the problem now (current) or the state consumers want to reach (desired)."},{"type":"analogy","prompt":"'Harming nature' is to current state as 'protecting nature' is to ___","options":["need satisfaction","subordinate goal","desired state","focal goal"],"answer":2,"explanation":"The lecture's example contrasts messages that emphasise the current state with those that emphasise the desired state.","lvl":1}]},{"id":"MMK266-2.3","name":"Align offerings with goals at category, sub-category and brand level","summary":"You can decide whether a brand should promote category-level or brand-unique goals based on category demand.","questions":[{"type":"order","prompt":"Put these offering goals in order from least to most specific.","items":["Buy a car","Buy a low-emissions car","Buy a Tesla"],"explanation":"Offering goals run from category to sub-category to brand. If hierarchically structured, achieving the brand goal also achieves the higher ones."},{"type":"mc","prompt":"In a consistent-demand category such as cars, alcohol or clothing, what should a brand emphasise?","options":["The unique superordinate goals its brand satisfies","The sub-category goals of its competitors","The category-level goals all brands satisfy","Only price and availability"],"answer":0,"explanation":"Category goals are satisfied by every brand in consistent-demand categories, so brands emphasise the unique superordinate goals they satisfy, such as Tesla's speed and stimulation.","lvl":3},{"type":"case","passage":"A start-up launches the first affordable home robot lawnmower in Australia. Few consumers have ever considered buying one.","prompt":"Based on the Week 2 notes, what messaging focus is most appropriate?","options":["The superordinate goals attached to the category or sub-category","Competitor weaknesses in the petrol mower market","Brand-unique goals only, ignoring the category","Nonconscious priming only, with no product claims"],"answer":0,"explanation":"In limited-demand categories and new innovations, brands (usually the leader) may focus on the superordinate goals of the category or sub-category, because demand for the category itself must be built.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Consistent-demand category","Limited-demand category"],"items":[{"text":"Cars","cat":0},{"text":"Alcohol","cat":0},{"text":"Clothing","cat":0},{"text":"Electric cars","cat":1},{"text":"A brand-new product innovation","cat":1}],"explanation":"Consistent-demand categories have diverse sub-categories and steady demand. Electric cars and new innovations have limited demand, so category-level goals matter more."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In consistent-demand categories, brands emphasise category-level goals because those goals are satisfied by all brands.","wrong":"emphasise","correct":"ignore","explanation":"Because all brands satisfy category goals, promoting them gives no advantage, so brands ignore them and stress their unique superordinate goals."},{"type":"type_answer","prompt":"In the Tesla example, which Schwartz value does the brand's speed satisfy?","answers":["stimulation"],"explanation":"Tesla being fast links the brand to stimulation (excitement, novelty and challenge), a goal other car brands may not satisfy as well.","lvl":3}]},{"id":"MMK266-2.4","name":"Explain semantic priming and its limits","summary":"You can explain how spreading activation primes latent goals and predict when priming will fail or backfire.","questions":[{"type":"fill_gap","prompt":"Complete the sentence.","text":"Activating the concept 'trees' also activates 'green', 'nature' and 'mountains' through spreading ___.","answers":["activation"],"explanation":"In semantic priming the mind links concepts by meaning, so activating one spreads activation to related concepts.","lvl":2},{"type":"case","passage":"Hahnel et al. (2014) showed consumers images of nature or of buildings before asking about electric cars. The nature images improved perceptions, but only for people with moderate universalism (nature).","prompt":"Why did the effect not appear for people already high in universalism (nature)?","options":["They were already positive, so there was little room to move","They sensed covert manipulation","They did not hold the goal at all","Nature images only work across the sense of smell"],"answer":0,"explanation":"Priming activates latent goals. Those already high in the value were already positive toward electric cars, so priming added little.","lvl":3},{"type":"mc","prompt":"Which statement is NOT one of the priming caveats in the notes?","options":["It works best when consumers do not yet hold the goal","Consumers who sense covert manipulation react against the goal","It only works if consumers already hold the goal","Its effects are usually short-lived"],"answer":0,"explanation":"Priming cannot create a goal; it only activates one the consumer already holds, so the last option contradicts the notes.","lvl":3},{"type":"case","passage":"A cleaning brand adds a lemon scent to its spray, uses yellow packaging with sparkling kitchen imagery, and names the range 'Fresh Start'.","prompt":"Which priming principle is the brand applying?","options":["Cues only work through vision","More related cues across senses raise the chance of priming the target goal","Priming effects last for years","A single cue always outperforms several"],"answer":1,"explanation":"Cues work across all senses (a lemon scent activates cleanliness goals), and more related cues increase the chance of priming the target goal.","lvl":2},{"type":"type_answer","prompt":"What type of priming links related concepts in memory by meaning?","answers":["semantic priming","semantic"],"explanation":"Semantic priming is the key type in the unit and it works through spreading activation between meaningfully related concepts.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Raises the chance priming works","Lowers the chance priming works"],"items":[{"text":"The consumer already holds the target goal","cat":0},{"text":"Several related cues are used together","cat":0},{"text":"The consumer senses covert manipulation","cat":1},{"text":"The consumer does not hold the goal at all","cat":1},{"text":"A scent congruent with the goal, such as lemon for cleanliness","cat":0}],"explanation":"Priming needs an existing goal and benefits from multiple related cues across senses. Suspected covert manipulation triggers reactance against the goal."}]}]},{"week":3,"topic":"Search","summary":"Internal search through the nested set model and consideration sets, and external search through sensation, attention, perception (touch), comprehension and associative networks.","skills":[{"id":"MMK266-3.1","name":"Classify offerings into the nested set model","summary":"You can place any brand a consumer mentions into the universal, awareness, consideration, inept or inert set.","questions":[{"type":"case","passage":"Sam knows of 12 shampoo brands. Three come to mind as suitable for his dry scalp. One he tried last year and hated. Two he has heard of but never really thought about.","prompt":"The brand Sam tried and hated belongs to which set?","options":["Inept set","Inert set","Consideration set","Unawareness set"],"answer":0,"explanation":"The inept set holds offerings perceived as unable to satisfy the goal, for example because of prior unfavourable experience. The two he has not thought about are inert.","lvl":3},{"type":"match","prompt":"Match each set to what it contains.","pairs":[["Universal set","Every conceivable offering available in the category"],["Awareness set","Offerings the consumer knows about"],["Consideration set","Known offerings perceived as able to satisfy the goal"],["Inert set","Known offerings the consumer has not given much thought"]],"explanation":"The sets are nested. The consideration set is the most important because choice is made from it."},{"type":"order","prompt":"Put these sets in order from largest to smallest.","items":["Universal set","Awareness set","Consideration set","Choice set"],"explanation":"Each set is a subset of the one before. Shocker et al. (1991) define the choice set as the final consideration set immediately before choice."},{"type":"mc","prompt":"Shocker et al. (1991) note a gift-giving goal can put cameras, watches and pens in competition. What does this show about consideration sets?","options":["They must contain brands from one product class","They only include market offerings","They are goal-driven, so members can span different categories","They are fixed across occasions"],"answer":2,"explanation":"Because the consideration set is built around a goal, any goal-relevant option can enter it, like the lecture's dinner example of cooking, a restaurant or Uber Eats.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Narayana and Markin describe the inert set as brands the customer is aware of but would not buy because of prior unfavourable experience.","wrong":"inert","correct":"inept","explanation":"That definition belongs to the inept set. The inert set is brands the customer is aware of but has not processed or seriously considered."},{"type":"mc","prompt":"According to Shocker et al., how do consumers typically move from awareness to choice?","options":["Only compensatory rules are used at every stage","Choice is random once the awareness set forms","Non-compensatory rules filter what gets considered, then compensatory trade-offs evaluate the reduced set","Compensatory trade-offs decide entry, then non-compensatory rules pick the winner"],"answer":2,"explanation":"This matches 'phased' decision strategies: filter with simple necessary criteria first, then analyse the smaller set in detail with trade-offs.","lvl":4}]},{"id":"MMK266-3.2","name":"Explain consideration-set size using satisficing","summary":"You can predict why consideration sets are large or small in a category by weighing benefit against search cost.","questions":[{"type":"match","prompt":"Match each category to its average consideration-set size.","pairs":[["Air fresheners","2.2 brands"],["Laundry detergents","4 brands"],["Financial services","1 brand"]],"explanation":"Set size reflects the trade-off between the benefit of considering one more option and the search cost of doing so."},{"type":"case","passage":"Research shows most Australians consider only one brand when choosing a superannuation fund, even though the product is complex and the stakes are high.","prompt":"According to the notes, what is the pointed implication for market-leading funds?","options":["They have little incentive to simplify or compete on quality, and can instead invest in brand salience","They should enlarge consumers' consideration sets","They must lower prices to enter the awareness set","They must simplify products to survive"],"answer":0,"explanation":"Financial services have very high search costs, heavy regulation and distant benefits, so sets stay at about one brand. Leaders can win simply by being the brand that comes to mind.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Settling for an option that is 'good enough' rather than searching for the absolute best is called ___.","answers":["satisficing"],"explanation":"Because processing is limited and most products cluster around a base quality, the gap to the best option is usually not worth the extra effort.","lvl":2},{"type":"mc","prompt":"Why is the average consideration set for laundry detergent larger than for air freshener?","options":["Consumers are more loyal to detergent brands","Detergent has more salient attributes, so there is more benefit from considering extra brands at a similar search cost","Air fresheners have higher search costs than any other category","Detergent is always cheaper"],"answer":1,"explanation":"Air fresheners have few salient attributes (cost, brand, fragrance), whereas detergents vary on stain removal, machine type, temperature and colour care.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The benefit of evaluating another offering shows increasing returns, because most products cluster around a base quality.","wrong":"increasing","correct":"diminishing","explanation":"Since most products are similar in quality, each extra option adds less benefit, which is why consumers stop searching early."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Pushes the set larger","Pushes the set smaller"],"items":[{"text":"Many salient attributes that differ between brands","cat":0},{"text":"Very high mental effort to compare options","cat":1},{"text":"Benefits that only arrive far in the future","cat":1},{"text":"Low search cost to compare brands","cat":0},{"text":"A notoriously complex, heavily regulated product","cat":1}],"explanation":"More benefit from comparing enlarges sets. Higher search costs and discounted future benefits shrink them, as in financial services."}]},{"id":"MMK266-3.3","name":"Apply attention techniques to win consumer attention","summary":"You can identify and apply contrast with competing stimuli, contrast with expectations, and alignment with motivations.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Contrast with competing stimuli","Contrast with expectations","Align with motivations"],"items":[{"text":"Olay's almost entirely white 'undo' ad among colourful cosmetics ads","cat":0},{"text":"DHL's semi-transparent page within a print ad spread","cat":0},{"text":"McDonald's 2017 Sydney concept store","cat":1},{"text":"Deakin concentrating ad spend around ATAR results release","cat":2},{"text":"Gift ads placed just before Christmas","cat":2},{"text":"Business-spending ads before the end of financial year","cat":2}],"explanation":"Contrast with competing stimuli stands out from nearby ads, contrast with expectations beats habituation to familiar formats, and alignment with motivations times messages to heightened goal relevance."},{"type":"case","passage":"Ridiculously Delicious sells premium peanut butter made from 100% Australian-grown peanuts. Supermarket shelves are dominated by jars with bright yellow lids and labels.","prompt":"Which packaging refresh best applies contrast with competing stimuli while staying consistent with a premium price?","options":["A matte black jar with minimal gold type and a small map of Queensland","Copying the Kraft peanut device","A bright yellow lid and label to match the category","A cheaper-looking plastic tub to signal value"],"answer":0,"explanation":"Contrast with competing stimuli means standing apart from what surrounds the product. A dark, minimal jar stands out on a yellow shelf and signals premium quality.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The brain ignoring stimuli it has seen again and again is called ___.","answers":["habituation"],"explanation":"Contrast with expectations counters habituation, which is why a traditional store is easily ignored but an unexpected concept store recaptures attention.","lvl":2},{"type":"mc","prompt":"Which statement about attention is consistent with the notes?","options":["Attention is unlimited, so ad clutter does not matter","Attention is limited, selective and divisible, though multitasking is overstated","Attention cannot be directed toward goals","Once an ad is good, winning attention is unnecessary"],"answer":1,"explanation":"Attention filters sensory overload, can be directed at goals, and can be split, but multitasking is overstated. If you cannot win attention, ad quality does not matter.","lvl":2},{"type":"type_answer","prompt":"According to the notes, what is the common thread across all the techniques for winning attention?","answers":["creativity"],"explanation":"We attend to novel, interesting things, so every technique relies on creativity.","lvl":4},{"type":"analogy","prompt":"Olay's white 'undo' ad is to contrast with competing stimuli as McDonald's Sydney concept store is to ___","options":["source identification","symbolic contamination","contrast with expectations","aligning with motivations"],"answer":2,"explanation":"The concept store subverts what consumers expect a McDonald's to look like, countering habituation.","lvl":4}]},{"id":"MMK266-3.4","name":"Apply touch research to perception and purchase","summary":"You can use findings on diagnosticity, ownership, contamination, weight and interpersonal touch to advise a retailer.","questions":[{"type":"case","passage":"An online fashion retailer finds shoppers hesitate because they cannot feel fabrics before buying.","prompt":"According to the notes, what has allowed clothing to shift online despite touch being diagnostic for it?","options":["Using interpersonal touch in delivery","Clearly promoted returns policies that act as a touch-proxy","Heavier packaging","Removing product photos"],"answer":1,"explanation":"Returns policies let consumers still touch the item before deciding to keep it, which reduces the barrier for touch-diagnostic categories.","lvl":2},{"type":"mc","prompt":"Why do clothing stores keep tried-on items separate from items on the shop floor?","options":["Because touch is not diagnostic for clothing","To lower oxytocin in shoppers","To avoid symbolic contamination, where seeing others touch a product reduces its perceived newness","To increase perceived ownership by other shoppers"],"answer":2,"explanation":"Seeing another person touch a product transfers a sense of their 'essence' and lowers purchase likelihood, so trial and purchase are separated, as with dedicated test-drive cars.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Bang & Olufsen deliberately make their remotes lighter, because when weight is not diagnostic, heavier products are perceived as higher quality.","wrong":"lighter","correct":"heavier","explanation":"B&O weights its remotes on purpose: extra weight suggests more materials and higher quality, which supports a premium price."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Touch is diagnostic","Touch is not diagnostic"],"items":[{"text":"Clothing","cat":0},{"text":"Bed linen","cat":0},{"text":"Books","cat":1},{"text":"Bath towels","cat":0},{"text":"A boxed board game","cat":1}],"explanation":"Touch is diagnostic for products that touch the skin, where feel varies. For products like books there is little tactile variation, which is why they sold well online early."},{"type":"match","prompt":"Match each touch finding to its source or concept.","pairs":[["Instrumental need for touch","Touching to check a product before buying"],["Autotelic need for touch","Touching for its own sake, for fun or emotion"],["Williams and Bargh (2008)","Holding hot coffee made a target seem warmer"],["Argo, Dahl and Morales (2006)","A t-shirt seemed less appealing if others had touched it"]],"explanation":"Peck and Childers' NFT scale has instrumental and autotelic subscales, while the other two studies show physical-to-interpersonal warmth and the contamination effect."},{"type":"case","passage":"A French department store opening in London trains staff to touch customers lightly on the arm, citing research that interpersonal touch increases evaluations and compliance.","prompt":"What is the main risk according to the notes?","options":["Hand touch is less acceptable than touching the face","Touch only works through smell","Appropriateness of touch is strongly cultural; a café study counted 0 touches per hour in London","Interpersonal touch always reduces tips"],"answer":2,"explanation":"Touch lowers cortisol and raises oxytocin, but norms vary greatly (San Juan 189, Paris 110, London 0 per hour), and with strangers only hands, and to a lesser degree arms, feel acceptable.","lvl":3}]},{"id":"MMK266-3.5","name":"Distinguish comprehension outcomes and semantic vs episodic memory","summary":"You can classify how consumers interpret a message and how comprehended information is stored for later internal search.","questions":[{"type":"case","passage":"A Listerine ad reads 'If you can see this, please back off'. One viewer concludes that Listerine must taste disgusting.","prompt":"What has occurred?","options":["Objective comprehension","Symbolic self-completion","Miscomprehension","Source identification"],"answer":2,"explanation":"The firm intended 'avoid bad breath and embarrassment'. Failing to take that meaning, and forming another, is miscomprehension.","lvl":2},{"type":"match","prompt":"Match each comprehension outcome to its definition.","pairs":[["Objective comprehension","The consumer takes the firm's intended meaning"],["Miscomprehension","The consumer fails to take the intended meaning"],["Subjective comprehension","Extra meanings the consumer adds, intended or not"]],"explanation":"In the shark-conservation ad, 'a world without sharks is scarier' is objective, 'not knowing where the shark is' is miscomprehension, and 'a world with no animals' is subjective."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Semantic storage","Episodic storage"],"items":[{"text":"McDonald's linked in memory to KFC and Domino's","cat":0},{"text":"Recalling last night's McDonald's dinner and who you went with","cat":1},{"text":"McDonald's linked to its charity work","cat":0},{"text":"Remembering how the staff treated you on that visit","cat":1}],"explanation":"Semantic memory stores information with conceptually related concepts, where perceptual maps reside. Episodic memory stores what we did, when, with whom and why."},{"type":"mc","prompt":"Which past experiences are most durable in episodic memory?","options":["Experiences that exactly met expectations","Experiences that notably exceeded or fell below expectations","Experiences with no emotional content","Routine experiences repeated many times"],"answer":1,"explanation":"Experiences that merely meet expectations fade fastest (a habituation effect), while those well above or below expectations are more durable.","lvl":2},{"type":"case","passage":"Kim Kardashian posts on Instagram about a morning-sickness medication, with a 'US residents only' disclaimer. Many followers read it as a personal recommendation.","prompt":"Which comprehension focus does this example chiefly illustrate?","options":["Episodic memory","Sensation","Source identification","Message comprehension"],"answer":2,"explanation":"Source identification asks whether a stimulus is a firm's marketing or an independent opinion, and influencer posts and product placement increasingly blur the line.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Comprehended information that is stored alongside conceptually related information is stored ___.","answers":["semantically","semantic"],"explanation":"Semantic storage connects new information to related concepts or changes connection strength, which links to semantic priming from Week 2.","lvl":3}]}]},{"week":4,"topic":"Evaluation: Attitude","summary":"How attitudes form through evaluative integration of salient beliefs, how to change them, why strong attitudes resist change, and how the Elaboration Likelihood Model predicts persuasion routes.","skills":[{"id":"MMK266-4.1","name":"Explain how salient beliefs integrate into an attitude","summary":"You can predict a consumer's overall attitude from their salient beliefs and the superordinate goals those beliefs implicate.","questions":[{"type":"case","passage":"Frankie values universalism (concern) and stimulation, weighting stimulation more heavily. She believes Country Road is ethically made but finds its conservative style boring.","prompt":"What is Frankie's likely attitude to Country Road, and why?","options":["Negative, because the boring style conflicts with her more heavily weighted goal of stimulation","Positive, because ethical production aligns with universalism (concern)","Neutral, because the beliefs cancel out regardless of weighting","Positive, because conservative style implicates face"],"answer":0,"explanation":"When positive and negative salient beliefs mix, integration weighs which belief has greater implication for the consumer's goals. Stimulation dominates for Frankie, so the attitude is negative.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Crano and Prislin (2006) define an attitude as an evaluative ___ of cognitions and affects experienced in relation to an object.","answers":["integration"],"explanation":"Evaluative integration automatically combines thoughts (cognitions) and feelings (affects) into an overall positive, negative, neutral or ambivalent view.","lvl":4},{"type":"mc","prompt":"What makes a belief 'salient' in multi-attribute models?","options":["It is objectively true","It is held by the majority of the population","It is top of mind because it is personally important, usually because it implicates a superordinate goal","It is the belief the firm advertises most"],"answer":2,"explanation":"We cannot process all beliefs, so we focus on the attributes and consequences that implicate our superordinate goals.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Positive","Negative","Ambivalent"],"items":[{"text":"A belief that mostly aligns with the consumer's superordinate goals","cat":0},{"text":"A belief that mostly conflicts with the consumer's superordinate goals","cat":1},{"text":"A reasonable mix of aligned and misaligned goals","cat":2},{"text":"Sara's overall attitude to Country Road","cat":0},{"text":"Frankie's overall attitude to Country Road","cat":1},{"text":"Holding strong positive and negative views of a brand at the same time","cat":2}],"explanation":"A belief's evaluation depends on how it lines up with the consumer's goals, and attitude is the aggregation of those evaluations."},{"type":"type_answer","prompt":"In Ajzen's expectancy-value model, attitude is proportional to the sum of b multiplied by e across salient beliefs. What does e stand for?","answers":["evaluation","subjective evaluation","the evaluation","evaluation of the attribute"],"explanation":"b is belief strength (the subjective probability the object has the attribute) and e is the subjective evaluation of that attribute.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Ajzen notes that attitude estimates built from an intuitively chosen list of beliefs correlate more strongly with standard attitude measures than estimates built from salient beliefs.","wrong":"more","correct":"less","explanation":"Arbitrary belief lists include many non-salient associations, so estimates based on elicited salient beliefs correlate more strongly with standard measures."}]},{"id":"MMK266-4.2","name":"Select an attitude-change strategy for a campaign","summary":"You can match a campaign to reinforcing a belief, changing its evaluation or salience, or adding a new belief, and justify the choice.","questions":[{"type":"match","prompt":"Match each campaign to the attitude-change strategy it used.","pairs":[["Apple's Think Different (1997)","Reinforce an existing belief"],["Guinness 'Good things come to those who wait'","Change the relative evaluation of a belief"],["VW Park Assist porcupine ad","Change the relative salience of a belief"],["Apple Watch fall detection keynote","Add a new belief"]],"explanation":"Think Different revived 'Apple equals creativity', Guinness turned the slow pour into a positive, VW made a non-salient benefit salient for conformity (interpersonal) consumers, and fall detection introduced a new health belief."},{"type":"case","passage":"A Burger King ad shows Ronald McDonald in a hat and coat, sneaking in to order at Burger King.","prompt":"Which attitude-change strategy is this, applied to the competitor?","options":["Reinforce an existing belief about Burger King","Change the relative salience of a Burger King attribute","Change the relative evaluation of a belief, flipping 'McDonald's is tasty' from positive toward negative","Add a new belief about McDonald's"],"answer":2,"explanation":"Flipping a positive belief to negative underpins comparative advertising. As a challenger brand, BK slyly implies its food is tastier.","lvl":4},{"type":"case","passage":"A phone maker launches the first mainstream handset with satellite emergency messaging, a feature no competitor offers.","prompt":"Which attitude-change strategy fits best?","options":["Add a new belief","Change relative evaluation","Reinforce an existing belief","Change relative salience of an old belief"],"answer":0,"explanation":"Adding a new belief is common for innovations, where a new attribute is a chance to shape perception, as with the Apple Watch's fall detection.","lvl":2},{"type":"mc","prompt":"Why do the notes warn marketers to 'be realistic' before trying to change an attitude?","options":["Attitudes come from multiple salient beliefs, so changing one may not change the overall attitude","Attitudes are formed from a single belief","Attitude change is always permanent","Weak attitudes can never be changed"],"answer":0,"explanation":"Because attitude is an aggregation, shifting one belief may leave the overall evaluation unchanged, especially if other beliefs are more important.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Highlighting how a currently non-salient belief aligns with a superordinate goal is changing the relative ___ of that belief.","answers":["salience"],"explanation":"Changing relative salience makes a belief top of mind, as the VW Park Assist ad did for consumers who dislike harming others.","lvl":3},{"type":"analogy","prompt":"Think Different is to reinforcing a belief as 'Good things come to those who wait' is to ___","options":["changing the relative evaluation of a belief","changing the relative salience of a belief","peripheral-route priming","adding a new belief"],"answer":0,"explanation":"Guinness helped consumers re-conceptualise the slow 119.5-second pour, flipping a negative belief into a positive one.","lvl":4}]},{"id":"MMK266-4.3","name":"Identify the features and causes of strong attitudes","summary":"You can tell strong from weak attitudes, name their causes, and explain what that means for changing them.","questions":[{"type":"order","prompt":"Put Boninger et al.'s consequences of holding an important attitude in order.","items":["Acquire information and think deeply, with selective exposure and elaboration","Build a large, organised, accessible and extreme store of knowledge","Resist change and reliably drive intention and action"],"explanation":"Howe and Krosnick (2017) present these as step-wise stages that map onto the lecture's list of strong-attitude features."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Cause of strong attitudes","Feature of strong attitudes"],"items":[{"text":"Self-interest","cat":0},{"text":"Social identification","cat":0},{"text":"Connection to underlying values","cat":0},{"text":"Selective information acquisition","cat":1},{"text":"Evaluative consistency","cat":1},{"text":"High resistance to change","cat":1}],"explanation":"The three causes match Howe and Krosnick's causes of attitude importance. The features describe how strong attitudes behave once held."},{"type":"case","passage":"Most consumers have weak attitudes toward particular toothpaste brands but strong attitudes about needing to brush their teeth.","prompt":"What does this mean for a toothpaste brand like Colgate?","options":["Weak attitudes never affect purchase","Brand attitudes are easy to change cheaply, but need repeated, varied reinforcement to stay changed","Brand attitudes cannot be changed at all","The brand should target the strong attitude to brushing only"],"answer":1,"explanation":"Weak attitudes are a double-edged sword: easy to shift via mass media but they do not stay shifted, and consumers block out repeated ads, hence Colgate's successive campaigns.","lvl":3},{"type":"mc","prompt":"Over about a year, roughly 80% of US Republicans and Democrats did not change party, a further 10% returned, and only about 10% defected. Which feature of strong attitudes does this show?","options":["Low accessibility","Ambivalence","High resistance to change","Selective elaboration of opposing views"],"answer":2,"explanation":"Strong attitudes are consequential across situations and highly resistant to change, which the party-loyalty data illustrate.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Because defending a strong attitude requires considerable mental and behavioural effort, consumers hold a large set of strong attitudes.","wrong":"large","correct":"small","explanation":"The effort required means people are miserly with attitude importance and hold only a small set of strong attitudes."},{"type":"type_answer","prompt":"US views on COVID-19 behaviours shifted to match party leaders' positions. Which feature of strong attitudes does this illustrate?","answers":["evaluative consistency"],"explanation":"Evaluative consistency means a strong attitude pulls weaker, related attitudes into line with it.","lvl":4}]},{"id":"MMK266-4.4","name":"Predict the ELM persuasion route from motivation and ability","summary":"You can decide whether a consumer will process centrally or peripherally given their motivation, perceived risk and ability.","questions":[{"type":"order","prompt":"Put the ELM decision flow in order for a consumer who ends up using the central route.","items":["Exposure to a persuasive message","Is the consumer motivated to process?","Is the consumer able to process?","Central-route evaluation of the argument"],"explanation":"If the answer to either question is no, the consumer takes the peripheral route. Only motivated and able consumers process centrally."},{"type":"case","passage":"Tom is anxious about choosing the right home insurance, a high-risk purchase. He sees a detailed insurance ad on a crowded, noisy train while his phone keeps buzzing.","prompt":"Which route is Tom most likely to use, and why?","options":["Central, because the ad is detailed","Peripheral, because distraction reduces his ability to process despite high motivation","Central, because perceived risk makes him motivated","Neither route applies to insurance"],"answer":1,"explanation":"Motivation alone is not enough. Distraction undermines ability, so even a motivated consumer falls back on peripheral cues.","lvl":3},{"type":"match","prompt":"Match each type of perceived risk to its example.","pairs":[["Functional","The phone's battery won't last the day"],["Financial","The offering may not be worth the money"],["Social","Using it could cause embarrassment"],["Physical","Using it could cause harm"]],"explanation":"Perceived risk is subjective and raises motivation to process. Social risk is felt most by consumers high in the value of face."},{"type":"mc","prompt":"In Petty and Cacioppo's (1979b) comprehensive-exam study, what happened when the policy was for students' own university?","options":["Weak arguments became more persuasive","Strong arguments became more persuasive and weak arguments less persuasive","Students relied more on source attractiveness","Argument quality stopped mattering"],"answer":1,"explanation":"High personal relevance increases elaboration, so argument quality matters much more, as thought-listing confirmed.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Affects motivation to process","Affects ability to process"],"items":[{"text":"Attitude strength","cat":0},{"text":"Perceived risk","cat":0},{"text":"Perceived personal relevance","cat":0},{"text":"Knowledge of the category","cat":1},{"text":"Distraction","cat":1},{"text":"Message comprehensibility","cat":1}],"explanation":"Motivation is the effort a consumer is prepared to give; ability is whether they can evaluate the information at all."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Petty and Briñol identify perceived personal ___ as the single most important driver of motivation to think about a message.","answers":["relevance"],"explanation":"Relevance, also called issue-involvement or ego-involvement, rises when a message links to the recipient's values, outcomes or identity.","lvl":3}]},{"id":"MMK266-4.5","name":"Contrast central and peripheral route cues and outcomes","summary":"You can classify persuasion cues by route and explain why central processing of strong attitudes is biased.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Central route","Peripheral route"],"items":[{"text":"Detailed information on how a tissue brand uses old-growth forest","cat":0},{"text":"Celebrity endorsements about protecting the Arctic","cat":1},{"text":"An attitude that is stable and resistant to change","cat":0},{"text":"An attitude vulnerable to further change","cat":1},{"text":"Careful scrutiny of argument quality","cat":0},{"text":"A pleasant mood transferring to the product","cat":1}],"explanation":"The Greenpeace pair shows each route. Central persuasion produces enduring attitudes; peripheral persuasion relies on cues such as source, mood and price and decays faster."},{"type":"case","passage":"A climate-change denier demands an impossible amount of evidence before changing their mind, yet accepts a single blog post that supports their view.","prompt":"What does this illustrate?","options":["Evaluative conditioning","Central-route processing that is biased because the information implicates a strong attitude","Peripheral processing caused by low motivation","Low ability to process"],"answer":1,"explanation":"Central-route processing is not the same as rational thinking. With strong attitudes the threshold to change is set unrealistically high and the threshold to support is very low.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Attitudes formed via the central route are relatively enduring and weakly predict future behaviour.","wrong":"weakly","correct":"strongly","explanation":"Central-route attitudes are enduring, resistant to counter-persuasion and strongly predictive of behaviour."},{"type":"case","passage":"In Tormala, Petty and Briñol's (2001) study, participants listed either two or ten positive thoughts about a message.","prompt":"Under high elaboration, which condition was more persuasive?","options":["Both were equally persuasive","Neither, because elaboration blocks persuasion","Two thoughts, because the ease of listing them boosted confidence in their validity","Ten thoughts, because more arguments must mean a better message"],"answer":2,"explanation":"This is self-validation: under high elaboration, fluency signals valid thoughts. Under low elaboration the numerosity heuristic made ten more persuasive.","lvl":4},{"type":"type_answer","prompt":"What name describes the ELM's signature idea that one variable can serve as an argument, a peripheral cue, or a biaser of thoughts depending on context?","answers":["multiple roles","multiple roles for variables"],"explanation":"Any single variable, such as source attractiveness, can play different roles in different situations.","lvl":4},{"type":"analogy","prompt":"Argument quality is to the central route as celebrity attractiveness is to ___","options":["perceived risk","the central route","the peripheral route","attitude strength"],"answer":2,"explanation":"Peripheral cues are extraneous to the message itself, such as source reputation, attractiveness, mood and price.","lvl":1}]}]},{"week":5,"topic":"Social Norms and Message Endorsers","summary":"Injunctive and descriptive norms, how norms form and change, and how experts, celebrities, trade characters, common people and influencers shape evaluation.","skills":[{"id":"MMK266-5.1","name":"Distinguish injunctive and descriptive norms","summary":"You can classify any normative message by whether it conveys approval or actual behaviour.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Injunctive norm","Descriptive norm"],"items":[{"text":"\"I should eat more vegetables\"","cat":0},{"text":"\"My friends eat lots of vegetables\"","cat":1},{"text":"\"85% of students drink 4 or fewer drinks when they party\"","cat":1},{"text":"\"9 out of 10 students disapprove of drinking to the point of passing out\"","cat":0},{"text":"\"Most guests in this hotel reuse their towels\"","cat":1},{"text":"\"My partner wants me to quit smoking\"","cat":0}],"explanation":"Injunctive norms are perceived approval or disapproval (what others want us to do). Descriptive norms are perceived prevalence (what others actually do)."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Descriptive norms capture what we think other people want us to do.","wrong":"Descriptive","correct":"Injunctive","explanation":"Injunctive norms concern approval; descriptive norms concern what others actually do."},{"type":"mc","prompt":"Why do the notes say the label 'peer pressure' can be misleading?","options":["It suggests norms only matter for harmful behaviours, when they also guide harmonious behaviour such as queueing","Peer pressure only applies to adults","Norms are unrelated to social pressure","Norms never influence harmful behaviour"],"answer":0,"explanation":"Social norms provide guidance on socially appropriate behaviour, such as joining the end of a queue or being polite to restaurant staff.","lvl":2},{"type":"case","passage":"A council places a sticker on wheelie bins reading: 'Most households in your street put their glass in the recycling bin.'","prompt":"Which type of norm does the sticker primarily target?","options":["Personalised normative feedback","Injunctive","Cultural","Descriptive"],"answer":3,"explanation":"Publicising how common a behaviour is targets the descriptive norm (perceived prevalence).","lvl":2},{"type":"type_answer","prompt":"Social norms are defined as the perceived social pressure to perform specific behaviours. What everyday term for them do the notes caution against?","answers":["peer pressure"],"explanation":"The term makes us think only of high-school warnings about smoking or speeding, rather than the everyday role norms play.","lvl":2},{"type":"analogy","prompt":"'Should' is to injunctive norm as 'do' is to ___","options":["homophily","descriptive norm","cultural norm","normative belief"],"answer":1,"explanation":"The exam tip: injunctive equals approval ('should'), descriptive equals actual behaviour ('do').","lvl":1}]},{"id":"MMK266-5.2","name":"Explain norm formation through referents, homophily and culture","summary":"You can trace how a consumer forms a norm and why norms differ across subgroups and nations.","questions":[{"type":"order","prompt":"Put the multi-attribute account of norm formation in order.","items":["Consumers are surrounded by social referents","Only some referents are salient for the specific behaviour","The consumer holds normative beliefs about whether each salient referent approves","The consumer aggregates these beliefs, emphasising very salient referents"],"explanation":"This mirrors evaluative integration for attitudes, applied to referents' approval rather than to product beliefs."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Status homophily","Value homophily"],"items":[{"text":"Age","cat":0},{"text":"Sex","cat":0},{"text":"Occupation","cat":0},{"text":"Education","cat":0},{"text":"Attitudes","cat":1},{"text":"Schwartz values","cat":1}],"explanation":"Status homophily covers ascribed (ethnicity, sex, age) and acquired (occupation, religion, education) attributes; value homophily covers internal states."},{"type":"match","prompt":"Match each product and communication combination to its international strategy.","pairs":[["Standardised product, standardised communication","Global strategy"],["Localised product, localised communication","Local strategy"],["Standardised product, localised communication","Mixed: uniform product, customised message"],["Localised product, standardised communication","Mixed: customised product, uniform message"]],"explanation":"Because cultural norms change very slowly, multinationals choose whether to leverage cultural differences in superordinate goals by localising product, message or both."},{"type":"case","passage":"For Jack, co-workers strongly influence whether he thinks he should quit smoking, but they barely register when he thinks about his weight. His partner matters a great deal in the smoking context.","prompt":"Which principle does this illustrate?","options":["Homophily only operates on value dimensions","Normative beliefs are fixed across behaviours","Culture overrides all individual referents","The salience of social referents varies by the behaviour being evaluated"],"answer":3,"explanation":"Which referents are salient depends on the behaviour, and very salient referents (like a partner) carry more weight in aggregation.","lvl":3},{"type":"mc","prompt":"Why can subgroups such as Lego fans or sporting-club supporters hold norms that differ from the broader population?","options":["Because they lack social referents","Because national culture prevents shared norms","Because norms only exist at the national level","Because homophily localises behavioural and attitudinal information among connected people"],"answer":3,"explanation":"We connect more with similar others, so information and norms become localised in subgroups, with tie strength affecting how far members follow them.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Oyserman (2017) defines ___ as the set of meanings that a group in a time and place come to adopt or develop.","answers":["culture"],"explanation":"Culture develops shared understandings for smooth interaction, and it grows through the regular contact that homophily produces.","lvl":3}]},{"id":"MMK266-5.3","name":"Choose between social norms marketing and personalised feedback","summary":"You can pick the right norm-change strategy for a context and avoid boomerang effects.","questions":[{"type":"case","passage":"A university health team drafts a poster: '1 in 10 students approve of drinking until they pass out.' Most students in fact disapprove.","prompt":"How should the message be improved according to the notes?","options":["Keep it, because minority messages create urgency","Add personalised feedback to every student instead","Reframe as a majority message: '9 out of 10 students disapprove of drinking to the point of passing out'","Remove all numbers from the message"],"answer":2,"explanation":"Social norms marketing should always use a majority message, and it works only where most people already perform the desired behaviour.","lvl":2},{"type":"case","passage":"An energy retailer sends home reports comparing each household's usage with similar homes. Low-use households start using more electricity.","prompt":"What fix do the notes recommend?","options":["Remove the peer comparison entirely","Switch to a minority message","Acknowledge the good behaviour of under-consumers, for example with a smiley face","Stop sending reports to high users"],"answer":2,"explanation":"Personalised normative feedback can backfire on under-consumers unless it recognises their good behaviour. Miller and Prentice also suggest giving feedback only to high consumers.","lvl":3},{"type":"match","prompt":"Match each concept to its description.","pairs":[["Social norms marketing","Publicising the actual high rate of a desirable behaviour to many people"],["Personalised normative feedback","Showing individuals their own behaviour against the actual peer average"],["Boomerang effect","Conveying that a bad behaviour is common makes it increase"],["Pluralistic ignorance","Privately rejecting a norm while wrongly assuming most others accept it"]],"explanation":"SNM targets prevalence cheaply but is scattershot; PNF targets intensity and is labour-intensive but more personal."},{"type":"mc","prompt":"In van der Linden's (2013) study of Dutch students' bottled-water use, what reduced intentions?","options":["A descriptive norm message alone","Neither, because norms have no effect on water use","Only the combination of a descriptive norm and a persuasive message","A persuasive message alone"],"answer":2,"explanation":"Students knew little about the environmental argument, so they could not interpret peers' behaviour without it. This shows norm influence is not just informational influence.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Good target for a norm campaign","Poor target for a norm campaign"],"items":[{"text":"Members of a sporting club, named as the reference group","cat":0},{"text":"Binge drinking, where people act against their preferences to avoid embarrassment","cat":0},{"text":"An environmental context where some people are free-riding","cat":0},{"text":"A behaviour that only a minority currently performs","cat":1},{"text":"A context where people already perceive the norm accurately","cat":1}],"explanation":"Norm campaigns need genuine misperceptions and a desirable behaviour that is already common, and they work well with high-homophily groups, embarrassment-driven behaviour and public goods."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Social norms marketing only works when most people already perform the undesirable behaviour.","wrong":"undesirable","correct":"desirable","explanation":"Highlighting high prevalence of an undesirable behaviour backfires; SNM works when the desired behaviour is already common but underestimated."}]},{"id":"MMK266-5.4","name":"Apply the meaning transfer model to celebrity endorsement","summary":"You can explain how meanings move from culture to celebrity to product to consumer and judge endorser fit.","questions":[{"type":"order","prompt":"Put McCracken's three locations of meaning in the order meaning moves through them.","items":["The culturally constituted world","Consumer goods","The individual consumer"],"explanation":"Advertising and fashion move meaning from the world into goods, and consumers then claim it through effort and ritual."},{"type":"match","prompt":"Match each stage of the celebrity's contribution to what happens.","pairs":[["Stage 1: role to celebrity","The celebrity acquires meanings from roles they perform"],["Stage 2: celebrity to product","Meanings transfer to the product when they appear together in an ad"],["Stage 3: product to consumer","The consumer takes possession of the meanings through effort and ritual"]],"explanation":"The celebrity acts as a 'super consumer' who has already assembled a clear self, offering consumers raw material for their own."},{"type":"case","passage":"Nintendo hired Helen Mirren, known as talented, feminist and sophisticated, to endorse the Wii Fit, positioned as fun, mass-market exercise.","prompt":"Why is this endorsement likely to fail?","options":["Mirren lacks attractiveness","Stage 3 transfer is automatic","Her meanings do not align with the product's positioning","Celebrities cannot endorse technology"],"answer":2,"explanation":"The practical rule of meaning transfer is alignment: the celebrity's meanings must match the offering's positioning.","lvl":2},{"type":"mc","prompt":"According to McCracken, why do celebrities outperform anonymous models as endorsers?","options":["They carry no meanings of their own","They are always cheaper","They supply precise personality and lifestyle meanings and own them through repeated public performance","They avoid any risk of negative information"],"answer":2,"explanation":"Models offer blunt demographic meaning. Strongly typecast celebrities, like Audrey Hepburn for elegance, deliver clear, powerful meanings.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Surrounding a celebrity in an ad with people, objects and copy that share the same meanings follows the principle of ___.","answers":["redundancy"],"explanation":"Redundancy selects the wanted meanings and keeps unwanted ones out of the evoked set.","lvl":4},{"type":"case","passage":"A sports-drink brand can sign a record-breaking athlete who is widely seen as untrustworthy, or a less decorated athlete seen as highly trustworthy.","prompt":"Based on Amos et al. (2008), which is the better choice?","options":["The trustworthy athlete, because trustworthiness (.46) matters while performance had no effect (-.05)","The record-breaker, because performance has the largest effect","Either, because celebrity attributes have no effect","Neither, because familiarity is all that matters"],"answer":0,"explanation":"Trustworthiness is a strong positive driver, performance or success in the field has no effect, and negative information (-.62) is the biggest risk.","lvl":3}]},{"id":"MMK266-5.5","name":"Match message endorser types to mechanisms and uses","summary":"You can choose an expert, celebrity, trade character, common person or influencer and justify it with its mechanism.","questions":[{"type":"match","prompt":"Match each endorser type to its underlying mechanism or strength.","pairs":[["Expert","Occupation, training or experience; suits credence goods"],["Celebrity","Meaning transfer model"],["Trade character","Company-controlled image with no scandal risk"],["Common person","Social cognitive theory, raising perceived behavioural control"]],"explanation":"Each endorser type works through a different mechanism, which is what an Assessment 2 justification should name and cite."},{"type":"case","passage":"A brand launches a probiotic supplement whose benefits cannot easily be observed even after weeks of use.","prompt":"Which endorser type is most appropriate?","options":["Celebrity","Expert","Trade character","Common person"],"answer":1,"explanation":"Experts suit complex offerings and credence goods, where heightened trust is needed because benefits are hard to verify.","lvl":2},{"type":"case","passage":"A new all-in-one laundry pod needs to show busy parents how simple it is to use.","prompt":"Which endorser type fits best, and why?","options":["Common person, because seeing someone like us succeed raises perceived behavioural control","Expert, because laundry is a credence good","Celebrity, through meaning transfer","Trade character, because it avoids scandals"],"answer":0,"explanation":"Common person endorsers are non-aspirational and relatable, and social cognitive theory explains why they boost confidence in using a product.","lvl":3},{"type":"mc","prompt":"Folse et al. (2012) compared trade characters designed to look sincere versus competent. What did they find?","options":["Competent characters built more trust","Both reduced brand attitude","Design made no difference","Sincere characters generated greater brand trust and brand attitude"],"answer":3,"explanation":"Sincerity links to warmth and agreeableness, which motivate brand trust.","lvl":3},{"type":"type_answer","prompt":"Schouten et al. (2020) found which endorser type is perceived as more trustworthy, more similar and easier to identify with than celebrities?","answers":["influencers","influencer","social media influencers"],"explanation":"Influencers blend celebrity image, expert credibility in a niche, and common-person relatability.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Common person endorsers work through social cognitive theory by lowering consumers' perceived behavioural control.","wrong":"lowering","correct":"raising","explanation":"Seeing someone similar perform a behaviour gives us confidence we can do it too, which increases perceived behavioural control, a TPB input."}]}]},{"week":6,"topic":"Persuasion I: Emotion-Based Techniques","summary":"Four techniques that change how consumers feel: fear appeals (EPPM), humour appeals (benign violation theory), evaluative conditioning and narrative advertising.","skills":[{"id":"MMK266-6.1","name":"Evaluate fear appeals using the EPPM","summary":"You can audit a fear appeal for susceptibility, severity, self-efficacy and response efficacy and predict the response.","questions":[{"type":"order","prompt":"Put the EPPM sequence in order for a fear appeal that succeeds.","items":["Exposure to the fear appeal","Threat appraisal finds the threat high","Efficacy appraisal finds the response effective and doable","Danger control response: the message is accepted"],"explanation":"Low threat ends processing with no response; high threat with low efficacy leads to fear control responses such as denial and reactance."},{"type":"match","prompt":"Match each EPPM sub-component to the question it answers.","pairs":[["Susceptibility","Could the threat happen to me?"],["Severity","Is the threat serious?"],["Self-efficacy","Can I perform the suggested response?"],["Response efficacy","Does the suggested response work?"]],"explanation":"Susceptibility and severity build threat; self-efficacy and response efficacy build efficacy."},{"type":"case","passage":"An anti-smoking ad shows a throat-cancer patient and offers free quitting help. It never suggests the viewer personally is at risk, or that quitting reduces the risk.","prompt":"Given Tannenbaum et al. (2015), which missing component is most damaging?","options":["Self-efficacy","Severity","Susceptibility","Humour"],"answer":2,"explanation":"Severity without susceptibility dramatically weakens an appeal (.23 versus .43 for susceptibility only).","lvl":3},{"type":"case","passage":"A wordless Dettol ad shows a man handling a germ-ridden dead animal, the germs passing along a chain of handshakes, and a quick squirt of sanitiser stopping the spread.","prompt":"Which EPPM component does the ad lack?","options":["Response efficacy","Susceptibility","Self-efficacy","Severity"],"answer":0,"explanation":"The ad shows severity, susceptibility and an easy action (self-efficacy), but does not explicitly reassure viewers that sanitiser actually reduces the threat.","lvl":3},{"type":"mc","prompt":"Susceptibility-only appeals were about as effective as susceptibility-plus-severity appeals. When should marketers still include severity?","options":["Only for commercial brands, not health agencies","For new or unknown threats, where consumers cannot be assumed to know the outcomes are severe","Never, because severity weakens appeals","Only when efficacy is excluded"],"answer":1,"explanation":"For well-known threats like cancer, severity is assumed. For unfamiliar threats, severity information is still needed.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"According to Witte, perceived threat determines the nature of the response to a fear appeal.","wrong":"nature","correct":"extent","explanation":"Threat determines the extent of the response, while efficacy determines its nature: danger control or fear control."}]},{"id":"MMK266-6.2","name":"Explain humour appeals using benign violation theory","summary":"You can identify which route makes an ad funny and predict where humour helps or hurts persuasion.","questions":[{"type":"case","passage":"Daihatsu ran two Charade ads. One simply stated the car's value for money. The other made the same point with sexual innuendo.","prompt":"Which route to humour does the second ad use?","options":["Making benign content seem like a violation","Narrative transportation","Evaluative conditioning","Minimising the gravity of a violation"],"answer":0,"explanation":"Adding a mild violation pushes mundane content into the benign-violation sweet spot, useful for making safe categories like cars grab attention.","lvl":3},{"type":"case","passage":"A health message reads: 'Drinking can cause memory loss, or worse, memory loss.'","prompt":"Which route to humour does this use, and why is it useful?","options":["Making benign content a violation, to make it scarier","Making benign content a violation, to lift credibility","Neither, because health messages cannot be humorous","Minimising a violation's gravity, which can cut through to audiences who downplay fear appeals"],"answer":3,"explanation":"A conventional health warning is a violation of physical safety. Minimising its gravity makes it a benign violation and reduces the concern it elicits.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Humour helps","Humour has little effect or hurts"],"items":[{"text":"Attention","cat":0},{"text":"Attitude towards the ad","cat":0},{"text":"Positive affective responses","cat":0},{"text":"Credibility","cat":1},{"text":"Cognitive responses","cat":1}],"explanation":"Eisend (2009) found humour boosts attention (.42) and ad attitude (.37) and emotions, but has little effect on cognitive responses and lowers credibility (-.13)."},{"type":"mc","prompt":"Based on Eisend (2009), which offering is humour most likely to help?","options":["Toothpaste (low involvement, functional)","A sweet snack (low involvement, hedonic)","A family car (high involvement, functional)","Office furniture (functional)"],"answer":1,"explanation":"Humour mainly moves emotional responses, so it works best for hedonic offerings (.38 for low-involvement hedonic) and can even hurt low-involvement functional ones (-.12).","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Walter et al. (2018) found that ___ humorous ads are the most persuasive.","answers":["moderately","moderate"],"explanation":"Ads that are too funny lose persuasive power, partly because people stop attending to the message while laughing.","lvl":3},{"type":"analogy","prompt":"The Seinfeld Strategy is to making benign content a violation as the Sarah Silverman Strategy is to ___","options":["evaluative conditioning","minimising the gravity of a violation","increasing psychological closeness","adding innuendo"],"answer":1,"explanation":"Martin and Ford (2018) describe Silverman taking grave topics and minimising their gravity so they become benign violations.","lvl":4}]},{"id":"MMK266-6.3","name":"Apply evaluative conditioning to brand pairings","summary":"You can label the stimuli in a conditioning campaign and use Hofmann et al.'s moderators to strengthen it.","questions":[{"type":"match","prompt":"Match each element of the Share a Coke campaign to its evaluative conditioning role.","pairs":[["Friends","Unconditioned stimulus"],["Happiness felt around friends","Unconditioned response"],["Coca-Cola before the campaign","Neutral stimulus"],["Coca-Cola after successful conditioning","Conditioned stimulus"]],"explanation":"Pairing Coke with friendship transfers the happiness response so Coke alone produces a conditioned response of happiness."},{"type":"order","prompt":"Put the stages of conditioning Coca-Cola with Christmas in order.","items":["Coke produces a neutral response while Christmas produces festivity","Coke is repeatedly paired with Christmas imagery","Coke alone produces feelings of festivity"],"explanation":"Before, during and after conditioning: the brand moves from neutral stimulus to conditioned stimulus."},{"type":"mc","prompt":"Hofmann et al. (2010) found EC effects of .74 for nonsensical stimuli versus .29 for sensical ones. What is the marketing implication?","options":["EC only works with real words","EC is especially effective for new offerings and for attitude formation","Brand names should never be used in EC","EC is best for changing attitudes to famous brands"],"answer":1,"explanation":"Unfamiliar stimuli carry no competing associations, so EC works best when building new attitudes rather than changing existing ones.","lvl":4},{"type":"case","passage":"A fashion retailer pumps a signature scent through its stores, hoping shoppers will associate the pleasant smell with the brand. Few shoppers consciously notice the connection.","prompt":"How could the retailer strengthen the effect, according to the notes?","options":["Use fear appeals instead","Keep the pairing hidden, since unaware pairing is strongest","Highlight the connection between scent and brand where it can be done naturally","Switch to a sensical stimulus"],"answer":2,"explanation":"EC works both ways but is up to three times stronger when consumers are aware of the pairing (.60 versus .21).","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Evaluative conditioning is far more effective with sensical stimuli such as existing brand names.","wrong":"sensical","correct":"nonsensical","explanation":"Nonsensical stimuli like ZONDLE or BOLI-PUNA have no competing associations, so EC effects are much larger."},{"type":"mc","prompt":"What is De Houwer and Hughes's (2016) main argument about evaluative conditioning?","options":["EC only works in non-human animals","EC cannot occur through instructions","EC is a primitive, purely peripheral process","EC is a symbolic phenomenon: pairings work like words, signalling how stimuli are related"],"answer":3,"explanation":"EC via instructions (UDIBNON versus BAYRAM) shows pairings can function as symbols, putting EC closer to argument-based persuasion than the ELM suggests.","lvl":4}]},{"id":"MMK266-6.4","name":"Explain narrative transportation and its antecedents","summary":"You can distinguish story from narrative, explain why transportation persuades, and design ads that make it likely.","questions":[{"type":"match","prompt":"Match each term to its definition.","pairs":[["Story","A storyteller's account of events leading to a transition to a later state"],["Narrative","The receiver's consumption of a story that makes it understandable"],["Storyteller","The producer who uses characters, plot and change"],["Story receiver","The consumer who interprets and gives the story meaning"]],"explanation":"Van Laer et al. (2014) separate the storyteller's production from the receiver's consumption, which is why transportation antecedents come from both sides."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Storyteller antecedent","Story receiver antecedent"],"items":[{"text":"Identifiable character","cat":0},{"text":"Imaginable plot","cat":0},{"text":"Verisimilitude","cat":0},{"text":"Familiarity with the story topic","cat":1},{"text":"Paying attention to the story","cat":1}],"explanation":"Storyteller antecedents are directly controllable by marketers; receiver antecedents suggest target segments."},{"type":"case","passage":"An agency pitches a narrative ad starring a famous Hollywood star in an over-the-top, explosion-filled chase sequence.","prompt":"Why might this ad fail to transport viewers?","options":["It has too much verisimilitude","The plot is too simple to follow","The celebrity has low identifiability and the action lacks verisimilitude","Narrative ads must be print only"],"answer":2,"explanation":"Viewers empathise with characters they 'see themselves in' and are transported by believable, lifelike stories, which is why suburban everyday settings are common.","lvl":3},{"type":"mc","prompt":"Why is narrative transportation so persuasive, according to Van Laer et al. (2014)?","options":["It only works through peripheral cues","It lifts affect, beliefs, attitudes and intentions while reducing critical thought","It increases scrutiny of message arguments","It relies on repeated exposure"],"answer":1,"explanation":"Transported consumers are less likely to scrutinise arguments (-.20), which is part of what makes narratives powerful.","lvl":3},{"type":"type_answer","prompt":"What term describes a story that is believable and lifelike, with the potential to actually happen?","answers":["verisimilitude"],"explanation":"Verisimilitude (.27) is one of the three storyteller antecedents of transportation.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Van Laer et al. found narrative transportation has its largest effect on cognitive responses.","wrong":"cognitive","correct":"affective","explanation":"The largest consequence of transportation is on affective response (.57); narrative persuasion is more affective than cognitive."}]}]},{"week":7,"topic":"Persuasion II: Cognitive Techniques","summary":"Techniques that change how consumers think: two-sided messages, comparative advertising and message framing (prospect theory), plus anthropomorphism, which works through both cognition and emotion.","skills":[{"id":"MMK266-7.1","name":"Design two-sided messages using Eisend's moderators","summary":"You can critique a two-sided ad on the amount, attribute type and placement of negative information.","questions":[{"type":"case","passage":"Avis's classic ad opens with 'We're number two', admitting it is not the most popular car rental firm, then explains it therefore tries harder.","prompt":"Based on Eisend (2006), how could the ad be improved?","options":["Replace it with a comparative ad against a new entrant","Remove all negative information","Add more negative information until it dominates","Move the negative information later in the message"],"answer":3,"explanation":"Negative information placed first lowers source credibility (-.64) and ad attitude, while placing it last raises credibility, brand attitude and intention.","lvl":3},{"type":"mc","prompt":"What proportion of negative information makes a two-sided message most effective?","options":["Between one third and one half","Under 10%","About three quarters","All information should be negative"],"answer":0,"explanation":"Below this window the ad does not stand out; above it the message plants genuine doubt.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Search attribute","Experience attribute","Credence attribute"],"items":[{"text":"How nice a piece of food looks","cat":0},{"text":"Price","cat":0},{"text":"How the food tastes","cat":1},{"text":"Durability","cat":1},{"text":"How nutritious the food is","cat":2},{"text":"The ecological treatment of fruit and vegetables","cat":2}],"explanation":"Search attributes can be judged before purchase, experience attributes only after use, and credence attributes need special knowledge or equipment."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Two-sided messages increase source credibility most when the negative information concerns search attributes.","wrong":"search","correct":"experience","explanation":"Credibility rises more when negatives concern experience or credence attributes, which consumers cannot verify in advance, as in 'It tastes awful. And it works.'"},{"type":"match","prompt":"Match each theory to how it explains two-sided messaging.","pairs":[["Attribution theory","Volunteering negatives runs against the selling motive, so consumers infer honesty"],["Optimal arousal theory","Two-sided messages are novel, so stimulation seekers attend to them"],["Inoculation theory","Mild attacks that are refuted strengthen attitudes against counterclaims"]],"explanation":"The lecture covers the first two; Eisend (2006) adds inoculation theory, which applies to refutational appeals."},{"type":"type_answer","prompt":"Which outcome showed the largest effect (.52) in Eisend's meta-analysis of two-sided messages?","answers":["perceived novelty","novelty"],"explanation":"Perceived novelty is the standout effect, consistent with optimal arousal theory, while attitude toward the ad was slightly negative (-.06).","lvl":5}]},{"id":"MMK266-7.2","name":"Apply comparative advertising evidence and ACCC rules","summary":"You can decide who should run comparative ads, whom to compare against, and what is legal in Australia.","questions":[{"type":"case","passage":"A new plant-based milk brand is about to launch in Australia and wants to lift brand attitude with a comparative ad.","prompt":"Based on Grewal et al. (1997), which approach is best?","options":["Compare against an established brand","Compare against another brand that launched last month","Compare only against the whole beverage category","Avoid comparative ads, since new brands gain nothing"],"answer":0,"explanation":"New brands gain most in brand attitude (.58), and an established comparison brand maximises brand attitude (.46). Never compare against a new entrant.","lvl":3},{"type":"mc","prompt":"Why should a brand never run a comparative ad against a brand that has just entered the market?","options":["It always raises the new brand's intention","New brands have no attributes to compare","It is illegal under the Competition and Consumer Act","It makes the advertiser look like a bully and consumers react very negatively"],"answer":3,"explanation":"Attacking a newcomer reads as bullying, which damages the advertiser.","lvl":2},{"type":"case","passage":"A Melbourne restaurant advertises 'the best steaks on earth'.","prompt":"How does the ACCC treat this claim?","options":["As misleading comparative advertising that must be withdrawn","As a two-sided message","As illegal because it names no competitor","As puffery, acceptable unless worded so consumers might think it literally true"],"answer":3,"explanation":"Puffery is wildly exaggerated or vague claims no one could take seriously. It is an implicit comparison and is permitted unless it could be read as literally true.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Significant positive effect","Significant negative effect"],"items":[{"text":"Attention","cat":0},{"text":"Behaviour","cat":0},{"text":"Brand awareness","cat":0},{"text":"Attitude toward the ad","cat":1},{"text":"Purchase intention","cat":0}],"explanation":"Grewal et al. show comparative ads buy attention (.47) and behaviour (.46) at the cost of ad liking (-.28)."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"To maximise purchase intention, a comparative ad should use an established brand as the comparison.","wrong":"established","correct":"leader","explanation":"An established comparison brand is best for brand attitude (.46), but the market leader is best for purchase intention (.36)."},{"type":"analogy","prompt":"BMW congratulating Audi on an award is to tit-for-tat advertising as Play-Doh comparing itself with children's apps is to ___","options":["a two-sided message","comparison against a whole category","puffery","a refutational appeal"],"answer":1,"explanation":"Following equifinality, many offerings satisfy the same goal, so Play-Doh competes with app entertainment for parents' wallets.","lvl":4}]},{"id":"MMK266-7.3","name":"Match message frames to desirable and undesirable outcomes","summary":"You can apply the gain-desirable and loss-undesirable recipe to rewrite health and packaging claims.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Matched frame (effective)","Mismatched frame"],"items":[{"text":"'Eat 2 fruit and 5 veg a day and your chances of living longer increase'","cat":0},{"text":"'Don't eat 2 fruit and 5 veg a day and your chances of living longer decrease'","cat":1},{"text":"'Eat 2 fruit and 5 veg a day and your risk of colon cancer decreases'","cat":0},{"text":"'Don't eat 2 fruit and 5 veg a day and your risk of colon cancer increases'","cat":1},{"text":"'80% fat-free'","cat":0},{"text":"'Contains 20% fat'","cat":1}],"explanation":"Gain frames suit desirable outcomes and loss frames suit undesirable ones. The mismatched combinations do not work."},{"type":"case","passage":"Two detergents cost $4.99. Royal Detergent says 'Kills 99% of germs'. Cleaner King says 'Only 1% of germs survive'. Most shoppers choose Royal.","prompt":"Why does Royal win?","options":["Cleaner King uses puffery","Its claim is framed as losing an undesirable outcome","Its claim is mathematically better","Its claim uses a gain frame for a desirable outcome"],"answer":1,"explanation":"Losing an undesirable outcome (germs) is the strongest pairing, while Cleaner King frames it as gaining an undesirable outcome.","lvl":3},{"type":"match","prompt":"Match each frame and outcome pairing to its effect size in the lecture's recipe.","pairs":[["Gain frame, desirable outcome",".07, significant"],["Gain frame, undesirable outcome",".01, not effective"],["Loss frame, desirable outcome",".00, not effective"],["Loss frame, undesirable outcome",".11, the strongest"]],"explanation":"Match the frame to the outcome: gain with desirable, loss with undesirable."},{"type":"mc","prompt":"What does O'Keefe and Jensen's (2007) meta-analysis of 93 disease-prevention studies add to the framing recipe?","options":["Framing has large effects for every health behaviour","Gain frames were significantly more persuasive, but the effect was tiny (r = .03) and driven mainly by dental hygiene messages","Loss frames are always far superior","Framing only works for undesirable outcomes"],"answer":1,"explanation":"Citing both the recipe and this qualification shows critical reading: the effect is real but small and concentrated in one behaviour type.","lvl":4},{"type":"case","passage":"A sunscreen brand wants to stress that daily use lowers the risk of skin cancer, an undesirable outcome.","prompt":"Which claim follows the recipe best?","options":["'Use it daily and your risk of skin cancer decreases'","'Skip it and your skin will look less healthy'","'Use it daily and your chance of a long life decreases'","'Use it daily and gain healthier skin'"],"answer":0,"explanation":"For an undesirable outcome, frame the message as losing that outcome, as in the colon-cancer example.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A gain-framed appeal emphasises the advantages of noncompliance with the communicator's recommendation.","wrong":"noncompliance","correct":"compliance","explanation":"Gain frames stress the advantages of compliance; loss frames stress the disadvantages of noncompliance."}]},{"id":"MMK266-7.4","name":"Apply prospect theory's loss aversion to consumer choices","summary":"You can predict risk-averse and risk-seeking choices from how options are framed.","questions":[{"type":"case","passage":"Participants choose between Program A (200 of 600 people will be saved) and Program B (a 1/3 chance all 600 are saved, 2/3 chance none are saved).","prompt":"What did most participants choose, and why?","options":["They split evenly","B, because gain frames make people risk seeking","B, because it has a higher expected value","A, because under a gain frame people are risk averse and lock in the certain outcome"],"answer":3,"explanation":"72% chose A. When the same options were framed as deaths, 78% chose the gamble, showing preferences flip with the frame.","lvl":3},{"type":"mc","prompt":"Offered a certain $900 or a 90% chance of $1,000 (10% chance of nothing), what do most people choose?","options":["Neither option","The gamble, because $1,000 is larger","They are indifferent","The certain $900, because of the regret of ending up with nothing"],"answer":3,"explanation":"Sure gains are preferred to probable gains, one of the three implications of loss aversion.","lvl":2},{"type":"match","prompt":"Match each prospect-theory implication to the typical preference.","pairs":[["Sure gain versus probable gain","Take the sure gain"],["Certain loss versus probable loss","Take the gamble on the probable loss"],["A $100 loss versus a $100 gain","The loss is felt more strongly"]],"explanation":"All three follow from the premise that consumers are loss averse."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The basic premise of prospect theory is that consumers are loss ___.","answers":["averse"],"explanation":"Losses loom larger than equivalent gains, which drives framing effects and also explains the endowment effect in Week 9.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"On the prospect theory value function, a $100 gain produces a steeper change in psychological value than a $100 loss.","wrong":"steeper","correct":"shallower","explanation":"The value function drops steeply for losses and rises more gently for gains."},{"type":"analogy","prompt":"Gain frame is to risk averse as loss frame is to ___","options":["gain seeking","risk seeking","risk neutral","loss averse"],"answer":1,"explanation":"In the disease outbreak problem, the loss frame led most people to prefer the risky option.","lvl":1}]},{"id":"MMK266-7.5","name":"Explain how anthropomorphism builds connection and comprehension","summary":"You can spot anthropomorphic tactics and explain them through connection, comprehension and competition.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Trade character","Human features in design","Human names or adjectives"],"items":[{"text":"Toucan Sam for Froot Loops","cat":0},{"text":"The M&M characters Red and Yellow","cat":0},{"text":"The smile in the Amazon logo","cat":1},{"text":"The smiling grille of the Mazda 3","cat":1},{"text":"Mr Sheen","cat":2},{"text":"Innocent juice","cat":2}],"explanation":"Marketing uses trade characters, faces in logos and design, human names, and human-only adjectives to prompt anthropomorphism."},{"type":"match","prompt":"Match each reason anthropomorphism works to its explanation.","pairs":[["Connection","The object becomes a source of social belonging"],["Comprehension","Effectance motivation leads us to apply human understandings as a shortcut"],["Competition","Objects are given agency, so consumers can feel judged by them"]],"explanation":"Connection and competition run largely through emotion, and comprehension through cognition, which is why anthropomorphism spans both."},{"type":"case","passage":"Newton et al. (2017) delivered portion-size health information either generically or in the voice of the consumer's own digestive tract, drawn with sad eyes and speech bubbles.","prompt":"Which process do the notes use this study to illustrate, and who was most affected?","options":["Comprehension, strongest among experts","Competition, with the effect especially strong among people who felt powerless","Connection, strongest among pet owners","Evaluative conditioning, strongest when pairing was unaware"],"answer":1,"explanation":"The anthropomorphised gut has agency and feelings, so consumers can feel judged. It reduced portion-size preferences, especially among those feeling powerless.","lvl":4},{"type":"mc","prompt":"Shoppers rate a plain bedside table neutrally but a table designed to resemble a face as cute and harmless. Which process explains this?","options":["Choice overload","Comprehension","Competition","Connection"],"answer":1,"explanation":"Human behaviour is the domain we understand best, so a face-like object is judged using human understandings, a mental shortcut.","lvl":3},{"type":"type_answer","prompt":"What name is given to consumers' desire to understand and predict what things around them will do?","answers":["effectance motivation","effectance"],"explanation":"Effectance motivation underlies the comprehension route of anthropomorphism.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In the Fairphone seminar, consumers will only bother replacing components if they feel detached from the phone.","wrong":"detached","correct":"attached","explanation":"Anthropomorphism is proposed to build emotional connection so consumers treat the phone as something they care for rather than a disposable commodity."}]}]},{"week":8,"topic":"Choice","summary":"How consumers pick among considered options: compensatory and non-compensatory rules, habits and loyalty, five heuristics, and choice overload.","skills":[{"id":"MMK266-8.1","name":"Distinguish compensatory and non-compensatory decision rules","summary":"You can classify a decision rule and explain why consumers filter first and weigh trade-offs second.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Non-compensatory rule","Compensatory weighing"],"items":[{"text":"'It must be vanilla'","cat":0},{"text":"Balancing attractive packaging against a higher price","cat":1},{"text":"'It must not be too expensive or too cheap'","cat":0},{"text":"Weighing support for local farmers against a higher price","cat":1},{"text":"'It must contain milk and sugar'","cat":0},{"text":"Letting a strong brand image offset a smaller size","cat":1}],"explanation":"Non-compensatory rules are thresholds that strengths elsewhere cannot offset; compensatory rules let positives offset negatives."},{"type":"order","prompt":"Put the lecture's ice cream choice in the order consumers work through it.","items":["Face sixteen ice creams of varying price and size","Apply 'must be vanilla'","Apply 'must contain milk and sugar'","Apply 'not too expensive or too cheap'","Weigh the remaining few on brand, packaging and ownership"],"explanation":"Non-compensatory filters come first, then compensatory weighing runs on the survivors."},{"type":"case","passage":"Aisha only buys Australian-owned milk. She walks past a cheaper imported brand with beautiful packaging and excellent reviews without a second look.","prompt":"What does this show?","options":["Non-compensatory decision-making: failing the threshold cannot be offset by strengths elsewhere","Choice overload","The halo effect","Compensatory decision-making, where packaging offsets price"],"answer":0,"explanation":"Brands must clear common threshold rules, because strengths on other attributes will not save them.","lvl":2},{"type":"mc","prompt":"When is full compensatory and non-compensatory decision-making usually used?","options":["Whenever a heuristic is available","Only for habitual purchases","In categories with few choices and high motivation to process","In categories with many options and little time"],"answer":2,"explanation":"With many options or limited time, consumers fall back on satisficing and simplifying techniques instead.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"If a past behaviour failed to achieve a goal, it tends to be repeated, which simplifies future decisions.","wrong":"failed","correct":"succeeded","explanation":"Habits form when past behaviour successfully helped achieve a goal, so repeating it saves decision effort."},{"type":"type_answer","prompt":"Besides satisficing, what type of technique do consumers use to make the decision itself easier, such as habits, loyalty and heuristics?","answers":["simplifying techniques","simplifying technique","simplifying"],"explanation":"Satisficing settles for good enough; simplifying techniques make the decision process itself easier.","lvl":4}]},{"id":"MMK266-8.2","name":"Apply the anchoring and price-quality effects to pricing","summary":"You can use anchors, precision, decoys and premium pricing to shape perceived value.","questions":[{"type":"case","passage":"A shoe store shows the same pair either at $300, or as 'Was $600, now $300'.","prompt":"What happens to shoppers' estimates of the shoes' true value in the second display?","options":["They stay the same","They fall below $300","They shift upward, anchored by the $600","They become random"],"answer":2,"explanation":"The anchoring effect means judgements are made in reference to previously encountered information, here the original price.","lvl":1},{"type":"case","passage":"A wine list shows a $25 bottle and a $40 bottle. Most diners see the $40 as expensive. The restaurant adds an $85 bottle.","prompt":"What is the likely effect?","options":["No effect, because anchors only work within one product","The $40 bottle now seems reasonable","Diners switch to the $85 bottle","The $25 bottle now seems expensive"],"answer":1,"explanation":"Anchoring works across products, and the $85 decoy makes the $40 option seem moderate.","lvl":2},{"type":"mc","prompt":"Why might a menu price of $14.70 anchor judgements more strongly than $15?","options":["Anchors only work when implausible","Precision reduces attention","High-precision anchors pull estimates closer to them, provided there is some reason for the precision","Round numbers are always more persuasive"],"answer":2,"explanation":"A precise anchor ($314 versus $300 in the lecture) is more influential, though the precision needs a plausible reason.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In Mussweiler and Strack (2001), people asked whether Gandhi died older or younger than 140 estimated an average age of ___ years.","answers":["67","67 years"],"explanation":"The group given an anchor of 9 estimated 50, showing anchors work even when implausibly extreme.","lvl":5},{"type":"analogy","prompt":"Lexus is to Toyota as Apple is to ___","options":["Lexus","Google","Samsung Galaxy","LG"],"answer":3,"explanation":"Both pairs show premium pricing that encourages the price-quality inference, either across a firm's own brands (Toyota versus Lexus) or relative to other brands (Apple versus LG).","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Anchoring effect","Price-quality effect"],"items":[{"text":"An $85 decoy wine on the list","cat":0},{"text":"A high price leads diners to expect a better meal","cat":1},{"text":"'Was $600, now $300'","cat":0},{"text":"Lexus priced well above Toyota to signal luxury","cat":1},{"text":"Pricing at $314 rather than $300","cat":0}],"explanation":"Anchoring is judging relative to prior information; the price-quality effect is using price itself as a proxy for quality."}]},{"id":"MMK266-8.3","name":"Explain the availability heuristic and ease of recall","summary":"You can predict how ease of recall shifts judgements and preferences, including Wanke et al.'s reversal.","questions":[{"type":"match","prompt":"Match each Wanke et al. (1997) prompt to the result.","pairs":[["'Name one reason to choose a BMW'","BMW preferred"],["'Name ten reasons to choose a BMW'","Mercedes preferred"],["'Name one reason not to choose a BMW'","Mercedes preferred"],["'Name ten reasons not to choose a BMW'","BMW preferred"]],"explanation":"What matters is the felt ease of recall: struggling to list ten reasons is read as evidence there are not many."},{"type":"case","passage":"From 2001 to 2009, US National Flood Insurance Program policies grew 0 to 4% a year, except 2006, when they jumped 14.3%. Actual flood risk had not changed.","prompt":"What best explains the 2006 jump?","options":["The halo effect of insurer branding","Anchoring on insurance prices","Hurricane Katrina in 2005 made flood events easy to recall","Choice overload among policies"],"answer":2,"explanation":"The availability heuristic treats easily recalled events as more likely or true.","lvl":2},{"type":"mc","prompt":"US crime rates have fallen while fear of crime has risen. Which explanation fits the availability heuristic?","options":["Repeated exposure makes crime likeable","Crime statistics are hard to find","People anchor on old crime rates","Frequent news coverage makes crime stories easy to recall, so perceptions detach from actual rates"],"answer":3,"explanation":"'If it bleeds, it leads': regular news consumers recall crime easily and judge it more common.","lvl":1},{"type":"case","passage":"A skincare brand's email survey asks loyal customers to 'list ten reasons you love our moisturiser' to deepen their commitment.","prompt":"What is the risk, based on Week 8?","options":["None, because more reasons always strengthen preference","Struggling to list ten reasons may weaken their preference for the brand","It triggers the price-quality effect","It will cause choice overload"],"answer":1,"explanation":"The exam tip: asking for many reasons in favour of your brand can backfire, so ask for one, not ten.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The Wanke et al. result shows that the felt difficulty of recall is ignored when consumers judge a brand.","wrong":"ignored","correct":"used","explanation":"Consumers use the felt ease or difficulty of recall as evidence, not just the content they recall."},{"type":"type_answer","prompt":"Which heuristic describes things that are easy to remember being judged as true or common?","answers":["availability heuristic","availability","the availability heuristic"],"explanation":"The availability heuristic relies on ease of recall rather than actual frequency.","lvl":1}]},{"id":"MMK266-8.4","name":"Identify mere exposure and halo effects in marketing","summary":"You can recognise both heuristics in examples and know the limits Montoya et al. place on repetition.","questions":[{"type":"case","passage":"A pop song is 'meh' on first listen, but after weeks on the radio listeners say 'this is what a song of summer should sound like' and then 'I love this song'.","prompt":"Which heuristic and model explain this?","options":["Halo effect, via attractiveness","Availability heuristic, via ease of recall","Mere exposure effect, explained by the representation-matching model","Anchoring, via precise numbers"],"answer":2,"explanation":"Repeated exposure makes a stimulus seem how it should be and correct, which leads to positive evaluation.","lvl":3},{"type":"mc","prompt":"Week 3 said consumers ignore non-novel stimuli. How does Montoya et al.'s (2017) meta-analysis reconcile this with mere exposure?","options":["Novelty and repetition are identical","Liking increases forever with repetition","Repetition increases liking and perceived goodness only up to a point, after which the effect turns","Repetition never increases liking"],"answer":2,"explanation":"Mere exposure has a ceiling, so repetition works but should not be pushed indefinitely.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Mere exposure effect","Halo effect"],"items":[{"text":"Liking a jingle more after hearing it many times","cat":0},{"text":"Judging a restaurant's food as tasty from its decor","cat":1},{"text":"Judging an app's performance from its login page","cat":1},{"text":"Rating an attractive person as more intelligent","cat":1},{"text":"Warming to a politician after seeing them on TV often","cat":0}],"explanation":"Mere exposure is liking through repetition; the halo effect is one attribute biasing judgements of other, unrelated attributes."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The ___ model explains mere exposure: frequent exposure makes a stimulus seem correct, which leads to positive evaluation.","answers":["representation-matching","representation matching"],"explanation":"The more often we meet a stimulus, the more we perceive it as how it should be.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The halo effect describes one attribute biasing evaluations of other, related attributes.","wrong":"related","correct":"unrelated","explanation":"The halo effect is striking because the biased attributes are unrelated, like decor and food taste."},{"type":"analogy","prompt":"Repeated airplay is to the mere exposure effect as stylish restaurant decor is to ___","options":["the anchoring effect","the availability heuristic","choice overload","the halo effect"],"answer":3,"explanation":"Investing in visible surfaces such as decor, packaging and interfaces leverages the halo effect.","lvl":2}]},{"id":"MMK266-8.5","name":"Explain choice overload and how to prevent it","summary":"You can diagnose too little or too much choice and recommend ways to curate options, including menu design.","questions":[{"type":"case","passage":"A streaming subscriber scrolls through thousands of titles for 30 minutes and then turns the TV off without watching anything.","prompt":"Which of Netflix's features is designed to prevent this?","options":["Showing every title in alphabetical order","Showing a percentage match for each title to highlight personal relevance","Raising the subscription price","Removing all genres"],"answer":1,"explanation":"Choice overload can lead to no choice at all. Showing personal relevance helps consumers navigate large assortments.","lvl":2},{"type":"match","prompt":"Match each way of preventing choice overload to its example.","pairs":[["Strong existing preferences","Already knowing you like science fiction"],["Helping consumers see personal relevance","Netflix's percentage match for each title"],["Enhancing consumer expertise","Releasing trailers so consumers know what is available"]],"explanation":"Each factor reduces the effort of choosing from a large set."},{"type":"mc","prompt":"According to the notes, what happens when consumers have too little choice, such as the movies on free-to-air TV?","options":["They feel overwhelmed","They always make no choice","They feel dissatisfied with whatever they choose","They become more brand loyal"],"answer":2,"explanation":"There is a sweet spot: too little choice brings dissatisfaction and too much brings overwhelm.","lvl":2},{"type":"type_answer","prompt":"In menu engineering, what are menu items with low popularity and low profitability called?","answers":["dogs","dog"],"explanation":"Items with high popularity and high profitability are 'stars'; the Burger Stack task aimed to reduce dogs and increase stars.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Too much choice leaves consumers feeling satisfied, as with the huge volume of movies available on Netflix.","wrong":"satisfied","correct":"overwhelmed","explanation":"Excessive choice overwhelms consumers and can result in no choice being made."},{"type":"case","passage":"Burger Stack's menu data show a burger with high profitability but low popularity. The seminar allows prices to be maintained, increased for low-profit items, or decreased for high-profit items.","prompt":"Which pricing move fits the seminar's guidance for this burger?","options":["Decrease its price to lift popularity, since its high margin can absorb it","Keep the price and add more menu items around it","Increase its price to signal quality","Remove it immediately without changes"],"answer":0,"explanation":"A high-profit item can afford a price cut to build popularity and move toward 'star' status.","lvl":3}]}]},{"week":9,"topic":"Post-Choice: Use and Post-Use Evaluation","summary":"What happens after the choice: the endowment effect, IKEA effect and hedonic treadmill during use, and expectation-disconfirmation, cognitive dissonance and regret after use.","skills":[{"id":"MMK266-9.1","name":"Explain the endowment effect and tactics that trigger it","summary":"You can explain why owners overvalue what they own and design tactics that build ownership before purchase.","questions":[{"type":"mc","prompt":"In Kahneman et al.'s (1991) mug experiment, owners valued the mug at about $7.12 while buyers valued it at about $2.87. What does this gap show?","options":["Buyers had better information about the mug","Ownership itself raises willingness to accept above willingness to pay","Buyers were more loss averse than sellers","The mugs were of different quality"],"answer":1,"explanation":"The mug is identical in both conditions; only the relationship to it changes, which is the signature of the endowment effect.","lvl":2},{"type":"match","prompt":"Match each explanation or tactic to how it produces the endowment effect.","pairs":[["Loss aversion","Selling feels like a loss, so the loss is priced into the valuation"],["Psychological ownership","Attachment between self and possession inflates value"],["'Try before you buy' schemes","Free trials let consumers form an attachment before paying"],["Product personalisation","KitKat printing winners' names and faces on packs"]],"explanation":"The two explanations are loss aversion and psychological ownership; the tactics all manufacture a sense of ownership before money changes hands."},{"type":"case","passage":"A mattress retailer offers a 100-night home trial with free returns. Very few customers send their mattress back, even those with mild complaints.","prompt":"What best explains the low return rate?","options":["The hedonic treadmill","Once the mattress feels like 'ours', returning it feels like a loss","The IKEA effect from assembly","Choice overload at the time of return"],"answer":1,"explanation":"Generous trials lower perceived risk while building ownership, so giving the product back feels like a loss that outweighs mild dissatisfaction.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In the mug experiment, willingness to accept sat well below willingness to pay.","wrong":"below","correct":"above","explanation":"Owners' minimum selling price (willingness to accept) was more than double buyers' maximum price (willingness to pay)."},{"type":"type_answer","prompt":"What term describes the attachment consumers form between themselves and the products they own, which inflates their value?","answers":["psychological ownership"],"explanation":"Like a named childhood toy, possessions help define identity, and that attachment is factored into valuation.","lvl":3},{"type":"analogy","prompt":"The endowment effect is to owning as the IKEA effect is to ___","options":["adapting","making","regretting","selling"],"answer":1,"explanation":"Both raise perceived value, but the IKEA effect adds authorship and personal investment through co-creation.","lvl":2}]},{"id":"MMK266-9.2","name":"Apply the IKEA effect and its boundary conditions","summary":"You can design co-creation that raises perceived value without deterring purchase.","questions":[{"type":"case","passage":"In the 1950s Betty Crocker's cake mix sold slowly. Psychologists found cooks did not feel involved in making the cake. The company removed the powdered egg so cooks had to add fresh eggs.","prompt":"Why did sales rise?","options":["It reduced symbolic contamination","The cake became more convenient","Adding eggs made cooks feel they had contributed, raising competence and the value they placed on the cake","Fresh eggs lowered the price"],"answer":2,"explanation":"The IKEA effect: co-creation makes consumers feel competent and able to signal competence, so they value the product more (Mochon et al., 2012).","lvl":2},{"type":"case","passage":"A 3D printer lets consumers co-create almost anything and feel highly competent, yet many interested shoppers decide not to buy one.","prompt":"Which boundary condition of the IKEA effect explains this?","options":["The co-creation must be easy; high anticipated effort becomes a purchase barrier","Consumers cannot signal competence with a 3D printer","3D printers are credence goods","The endowment effect cancels the IKEA effect"],"answer":0,"explanation":"Consumers value past effort far more than anticipated future effort, so the setup and tinkering deter purchase.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In Norton et al.'s (2012) experiment, participants who assembled an IKEA box bid ___% higher than those who did not.","answers":["63","63%"],"explanation":"The 63% premium is the headline demonstration that co-creation raises valuation.","lvl":5},{"type":"mc","prompt":"The IKEA effect maps onto which pair of Schwartz values?","options":["Tradition and conformity","Security and power","Hedonism and stimulation","Self-direction (feeling competent) and achievement (signalling competence)"],"answer":3,"explanation":"Making things serves superordinate motives of competence and recognition, so consumers attach extra value to what they helped create.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Likely to produce an IKEA effect","Unlikely to produce an IKEA effect"],"items":[{"text":"A meal kit that is quick to cook and produces a dish worth photographing","cat":0},{"text":"A flat-pack shelf that assembles in ten minutes","cat":0},{"text":"Sneakers the buyer customises online","cat":0},{"text":"A device that needs days of setup before first use","cat":1},{"text":"A hidden internal step whose result no one can see or show off","cat":1}],"explanation":"The two boundary conditions are that consumers can feel or signal competence and that the co-creation is low effort."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Consumers value anticipated future effort far more than effort they have already expended.","wrong":"more","correct":"less","explanation":"Past effort adds value, but anticipated effort is a cost, which is why high-effort co-creation can deter buyers."}]},{"id":"MMK266-9.3","name":"Explain the hedonic treadmill and its marketing implications","summary":"You can explain why consumption happiness fades and what that means for novelty, variety and materialism.","questions":[{"type":"mc","prompt":"In 2019 the average Australian scored 7.2 out of 10 for happiness. According to the hedonic treadmill, what happens after buying something enjoyable?","options":["Happiness rises permanently above 7.2","Happiness falls below baseline and stays there","Happiness surges above baseline, then drifts back to about 7.2 as the consumer habituates","Happiness is unaffected by consumption"],"answer":2,"explanation":"Consumers adapt to their circumstances, so the boost from consumption is temporary.","lvl":2},{"type":"case","passage":"Jess buys a new pair of shoes every fortnight to recapture the buzz she felt with her first designer pair. Each buzz feels smaller and fades faster.","prompt":"What does this pattern illustrate, and what does it underpin?","options":["The hedonic treadmill, which underpins materialism","Positive disconfirmation, which underpins delight","The endowment effect, which underpins loyalty","The IKEA effect, which underpins co-creation"],"answer":0,"explanation":"Chasing the fading high of consumption, seeking purpose and meaning from products, is the basis of materialism (Week 11).","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Seeking purpose and meaning from products, and chasing the high of consumption, is the basis of ___.","answers":["materialism"],"explanation":"Materialism does not usually lead to longer-term happiness because of habituation.","lvl":2},{"type":"mc","prompt":"What does the hedonic treadmill imply for marketers?","options":["One great experience sustains a relationship indefinitely","Repeating identical products produces growing emotional returns","Adaptation only happens after negative events","Genuine novelty and variety can reset the happiness spike, so plan for repeat engagement"],"answer":3,"explanation":"Because the high fades, brands cannot rely on one experience, but the fading also motivates repeat consumption, which novelty can harness.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Diener et al. (2006) found people adapt after positive life events but never after negative events such as unemployment.","wrong":"never","correct":"also","explanation":"People adapt after both positive and negative events, though for some negative events the shift can be more lasting."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Raises perceived value","Erodes emotional value over time"],"items":[{"text":"The endowment effect","cat":0},{"text":"The IKEA effect","cat":0},{"text":"A free trial that builds ownership","cat":0},{"text":"The hedonic treadmill","cat":1},{"text":"Habituating to a new purchase","cat":1}],"explanation":"Ownership and co-creation raise value around acquisition, while the treadmill erodes emotional value over a longer horizon."}]},{"id":"MMK266-9.4","name":"Map performance against expectations to post-use emotions","summary":"You can place performance on Santos and Boote's expectation levels and predict delight, satisfaction, acceptance or dissatisfaction.","questions":[{"type":"order","prompt":"Put the lecture's peripheral expectation levels in order from highest to lowest.","items":["Ideal","Desirable","Prediction (core expectation)","Minimum tolerable","Worst imaginable"],"explanation":"The zone of tolerance spans from the ideal down to the minimum tolerable. The prediction is the core expectation for a specific offering."},{"type":"match","prompt":"Match each affective state to where performance falls (Santos and Boote, 2003).","pairs":[["Delight","Between the ideal and the desired"],["Satisfaction (positive indifference)","Between the desired and the predicted"],["Acceptance (negative indifference)","Between the predicted and the minimum tolerable"],["Dissatisfaction","Between the minimum tolerable and the worst imaginable"]],"explanation":"Delight and dissatisfaction lie outside the zone of indifference; satisfaction and acceptance lie within it."},{"type":"case","passage":"Game of Thrones earned consistently high IMDb ratings across seven seasons. The eighth and final season's ratings collapsed amid widespread fan anger.","prompt":"What does the expectation-disconfirmation model say went wrong?","options":["Early success pushed expectations toward the ideal, so the final season produced negative disconfirmation","The zone of tolerance expanded to include everything","Fans experienced the IKEA effect","Expectations were set too low"],"answer":0,"explanation":"Success inflates the expectations a brand must keep meeting; expectation setting is the crucial lever.","lvl":3},{"type":"case","passage":"A traveller always expects her regional flight to be delayed. Today it is delayed again, exactly as predicted.","prompt":"According to Santos and Boote, what is she likely to feel?","options":["Dissatisfaction, because her predicted expectation coincided with the minimum tolerable level","Delight, because the expectation was confirmed","No emotion is possible when expectations are confirmed","Satisfaction, because confirmation always satisfies"],"answer":0,"explanation":"Simple confirmation can produce any state, depending on which peripheral level the prediction lines up with (P4).","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Inside the zone of indifference","Outside the zone of indifference"],"items":[{"text":"Satisfaction (positive indifference)","cat":0},{"text":"Acceptance (negative indifference)","cat":0},{"text":"Delight","cat":1},{"text":"Dissatisfaction","cat":1}],"explanation":"States inside the zone produce no complimenting or complaining; delight leads to compliments and loyalty, dissatisfaction to complaints and switching."},{"type":"mc","prompt":"A customer complains about a faulty kettle. She receives a full refund but is spoken to rudely by staff and leaves angry. Which element of perceived justice was violated?","options":["Distributive justice","Response efficacy","Interactional justice","Procedural justice"],"answer":2,"explanation":"Interactional justice is the fairness of interpersonal treatment. Distributive concerns the tangible outcome and procedural concerns the procedures used.","lvl":3}]},{"id":"MMK266-9.5","name":"Select strategies to reduce cognitive dissonance and regret","summary":"You can match consumer and marketer strategies to dissonance or regret and justify one for a product.","questions":[{"type":"match","prompt":"Match each consumer dissonance strategy to the marketing tactic that leverages it.","pairs":[["Cognitive rationalisation","RSPCA-approved chicken"],["Self-affirmation","Linking lamb with Australia Day"],["Distraction or forgetting","Meat names such as beef, pork and venison"],["Behaviour change","Plant-based Beyond Meat burgers"]],"explanation":"Marketing strategies mirror the consumer strategies, doing the psychological work on the consumer's behalf."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Direct resolution","Escapism","Fluid compensation"],"items":[{"text":"Changing the attitude ('I don't really care about animals')","cat":0},{"text":"Adding a rationalising belief ('animals don't suffer')","cat":0},{"text":"Becoming vegetarian","cat":0},{"text":"Not thinking about where the meat came from","cat":1},{"text":"Trivialisation ('it doesn't matter what I do')","cat":2},{"text":"Self-affirmation ('there are more important things to worry about')","cat":2}],"explanation":"These map the Week 9 dissonance strategies onto the Week 1 compensatory strategies, a link the assessment rewards."},{"type":"case","passage":"Thirty days after purchase, Bellroy emails customers congratulating them and re-stating the benefits of a slim wallet.","prompt":"Which strategy is this, and what does it target?","options":["Two-sided messaging, targeting delight","Expectation setting, targeting dissonance","Facilitating behaviour change, targeting dissonance","A post-purchase message, targeting regret"],"answer":3,"explanation":"Post-purchase messages reach buyers when excitement has faded and doubt can creep in, reinforcing that the choice was right.","lvl":3},{"type":"case","passage":"Butterball runs a helpline advising consumers how to cook a Thanksgiving turkey.","prompt":"Why does this reduce regret?","options":["It gives instructions and after-sales support so complex products are used correctly and not blamed","It hides the animal source of the product","It uses social norms","It sets low expectations"],"answer":0,"explanation":"A badly cooked turkey would be blamed on the product, so support during use heads off disappointment and lost repeat sales.","lvl":2},{"type":"mc","prompt":"McGrath (2017) reports that people tend to use whichever dissonance-reduction route is presented to them first. What is the marketing implication?","options":["Avoid giving consumers any reduction route","Encourage behaviour change so they stop buying","Put a convenient, purchase-preserving route, such as reassuring certification, in front of consumers first","Always present attitude change first"],"answer":2,"explanation":"If the first route offered preserves the purchase, consumers are likely to take it rather than change behaviour.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Regret is fundamentally comparative, arising from a factual comparison between the outcome of the choice and the road not taken.","wrong":"factual","correct":"counterfactual","explanation":"Regret comes from counterfactual comparison, imagining what might have happened had the consumer chosen differently."}]}]},{"week":10,"topic":"Diffusion of Innovations","summary":"What counts as an innovation, why consumers adopt (Arts et al., 2011), and how innovations diffuse socially through adopter categories at an accelerating rate.","skills":[{"id":"MMK266-10.1","name":"Classify innovations using the four definitions of newness","summary":"You can answer 'new to whom?' for any offering and keep adoption and diffusion distinct.","questions":[{"type":"case","passage":"Spotify launched streaming in 2008. Apple launched its own music streaming service in 2016, when similar services had existed for almost a decade.","prompt":"Under which definition is Apple's service still an innovation?","options":["Firm-oriented","Market-oriented","Product-oriented","Consumer-oriented"],"answer":0,"explanation":"The firm-oriented definition counts anything a firm introduces for the first time, even if the market already has it.","lvl":3},{"type":"case","passage":"Face masks have existed for centuries, yet the first time many Australians wore one in the street it felt unusual and new.","prompt":"Which definition of innovation does this illustrate?","options":["Firm-oriented","Market-oriented","Consumer-oriented","Product-oriented"],"answer":2,"explanation":"The consumer-oriented definition counts anything a consumer perceives as new, so old technologies can be innovations for some consumers.","lvl":3},{"type":"match","prompt":"Match each definition of innovation to what the offering is new to.","pairs":[["Product-oriented","Other products meeting the same need"],["Consumer-oriented","The consumer"],["Firm-oriented","The firm"],["Market-oriented","The market"]],"explanation":"The four definitions are complementary and show innovation is in the eye of the beholder."},{"type":"mc","prompt":"Under the market-oriented definition, a product counts as an innovation if:","options":["The firm has never sold it before","Any single consumer perceives it as new","It has been bought by only a small proportion of the target market, or has been on sale only a short time","It requires completely new behaviour"],"answer":2,"explanation":"The lecture illustrated both criteria with virtual reality: time on market and units shipped.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Adoption","Diffusion"],"items":[{"text":"One consumer deciding to buy a digital camera","cat":0},{"text":"Worldwide digital camera sales over 15 years","cat":1},{"text":"An individual rejecting a VR headset","cat":0},{"text":"Mobile phones spreading through the Australian population","cat":1},{"text":"A micro process","cat":0},{"text":"A macro process","cat":1}],"explanation":"Adoption is the individual's accept-or-reject decision; diffusion is the sum of those decisions spreading through a population."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Diffusion is a micro process that captures the sum of all individual adoption decisions in a population.","wrong":"micro","correct":"macro","explanation":"Adoption is micro (the individual); diffusion is macro (the community or population)."}]},{"id":"MMK266-10.2","name":"Classify innovations by the behaviour change they require","summary":"You can classify an unseen innovation by the amount of behaviour change it requires and plan support accordingly.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Continuous","Dynamically continuous","Discontinuous"],"items":[{"text":"The 2020 Mazda 3 with refreshed styling and better braking","cat":0},{"text":"A phone update with a slightly better camera","cat":0},{"text":"Switching from a petrol car to a Tesla","cat":1},{"text":"The first flying cars","cat":2},{"text":"The arrival of the train as a new transport mode","cat":2}],"explanation":"Continuous needs no behaviour change, dynamically continuous needs some minor change (recharging, not refuelling), and discontinuous needs entirely new behaviour."},{"type":"mc","prompt":"According to the exam tip, what is the most precise marker for classifying product-oriented innovations?","options":["The size of the technology change","How long the firm has sold it","The price of the product","The amount of behaviour change required of the consumer"],"answer":3,"explanation":"Defining the types by technology change alone is a common exam trap; behaviour change is the precise marker.","lvl":3},{"type":"case","passage":"A company launches an induction cooktop that requires new cookware and changes how households cook, although it still sits in the kitchen like a normal stove.","prompt":"What should the company provide to support adoption?","options":["Education, training or intuitive design to ease the behaviour change","Nothing, because continuous innovations need no support","A trade character to avoid scandals","Only a price discount"],"answer":0,"explanation":"Dynamically continuous innovations often require a bigger behaviour change, so firms provide education, training or cleverly designed intuitive technology.","lvl":1},{"type":"order","prompt":"Put the product-oriented innovation types in order from least to most disruptive.","items":["Continuous innovation","Dynamically continuous innovation","Discontinuous innovation"],"explanation":"Disruption and required behaviour change rise across the three types, while frequency falls."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Because the benefit of upgrading is large, consumers may skip several release cycles of a continuous innovation.","wrong":"large","correct":"small","explanation":"Continuous innovations are minor tweaks, so the small upgrade benefit leads many consumers to skip releases."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A Tesla requires recharging rather than refuelling, which makes it a dynamically ___ innovation.","answers":["continuous"],"explanation":"It is fundamentally like a Mazda 3 but forces some new behaviours, such as charging at home.","lvl":4}]},{"id":"MMK266-10.3","name":"Distinguish line, form and category extensions and fit","summary":"You can classify a firm-oriented innovation and judge whether a category extension has enough fit.","questions":[{"type":"match","prompt":"Match each So Good product to the type of extension it represents.","pairs":[["Chocolate-flavoured soy milk","Product line extension"],["Refrigerated soy milk","Product form extension"],["So Good soy ice cream","Product category extension"]],"explanation":"Line extensions add attributes, form extensions change the functional format, and category extensions apply the brand to a new category."},{"type":"case","passage":"In the 1980s Colgate launched a range of ready-to-eat meals. They did not last long.","prompt":"What is the most likely reason?","options":["Form extensions always fail","Colgate lacked brand recognition","It was a line extension with too few flavours","The category extension lacked fit between toothpaste and dinners"],"answer":3,"explanation":"Category extensions leverage brand trust only when there is a logical connection, or fit, between the original product and the extension.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Line extension","Form extension","Category extension"],"items":[{"text":"A new flavour of an existing yoghurt","cat":0},{"text":"A larger family-size pack","cat":0},{"text":"Juice sold as a concentrate","cat":1},{"text":"Biscuits sold as ready-to-bake dough","cat":1},{"text":"So Good soy ice cream","cat":2},{"text":"Colgate ready meals","cat":2}],"explanation":"Format changes are form extensions; new attributes like size and flavour are line extensions; new categories are category extensions."},{"type":"type_answer","prompt":"What term describes the logical connection between an original product and a category extension?","answers":["fit"],"explanation":"Fit determines whether trust and recognition transfer to the extension.","lvl":3},{"type":"mc","prompt":"Which type of firm-oriented innovation is the most common?","options":["Line extensions","Category extensions","Discontinuous innovations","Form extensions"],"answer":0,"explanation":"Line extensions are most common, adding attributes to keep up with competitors or appeal to new segments. Form extensions are rarer.","lvl":3},{"type":"analogy","prompt":"Chocolate soy milk is to line extension as refrigerated soy milk is to ___","options":["discontinuous innovation","category extension","form extension","market-oriented innovation"],"answer":2,"explanation":"Refrigerated soy milk is the same product in a different format, so shoppers in the fridge section can still find it.","lvl":4}]},{"id":"MMK266-10.4","name":"Interpret how innovation traits affect intention and behaviour","summary":"You can state the direction of each Arts et al. effect and explain the gap using construal level theory.","questions":[{"type":"match","prompt":"Match each innovation characteristic to its pattern in Arts et al. (2011).","pairs":[["Compatibility","Strong positive on intention (.41), weak on behaviour (.07)"],["Complexity","Positive on intention (.21), negative on behaviour (-.20)"],["Uncertainty","Strong negative on intention (-.47), weak on behaviour (-.04)"],["Relative advantage","Positive on both, slightly stronger for behaviour (.21)"]],"explanation":"Compatibility and uncertainty dominate intention, relative advantage drives behaviour, and complexity flips sign."},{"type":"case","passage":"A feature-packed VR headset generates huge pre-launch interest and strong purchase intentions, but actual sales disappoint once it hits shelves.","prompt":"Which Arts et al. finding best explains this, and what should the firm do?","options":["Complexity lifts intention but lowers behaviour; manage expectations and support the learning curve","Compatibility is too strong; reduce lifestyle fit","Uncertainty increases behaviour; add more risk","Observability is too high; hide the product"],"answer":0,"explanation":"Novel complex features spark interest, but consumers underestimate complexity, so concrete learning costs become a barrier at purchase.","lvl":3},{"type":"mc","prompt":"How does construal level theory explain the intention-behaviour gap?","options":["Only demographics differ between the stages","Near decisions are abstract and focus on why; distant decisions are concrete and focus on how","Distant intention decisions are abstract and focus on desirability (why); near behaviour decisions are concrete and focus on feasibility and cost (how)","Consumers use identical criteria at both stages"],"answer":2,"explanation":"Arts et al. borrow CLT from Trope and Liberman (2003), linking the behaviour stage to loss aversion as costs loom larger.","lvl":3},{"type":"case","passage":"Two posters advertise the foreign-language film Parasite. One prominently displays its four Oscar wins, including Best Picture.","prompt":"Which innovation characteristic does the Oscar poster address?","options":["Observability","Trialability","It reduces uncertainty, which most damages adoption intention","Complexity"],"answer":2,"explanation":"Credible quality signals reduce perceived risk that the innovation will not deliver, the biggest brake on intention.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"To increase adoption behaviour, marketers should chiefly emphasise compatibility.","wrong":"compatibility","correct":"relative advantage","explanation":"Compatibility mainly drives intention; relative advantage is the lever for behaviour. Most campaigns work all three levers."},{"type":"mc","prompt":"In 1964, 45% of people surveyed said they wanted AT&T's Picturephone at home, yet the product failed. What lesson do Arts et al. draw?","options":["Treat stated intentions cautiously, because intention and behaviour rest on different criteria","Purchase intention is a reliable sales forecast","Videophones had too little complexity","Demographic segmentation would have fixed it"],"answer":0,"explanation":"A Synovate review found 91% of the variance in purchase behaviour is not captured by purchase intent.","lvl":2}]},{"id":"MMK266-10.5","name":"Explain diffusion through consumer traits and adopter categories","summary":"You can identify who drives adoption and explain why diffusion is social and accelerating.","questions":[{"type":"order","prompt":"Put Rogers' adopter categories in order from first to last to adopt.","items":["Innovators","Early adopters","Early majority","Late majority","Laggards"],"explanation":"Innovators (about 2.5%) and early adopters (about 13.5%) lead, and early adopters often decide whether an innovation reaches the majority."},{"type":"case","passage":"Aid agencies promoting boiled drinking water sent trained experts to give formal flip-chart presentations in villages. Adoption sat at about 4%.","prompt":"What change did Rogers' insight lead to, and with what result?","options":["Using celebrities, lifting adoption to 30%","Working through trusted local peers who spoke informally, asked advice and listened, lifting adoption to about 60%","Better flip charts, lifting adoption to 10%","Offering cash incentives, lifting adoption to 90%"],"answer":1,"explanation":"Diffusion is fundamentally social: who carries the message matters more than the quality of the information.","lvl":3},{"type":"mc","prompt":"Which consumer characteristic had by far the strongest effect on adoption intention in Arts et al. (2011)?","options":["Product involvement (.73)","Opinion leadership","Age","Income"],"answer":0,"explanation":"Product involvement is another way of describing attitude strength; for involved consumers the category is central to identity.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Stronger effect on intention","Stronger effect on behaviour"],"items":[{"text":"Product involvement","cat":0},{"text":"Education","cat":0},{"text":"Opinion leadership","cat":1},{"text":"Innovativeness","cat":1},{"text":"Income","cat":1}],"explanation":"Opinion leadership drives behaviour (.19) but not intention (-.01); innovativeness is positive on both but stronger for behaviour. Demographic effects are small overall."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Innovators make up about ___ of adopters.","answers":["2.5%","2.5","2.5 percent"],"explanation":"Innovators are high-involvement, highly innovative, risk-tolerant consumers; early adopters are the next 13.5%.","lvl":5},{"type":"mc","prompt":"The telephone took about 65 years to go from 5% to 90% of the US population, while the mobile phone took about 15. Which is one explanation offered in the lecture?","options":["Recent innovations may be less extreme and less discontinuous than earlier ones","Older innovations had more relative advantage","Diffusion has slowed over the last century","Consumers have become worse at understanding innovations"],"answer":0,"explanation":"The lecture also suggests consumers may be better at adopting innovations and that society is more consumer-oriented; the truth is probably a mix.","lvl":4}]}]}]};
window.LAMPLIGHT_UNITS["MMK101"] = {"code":"MMK101","name":"Marketing Fundamentals","term":"T1 2026","weeks":11,"weekList":[{"week":1,"topic":"What Is Marketing? Core Concepts","summary":"Marketing as creating value, the five orientations, core concepts, CRM, demarketing and responsible marketing.","skills":[{"id":"MMK101-1.1","name":"Explain marketing as creating value using the AMA definition","summary":"You can unpack each part of the AMA (2017) definition and show why value, not advertising, is the heart of marketing.","questions":[{"type":"mc","prompt":"According to the AMA (2017) definition used in MMK101, which idea sits at the heart of marketing?","options":["Maximising sales volume for the company","Advertising and promoting products to as many people as possible","Creating value for customers, clients, partners and society at large","Setting the lowest price in the market"],"answer":2,"explanation":"The single keyword in the AMA definition is value. Advertising is only one way of communicating value, not the whole of marketing.","lvl":1},{"type":"case","passage":"A friend argues that bottled water is just water, so branding is pointless. In class, students said they choose Pump because the pop top works one-handed at the gym, and Voss because the glass bottle feels premium.","prompt":"What does this best illustrate?","options":["The water inside each brand differs significantly in quality","Marketing attaches value through branding, packaging and perceptions to a basically identical product","Consumers mainly choose water brands on price","Bottled water demand is driven only by basic needs"],"answer":1,"explanation":"The water bottle example shows that the product inside is basically the same; the value comes from branding, packaging and perceived quality cues.","lvl":2},{"type":"match","prompt":"Match each part of the AMA definition to what it means.","pairs":[["Creating value","Designing something genuinely better than competing options"],["Communicating value","Telling people about it, mostly through promotion"],["Delivering value","Getting it to the customer through distribution"],["Exchanging","The customer pays and the firm gets paid"]],"explanation":"Each verb in the definition maps to a marketing task: design, promotion, distribution and a mutually beneficial exchange."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Marketing is the activity, set of institutions, and processes for creating, communicating, delivering and exchanging offerings that have ___ for customers, clients, partners and society at large.","answers":["value"],"explanation":"This is the AMA (2017) definition, and value is its keyword.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In the water bottle example, Pump's pop top that works one-handed shows that price is the value customers are buying.","wrong":"price","correct":"convenience","explanation":"Pump's value is convenience (one-handed use at the gym or driving). The notes stress price usually comes in only at the end as a trade-off."},{"type":"analogy","prompt":"Voss is to a premium glass bottle as Pump is to ___","options":["one-handed convenience","100% recycled packaging","a Fijian origin story","the lowest price on the shelf"],"answer":0,"explanation":"Voss signals premium through glass, while Pump's value is the convenient pop top. The origin story belongs to Fiji and recycled packaging to Mount Franklin.","lvl":3}]},{"id":"MMK101-1.2","name":"Distinguish the five marketing orientations and eras","summary":"You can place a business mindset in the right orientation and explain why marketing and societal orientations start from the customer.","questions":[{"type":"order","prompt":"Put the eras of marketing in order from earliest to current.","items":["Production era","Product era","Selling era","Marketing era","Societal marketing era"],"explanation":"OpenStax frames the five orientations as a timeline: production, product, selling, marketing, then societal marketing."},{"type":"case","passage":"An appliance maker spends years perfecting a technically advanced blender. Management believes home cooks will automatically love it, so no one researches what cooks actually need.","prompt":"Which orientation is this, and what is the main risk?","options":["Marketing orientation, because it focuses on quality","Societal marketing orientation, because durable products last longer","Production orientation, risking a price war","Product orientation, risking marketing myopia"],"answer":3,"explanation":"A product orientation assumes the best product will sell itself. Being so product-focused that you lose sight of the customer need is marketing myopia.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Starts from the company","Starts from the customer"],"items":[{"text":"Marketing orientation","cat":1},{"text":"Production orientation","cat":0},{"text":"Societal marketing orientation","cat":1},{"text":"Sales orientation","cat":0},{"text":"Product orientation","cat":0}],"explanation":"The exam distinction: marketing and societal marketing orientations start from customer needs, while production, product and sales orientations start from the company itself."},{"type":"type_answer","prompt":"What term describes being so product-focused that a firm loses sight of the actual customer need?","answers":["marketing myopia","myopia"],"explanation":"Marketing myopia is the danger of the product era, linked to old-school Apple's 'customers don't know what they want' thinking.","lvl":3},{"type":"mc","prompt":"Which orientation balances the customer's wants, the company's profit and society's long-term wellbeing?","options":["Product orientation","Societal marketing orientation","Marketing orientation","Sales orientation"],"answer":1,"explanation":"The societal marketing orientation adds society's long-term wellbeing and the environment to the customer focus of the marketing orientation.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In the selling era, demand outstripped supply, so firms focused on producing efficiently and making products affordable.","wrong":"selling","correct":"production","explanation":"When demand outstripped supply, the focus was efficient production. The selling era came later when supply outgrew demand."}]},{"id":"MMK101-1.3","name":"Differentiate needs, wants, demands, markets and exchange","summary":"You can classify examples as needs, wants or demands and explain markets, exchange, transactions and market offerings.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Need","Want","Demand"],"items":[{"text":"Needing to stay connected with others","cat":0},{"text":"Wanting a Tesla and having finance approved to buy it","cat":2},{"text":"Needing shelter","cat":0},{"text":"Wanting an iPhone specifically","cat":1},{"text":"A student with savings who is ready to buy an iPhone today","cat":2},{"text":"Wanting a Voss bottle rather than any water","cat":1}],"explanation":"Needs are basic requirements, wants are culture-shaped expressions of a need, and demands are wants backed by purchasing power."},{"type":"mc","prompt":"Why do marketers usually measure demand rather than needs or wants?","options":["Demand is wants backed by purchasing power, so it can actually be counted","Wants are shaped by culture, so they cannot exist in a market","Needs change too quickly to measure","Marketers create needs, so they already know them"],"answer":0,"explanation":"Marketers try to turn needs and wants into demand, and demand is measured because it is the countable part. Marketers do not create needs; they already exist.","lvl":2},{"type":"case","passage":"Deakin runs open days aimed at Year 12 students who have not yet applied, while also surveying current students about their satisfaction with teaching.","prompt":"How does this reflect the MMK101 definition of a market?","options":["A market is defined by the product rather than the buyers","A market only includes current paying customers","A market is the physical place where exchange happens","A market includes both actual and potential buyers who share a need or want"],"answer":3,"explanation":"A market is the set of actual and potential buyers sharing a need. Marketers keep actual buyers happy and convert potential ones, such as next year's Year 12s.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A ___ is the actual completed trade, involving at least two things of value plus agreed conditions, time and place.","answers":["transaction"],"explanation":"A transaction is the measurable result of marketing effort, while exchange is the broader willingness to trade.","lvl":3},{"type":"analogy","prompt":"Exchange is to willingness to trade as transaction is to ___","options":["a potential buyer","perceived sacrifice","the completed, measurable trade","a basic human need"],"answer":2,"explanation":"Exchange is the more basic idea of trading value; the transaction is the completed trade that proves marketing worked.","lvl":3},{"type":"type_answer","prompt":"What term does MMK101 use for the bundle of goods, services and experiences that satisfies a need, such as a MacBook plus AppleCare, updates and warranty?","answers":["market offering","market offerings","offering"],"explanation":"Almost nothing is purely a product or a service, so the unit calls the whole bundle a market offering.","lvl":3}]},{"id":"MMK101-1.4","name":"Apply customer value, satisfaction, the marketing process and CRM","summary":"You can calculate perceived value in words, sequence the marketing process and match CRM types and customer terms to scenarios.","questions":[{"type":"mc","prompt":"How does MMK101 define perceived customer value?","options":["Selling price minus production cost","Perceived benefits minus perceived sacrifice (money, time, effort and risk)","The total potential profit from all current and future customers","Product performance compared with expectations after purchase"],"answer":1,"explanation":"Perceived value is benefits minus sacrifice, and sacrifice includes more than money. Performance versus expectations is satisfaction, and total potential profit is customer equity.","lvl":2},{"type":"case","passage":"A café's loyalty app records every order. The café analyses the data, spots that iced drink sales spike on warm afternoons, and adjusts its specials based on that trend.","prompt":"Which type of CRM is the café using?","options":["Analytical CRM","Operational CRM","Collaborative CRM","Transactional CRM"],"answer":0,"explanation":"Analytical CRM collects and analyses customer data to spot trends for data-driven decisions. Operational CRM automates turning leads into customers, and collaborative CRM shares data across businesses.","lvl":3},{"type":"order","prompt":"Put the five steps of the marketing process in order.","items":["Understand the marketplace and customer needs and wants","Design a customer-driven marketing strategy","Construct an integrated marketing program that delivers superior value","Build profitable relationships and create customer delight","Capture value from customers in return"],"explanation":"The first four steps create value for customers and the fifth captures value back as profit, loyalty, referrals and brand equity."},{"type":"match","prompt":"Match each customer term to its meaning.","pairs":[["Customer loyalty","An ongoing positive relationship that drives repeat purchases"],["Customer retention","Keeping existing customers, which is cheaper than winning new ones"],["Customer equity","The total potential profit from all current and future customers"],["Customer satisfaction","Product performance compared with expectations after purchase"]],"explanation":"Loyalty and retention feed customer equity, which is the value captured in step 5 of the marketing process."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Customer satisfaction is usually measured before purchase by comparing the product's performance against the customer's expectations.","wrong":"before","correct":"after","explanation":"Satisfaction compares performance with expectations and is usually measured after purchase or consumption."},{"type":"case","passage":"Maya enrols at Deakin even though the tuition, travel time and study effort are significant, because she believes the employability, skills and knowledge will outweigh them.","prompt":"Which concept best explains her decision?","options":["High customer equity, because she will be a profitable future customer","A transaction without any exchange","Demarketing, because the cost reduces demand","Positive perceived value, because perceived benefits exceed perceived sacrifice"],"answer":3,"explanation":"This is the notes' own Deakin example of perceived value: she enrols only because the benefits outweigh the money, time and effort.","lvl":2}]},{"id":"MMK101-1.5","name":"Distinguish demarketing, CSR, societal, social and cause marketing","summary":"You can recognise demarketing and tell apart CSR, societal, social, cause-related and ethical marketing in real cases.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Temporary demarketing","Permanent demarketing"],"items":[{"text":"A hospital booking system slowing access to specialists","cat":0},{"text":"Machu Picchu limiting daily tickets during high demand","cat":0},{"text":"Uluru being permanently closed to climbers","cat":1},{"text":"An anti-smoking campaign discouraging smoking for good","cat":1}],"explanation":"Temporary demarketing manages demand that is too high for capacity; permanent demarketing discourages harmful behaviour or access for good."},{"type":"mc","prompt":"Which statement correctly describes demarketing?","options":["Increasing demand in off-peak periods","Linking product purchases to fundraising for a cause","Deliberately reducing demand, either temporarily or permanently","Marketing a cause to raise donations"],"answer":2,"explanation":"Watch the MCQ wording: demarketing reduces demand. Any option that increases demand is normal marketing.","lvl":2},{"type":"match","prompt":"Match each concept to the class example.","pairs":[["Corporate Social Responsibility","Going beyond what the law requires to do the right thing"],["Societal marketing concept","The Body Shop's plant-based, cruelty-free approach"],["Social marketing","Misereor's 'Social Swipe' donation poster"],["Cause-related marketing","Qantas x UNICEF linking purchases to fundraising"]],"explanation":"CSR goes beyond legal duty, societal marketing benefits the wider community, social marketing markets a cause or behaviour, and cause-related marketing links purchases to fundraising."},{"type":"case","passage":"A sportswear brand promises a small donation to an ocean charity for every shoe sold. Its ads focus almost entirely on a 40% discount and barely mention the charity.","prompt":"What criticism from the notes best applies?","options":["It is unethical because SDGs must always be cited","It risks tipping into cause-exploitative marketing, more about selling than giving","It is social marketing because it markets a behaviour","It is demarketing because it reduces demand"],"answer":1,"explanation":"Cause-related marketing lets firms do well by doing good, but critics warn it becomes cause-exploitative when it is more about selling than giving.","lvl":3},{"type":"type_answer","prompt":"How many UN Sustainable Development Goals were adopted by 193 countries in 2015 under the 2030 Agenda?","answers":["17","seventeen"],"explanation":"The 2030 Agenda introduced 17 SDGs, cited as UN (2015), which was flagged in A1 marker feedback.","lvl":4},{"type":"mc","prompt":"Which of these is NOT one of the core principles of ethical marketing listed in the notes?","options":["Marketers must be transparent about what they say and who they target","All marketing should be true","Marketing should always aim to maximise short-term sales","The end user's privacy is a top priority"],"answer":2,"explanation":"Ethical marketing is a philosophy of fairness, honesty and responsibility: truth, privacy, following the rules and transparency. Maximising short-term sales is not a principle.","lvl":1}]}]},{"week":2,"topic":"Analysing the Marketing Environment","summary":"Reading the micro and macro environment, generational trends, opportunities and threats, and the 7Ps toolbox.","skills":[{"id":"MMK101-2.1","name":"Classify microenvironment actors and their impact","summary":"You can identify the six microenvironment actors in a scenario and explain whether each creates an opportunity or threat.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Microenvironment","Macroenvironment"],"items":[{"text":"Media publics","cat":0},{"text":"Rising interest rates","cat":1},{"text":"An ageing population","cat":1},{"text":"Suppliers of raw materials","cat":0},{"text":"New AI and e-wallet payment technology","cat":1},{"text":"Competitors such as Uniqlo and H&M","cat":0}],"explanation":"Microenvironment actors are close to the company (company, suppliers, intermediaries, competitors, publics, customers). Macro forces are broad societal forces (demographic, economic, natural, technological, political, cultural)."},{"type":"case","passage":"BHP's Local Buying Program works with Indigenous businesses such as Gumala Enterprises to provide the resources BHP needs to operate.","prompt":"Which microenvironment actor does this program relate to?","options":["Suppliers","Competitors","Publics","Marketing intermediaries"],"answer":0,"explanation":"Suppliers provide the resources needed to make the offering, and smart marketers treat suppliers as partners, as BHP does.","lvl":2},{"type":"mc","prompt":"Which of these is a marketing intermediary?","options":["A government regulator","The company's own R&D department","A citizen-action group lobbying the company","A physical distribution firm that moves stock to retailers"],"answer":3,"explanation":"Intermediaries help promote, sell and distribute: resellers, physical distribution firms, marketing services agencies and financial intermediaries. The others are publics or the company itself.","lvl":2},{"type":"type_answer","prompt":"Which microenvironment actor is any group with an actual or potential interest in, or impact on, the company, such as media, local or citizen-action groups?","answers":["publics","public"],"explanation":"The textbook lists seven publics: financial, media, government, citizen-action, local, general and internal.","lvl":3},{"type":"case","passage":"Rio Tinto and BHP publicly acknowledged the Uluru Statement from the Heart, responding to the communities near where they operate.","prompt":"Which type of public is most directly involved?","options":["Internal publics","Government publics","Financial publics","Local publics"],"answer":3,"explanation":"The notes use this acknowledgement as the example of engaging local publics.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Customers are a bigger threat when they are very demanding and have few alternatives, giving them bargaining power.","wrong":"few","correct":"many","explanation":"Customers have bargaining power, and so are a bigger threat, when they have lots of choice. They are less of a threat when you are the only real option."}]},{"id":"MMK101-2.2","name":"Identify the six macroenvironment forces in scenarios","summary":"You can assign real events to the demographic, economic, natural, technological, political or cultural force.","questions":[{"type":"match","prompt":"Match each example to the macroenvironment force it reflects.","pairs":[["ABAC ordering CUB to rename 'Hard Solo'","Political"],["Alibaba's Hema facial-recognition checkout","Technological"],["Tiffany & Co. and The Reject Shop serving different income tiers","Economic"],["Growing shortages of raw materials","Natural"]],"explanation":"Regulation is political, new retail tech is technological, income distribution is economic, and raw material shortages are a long-term natural trend."},{"type":"case","passage":"During the 2019 bushfires, a pharmacy chain saw mask sales jump sharply within days, while a clothing retailer had earlier suffered when a warm 2018 winter hurt winter clothing sales.","prompt":"Which macro force explains both effects?","options":["The demographic environment","The cultural environment, through secondary values","The natural environment, through short-term weather and disaster effects","The economic environment, through income distribution"],"answer":2,"explanation":"Short-term natural effects such as weather and natural disasters hit sales directly, as in the notes' bushfire and warm winter examples.","lvl":3},{"type":"mc","prompt":"Which of these is a secondary belief that marketers can realistically shift?","options":["Core values passed from parents to children","Marrying early","Values reinforced by schools and religion over generations","Believing in marriage"],"answer":1,"explanation":"Core beliefs are highly persistent. Secondary beliefs are more open to change: 'believe in marriage' is core, 'marry early' is secondary.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In Australia, business legislation that protects companies from each other through fair competition is enforced by the ___.","answers":["ACCC","Australian Competition and Consumer Commission"],"explanation":"Legislation protects companies from each other, consumers from unfair practices, and society from unrestrained business; the ACCC enforces competition.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The cultural environment covers facts and numbers such as population size, age and family structure.","wrong":"cultural","correct":"demographic","explanation":"Demographic means facts and numbers; cultural covers qualitative values and perceptions. MCQs love testing that line."},{"type":"type_answer","prompt":"According to the notes, what is the single most important demographic trend in Australasia?","answers":["ageing population","an ageing population","aging population","changing age structure","the changing age structure"],"explanation":"Falling birthrates plus longer life expectancy produce an ageing population, the key Australasian demographic trend.","lvl":4}]},{"id":"MMK101-2.3","name":"Match generational cohorts and demographic trends to markets","summary":"You can link each generation and demographic shift to its buying traits and suitable marketing approach.","questions":[{"type":"match","prompt":"Match each generation to its key trait.","pairs":[["Baby boomers","About 28% of the population but around 56% of national wealth"],["Generation X","Frugal, sceptical of overt marketing, research heavily before buying"],["Millennials (Gen Y)","Seek authenticity and want to co-create 'Instagramable' experiences"],["Generation Z","Digital integrators, 63% more likely to support a brand backing a cause"]],"explanation":"Each cohort needs a different approach, from wealth-focused offers for boomers to cause-driven brands for Gen Z."},{"type":"case","passage":"A travel company launches 'Fun Over 50' adventure tours for energetic retirees who refuse to slow down.","prompt":"Which group is it targeting?","options":["Zoomers, the more active baby boomers","Generation X, who are family-first and frugal","Millennials, who want to co-create experiences","Generation Z, who spend via their parents"],"answer":0,"explanation":"Zoomers are active baby boomers, and Fun Over 50 travel is the notes' example.","lvl":3},{"type":"mc","prompt":"A financial services brand wants to win Generation X customers. Which approach best fits the notes?","options":["Provide hard evidence and testimonials they can research before buying","Focus only on co-created Instagram experiences","Avoid email and social media entirely","Rely on overt, hard-sell promotion"],"answer":0,"explanation":"Gen X are sceptical of overt marketing and research heavily, so evidence and testimonials convince them. They still use social media and email.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Changing family","Geographic shift","Increasing diversity"],"items":[{"text":"Smaller and more non-traditional households","cat":0},{"text":"Sea-change and tree-change moves","cat":1},{"text":"More women in the workforce lifting demand for HelloFresh","cat":0},{"text":"The SOHO and telecommuting boom","cat":1},{"text":"An LGBTIQ+ market worth around $20 billion a year","cat":2},{"text":"Link Disability Magazine reaching Australians living with disability","cat":2}],"explanation":"These are the notes' three demographic trend groups beyond age: the changing family, geographic population shifts and increasing diversity."},{"type":"analogy","prompt":"Smiggle is to Generation Z as Airbnb is to ___","options":["Generation X","Baby boomers","Zoomers","Millennials"],"answer":3,"explanation":"The notes list Smiggle, Cotton On Kids and EB Games for Gen Z, and Airbnb and Uber for Millennials.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Baby boomers were born between 1946 and ___.","answers":["1964"],"explanation":"Baby boomers span 1946 to 1964 and are the wealthiest generation in Australian history.","lvl":4}]},{"id":"MMK101-2.4","name":"Analyse environmental factors as opportunities or threats","summary":"You can judge a factor as micro or macro, opportunity or threat, evidence it properly, and tell proactive from reactive responses.","questions":[{"type":"case","passage":"For Cotton On's new bamboo clothing line, research shows there are hundreds of bamboo fabric suppliers operating in Australia.","prompt":"How should this factor be classified in an environment analysis?","options":["A microenvironment threat, because more suppliers means more competition","A macroenvironment threat, because bamboo is a natural resource","A microenvironment opportunity, because suppliers have low bargaining power","A macroenvironment opportunity, because it is a political factor"],"answer":2,"explanation":"Suppliers are micro actors. Many suppliers means low bargaining power over Cotton On, which is an opportunity, ideally quantified.","lvl":4},{"type":"mc","prompt":"Which statement would score best in an Assignment 1 style environment analysis?","options":["Cotton On is a Melbourne-based clothing brand","Import tariffs on bamboo clothing are X% (per IBISWorld), which is a threat to Cotton On's costs","Cotton On will respond by launching an eco-friendly campaign","Tariffs are high, which is bad for the company"],"answer":1,"explanation":"Markers want specific, sourced evidence tied to the impact on the company. Describing what the company does belongs to strategy, not environment analysis.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Proactive","Reactive"],"items":[{"text":"Running media events to shape public opinion","cat":0},{"text":"Creating a whole new industry, as Uber did","cat":0},{"text":"Passively accepting population shifts","cat":1},{"text":"Taking opportunities as they come","cat":1},{"text":"Hiring lobbyists to influence regulation","cat":0},{"text":"Watching trends and adapting to them","cat":1}],"explanation":"Proactive firms try to change the environment; reactive firms treat it as uncontrollable and adapt."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"When analysing the environment, keep the discussion to internal factors and their impact on the company.","wrong":"internal","correct":"external","explanation":"The seminar correction: stick to external factors and their impact on the company, and do not describe what the company is doing."},{"type":"mc","prompt":"Which forces does the textbook say really cannot be controlled, so firms must simply react?","options":["Population shifts, the economy and major cultural values","Regulation influenced by lobbyists","Competitor behaviour kept in line through complaints","Public opinion shaped through media events"],"answer":0,"explanation":"Smart marketers aim to be proactive, but some forces such as population shifts, the economy and major cultural values cannot be controlled.","lvl":3},{"type":"type_answer","prompt":"'There are three kinds of companies: those who make things happen, those who watch things happen, and those who wonder what's happened.' Which response to the environment do smart marketers aim for?","answers":["proactive","a proactive response","proactive response"],"explanation":"The textbook uses this line to argue that smart marketers try to be proactive rather than merely reactive.","lvl":3}]},{"id":"MMK101-2.5","name":"Identify elements of the extended 7Ps marketing mix","summary":"You can match each of the 7Ps to its role and explain why services need people, process and physical evidence.","questions":[{"type":"match","prompt":"Match each P to what it covers.","pairs":[["Price","The only P that brings in revenue"],["People","Staff who deliver and represent the service"],["Process","The steps and systems that deliver the service"],["Physical evidence","Tangible cues such as decor, uniforms and equipment"]],"explanation":"The 4Ps plus people, process and physical evidence form the extended marketing mix."},{"type":"mc","prompt":"According to Rathod (2016), why were three extra Ps added to the original 4Ps?","options":["Physical goods needed more promotion tools","The 4Ps ignored price as a revenue source","Services are intangible, inseparable, variable and perishable, so the 4Ps were not enough","McCarthy (1960) originally proposed seven Ps"],"answer":2,"explanation":"Service characteristics mean people, process and physical evidence often matter more to customers in service industries than product, price or promotion.","lvl":3},{"type":"case","passage":"A physiotherapy clinic renovates its waiting room, gives staff branded uniforms and prints professional brochures so new patients feel confident before treatment begins.","prompt":"Which P is the clinic mainly investing in?","options":["Place","Physical evidence","Process","People"],"answer":1,"explanation":"Physical evidence is the tangible cues customers use to judge an intangible service: building, decor, uniforms and communication materials.","lvl":2},{"type":"order","prompt":"Put the three steps of the MMK101 unit map in order.","items":["Market analysis","Marketing strategy (STDP)","Marketing mix (7Ps)"],"explanation":"Analyse the market first, then set strategy through STDP (Assignment 1), then carry it out through the 7Ps (Assignment 2)."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The classic 4Ps of the marketing mix were proposed by ___ in 1960.","answers":["McCarthy"],"explanation":"The 4Ps come from McCarthy (1960); services marketing added three more Ps.","lvl":4},{"type":"analogy","prompt":"Staff training is to People as a quick, consistent step-by-step check-in procedure is to ___","options":["Physical evidence","Promotion","Place","Process"],"answer":3,"explanation":"People covers the staff; Process covers the steps and systems that deliver the service smoothly and consistently.","lvl":2}]}]},{"week":3,"topic":"Differentiation & Positioning","summary":"Creating points of difference on the five bases, choosing value propositions, and writing positioning statements and maps.","skills":[{"id":"MMK101-3.1","name":"Distinguish differentiation, positioning and differentiated marketing","summary":"You can define each term precisely, avoid the differentiated marketing trap, and explain that position lives in the customer's mind.","questions":[{"type":"mc","prompt":"Which option defines positioning as taught in MMK101?","options":["Advertising the product's features to the widest possible audience","Arranging for an offering to occupy a clear, distinctive and desirable place in target customers' minds relative to competitors","Targeting several segments with a separate tailored offer for each","Creating real or perceived differences between your offering and competitors' to create superior value"],"answer":1,"explanation":"Positioning is how differences are perceived in the customer's mind. Creating the differences is differentiation, and targeting several segments is differentiated marketing.","lvl":2},{"type":"case","passage":"VF Corporation runs more than 30 premium lifestyle brands, each designed to tap a defined segment's aspirations to fashion, status and wellbeing.","prompt":"Which concept does this best illustrate?","options":["Concentrated marketing on a single niche","Positioning by contrast against an 'enemy' brand","Differentiation, creating points of difference for one offering","Differentiated (segmented) marketing, a targeting decision"],"answer":3,"explanation":"Serving several segments with tailored offers is differentiated marketing, which is a targeting decision and a classic MCQ trap next to differentiation.","lvl":4},{"type":"case","passage":"BP changed its logo to a green sunburst to look environmental, yet many consumers still do not see BP as an environmental brand.","prompt":"What does this case show about positioning?","options":["Image differentiation can be built quickly with one campaign","Positioning is set by what the company says about itself","Brands can influence perception, but the target audience ultimately decides the position","A logo change guarantees a successful reposition"],"answer":2,"explanation":"Brands influence; the audience decides. BP cannot simply dictate an environmental perception.","lvl":2},{"type":"match","prompt":"Match each required quality of a position to its meaning.","pairs":[["Clear","Easily and obviously seen against competing brands"],["Distinctive","Different and outstanding, not a copy of what rivals own"],["Desirable","Genuinely positive, something the target customer wants"]],"explanation":"The positioning definition contains three qualities the lecturer drilled: clear, distinctive and desirable."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A product position is defined by the company's perception of its product relative to competing brands.","wrong":"company's","correct":"customer's","explanation":"The product position is the set of perceptions, impressions and feelings the customer holds. It does not matter what the company thinks."},{"type":"analogy","prompt":"Samsung versus iPhone is to distinctiveness as Dyson's original bagless vacuum is to ___","options":["differentiation","repositioning","differentiated marketing","commoditisation"],"answer":0,"explanation":"Samsung and iPhone are functionally similar but distinct in branding. Dyson's bagless vacuum was a genuine, preemptive product difference.","lvl":3}]},{"id":"MMK101-3.2","name":"Classify brands by the five bases of differentiation","summary":"You can link a brand's advantage to the product, service, channel, people or image base and state it specifically.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Product","Channel","People"],"items":[{"text":"Bunnings' knowledgeable staff in red uniforms","cat":2},{"text":"Tesla's futuristic design","cat":0},{"text":"Amazon's early dominance through a fast, wide-range direct channel","cat":1},{"text":"Dyson's instantly recognisable design","cat":0},{"text":"Dell's online build-to-order model","cat":1},{"text":"Disney training every employee around 'make people happy'","cat":2}],"explanation":"These are the brand-to-base placements from the seminar. Amazon and Dell won on distribution, not unique products."},{"type":"mc","prompt":"Which list shows the five bases of differentiation taught in MMK101?","options":["Product, service, channel, people, image","Product, price, place, promotion, people","Product, service, price, image, promotion","Quality, price, channel, people, image"],"answer":0,"explanation":"The five bases are NOT the marketing mix Ps. The poll option listing price, place and promotion was a deliberate trap.","lvl":3},{"type":"case","passage":"A software firm's advantage comes from back-stage engineering talent. The engineers never meet customers, but the firm's culture and training depth are very hard for rivals to copy.","prompt":"Which base of differentiation is the firm drawing on?","options":["Service","People","Image","Channel"],"answer":1,"explanation":"People differentiation is not only front-line staff. Google and Microsoft create value through back-stage talent, and culture is hard to copy.","lvl":3},{"type":"case","passage":"An airline's crew are trained to anticipate what passengers want before they ask, from booking help to in-flight care to follow-up after arrival.","prompt":"Which base does this mainly reflect?","options":["Image","Channel","Product","Service"],"answer":3,"explanation":"Service differentiation spans the customer journey. Anticipating needs, as Singapore Airlines does, is the gold standard beyond normal service.","lvl":2},{"type":"type_answer","prompt":"Which differentiation base covers corporate associations such as innovative, sustainable or prestigious, built through symbols like Nike's swoosh?","answers":["image","brand image","image base"],"explanation":"Brand image is built over years through symbols, associations and consistent operations, so it cannot be advertised into existence.","lvl":3},{"type":"order","prompt":"Put the stages of the service customer journey in order.","items":["Pre-purchase","Purchase","Post-purchase (after-sales)"],"explanation":"Service differentiation asks what the firm does at each stage: information and trials, an easy transaction, then warranty, repairs and updates."}]},{"id":"MMK101-3.3","name":"Evaluate points of difference against the seven criteria","summary":"You can test a proposed POD against the seven criteria and explain why price is not a differentiation base.","questions":[{"type":"case","passage":"A new phone model's only visible change is a better camera, yet it costs about $500 more. Many buyers cannot see what they are paying extra for.","prompt":"Which criterion for a worthwhile point of difference is failing?","options":["Preemptive","Profitable","Communicable","Important"],"answer":2,"explanation":"Communicable means the buyer can see or perceive the difference. If the improvement is not visible, the value is not communicated.","lvl":4},{"type":"mc","prompt":"Why is price not a sustainable basis for differentiation?","options":["Price is already covered by the image base","It can be matched overnight, and market leaders can outlast smaller rivals in a price war","Customers never consider price when buying","The ACCC prohibits competing on price"],"answer":1,"explanation":"Price is easily copied (Bunnings and Officeworks change thousands of tickets a day) and leaders with economies of scale set the price guideline.","lvl":2},{"type":"match","prompt":"Match each criterion to its meaning.","pairs":[["Preemptive","Not easily copied, giving a head start"],["Affordable","Customers can pay the price the feature requires"],["Profitable","The company still makes money from it"],["Distinctive","Competitors do not already offer the same thing"]],"explanation":"A POD should pass all seven tests: important, distinctive, superior, communicable, preemptive, affordable and profitable."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Kmart and Aldi's low prices are the visible result of ___ leadership, not a differentiation base in themselves.","answers":["cost"],"explanation":"Lean operations and supplier relationships cut cost; the low price is the symptom and cost leadership is the strategy.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"For fast-moving consumer goods, aim for points of difference that competitors find hard to copy for around six weeks or more.","wrong":"weeks","correct":"months","explanation":"The lecturer's rule of thumb is around six months or more, which is what makes a POD preemptive."},{"type":"type_answer","prompt":"How many points of difference does the Assignment 1 positioning statement require?","answers":["two","2"],"explanation":"Two PODs are required so they can become the two axes of the positioning map.","lvl":3}]},{"id":"MMK101-3.4","name":"Match brands to the four value-proposition strategies","summary":"You can place a brand on the price-quality grid and spot the muddled middle.","questions":[{"type":"match","prompt":"Match each brand to its value-proposition strategy.","pairs":[["Hermès","More-for-more"],["Lexus versus Mercedes","More-for-the-same"],["Big W","Same-for-less"],["A no-frills airline","Less-for-much-less"]],"explanation":"The four strategies are different price-quality relationships, each serving segments with different priorities."},{"type":"case","passage":"TWG Tea took a commodity and made it luxury with canary-yellow canisters, more than 1,000 single-estate teas with exotic names, and premium retail in fashion capitals.","prompt":"Which value-proposition strategy is TWG using?","options":["More-for-the-same","Same-for-less","Less-for-much-less","More-for-more"],"answer":3,"explanation":"TWG offers the most prestigious product and charges a premium to match, targeting buyers with low price sensitivity.","lvl":2},{"type":"case","passage":"Amazon positioned its Kindle Fire tablet against the iPad as 'premium products at non-premium prices', offering similar capability for less.","prompt":"Which strategy does this represent?","options":["More-for-more","Less-for-much-less","Same-for-less","More-for-the-same"],"answer":2,"explanation":"Same-for-less offers the same quality at a lower price without claiming to be better, funded by efficiency or buying power.","lvl":2},{"type":"mc","prompt":"What is the 'muddled middle' danger in value-proposition strategy?","options":["Trying to be both 'more' and 'cheaper' at once, so the brand stands for nothing","Using only one clear value proposition","Choosing a less-for-much-less strategy","Charging a premium for genuinely high quality"],"answer":0,"explanation":"All four strategies are legitimate. The danger is unclear or inconsistent positioning that lacks credibility.","lvl":2},{"type":"analogy","prompt":"Patek Philippe is to more-for-more as budget motels are to ___","options":["less-for-much-less","more-for-the-same","same-for-less","more-for-more"],"answer":0,"explanation":"Budget accommodation offers fewer features at a much lower price, which is honest positioning for buyers who do not need the best.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Lexus challenged Mercedes, BMW and Audi with comparable quality at a markedly higher price.","wrong":"higher","correct":"lower","explanation":"Lexus is the definitive more-for-the-same case: comparable or better engineering at a markedly lower price."}]},{"id":"MMK101-3.5","name":"Construct positioning statements, maps and repositioning moves","summary":"You can write a consistent positioning statement, build a map on the same two PODs, and explain repositioning cases.","questions":[{"type":"order","prompt":"Put the parts of the MMK101 positioning statement template in order.","items":["To [target segment]","who [need],","our [brand] is [a/an product concept]","that [point of difference 1] and [point of difference 2]."],"explanation":"Use the unit's exact one-sentence template, not the textbook's, and keep the commas."},{"type":"case","passage":"A student writes: 'To the corporate executive who needs an efficient car, our Tesla brand is an electric vehicle that drives 600km per charge with lower running cost.'","prompt":"What is the main problem with this draft?","options":["It should be written as a consumer slogan","The product concept should be 'Model Y'","It needs three points of difference","The need does not match the segment, because executives prioritise prestige"],"answer":3,"explanation":"The seminar marked this down: pick the need that genuinely reflects the segment, then make both PODs answer it.","lvl":3},{"type":"mc","prompt":"On a positioning map, where should your focus brand sit?","options":["Anywhere, as long as competitors are nearby","Bottom-left, to signal affordability","Top-right, highest on both chosen dimensions","In the centre, to appeal to everyone"],"answer":2,"explanation":"As the Kool-Aid question showed, the focus brand must be highest on both valuable positions, or those values stop helping it.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A positioning statement is an external communication tool that tells everyone in the organisation who you serve and your points of difference.","wrong":"external","correct":"internal","explanation":"A positioning statement is internal and strategic; slogans such as 'Just Do It' are the external, consumer-facing versions."},{"type":"case","passage":"Old Spice was seen as 'smells like my grandpa'. Its famous relaunch featured an ex-NFL player and updated packaging.","prompt":"What did the repositioning change?","options":["Its channel, to sell only online","The communication and packaging, while the scent stayed the same","Its price, to become a same-for-less brand","The scent, to remove the old-fashioned smell"],"answer":1,"explanation":"Old Spice kept the very thing customers disliked; the communication changed the perception.","lvl":2},{"type":"mc","prompt":"Which pair of axes best suits a Tesla positioning map for Prestige Seekers?","options":["Quality versus price","Futuristic versus conventional design, and high-quality versus basic materials","Social media presence versus none, and price","Affordable versus expensive, and quality versus no quality"],"answer":1,"explanation":"Axes must be the two specific PODs. Avoid the bare word 'quality' and avoid 'affordable', which relates to price, not differentiation.","lvl":3}]}]},{"week":4,"topic":"Consumer Buyer Behaviour","summary":"Why consumers buy: buying behaviour types, influencing factors, the decision process, roles, personality and adoption.","skills":[{"id":"MMK101-4.1","name":"Classify the four types of consumer buying behaviour","summary":"You can place a purchase in the right buying behaviour type using involvement and brand difference, and read the Black Box model.","questions":[{"type":"match","prompt":"Match each buying behaviour type to its example.","pairs":[["Complex","Buying a new car"],["Dissonance-reducing","Replacing kitchen floor tiles"],["Habitual","Buying the usual brand of milk"],["Variety-seeking","Trying new chip flavours"]],"explanation":"The four types come from two dimensions: level of involvement and perceived differences between brands."},{"type":"case","passage":"Sam is happy with his usual chips but buys a different new flavour every week just for novelty. It is a cheap, low-effort purchase.","prompt":"Which buying behaviour is this?","options":["Complex","Habitual","Variety-seeking","Dissonance-reducing"],"answer":2,"explanation":"Low involvement plus high brand difference, switching for novelty rather than dissatisfaction, is variety-seeking.","lvl":2},{"type":"mc","prompt":"Which combination defines dissonance-reducing buying behaviour?","options":["Low involvement and high perceived brand differences","Low involvement and low perceived brand differences","High involvement and high perceived brand differences","High involvement and low perceived brand differences"],"answer":3,"explanation":"Buyers of things like floor tiles decide fairly quickly because brands seem similar, but may feel buyer's remorse afterwards.","lvl":3},{"type":"mc","prompt":"In the Buyer's Black Box model, which of these is an output (buyer response)?","options":["Purchase timing, amount and frequency","Buyer attitudes and motives","The 4Ps as marketing stimuli","Economic and cultural environmental stimuli"],"answer":0,"explanation":"Outputs are product, brand and dealer choice plus timing, amount and frequency. Attitudes sit inside the box, and the 4Ps and environment are inputs.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"In the Buyer's Black Box model, marketers can see the stimuli and the responses, but the mental processing inside the ___ is hidden.","answers":["black box","box"],"explanation":"Because the processing is hidden, marketers try to decode the black box and intervene before responses appear.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Habitual buying behaviour involves low involvement and high perceived differences between brands.","wrong":"high","correct":"low","explanation":"Habitual buying is low involvement with low brand difference, such as buying the usual milk with little thought."}]},{"id":"MMK101-4.2","name":"Identify cultural, social, personal and psychological influences","summary":"You can assign an influence on buying to the right factor group, including Maslow, perception and situational factors.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Cultural","Social","Personal"],"items":[{"text":"Minecraft gamers as a subculture","cat":0},{"text":"A friend group's restaurant recommendation","cat":1},{"text":"Brides wearing red in India and white in Western contexts","cat":0},{"text":"Choosing a practical SUV because of young children","cat":1},{"text":"A 40-year-old new parent versus an empty-nester","cat":2},{"text":"A tradie buying a ute and safety gear","cat":2}],"explanation":"Culture and subculture are cultural; family and reference groups are social; occupation and life-cycle stage are personal."},{"type":"order","prompt":"Put Maslow's hierarchy of needs in order from lowest to highest.","items":["Physiological","Safety and security","Social (belonging)","Esteem","Self-actualisation"],"explanation":"People satisfy lower needs first. Snickers targets physiological needs; Nike's 'Find Your Greatness' targets self-actualisation."},{"type":"case","passage":"In the Pepsi Challenge, many Coke loyalists preferred Pepsi in a blind taste test, yet they stayed loyal to Coke afterwards.","prompt":"Which perceptual process explains this?","options":["The Law of Effect","Selective retention","Selective distortion","Selective attention"],"answer":2,"explanation":"Selective distortion bends information to fit existing beliefs, so a blind result did not change their brand belief.","lvl":3},{"type":"match","prompt":"Match each psychological concept to its example.","pairs":[["Selective attention","Noticing food ads only when hungry"],["Selective retention","Remembering messages that match your values"],["Law of Effect","A good iPhone experience making you buy other Apple products"],["Ideal self-concept","Buying a luxury fitness brand for who you want to be"]],"explanation":"Perception filters what we notice and remember; learning repeats pleasant outcomes; self-concept drives aspirational buying."},{"type":"case","passage":"A grocery store installs bright LED lighting along one side of the store, and purchases on the lit side rise by about 25%.","prompt":"Which type of influence is this?","options":["A situational factor, the physical environment","A personal factor, lifestyle","A psychological factor, motivation","A cultural factor, social class"],"answer":0,"explanation":"Situational factors such as lighting, music and scent are especially powerful in-store.","lvl":2},{"type":"type_answer","prompt":"An attitude combines beliefs, affect (feelings) and which third component?","answers":["behavioural intention","intention","behavioral intention","behaviour intention"],"explanation":"An attitude is beliefs plus feelings plus behavioural intention (buy or not), and the three can be inconsistent.","lvl":3}]},{"id":"MMK101-4.3","name":"Apply the five-stage consumer decision process","summary":"You can sequence the stages, spot heuristics and cognitive dissonance, and choose marketing interventions for each stage.","questions":[{"type":"order","prompt":"Put the five stages of the consumer decision process in order.","items":["Need recognition","Information search","Evaluation of alternatives","Purchase decision","Post-purchase evaluation"],"explanation":"The process runs before, during and after the transaction, although habitual buys can skip stages."},{"type":"case","passage":"After booking a holiday to New York, Priya keeps wondering whether she should have picked Europe, and reads reviews and travel vlogs to reassure herself.","prompt":"Which stage and concept does this show?","options":["Evaluation of alternatives, using a heuristic","Information search, moving to active search","Need recognition, from an external stimulus","Post-purchase evaluation, with cognitive dissonance"],"answer":3,"explanation":"Post-purchase doubt is cognitive dissonance; consumers seek confirming information after buying.","lvl":2},{"type":"mc","prompt":"A shopper assumes a $90 bottle of wine must be better than a $20 one. Which heuristic is this?","options":["Selective retention","Price equals quality","Brand loyalty","Country of origin"],"answer":1,"explanation":"Heuristics are mental shortcuts in the purchase stage; assuming higher price means higher quality is the price-quality heuristic.","lvl":1},{"type":"match","prompt":"Match each decision stage to a suitable marketing intervention.","pairs":[["Need recognition","Winter holiday ads that trigger the need early"],["Information search","SEO, hashtags and testimonials"],["Evaluation of alternatives","Highlighting your valuable position against competitors"],["Purchase decision","'Buy now' buttons and scarcity cues like 'only 1 left'"]],"explanation":"The seminar holiday activity showed a different marketing tool fits each stage."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The group of options left after a consumer judges attributes against personal criteria, such as PS5 versus Nintendo versus Xbox, is the ___ set.","answers":["consideration"],"explanation":"Evaluation of alternatives treats products as bundles of attributes and narrows them to a consideration set.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"When product performance exceeds expectations in post-purchase evaluation, the customer is satisfied.","wrong":"satisfied","correct":"delighted","explanation":"Meeting expectations means satisfied, exceeding them means delighted, and falling short means dissatisfied."}]},{"id":"MMK101-4.4","name":"Identify buyer decision roles, brand personality and self-concept","summary":"You can target the right decision role and link brands to personality dimensions and self-concept.","questions":[{"type":"case","passage":"Old Spice found that about 60% of its men's products were bought by women for their partners, so its 2010 relaunch spoke directly to women.","prompt":"Which roles were women playing in these purchases?","options":["Buyer and decider, while men were the users","Influencers only","Users, while men were the buyers","Initiators only"],"answer":0,"explanation":"Marketers must target the right role. Old Spice spoke to women as buyer and decider even though men used the product.","lvl":3},{"type":"match","prompt":"Match each brand to its brand personality dimension.","pairs":[["Red Bull","Excitement"],["Microsoft","Competence"],["Chanel","Sophistication"],["Jeep","Ruggedness"]],"explanation":"Aaker-style dimensions from the notes: sincerity, excitement, competence, sophistication and ruggedness."},{"type":"mc","prompt":"When a family buys a ute, the uncle who says 'buy a HiLux' is playing which role?","options":["Initiator","Influencer","Buyer","Decider"],"answer":1,"explanation":"The influencer is the person whose views or advice carry weight, even though they may not decide or pay.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Actual self-concept","Ideal self-concept","Social self-concept"],"items":[{"text":"Joining a premium gym as an aspiration","cat":1},{"text":"Buying everyday brands that fit who I think I am","cat":0},{"text":"Choosing a visible watch brand to impress colleagues","cat":2},{"text":"Buying luxury activewear for the person I want to become","cat":1},{"text":"Choosing a phone mainly by how others will see me","cat":2},{"text":"Picking a practical backpack because 'that's just me'","cat":0}],"explanation":"Actual is who I think I am, ideal is who I want to be, and social is how I think others see me, which matters for publicly consumed products."},{"type":"type_answer","prompt":"Which brand personality dimension (down-to-earth, honest, wholesome, cheerful) do the notes link to Coles?","answers":["sincerity"],"explanation":"Coles is the notes' example of sincerity.","lvl":4},{"type":"analogy","prompt":"Initiator is to first suggesting the purchase as user is to ___","options":["giving advice that carries weight","paying for the product","making the final decision","consuming or using the product"],"answer":3,"explanation":"The five roles are initiator, influencer, decider, buyer and user, and they can be different people.","lvl":1}]},{"id":"MMK101-4.5","name":"Apply the adoption process and Rogers' adopter categories","summary":"You can sequence adoption, match adopter categories to percentages, and explain what speeds adoption and word of mouth.","questions":[{"type":"order","prompt":"Put the new-product adoption process in order.","items":["Awareness","Interest","Evaluation","Trial","Adoption"],"explanation":"Trial is the critical risk-reduction stage before full adoption."},{"type":"match","prompt":"Match each adopter category to its share of the population.","pairs":[["Innovators","2.5%"],["Early adopters","13.5%"],["Early majority","34%"],["Laggards","16%"]],"explanation":"Rogers (1962): innovators 2.5%, early adopters 13.5%, early and late majority 34% each, laggards 16%."},{"type":"mc","prompt":"Which adopter category is the most valuable target when launching a new product?","options":["Early majority","Innovators","Early adopters","Laggards"],"answer":2,"explanation":"Innovators buy first, but early adopters are trusted opinion leaders who pull the majority along through personal influence.","lvl":2},{"type":"case","passage":"A car maker offers free weekend test drives of its new electric car so buyers can try it before committing.","prompt":"Which characteristic affecting the rate of adoption is the firm using?","options":["Complexity","Compatibility","Relative advantage","Divisibility"],"answer":3,"explanation":"Divisibility is whether a product can be trialled first, through test drives or samples.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"High complexity speeds up the rate of adoption of a new product.","wrong":"speeds","correct":"slows","explanation":"Complexity is how hard a product is to understand or use, and high complexity slows adoption."},{"type":"case","passage":"A supplement brand gives free products to a fitness influencer whose perceived expertise makes followers trust her, hoping to spark word of mouth in her community.","prompt":"Which concept does this illustrate?","options":["Habitual buying behaviour","Buzz marketing using an opinion leader","Selective retention","Subliminal advertising"],"answer":1,"explanation":"Buzz marketing enlists opinion leaders as ambassadors. In the two-step flow, personal influence drives adoption after media creates awareness.","lvl":2}]}]},{"week":5,"topic":"Product & Marketing Analytics","summary":"The three levels of product, product classes and lines, packaging, marketing research and product metrics.","skills":[{"id":"MMK101-5.1","name":"Distinguish the core, actual and augmented product levels","summary":"You can place any product feature at the right level and choose the level a strategy should change.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Core product","Actual product","Augmented product"],"items":[{"text":"The Apple Genius Bar","cat":2},{"text":"A smartphone's sleek touchscreen design","cat":1},{"text":"Tiffany's signature blue box","cat":1},{"text":"The iPhone's connectivity, freedom and status","cat":0},{"text":"Butterball's annual turkey-cooking hotline","cat":2},{"text":"Lunatello's peace of mind about what goes on your family's skin","cat":0}],"explanation":"Core is the underlying benefit, actual is the tangible offering including packaging and design, and augmented is the extra service and support."},{"type":"case","passage":"Lunatello, a small start-up with essentially one physical balm, plans to add sample sizes, educational content about tallow science and a loyalty program.","prompt":"Which product level is Lunatello mainly developing?","options":["The augmented product","The product mix","The actual product","The core product"],"answer":0,"explanation":"For a small business, the augmented layer is where there is most room to add value without launching a new product.","lvl":3},{"type":"mc","prompt":"What is the core product?","options":["The warranty and after-sales care","All product lines the company sells","The underlying need or benefit the customer is really buying","The features, brand name and packaging"],"answer":2,"explanation":"The core answers 'what problem am I really solving?', such as convenience for a single-use water bottle.","lvl":1},{"type":"case","passage":"The same French jam is sold in a tall, elongated glass jar that signals 'artisan', and in a stocky plastic squeeze bottle that signals 'budget convenience'.","prompt":"What does this show?","options":["Packaging belongs only to the augmented product","Packaging is part of the actual product and identifies, describes and promotes it","Packaging is a purely practical decision","Packaging is part of the core product benefit"],"answer":1,"explanation":"Packaging is a strategic actual-product decision; the lecturer's jam example shows it changes what the product signals.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The ___ product is the extra services, support and benefits layered on top, such as warranties, return policies and after-sales care.","answers":["augmented"],"explanation":"These extras are often unseen but create real differentiation.","lvl":2},{"type":"analogy","prompt":"The Genius Bar is to the augmented product as Apple's white glossy box is to the ___","options":["actual product","product mix","core product","unsought product"],"answer":0,"explanation":"Packaging that signals premium before you see the device is part of the actual product.","lvl":3}]},{"id":"MMK101-5.2","name":"Classify products into consumer product types and broadened concepts","summary":"You can classify offerings as convenience, shopping, specialty or unsought and recognise people, places and ideas as products.","questions":[{"type":"match","prompt":"Match each consumer product type to its example.","pairs":[["Convenience","Milk"],["Shopping","A winter jacket"],["Specialty","A Rolex"],["Unsought","Life insurance"]],"explanation":"Products are classified by how consumers buy them, which shapes pricing, distribution and promotion."},{"type":"case","passage":"A family spends several weekends comparing sofas across furniture stores on style, price and quality before buying.","prompt":"Which consumer product type is the sofa?","options":["Specialty product","Unsought product","Shopping product","Convenience product"],"answer":2,"explanation":"Shopping products are bought less often, with research and comparison, at mid prices through selective distribution.","lvl":2},{"type":"mc","prompt":"Which marketing approach does an unsought product usually need?","options":["Exclusive distribution and high prices","Wide distribution with little promotion","Side-by-side comparison displays","Aggressive promotion, because consumers are unaware or not actively seeking it"],"answer":3,"explanation":"Blood donation, funeral services and life insurance are not sought until prompted, so they need aggressive promotion.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Specialty products are frequent, low-price, habitual purchases that are widely distributed.","wrong":"Specialty","correct":"Convenience","explanation":"That describes convenience products. Specialty products are unique, high-price and exclusive, and consumers make a special effort."},{"type":"type_answer","prompt":"Lunatello currently sits closest to a shopping product. Which product class does it aspire to, where brand trust drives repurchase without comparison?","answers":["specialty","specialty product","speciality","speciality product"],"explanation":"Naming the classification in A2 shows how it shapes distribution and promotion.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["People","Places","Ideas"],"items":[{"text":"A tourist destination competing for visitors","cat":1},{"text":"A place recovering from conflict marketing to bring tourists back","cat":1},{"text":"A politician in the Victorian election","cat":0},{"text":"FightMND","cat":2},{"text":"A blood-donation campaign","cat":2},{"text":"Taylor Swift managing her personal brand","cat":0}],"explanation":"The broadened concept of product applies marketing to people, places and ideas as well as goods and services."}]},{"id":"MMK101-5.3","name":"Apply product line, branding and packaging decisions","summary":"You can identify line filling, stretching, licensing and product mix moves and judge packaging and labelling decisions.","questions":[{"type":"match","prompt":"Match each product decision to its example.","pairs":[["Line filling","Shampoo variants for dry, oily and curly hair"],["Line stretching","Toyota extending upward into luxury with Lexus"],["Licensing","HiSmile toothpaste in Reese's flavour"],["Product mix diversification","Coles and Woolworths selling insurance"]],"explanation":"Filling adds variants, stretching adds price tiers, licensing rents another brand's equity, and the product mix spans all lines."},{"type":"case","passage":"HiSmile launched a Reese's Peanut Butter Cup flavoured toothpaste to stand out, using the Reese's name rather than building recognition from scratch.","prompt":"Which strategy is this?","options":["Line filling","Licensing","Line stretching","Product-bundle pricing"],"answer":1,"explanation":"Licensing rents another brand's equity to enter or stand out in a category without building recognition from scratch.","lvl":3},{"type":"mc","prompt":"In the retail 'good-better-best' strategy, which products now heavily take the 'good' entry-level tier?","options":["Home brands","Specialty products","Licensed products","Premium branded products"],"answer":0,"explanation":"Good is entry level, now largely taken by home brands, with branded products holding the better and best tiers.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The total set of all product lines and items a company offers is its product ___.","answers":["mix","assortment"],"explanation":"The product mix or assortment is everything a company sells, such as everything Nestlé offers.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Product line length is the number of product lines a company offers.","wrong":"lines","correct":"items","explanation":"Product line length is the number of items within a single line; all the lines together form the product mix."},{"type":"case","passage":"Sunbites crackers feature 'with quinoa' prominently on the front of pack, yet the product contains only 3.5% quinoa.","prompt":"How can a shopper tell the quinoa content is small?","options":["Allergen labels list the main ingredient first","Front-of-pack claims must show exact percentages","Australian law requires ingredients to be listed in descending order by quantity","Certifications show ingredient proportions"],"answer":2,"explanation":"Descending-order labelling is why sugar often appears first on cereals and why the quinoa in Sunbites is clearly minor.","lvl":2}]},{"id":"MMK101-5.4","name":"Plan marketing research using objectives and data types","summary":"You can sequence the research process, pick the right objective and data type, and spot stated versus actual behaviour.","questions":[{"type":"order","prompt":"Put the four steps of the marketing research process in order.","items":["Define the problem and set objectives","Develop the research plan","Collect and analyse the data","Interpret and report findings"],"explanation":"Defining the problem is the most critical step, and the process can loop back if data is not answering the question."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Primary data","Secondary data"],"items":[{"text":"Observing shoppers in store (ethnography)","cat":0},{"text":"The MMK101 Lunatello cohort survey","cat":0},{"text":"An academic journal article","cat":1},{"text":"An IBISWorld industry report","cat":1},{"text":"A focus group run for this decision","cat":0},{"text":"ABS population data","cat":1}],"explanation":"Primary data is collected for this specific problem; secondary data already exists for another purpose."},{"type":"case","passage":"A snack brand trials new packaging in a handful of stores in one region to test whether it actually increases sales before a national rollout.","prompt":"Which type of research objective is this?","options":["Ethnographic","Descriptive","Exploratory","Experimental (causal)"],"answer":3,"explanation":"Experimental research tests cause and effect, often by trialling in a few stores or one region first.","lvl":2},{"type":"case","passage":"At Reflex, shoppers said they buy Australian-made paper, but when researchers watched them shop, most did not.","prompt":"What does this case show?","options":["Ethnography reveals the gap between stated and actual behaviour","Secondary data is more relevant than primary data","Surveys are always more accurate than observation","Consumers reliably report their true motives"],"answer":0,"explanation":"People say one thing and do another, which is why observation is powerful and feedback should not be taken at face value.","lvl":2},{"type":"match","prompt":"Match each criterion for evaluating secondary data to its question.","pairs":[["Relevance","Does it address the research question?"],["Accuracy","Was it rigorously collected?"],["Currency","Is it recent enough?"],["Impartiality","Is it objective, and who paid for it?"]],"explanation":"Secondary data is fast and cheap but may not fit, so check relevance, accuracy, currency and impartiality."},{"type":"mc","prompt":"Which statement about qualitative research is correct?","options":["It relies on loyalty and sales data","It tells you WHY something is happening, using methods like focus groups and interviews","It is always secondary data","It tells you WHAT is happening using large samples and statistics"],"answer":1,"explanation":"Quantitative data shows what is happening with numbers; qualitative data explains why through words, themes and meanings.","lvl":1}]},{"id":"MMK101-5.5","name":"Use the MIS, big data and product metrics to guide decisions","summary":"You can name MIS sources and the 5 Vs, choose a product metric, and apply the insight-to-metric chain.","questions":[{"type":"match","prompt":"Match each Marketing Information System source to its example.","pairs":[["Internal records","Flybuys loyalty-program data"],["Marketing intelligence","Social listening and competitor monitoring"],["Marketing research","A formal study for one specific decision"]],"explanation":"An MIS draws on internal records, marketing intelligence and marketing research."},{"type":"type_answer","prompt":"Which 'V' of big data refers to the accuracy and trustworthiness of the data?","answers":["veracity"],"explanation":"The 5 Vs are volume, velocity, variety, veracity and value.","lvl":3},{"type":"mc","prompt":"Lunatello wants to know how many first-time buyers of a new balm came back to buy again. Which metric fits?","options":["Trial rate","Share of voice","Repeat purchase rate","Click-through rate"],"answer":2,"explanation":"Trial rate counts first-time buyers; repeat purchase rate counts how many trialists returned.","lvl":2},{"type":"case","passage":"After Lunatello changed its jar, sales rose 20%. The same month, it also ran a heavy discount and a competitor ran out of stock.","prompt":"Why is the sales figure alone not enough to judge the product change?","options":["Sales data is always misleading and should be ignored","Only star ratings can measure product changes","A 20% rise proves the jar change worked","Other factors may be driving the bump, so pair sales data with qualitative feedback"],"answer":3,"explanation":"The notes warn that sales bumps may have nothing to do with the product change, so pick metrics that reflect the change and add qualitative feedback.","lvl":1},{"type":"order","prompt":"Put the Assignment 2 evidence-to-strategy chain in order.","items":["Insight","Implication","Strategy","Metric"],"explanation":"What the data shows, what it means for the target market, what Lunatello should do, and how success is measured."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In multi-select survey questions, percentages that add up to more than 100% are abnormal.","wrong":"abnormal","correct":"normal","explanation":"When respondents can pick several options, totals above 100% are expected."}]}]},{"week":6,"topic":"Promotion & Integrated Marketing Communications","summary":"The five promotion tools, IMC, media and campaign planning, ethics and regulation, and promotion metrics.","skills":[{"id":"MMK101-6.1","name":"Distinguish the five tools of the promotion mix","summary":"You can define each promotion tool, tell personal from non-personal, and pick the right tool for a scenario.","questions":[{"type":"match","prompt":"Match each promotion tool to its definition.","pairs":[["Advertising","Paid, non-personal, one-way communication by an identified sponsor"],["Sales promotion","Short-term incentives encouraging immediate purchase"],["Personal selling","A two-way presentation by the firm's sales force"],["Public relations","Earning favourable publicity and heading off unfavourable stories"]],"explanation":"Direct and digital marketing is the fifth tool, using databases for targeted, measurable responses."},{"type":"case","passage":"A charity sends past donors a personalised letter showing their name, their last donation and their sponsored child's progress, using the address held from sign-up.","prompt":"Which promotion tool is this?","options":["Direct and digital marketing","Sales promotion","Public relations","Advertising"],"answer":0,"explanation":"Direct mail uses an existing database for personalised messages, which is why charities like World Vision still use snail mail.","lvl":3},{"type":"case","passage":"Coca-Cola sets up a pop-up stand at Southern Cross Station where staff talk to passers-by and hand out its 'share happiness' cans.","prompt":"Which direct marketing sub-tool is this?","options":["Publicity","Telemarketing","Direct mail","Kiosk marketing"],"answer":3,"explanation":"Kiosk marketing is the pop-up stand in a shopping centre or station where staff engage people directly.","lvl":4},{"type":"mc","prompt":"Which promotion tool is strongest for building trust in complex, high-value purchases?","options":["Out-of-home billboards","Personal selling","Advertising","Sales promotion"],"answer":1,"explanation":"Personal selling is personal and two-way, making it the best trust builder, although it is expensive per contact.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Discounts generally need to be more than about ___ per cent before they strongly affect fast-moving consumer goods.","answers":["30","thirty"],"explanation":"The seminar noted discounts of more than about 30% are needed for strong FMCG impact.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Personal","Non-personal"],"items":[{"text":"A press release earning a news story","cat":1},{"text":"A coupon in a catalogue","cat":1},{"text":"A sales rep presenting to a retail buyer","cat":0},{"text":"A consultant demonstrating software to a client","cat":0},{"text":"A radio ad on Nova","cat":1}],"explanation":"Personal selling uses your people in two-way contact; advertising, sales promotion and PR are non-personal."}]},{"id":"MMK101-6.2","name":"Explain IMC and analyse the Weis campaign","summary":"You can use the correct IMC terminology, explain why tools are integrated, and read the Weis case across objectives, tools and metrics.","questions":[{"type":"mc","prompt":"What is the deliberate blend of advertising, sales promotion, PR, personal selling and direct and digital marketing called when coordinated to send one message?","options":["Integrated marketing","Differentiated marketing","Integrated Marketing Communications (IMC), the promotion mix","The marketing mix"],"answer":2,"explanation":"The first MCQ trap: 'integrated marketing' is a broad general concept. If the word 'communications' is missing, it is the wrong answer.","lvl":2},{"type":"case","passage":"Apple uses very little sales promotion. Its main exception is a small student discount of around 10%.","prompt":"Why does Apple limit sales promotion?","options":["Students are Apple's only target market","Sales promotion is illegal for technology products","Heavy discounting would clash with its premium positioning","Apple has no budget for promotions"],"answer":2,"explanation":"The mix should reflect the positioning. The student discount is used for ethical and access reasons.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The Weis campaign's positioning leaned on an emotional connection with the Australian 'snow seeker'.","wrong":"snow","correct":"sunshine","explanation":"Weis positioned around the 'sunshine seeker' and an iconic Aussie summer feeling."},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Above the line","Below the line","Digital"],"items":[{"text":"Social media and online video","cat":2},{"text":"Out-of-home presence","cat":0},{"text":"Free product sampling","cat":1},{"text":"Spotify audio","cat":2},{"text":"Radio partnership with Nova","cat":0},{"text":"Competitions and contests","cat":1}],"explanation":"ATL reaches a broad audience through mass media, BTL targets people directly, and digital tools blur the two."},{"type":"type_answer","prompt":"In the Weis IMC campaign, by what percentage did total value sales increase year on year?","answers":["11","11%","11 per cent","eleven"],"explanation":"The campaign also lifted unit sales 5% across all states and reached about 4.7 million people.","lvl":5},{"type":"case","passage":"A student writes that the Weis campaign's objective was 'to be the Aussie summer treat that sparks sunshine feelings'.","prompt":"What is wrong with this objective?","options":["It confuses positioning (the value) with objectives such as awareness, penetration and sales","Weis had no stated objectives","Objectives must mention the budget","It is too specific to be an objective"],"answer":0,"explanation":"Keep positioning separate from objectives. Weis aimed to grow awareness, drive penetration and lift sales and share.","lvl":3}]},{"id":"MMK101-6.3","name":"Plan campaigns with media criteria, push-pull and budgets","summary":"You can compare media on shelf life and quality, choose push or pull tools, set a budget method and sequence AIDA.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Push strategy","Pull strategy"],"items":[{"text":"Trade promotions to retailers","cat":0},{"text":"Consumer advertising that creates demand","cat":1},{"text":"Consumer coupons and competitions","cat":1},{"text":"Personal selling to supermarket buyers","cat":0}],"explanation":"Push moves product through the channel via trade and selling; pull draws customers in via advertising and consumer promotion."},{"type":"mc","prompt":"Which medium has the shortest shelf life (longevity)?","options":["A billboard","An out-of-home transit poster","A glossy magazine","A newspaper"],"answer":3,"explanation":"A newspaper lasts about one day, while a billboard can last around six months.","lvl":2},{"type":"match","prompt":"Match each media evaluation criterion to its meaning.","pairs":[["Longevity","How long the medium lasts"],["Reproduction quality","How good the visual or audio reproduction is"],["Pass-along rate","How many extra people see one copy"]],"explanation":"Evaluate the medium itself, not the ad inside it."},{"type":"order","prompt":"Put the AIDA stages in order.","items":["Attention","Interest","Desire","Action"],"explanation":"A campaign targets the buyer-readiness stage the audience is actually at and moves them toward purchase."},{"type":"case","passage":"A brand first decides it wants to lift awareness among its target segment by 20%, then works out the cost of each task needed to get there.","prompt":"Which budgeting method is this?","options":["Affordable","Objective-and-task","Competitive-parity","Percentage-of-sales"],"answer":1,"explanation":"Objective-and-task is the most defensible method: decide what to achieve, then cost it.","lvl":2},{"type":"analogy","prompt":"Television is to above the line as product sampling is to ___","options":["below the line","above the line","public relations","personal selling"],"answer":0,"explanation":"ATL covers mass media such as TV, radio and outdoor; BTL covers targeted tools such as sampling, competitions and merchandise.","lvl":2}]},{"id":"MMK101-6.4","name":"Apply ethical and legal rules to promotion and influencers","summary":"You can recognise disclosure breaches, rules on targeting under-16s, and misuse of social media in positioning.","questions":[{"type":"case","passage":"An influencer posted about Magnum without disclosing that Unilever paid for it. After complaints she added '#ad', but the brand still had to apologise.","prompt":"What was the core problem?","options":["Influencers are banned from promoting ice cream","Adding '#ad' is never acceptable","The post targeted children under 16","Paid content was not clearly disclosed as advertising"],"answer":3,"explanation":"Paid influencer content must be clearly disclosed with tags like #ad or #PaidPartnership, and brands must monitor what influencers post.","lvl":1},{"type":"mc","prompt":"A brand's product suits young teenagers. What approach do the notes recommend?","options":["Advertise directly to under-16s on social media","Use vague tags like '#sp' on paid posts","Target the parents instead of children under 16","Run a viral TikTok hashtag challenge aimed at teens"],"answer":2,"explanation":"The Australian advertising code prohibits targeting children under 16, so ethical creativity aimed at parents avoids backlash.","lvl":1},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Compliant disclosure","Non-compliant"],"items":[{"text":"Using #PaidPartnership","cat":0},{"text":"Posting paid content with no tag","cat":1},{"text":"Labelling a post 'commercial partnership'","cat":0},{"text":"Using a vague '#sp' tag","cat":1},{"text":"Tagging a paid post #ad","cat":0}],"explanation":"Disclosure must be clear. Dodging the obvious word 'ad' to look like genuine user content breaches the code."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"From 10 December 2025, Australians under ___ are restricted from creating or keeping accounts on certain social media platforms.","answers":["16","sixteen"],"explanation":"This, plus the advertising code's under-16 rule, shapes how brands can use social media.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Even an unpaid endorsement that looks like an ad can never breach advertising standards.","wrong":"never","correct":"still","explanation":"The notes warn that even unpaid endorsements resembling ads can breach standards, so brands must monitor influencers."},{"type":"mc","prompt":"A student lists 'strong social media presence' as a point of difference in Assignment 1. What is the best feedback?","options":["It counts as channel differentiation","Social media is a promotion technique, so it belongs in the mix, not the positioning","It is fine as long as the platforms are named","It is a strong people-based point of difference"],"answer":1,"explanation":"The lecturer flagged this error: social media is how value is communicated, not a positioning base.","lvl":3}]},{"id":"MMK101-6.5","name":"Select data-driven promotion channels and metrics","summary":"You can read survey data to choose channels, flag sample bias and set promotion-specific metrics for Assignment 2.","questions":[{"type":"case","passage":"In the Gourmet Garden survey, in-store point of sale and on-pack recipes scored highest as information sources, while radio and print scored low.","prompt":"Which recommendation best follows from the data?","options":["Use social media for everything regardless of the data","Shift the budget into print advertising","Invest heavily in radio to fix the low score","Reinforce point-of-sale visibility, such as displays near fresh herbs and recipe cards"],"answer":3,"explanation":"Read the data, then choose channels. Strong point-of-sale results point to displays, sampling and recipe cards.","lvl":1},{"type":"mc","prompt":"The Gourmet Garden survey showed very high social media use, but respondents were university students. What should you do?","options":["Flag that the social media skew may not generalise because of sample bias","Assume every segment uses social media equally","Treat the result as secondary data","Ignore the survey entirely"],"answer":0,"explanation":"Mind the bias: a student sample may not represent your persona's real media habits.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Promotion metric","Product metric"],"items":[{"text":"Share of voice","cat":0},{"text":"Repeat purchase rate","cat":1},{"text":"Trial rate","cat":1},{"text":"Click-through rate","cat":0},{"text":"Pre and post satisfaction surveys","cat":1},{"text":"Brand awareness","cat":0}],"explanation":"Promotion metrics include awareness, reach, knowledge, share of voice and clicks; product metrics track trial, repeat and satisfaction."},{"type":"type_answer","prompt":"How many low-cost promotion tools must Assignment 2 recommend for Lunatello?","answers":["three","3"],"explanation":"Each of the three tools needs its own sub-headed section, evidence and a metric.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Assignment 2 requires each promotion tool to be justified with at least two primary and at least two tertiary data points.","wrong":"tertiary","correct":"secondary","explanation":"Each tool needs at least two primary data points from the Lunatello survey and at least two secondary data points."},{"type":"mc","prompt":"How should channels be named in the Assignment 2 promotion section?","options":["List every available platform to show breadth","Write 'social media' generally to save words","Name specific platforms such as Instagram, YouTube or TikTok that match the persona's media habits","Choose TV for every segment"],"answer":2,"explanation":"Specific platforms linked to the persona's media habits show the data-driven choice markers look for.","lvl":1}]}]},{"week":7,"topic":"Pricing: Capturing Customer Value","summary":"Setting price between floor and ceiling, the three major strategies, new-product pricing, adjustments and the law.","skills":[{"id":"MMK101-7.1","name":"Explain price, the tri-component model, floor and ceiling","summary":"You can define price narrowly and broadly, apply the tri-component model and identify what sets the floor and ceiling.","questions":[{"type":"mc","prompt":"What sets the price floor?","options":["The level of market demand","Product cost","Consumer willingness to pay","Competitors' prices"],"answer":1,"explanation":"The seminar MCQ: the floor is your cost, the break-even point. Competitors and demand move the price within the range.","lvl":2},{"type":"match","prompt":"Match each pricing term to its meaning.","pairs":[["Price floor","Product cost, where no profit is made"],["Price ceiling","Consumer perceived value, the most they will pay"],["Price (broad)","All values given up: money, time, effort, risk and opportunity cost"],["Price (narrow)","The amount of money charged"]],"explanation":"Every price sits between a cost-based floor and a value-based ceiling."},{"type":"mc","prompt":"Which of these is NOT one of the three boxes in the tri-component model of price?","options":["Stay competitive","Cover the cost","Create customer value","Maximise market share at any cost"],"answer":3,"explanation":"A good price must cover cost, read as value for money, and stack up against competitors.","lvl":1},{"type":"case","passage":"A new cereal brand appears in Woolworths with a shelf label reading 'introductory price', set below the price it will charge once established.","prompt":"What is the brand doing?","options":["Deceptive pricing with a fake discount","Market skimming for innovative products","Using an introductory price, common for new entrants who are usually price-takers","Predatory pricing to drive out Kellogg's"],"answer":2,"explanation":"A deliberately low starting price is a common technique for new, smaller entrants benchmarking against the market leader.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Price is the only element of the marketing mix that produces ___.","answers":["revenue","income"],"explanation":"Every other P spends money, which puts pressure on marketers to set a price that captures value and covers cost.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Charging above the price floor means customers won't buy because it exceeds their perceived value.","wrong":"floor","correct":"ceiling","explanation":"The ceiling is set by customer perceived value; charge above it and they won't buy. Above the floor you start to profit."}]},{"id":"MMK101-7.2","name":"Distinguish value-, cost- and competition-based pricing","summary":"You can classify a pricing approach, including good-value, value-added, cost-plus and break-even pricing.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Customer value-based","Cost-based","Competition-based"],"items":[{"text":"Bunnings' 10% price guarantee","cat":2},{"text":"Adding a standard 20% markup to unit cost","cat":1},{"text":"Kmart's good-value low prices","cat":0},{"text":"Setting price to hit an investor's target return","cat":1},{"text":"A Hermès Birkin priced on value-adding features","cat":0},{"text":"Coles and Woolworths alternating weekly specials","cat":2}],"explanation":"Value-based starts from perceived value, cost-based from cost plus a return, and competition-based from rivals' prices and offerings."},{"type":"case","passage":"A start-up's investor wants a 30% return. The founder totals fixed and variable costs, finds where revenue meets cost, then adds the target return to set the price.","prompt":"Which pricing approach is this?","options":["Break-even (target-return) pricing","Cost-plus (markup) pricing","Value-added pricing","Competition-based pricing"],"answer":0,"explanation":"Break-even pricing sets price to break even or hit a desired profit, with a target-return gap added on top.","lvl":3},{"type":"mc","prompt":"What is value-added pricing?","options":["Offering quality and service at a fair low price","Attaching value-adding features and services to justify a higher price rather than cutting price","Adding a standard markup to unit cost","Matching the market leader's price"],"answer":1,"explanation":"Value-added pricing is a differentiation strategy used by luxury brands such as Chanel and Dior; good-value pricing is the low-price form.","lvl":2},{"type":"case","passage":"Airbnb's software nudges hosts to raise nightly prices when views of similar listings rise, and airlines reprice seats constantly.","prompt":"Which pricing strategy do the notes use these examples for?","options":["Captive-product pricing","Value-added pricing","Cost-plus pricing","Competition-based pricing"],"answer":3,"explanation":"Online platforms now adjust prices automatically in response to the market and competitors.","lvl":4},{"type":"analogy","prompt":"Cost-based pricing is to everyday necessity products as value-based pricing is to ___","options":["premium, novel or unique products","by-products","products with thin margins","supermarket staples"],"answer":0,"explanation":"Cost-based suits necessities with thin margins; value-based suits products that justify a high price.","lvl":2},{"type":"type_answer","prompt":"Which cost-based approach adds a standard markup percentage to the unit cost?","answers":["cost-plus pricing","cost-plus","cost plus","markup pricing","cost-plus (markup) pricing"],"explanation":"The markup is flexible but must be fair; too large and the ACCC may take interest.","lvl":2}]},{"id":"MMK101-7.3","name":"Choose between market skimming and penetration pricing","summary":"You can match conditions to skimming or penetration and track how strategies change after launch.","questions":[{"type":"match","prompt":"Match each product to its launch pricing strategy from the 'Price is Right' activity.","pairs":[["Disney+ at $8.99 a month in 2019","Penetration"],["Nintendo Switch 2 at about $699","Skimming"],["Disney+ today, matching Netflix","Competition-based"]],"explanation":"Companies use different strategies at different times: skimming or penetration at launch, then a major strategy once established."},{"type":"case","passage":"A tech firm launches a patented gadget. Its quality and image support a high price, many wealthy early buyers want it, and rivals cannot copy the technology for a year.","prompt":"Which launch strategy fits best?","options":["Captive-product pricing","Market penetration","Market skimming","Good-value pricing"],"answer":2,"explanation":"Skimming fits when quality and image support a high price, enough buyers want it, and competitors cannot easily enter.","lvl":2},{"type":"mc","prompt":"Which condition most undermines a market skimming strategy?","options":["Buyers are willing to pay a high price","Competitors can enter the market easily","The product has a strong premium image","The technology is protected by trade secrets"],"answer":1,"explanation":"Skimming needs a sustainable advantage (around 6 to 12 months in fast-moving tech); easy entry erodes it.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Skimming","Penetration"],"items":[{"text":"Competitors cannot easily enter","cat":0},{"text":"Quality and image support a high price","cat":0},{"text":"The firm has strong economies of scale","cat":1},{"text":"Enough buyers want it at a high price","cat":0},{"text":"The product is easily copied FMCG","cat":1},{"text":"Customers are highly price-sensitive","cat":1}],"explanation":"Skimming suits innovative premium products; penetration suits easily copied products where scale and price sensitivity matter."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Market penetration sets a high initial price to skim revenue from the wealthiest buyers first.","wrong":"penetration","correct":"skimming","explanation":"Skimming starts high and lowers over time; penetration starts low to win share quickly."},{"type":"case","passage":"A new streaming service launches at a low monthly price to build a large subscriber base quickly. Years later, it raises prices to sit alongside its main rival.","prompt":"Which pattern of strategies does this show?","options":["Skimming at launch, then value-added pricing","Captive-product pricing throughout","Predatory pricing, then price fixing","Penetration at launch, then competition-based pricing once established"],"answer":3,"explanation":"This mirrors Disney+, which launched with penetration pricing and now matches Netflix.","lvl":3}]},{"id":"MMK101-7.4","name":"Apply product-mix pricing and respond to price changes","summary":"You can identify product-mix pricing strategies and choose a viable response when a competitor cuts price.","questions":[{"type":"match","prompt":"Match each product-mix pricing strategy to its example.","pairs":[["Captive-product pricing","Cheap printers with profit on ink"],["Optional-product pricing","A car's paid add-on extras"],["By-product pricing","Honey by-products sold as wax candles"],["Product-bundle pricing","Microsoft software suites"]],"explanation":"Product-mix pricing sets prices across a range rather than for one item."},{"type":"order","prompt":"Put the steps for responding to a competitor's price cut in order.","items":["Check whether the competitor has actually cut price","Assess whether it meaningfully hurts your share or profit","Choose a response: cut price, raise perceived value or launch a fighter brand"],"explanation":"If either of the first two answers is no, you may not need to act at all."},{"type":"mc","prompt":"Which response to a competitor's price cut is NOT viable?","options":["Improve quality and lower price at the same time","Raise perceived value by improving quality","Reduce price in the short term","Launch a lower-priced fighter brand"],"answer":0,"explanation":"Improving quality adds cost, so also cutting price means losing money. This was a seminar exam trap.","lvl":3},{"type":"case","passage":"A department store facing cheaper rivals launches its own lower-priced private label clothing range, as David Jones has done.","prompt":"What is this response called?","options":["Captive-product pricing","Resale price maintenance","A fighter brand","By-product pricing"],"answer":2,"explanation":"A fighter brand is a lower-priced brand launched to counter cheaper competitors without cutting the main brand's price.","lvl":2},{"type":"type_answer","prompt":"The Big Mac Index is an informal way to compare what across countries?","answers":["purchasing power parity","PPP","purchasing power"],"explanation":"It converts local Big Mac prices to US dollars, showing how the same product is priced differently across markets.","lvl":4},{"type":"case","passage":"A cinema charges less for weekday matinees and for seniors and students than for Saturday night adult tickets.","prompt":"Which price-adjustment strategy is this?","options":["Geographical pricing","Segmented pricing","Captive-product pricing","Predatory pricing"],"answer":1,"explanation":"Segmented pricing sets different prices by session, age or other segments, as the notes' cinema example shows.","lvl":2}]},{"id":"MMK101-7.5","name":"Recognise illegal and legal pricing practices","summary":"You can identify practices prohibited under the Competition and Consumer Act and spot legal price discrimination.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Illegal in Australia","Often legal"],"items":[{"text":"Seniors discounts","cat":1},{"text":"Student discounts","cat":1},{"text":"Fake 'was/now' discounts","cat":0},{"text":"Resale price maintenance","cat":0},{"text":"Price fixing with competitors","cat":0},{"text":"Predatory pricing below cost","cat":0}],"explanation":"The Act prohibits price fixing, predatory pricing, resale price maintenance and deceptive pricing. Price discrimination is often legal."},{"type":"case","passage":"The ACCC alleges a supermarket raised a product's regular price from $6 to $7.80, then promoted a 'Prices Dropped' deal at $6.70, still above the original $6.","prompt":"Which prohibited practice is alleged?","options":["Resale price maintenance","Predatory pricing","Deceptive pricing","Price fixing"],"answer":2,"explanation":"This is the Coles and Woolworths 'Down Down' case: advertising discounts that are not genuine is deceptive pricing.","lvl":2},{"type":"mc","prompt":"What is resale price maintenance?","options":["Selling below cost to drive out a rival","Competitors agreeing prices with each other","Charging students less than other customers","A manufacturer requiring retailers to charge a specified price"],"answer":3,"explanation":"Resale price maintenance is an across-channel practice that is prohibited; price fixing is within-channel between competitors.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In Australia, price discrimination such as student and senior discounts is usually illegal.","wrong":"illegal","correct":"legal","explanation":"Price discrimination is often legal in Australia and only problematic in some cases, so do not confuse it with predatory or deceptive pricing."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The key pricing legislation is the Competition and Consumer Act 2010 (Cth), enforced by the ___.","answers":["ACCC","Australian Competition and Consumer Commission"],"explanation":"The ACCC enforces the Act and is suing over misleading supermarket promotions.","lvl":2},{"type":"analogy","prompt":"Agreeing prices with a competitor is to price fixing as selling below cost to drive out a rival is to ___","options":["predatory pricing","price discrimination","deceptive pricing","penetration pricing"],"answer":0,"explanation":"Predatory pricing punishes or eliminates competitors and is illegal; penetration pricing is a legitimate low launch price.","lvl":1}]}]},{"week":8,"topic":"Place: Distribution & Logistics","summary":"Supply chains, marketing channels and intermediaries, multichannel networks, channel conflict, trends and place metrics.","skills":[{"id":"MMK101-8.1","name":"Distinguish supply chain terms and SCM decisions","summary":"You can separate supply chain, logistics, marketing channel and SCM, and apply the major SCM decisions.","questions":[{"type":"match","prompt":"Match each term to what it covers.","pairs":[["Supply chain","The entire process from raw materials to the end user"],["Logistics","The physical flow of goods: warehousing and transport"],["Marketing channel","The system making goods available to buy, with ownership transferring"],["Supply chain management","Managing all members and activities from procurement to distribution"]],"explanation":"The marketing channel is the unit's focus and the second half of the supply chain."},{"type":"mc","prompt":"What is the goal of any supply chain, according to the lecturer?","options":["Minimise cost even if service suffers","Deliver a target level of customer service at the least cost to the company","Deliver the fastest possible service regardless of cost","Use as many intermediaries as possible"],"answer":1,"explanation":"Distribution is always a trade-off between the benefit of higher service and the cost of providing it.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Onshoring","Nearshoring","Friendshoring"],"items":[{"text":"Moving production to a close neighbouring country","cat":1},{"text":"Locating a plant in a politically friendly country","cat":2},{"text":"Returning a factory from overseas to Australia","cat":0},{"text":"Bringing chip manufacturing back home","cat":0},{"text":"Choosing an allied nation to reduce geopolitical risk","cat":2},{"text":"Shifting assembly to a nearby country to cut transit time","cat":1}],"explanation":"Geopolitics has reshaped plant location decisions beyond simply offshoring for cheap labour."},{"type":"case","passage":"Coles, Woolworths and Aldi share live sales data with suppliers through a supplier portal, so a sale automatically triggers the next delivery.","prompt":"Which SCM function does this represent?","options":["Plant location","Resource management","Purchasing","Information workflow"],"answer":3,"explanation":"Information workflow is the shared supply-chain information system, such as vendor-managed inventory (VMI).","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Air freight is the cheapest transport type, which is why many Australian factories sit on the coast near ports.","wrong":"Air","correct":"Sea","explanation":"Waterway or sea freight is the cheapest, which is why factories cluster near ports between Melbourne and Sydney."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Holding minimal inventory, produced or delivered as needed to protect cash flow, is called ___ inventory.","answers":["just-in-time","JIT","just in time"],"explanation":"Excess stock ties up cash, needs warehousing and risks spoilage, so JIT is preferred.","lvl":2}]},{"id":"MMK101-8.2","name":"Identify channel length and how intermediaries add value","summary":"You can name channel structures, explain the value intermediaries add, and weigh the loss of control.","questions":[{"type":"match","prompt":"Match each channel structure to its flow.","pairs":[["Direct (zero-level)","Manufacturer to consumer"],["One-level","Manufacturer to retailer to consumer"],["Two-level","Manufacturer to wholesaler to retailer to consumer"]],"explanation":"Channel length is the number of intermediary levels between manufacturer and consumer."},{"type":"case","passage":"Dove produces millions of units of body wash and sells large quantities to wholesalers, who split them into smaller assortments for retailers.","prompt":"Which intermediary value does this show?","options":["Breaking bulk","Disintermediation","Just-in-time inventory","Channel conflict"],"answer":0,"explanation":"Breaking bulk lets consumers buy a variety of products in small amounts.","lvl":2},{"type":"mc","prompt":"What trade-off comes with adding more channel members?","options":["Ownership stays with the manufacturer","More control and lower complexity","Less control and a more complex, costly channel","Guaranteed faster delivery"],"answer":2,"explanation":"This was a straight MCQ answer: more members means less control, more complexity, and ownership handed down the line.","lvl":2},{"type":"type_answer","prompt":"What term describes the number of intermediary levels between the manufacturer and the consumer?","answers":["channel length","length"],"explanation":"Direct, one-level and two-level are the three common structures for Assignment 2.","lvl":3},{"type":"analogy","prompt":"Selling on your own website is to a zero-level channel as selling through Woolworths is to a ___","options":["zero-level channel","one-level channel","disintermediated channel","two-level channel"],"answer":1,"explanation":"A retailer is one intermediary level; adding a wholesaler makes it two-level.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A wholesaler buying from many suppliers and selling on dramatically increases the total number of transactions needed.","wrong":"increases","correct":"reduces","explanation":"Intermediaries add value by reducing the number of transactions needed to reach customers."}]},{"id":"MMK101-8.3","name":"Design multichannel networks and spot omnichannel trends","summary":"You can build a multichannel network from evidence, and distinguish multichannel, omnichannel and disintermediation.","questions":[{"type":"case","passage":"Who Gives A Crap ships from its Australian warehouses in three ways: via its own website with Australia Post, via Aldi, Woolworths and Harris Farm, and via Amazon.","prompt":"What type of channel is Warehouse to Amazon to consumer?","options":["A distributor channel","A retailer channel","A direct channel","An online marketplace channel"],"answer":3,"explanation":"Amazon is an online marketplace or platform, one of the three common options in the A2 diagram.","lvl":3},{"type":"mc","prompt":"What is the difference between multichannel and omnichannel?","options":["Multichannel means cutting out intermediaries","Omnichannel uses several channels that are integrated and talk to each other","Multichannel channels are always integrated","Omnichannel uses only one channel"],"answer":1,"explanation":"A common MCQ trap: multichannel is several channels; omnichannel is the more advanced, integrated version.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Multichannel","Omnichannel","Disintermediation"],"items":[{"text":"An emailed coupon redeemed in store","cat":1},{"text":"Airlines selling direct instead of via Flight Centre","cat":2},{"text":"Listing on Amazon as well as in retailers","cat":0},{"text":"Netflix bypassing video-rental stores","cat":2},{"text":"Selling separately via your website and Aldi","cat":0},{"text":"Click-and-collect","cat":1}],"explanation":"Integrated channels are omnichannel; simply having several is multichannel; bypassing middlemen is disintermediation."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Disintermediation means adding intermediaries to reach more customers.","wrong":"adding","correct":"bypassing","explanation":"Disintermediation cuts out the middleman to reduce cost, gain control and reduce complexity."},{"type":"mc","prompt":"Which channel set is most realistic for Lunatello, a micro business, in Assignment 2?","options":["Its own website and Instagram or TikTok shop, selected researched retailers, and online marketplaces","Disintermediation of all channels","A single two-level channel through wholesalers","A national distributor supplying superstores and Costco"],"answer":0,"explanation":"Lunatello should keep it low-cost; a distributor is probably unrealistic, and intermediaries must be researched and named.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A multichannel distribution network is when a single firm sets up two or more marketing ___ to reach one or more segments.","answers":["channels"],"explanation":"It is not just more places to buy; channel members must also add value through expertise, relationships and speed.","lvl":2}]},{"id":"MMK101-8.4","name":"Classify vertical and horizontal channel conflict","summary":"You can tell whether a conflict is between channel levels or within one level.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Vertical conflict","Horizontal conflict"],"items":[{"text":"A wholesaler versus a retailer it supplies","cat":0},{"text":"A franchisee undercutting a neighbour with cheaper Coles milk","cat":1},{"text":"Two retailers clashing over the same brand's price","cat":1},{"text":"Bonds socks cheap at Kmart but dear at Myer","cat":1},{"text":"A supplier versus a Starbucks store","cat":0},{"text":"A manufacturer versus its distributor","cat":0}],"explanation":"Vertical conflict is between different levels; horizontal conflict is within the same level."},{"type":"case","passage":"In a Mrs Fields franchise network, one franchisee buys cheaper milk from Coles instead of the authorised supplier and undercuts a neighbouring franchisee on cost.","prompt":"Which type of channel conflict is this?","options":["Vertical conflict","Disintermediation","Horizontal conflict","Omnichannel conflict"],"answer":2,"explanation":"Both franchisees are at the same level of the channel, so the conflict is horizontal.","lvl":3},{"type":"mc","prompt":"Which statement defines vertical channel conflict?","options":["Conflict between two unrelated industries","Conflict caused by cutting out intermediaries","Conflict between different levels of the same channel, such as manufacturer and distributor","Conflict among retailers at the same level"],"answer":2,"explanation":"Different levels have different roles, which is the source of vertical conflict.","lvl":2},{"type":"analogy","prompt":"Manufacturer versus distributor is to vertical conflict as Kmart versus Myer is to ___","options":["horizontal conflict","vertical conflict","breaking bulk","disintermediation"],"answer":0,"explanation":"Kmart and Myer are both retailers, so their clash is at the same level.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Horizontal conflict occurs between different levels of the channel.","wrong":"different","correct":"same","explanation":"Horizontal conflict is within the same level; vertical is between different levels."},{"type":"type_answer","prompt":"What type of channel conflict occurs within the same level of the channel, such as among retailers?","answers":["horizontal","horizontal conflict","horizontal channel conflict"],"explanation":"Bonds socks priced differently at Kmart and Myer is the notes' horizontal example.","lvl":2}]},{"id":"MMK101-8.5","name":"Select place metrics and distribution-linked SDGs","summary":"You can choose a fitting distribution metric, judge performance and match SDGs to the right P.","questions":[{"type":"match","prompt":"Match each place metric to what it measures.","pairs":[["On-time delivery","Whether deliveries arrive within the promised window"],["In-full rate","Whether the full order arrives"],["Stock availability","How often the product is in stock when wanted"],["Channel-relationship strength","How strong relationships with channel members are"]],"explanation":"The seminar highlighted these commonly used metrics; the lecture list adds points of distribution, coverage, hours and sales per store."},{"type":"case","passage":"A brand finds its balm is in stock only 75% of the time when shoppers look for it at its retailers.","prompt":"How should this stock availability result be judged?","options":["Irrelevant, because stock is a product metric","Failing, because stock availability should be above 80%","Excellent, because anything above 50% is strong","Acceptable, because in-full rate matters more"],"answer":1,"explanation":"Aim for more than 80% availability; under 80% is a failure.","lvl":3},{"type":"mc","prompt":"Lunatello sources locally rather than overseas, shortening its supply chain. Which SDG best fits its distribution strategy?","options":["SDG 4 Quality Education","SDG 6 Clean Water and Sanitation","SDG 17 Partnerships for the Goals","SDG 13 Climate Action"],"answer":3,"explanation":"Local sourcing cuts logistics and carbon footprint, a strong SDG 13 argument for Place.","lvl":3},{"type":"case","passage":"A student links Who Gives A Crap's pledge to build toilets in developing countries (SDG 6) to its distribution strategy.","prompt":"What is the best feedback?","options":["It is a strong distribution SDG because toilets are distributed","It should be linked to price instead","SDGs cannot be used in Assignment 2","It is really a promotion or PR point, so match the SDG to the right P"],"answer":3,"explanation":"The seminar flagged this: match each SDG to the P it genuinely fits.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Place management ensures the right assortment is at the right place, at the right time and in the right ___.","answers":["condition"],"explanation":"About one in four online purchases is returned, often because it arrives damaged or not as described.","lvl":4},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Product","Place","Promotion"],"items":[{"text":"SDG 6 for a toilet-building pledge in campaigns","cat":2},{"text":"SDG 13 for local sourcing and short supply chains","cat":1},{"text":"SDG 15 for grass-fed, ethically sourced tallow","cat":0},{"text":"SDG 14 for reducing sea-freight packaging waste","cat":1},{"text":"SDG 12 for organic, responsibly produced ingredients","cat":0}],"explanation":"Assignment 2 needs at least two SDGs across at least two Ps, each matched to the P it genuinely supports."}]}]},{"week":9,"topic":"Services Marketing & Retailing","summary":"The four service characteristics, the extended mix, internal and interactive marketing, service channels and retailing.","skills":[{"id":"MMK101-9.1","name":"Explain the four characteristics of services","summary":"You can identify intangibility, inseparability, variability and perishability and the marketing challenge each creates.","questions":[{"type":"match","prompt":"Match each service characteristic to its meaning.","pairs":[["Intangibility","Cannot be seen, touched or felt before purchase"],["Inseparability","Cannot be separated from its provider and is often co-created"],["Variability","Quality varies by who provides it, when and for whom"],["Perishability","Cannot be stored for later sale"]],"explanation":"Each characteristic creates a marketing challenge that the extended mix is designed to solve."},{"type":"case","passage":"A 9am flight departs with 40 empty seats. Once the plane leaves, those seats can never be sold.","prompt":"Which service characteristic does this illustrate?","options":["Perishability","Variability","Inseparability","Intangibility"],"answer":0,"explanation":"Services are time-bound and cannot be stored, so supply and demand must be managed to capture revenue.","lvl":1},{"type":"mc","prompt":"Which service characteristic is the root cause that leads to the other three?","options":["Inseparability","Variability","Intangibility","Perishability"],"answer":2,"explanation":"The notes describe intangibility as the root cause of inseparability, variability and perishability.","lvl":3},{"type":"case","passage":"Close to a sold-out Taylor Swift MCG show, the promoter released restricted-view seats at about $80 so they would not sit empty.","prompt":"Which challenge was the promoter managing?","options":["Inseparability, by removing the performer","Perishability, by on-selling unsold capacity","Variability, by standardising the show","Intangibility, by adding physical cues"],"answer":1,"explanation":"Unsold seats perish at showtime, so late releases, booking systems and off-peak pricing capture revenue.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Intangibility","Variability","Perishability"],"items":[{"text":"Discounted last-minute cinema tickets","cat":2},{"text":"Cheaper off-peak haircuts","cat":2},{"text":"Hairdresser apprenticeships and a set process","cat":1},{"text":"A stylist's own hair and product display","cat":0},{"text":"Cinema Gold Class seats and trailers","cat":0},{"text":"Airline crew following a standard service script","cat":1}],"explanation":"The seminar grid showed how cinemas, airlines and salons tackle each characteristic."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A service is an activity, benefit or satisfaction offered for sale that is essentially intangible and does not result in the ___ of anything.","answers":["ownership"],"explanation":"Education is the example: you gain knowledge but walk out owning only a piece of paper.","lvl":3}]},{"id":"MMK101-9.2","name":"Match the extended marketing mix to service challenges","summary":"You can link people, process and physical evidence to the characteristic each mainly solves, and make services tangible.","questions":[{"type":"match","prompt":"Match each extra P to the service characteristic it mainly solves.","pairs":[["People","Variability"],["Process","Inseparability and perishability"],["Physical evidence","Intangibility"]],"explanation":"People reduce inconsistency, process manages delivery and demand, and physical evidence provides tangible cues."},{"type":"case","passage":"Choosing a restaurant you have never tried, you check whether it is clean, whether other diners' plates look finished, whether the menu is a crisp card or sticky laminate, and what staff are wearing.","prompt":"Which P are you using to judge the service?","options":["Promotion","Physical evidence","Place","Process"],"answer":1,"explanation":"These are tangible cues read before you have eaten anything, the notes' example of physical evidence.","lvl":2},{"type":"mc","prompt":"How do the notes distinguish place from physical evidence for services?","options":["Place is the building; physical evidence is the booking system","They are the same thing for services","Place is how the service reaches the customer; physical evidence is the tangible point-of-sale environment","Physical evidence only applies to goods"],"answer":2,"explanation":"They are easy to confuse. Physical evidence covers the servicescape cues, including a website for online businesses.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Physical evidence mainly solves the variability of services.","wrong":"variability","correct":"intangibility","explanation":"Physical evidence tackles intangibility; people mainly tackle variability."},{"type":"case","passage":"Metro Trains' 'Dumb Ways to Die' campaign turned a rail safety message into a song, 21 characters, posters, plush toys, stickers and games.","prompt":"What did the merchandise and characters mainly achieve?","options":["They made an intangible safety message tangible and shareable","They were a push strategy through retailers","They replaced the need for any Metro branding","They reduced the perishability of train seats"],"answer":0,"explanation":"Tangible artefacts made the message concrete, and the Metro logo tied everything back to the brand.","lvl":2},{"type":"type_answer","prompt":"What term do the notes use for the physical environment or point of sale where a service happens?","answers":["servicescape","the servicescape"],"explanation":"The servicescape includes the building, layout, decor, uniforms, equipment and even the website.","lvl":3}]},{"id":"MMK101-9.3","name":"Distinguish internal and interactive marketing and service channels","summary":"You can explain the two extra services marketing approaches and classify service distribution channels.","questions":[{"type":"mc","prompt":"What is internal marketing?","options":["The buyer-seller interaction during service delivery","Marketing to customers inside a physical store","Advertising to existing customers only","Orienting and motivating customer-contact and support staff to work as a team to deliver satisfaction"],"answer":3,"explanation":"You cannot have happy customers without engaged, well-trained staff.","lvl":2},{"type":"case","passage":"A hotel chain runs team workshops and recognition programs so that housekeeping, reception and kitchen staff all work together to delight guests.","prompt":"Which services marketing approach is this?","options":["Shopper marketing","Internal marketing","Interactive marketing","Disintermediation"],"answer":1,"explanation":"Motivating staff as a team to deliver satisfaction is internal marketing.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Direct","Via retailer","Via agent or broker"],"items":[{"text":"Health insurance through Compare the Market","cat":2},{"text":"A phone plan sold through a Telstra store","cat":1},{"text":"A home loan through a mortgage broker","cat":2},{"text":"A data plan sold in an Optus store","cat":1},{"text":"A play you attend","cat":0},{"text":"A lecturer teaching a class","cat":0}],"explanation":"Service channels are shorter than for goods but rely heavily on people."},{"type":"analogy","prompt":"Internal marketing is to motivating staff as interactive marketing is to ___","options":["managing warehouses","advertising in mass media","the buyer-seller interaction during delivery","setting the price ceiling"],"answer":2,"explanation":"In interactive marketing, the moment of contact is the marketing.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Service distribution channels are much shorter than for goods but rely more on ___ than on warehouses and trucks.","answers":["people","human capital"],"explanation":"Service delivery depends on human capital.","lvl":3},{"type":"mc","prompt":"Which of these is an example of self-service technology in service delivery?","options":["A personal stylist consultation","A mortgage broker meeting","A lecturer's face-to-face class","Coles and Woolworths self-checkouts"],"answer":3,"explanation":"Self-service tech includes airline check-in, fast-food touchscreens and supermarket self-checkout.","lvl":1}]},{"id":"MMK101-9.4","name":"Classify retail channels and retailer types","summary":"You can tell single, multi, cross and omnichannel retailing apart and classify retailers four ways.","questions":[{"type":"match","prompt":"Match each retail channel type to its meaning.","pairs":[["Single-channel","Sell and deliver through one channel only"],["Multichannel","Transactions completed via a combination of channels"],["Cross-channel","Using different channels for the same purchase"],["Omnichannel","A fully integrated experience across channels at once"]],"explanation":"Macy's letting shoppers scan an item in store to see other sizes is the omnichannel example."},{"type":"case","passage":"Jess researches a jacket on a retailer's website and reads reviews on her phone, then goes to the store to try it on and buy it.","prompt":"Which retail channel behaviour is this?","options":["Cross-channel","Disintermediation","Single-channel","Shopper marketing"],"answer":0,"explanation":"Cross-channel means the customer uses several different channels for the same purchase.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Amount of service","Relative prices","Product line"],"items":[{"text":"A department store","cat":2},{"text":"A direct factory outlet (DFO)","cat":1},{"text":"Apple's full-service stores","cat":0},{"text":"A supermarket","cat":2},{"text":"Costco as a warehouse club","cat":1},{"text":"A self-service retailer","cat":0}],"explanation":"Retailers can be classified by amount of service, product line, relative prices and organisational approach."},{"type":"mc","prompt":"Which retail approach best fits Lunatello, a low-cost, one-person business?","options":["Build a hypermarket presence","Open identical flagship stores like Apple","Keep it lean; a superstore or Costco route does not fit","Supply warehouse clubs to maximise volume"],"answer":2,"explanation":"Retail choices reflect positioning and resources, so Lunatello should stay lean.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Retailing is selling goods or services directly to final consumers for business use.","wrong":"business","correct":"personal","explanation":"Retailing is selling to final consumers for personal, non-business use."},{"type":"type_answer","prompt":"What term describes point-of-sale promotion and advertising used to extend brand equity to the 'last mile' and shape in-store decisions?","answers":["shopper marketing"],"explanation":"Shopper marketing targets the in-store moment where products and services meet the consumer.","lvl":4}]}]},{"week":10,"topic":"New Product Development","summary":"The eight-stage NPD process, screening and concept testing, why new products fail, and the product life cycle.","skills":[{"id":"MMK101-10.1","name":"Sequence the eight stages of the NPD process","summary":"You can put the NPD stages in order and explain what happens at each, including stage gates and exit strategies.","questions":[{"type":"order","prompt":"Put the first five NPD stages in order.","items":["Idea generation","Idea screening","Concept development and testing","Marketing strategy development","Business analysis"],"explanation":"The NPD process is order-sensitive, and following it makes success more likely."},{"type":"order","prompt":"Put the final four NPD stages in order.","items":["Business analysis","Product development","Test marketing","Commercialisation"],"explanation":"After the numbers check out, the concept becomes a real product, is trialled in a limited market, then fully launched."},{"type":"case","passage":"Hallmark spent about $1 million trialling a design-and-send card app in Australia, a small market, before any global rollout. It did not take off and was stopped.","prompt":"Which NPD stage was Hallmark in?","options":["Commercialisation","Test marketing","Business analysis","Idea screening"],"answer":1,"explanation":"Test marketing trials the real product and program in a limited setting such as a region or limited edition.","lvl":2},{"type":"mc","prompt":"What is a stage gate in NPD?","options":["The final full-market launch","A retailer's annual range review","A patent protecting the idea","A checkpoint needing executive sign-off before the idea proceeds to the next stage"],"answer":3,"explanation":"At any gate the idea can be parked, which limits wasted investment.","lvl":2},{"type":"match","prompt":"Match each NPD stage to what happens.","pairs":[["Idea generation","Systematic search of internal, external and crowdsourced ideas"],["Business analysis","Reviewing sales, cost, profit projections and risk"],["Product development","Turning the concept into a workable product, a big jump in investment"],["Commercialisation","Full launch to the whole market"]],"explanation":"Each stage builds on the last, with investment rising sharply at product development."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Deciding in advance the point at which you will walk away from a failing launch is called an ___ strategy.","answers":["exit"],"explanation":"Better to lose $50K than hundreds of thousands on a failing launch.","lvl":2}]},{"id":"MMK101-10.2","name":"Apply R-W-W screening and concept testing","summary":"You can screen ideas with R-W-W, separate idea, concept and image, and avoid myopia and face-value feedback.","questions":[{"type":"fill_gap","prompt":"Complete the sentence.","text":"The R-W-W screening test asks: Is it Real? Can we Win? Is it ___ doing?","answers":["Worth","worth"],"explanation":"All three must be yes for an idea to pass screening.","lvl":2},{"type":"match","prompt":"Match each term to the Happy Snack Company example.","pairs":[["Product idea","A market gap for a nutrient-dense, allergen-free, sustainable snack"],["Product concept","A healthier chocolate-coated wholefood treat, described in consumer terms"],["Product image","How sports types, health-conscious mums and vegans actually perceive it"]],"explanation":"An idea is a possible product, a concept is a detailed consumer-terms version, and an image is how consumers perceive it."},{"type":"case","passage":"Lego runs a community ideas site where fans submit set designs, and popular designs can be developed into real products.","prompt":"Which source of idea generation is this?","options":["Crowdsourcing","Test marketing","Top-down direction","Internal R&D only"],"answer":0,"explanation":"Ideas can come from R&D, employees, customers, suppliers and crowdsourcing, as with Lego and P&G.","lvl":2},{"type":"mc","prompt":"During screening, a team loves an idea because it is technically impressive but never considers how customers would see it. What danger is this?","options":["First-mover advantage","Product obsolescence","Horizontal conflict","Marketing myopia"],"answer":3,"explanation":"Marketing myopia is being so internally focused you cannot see the product from the customer's point of view.","lvl":2},{"type":"case","passage":"In early testing, Red Bull was described as tasting 'like medicine'. Instead of scrapping it, the founder repositioned it as a small-can energy hit.","prompt":"What lesson does this give for concept testing?","options":["Do not take consumer feedback at face value; find the barrier and solve it","Always scrap products that test poorly on taste","Consumer feedback should be ignored","Taste tests are the only valid concept test"],"answer":0,"explanation":"Red Bull listened for the barrier, then solved it through positioning, becoming a global success.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In R-W-W screening, an idea proceeds only if some of the three questions are answered yes.","wrong":"some","correct":"all","explanation":"Real, Win and Worth must all be yes."}]},{"id":"MMK101-10.3","name":"Diagnose why new products fail","summary":"You can pinpoint where in the NPD process a product broke down and weigh risks against rewards.","questions":[{"type":"case","passage":"Coca-Cola Life was a stevia-sweetened 'healthier' coke in green packaging. Coke drinkers wanted full sugar or zero, and many disliked the stevia aftertaste. It was discontinued around 2020.","prompt":"Where did the process break down?","options":["Only at commercialisation, due to distribution","At product development, due to cost","From the start (a grey middle ground nobody wanted) and at test marketing (the aftertaste)","Only at idea generation, due to a lack of ideas"],"answer":2,"explanation":"The seminar argued it failed from the outset and again at test marketing.","lvl":3},{"type":"case","passage":"Google Glass confused consumers about whether it was for entertainment or prescription use, and it was priced too high for a very small market.","prompt":"At which stages did Google Glass fail?","options":["Business analysis only","Concept development and testing, and marketing strategy development","Commercialisation only","Idea generation and test marketing only"],"answer":1,"explanation":"A confusing concept and a mismatched price and market pointed to these two stages; Ray-Ban Meta glasses have a clearer purpose and price.","lvl":4},{"type":"case","passage":"Reflex developed a thicker, carbon-neutral sticky note that consumers preferred in testing, but Officeworks would not range it over market leader 3M.","prompt":"Why did the product fail?","options":["It launched into a declining category","It had no point of difference","Consumers disliked the product in testing","The retailer's one-in, one-out gate blocked distribution"],"answer":3,"explanation":"Unless you sell direct or online, retailers can be a hard stop; the carbon credits also added cost.","lvl":3},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Risk","Reward"],"items":[{"text":"Targeting new markets","cat":1},{"text":"Launching a 'me too' product with no point of difference","cat":0},{"text":"Increasing the revenue stream","cat":1},{"text":"Increasing market share","cat":1},{"text":"Doubtful financial feasibility","cat":0},{"text":"Poor timing","cat":0}],"explanation":"NPD is risky, with over 85% of new products failing, but the rewards when one lands can be huge."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Over ___% of new products fail.","answers":["85"],"explanation":"This failure rate is why a systematic development process matters.","lvl":5},{"type":"mc","prompt":"Dyson built an air-purifying mask and headset, but the founder said the market 'isn't ready yet'. Which reason for failure does this reflect?","options":["Distribution problems","Poor timing","Too much competition","Price set too low"],"answer":1,"explanation":"Dyson's product was possibly 20 to 30 years ahead of its time.","lvl":1}]},{"id":"MMK101-10.4","name":"Identify product life cycle stages and strategies","summary":"You can place products in a PLC stage, describe how sales, profit and competitors move, and pick the right strategy.","questions":[{"type":"order","prompt":"Put the product life cycle stages in order.","items":["Introduction","Growth","Maturity","Decline"],"explanation":"Products follow a bell-curve life cycle after launch; before launch, sales are zero and profit is negative."},{"type":"match","prompt":"Match each PLC stage to its profile.","pairs":[["Introduction","Low sales, negative profit, innovators, few competitors"],["Growth","Sales rising fast, early adopters, growing competition"],["Maturity","Peak sales, high profit, many competitors, defend share"],["Decline","Falling sales, laggards, harvest or discontinue"]],"explanation":"Each stage calls for a different strategy focus."},{"type":"case","passage":"The smartphone market has many established competitors, sales are at a stable peak and most buyers are mainstream consumers.","prompt":"Which strategy focus fits this stage?","options":["Defend share and differentiate","Build preference and share as a new category","Build awareness with heavy promotion","Harvest or discontinue"],"answer":0,"explanation":"Smartphones sit in maturity, where firms defend share and differentiate.","lvl":3},{"type":"mc","prompt":"Which PLC stage are fax machines and landline phones in?","options":["Growth","Introduction","Decline","Maturity"],"answer":2,"explanation":"Declining categories are poor markets to enter; no one is making new landline phones.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Before launch, during product development, sales are zero and profit is positive.","wrong":"positive","correct":"negative","explanation":"Before launch costs are high and there are no sales, so profit is negative."},{"type":"analogy","prompt":"Space tourism is to the introduction stage as AI tools are to the ___ stage","options":["introduction","growth","maturity","decline"],"answer":1,"explanation":"The notes place AI tools and electric cars in growth, and smartphones and streaming in maturity.","lvl":2}]}]},{"week":11,"topic":"Sustainable Marketing, Ethics & Compliance","summary":"Sustainable marketing beyond the law, the triple bottom line, criticisms of marketing, ethics, consumer rights and compliance.","skills":[{"id":"MMK101-11.1","name":"Define sustainable marketing and its evolution beyond the law","summary":"You can separate sustainable marketing from legal minimums and place it in the evolution of marketing concepts.","questions":[{"type":"mc","prompt":"Which of these is an example of sustainable marketing?","options":["Paying staff the minimum wage","Delivering quarterly returns to shareholders","Auditing suppliers to ensure they do not harm the environment before the law requires it","Complying with the single-use plastic bag ban"],"answer":2,"explanation":"The defining test: sustainable marketing goes beyond legal obligations. The other options are just what the law or the job requires.","lvl":2},{"type":"order","prompt":"Put the marketing concepts in order of evolution.","items":["Production concept","Product concept","Selling concept","Marketing concept","Sustainable marketing concept"],"explanation":"Each step widens the lens, with the sustainable marketing concept balancing economic, social and environmental returns."},{"type":"analogy","prompt":"The sustainable marketing concept is to the marketing concept as the marketing concept is to the ___","options":["selling concept only","societal marketing concept","triple bottom line","product and production concepts"],"answer":3,"explanation":"The notes describe the sustainable marketing concept as a step up in breadth, just as the marketing concept was.","lvl":4},{"type":"case","passage":"Thank You began by selling bottled water no different from any other brand, yet consumers happily paid a premium.","prompt":"What explains the premium?","options":["Consumers were emotionally attached to the brand's cause and purpose","The water was a superior product","Bottled water is a specialty product","Thank You used predatory pricing"],"answer":0,"explanation":"Sustainability attaches to a brand's purpose more than a single product, which is why purpose-driven brands can earn a premium.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The defining test of sustainable marketing is that it goes beyond ___ obligations.","answers":["legal"],"explanation":"Doing what the law requires is not sustainable marketing; the proactive extra is.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Legal minimum","Proactive sustainability"],"items":[{"text":"Publishing diversity and inclusion targets","cat":1},{"text":"Complying with the plastic bag ban","cat":0},{"text":"KitKat moving to a recyclable wrapper","cat":1},{"text":"Auditing third-party factories for conditions","cat":1},{"text":"Paying the minimum wage","cat":0},{"text":"Delivering required shareholder returns","cat":0}],"explanation":"True sustainable marketing puts the environment and people at the heart of decisions before the law demands it."}]},{"id":"MMK101-11.2","name":"Apply the triple bottom line of planet, people and profit","summary":"You can assign practices to the three pillars and explain why profit must run through governance.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Planet","People","Profit"],"items":[{"text":"Strong board governance","cat":2},{"text":"Protecting consumer data through risk management","cat":2},{"text":"Auditing factories for labour conditions","cat":1},{"text":"Recycling and waste minimisation","cat":0},{"text":"Weighing road, sea and air freight by carbon impact","cat":0},{"text":"Setting targets for women and Indigenous representation","cat":1}],"explanation":"Planet covers the environment, People everyone along the supply chain, and Profit governance, risk and compliance."},{"type":"case","passage":"In the 1970s, Ford knew of a fatal fault in the Pinto but calculated that facing lawsuits was cheaper than a recall, so it did not recall.","prompt":"How does this breach the triple bottom line?","options":["It ignored the societal marketing era only","It was an example of good governance","Profit was pursued at the expense of people","It over-invested in the planet pillar"],"answer":2,"explanation":"Firms must be profitable, but not at the detriment of people or the environment.","lvl":2},{"type":"mc","prompt":"How do the notes define Corporate Social Responsibility (CSR)?","options":["Integrating social and environmental concerns into business operations and practices","Donating a fixed share of profit each year","Complying with competition law","Marketing a cause to change behaviour"],"answer":0,"explanation":"This was the MCQ answer. CSR provides the principles that regulate sustainable marketing.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Research shows investing in people and diversity drives a lower economic return.","wrong":"lower","correct":"greater","explanation":"Sustainability is not zero-sum: diverse boards tend to outperform and supported staff take fewer sick days."},{"type":"type_answer","prompt":"The triple bottom line's three pillars are Planet, People and which third pillar?","answers":["profit"],"explanation":"The pillars should be considered together, for the long term, not in isolation.","lvl":1},{"type":"case","passage":"Disney's reputation was damaged when conditions at the third-party manufacturing hubs making its products were exposed.","prompt":"Which pillar and lesson does this highlight?","options":["People: only the target audience matters","Profit: brands must lift quarterly returns","Planet: brands must cut freight emissions","People: brands must audit partners because the reputational hit lands on the brand"],"answer":3,"explanation":"People means everyone along the supply chain, so brands audit factories, logistics and distributors.","lvl":2}]},{"id":"MMK101-11.3","name":"Identify the social criticisms of marketing","summary":"You can match practices to criticisms of marketing and analyse loyalty programs critically and fairly.","questions":[{"type":"match","prompt":"Match each practice to the criticism of marketing it reflects.","pairs":[["Shrinkflation","High prices"],["The Coles ACCC pricing case","Deceptive practices"],["Designing products to be replaced sooner than needed","Planned obsolescence"],["Manufacturing wants and pushing consumption","Increased materialism"]],"explanation":"Other criticisms include barriers to entry and harm to competitors."},{"type":"case","passage":"A CHOICE survey found 79% of respondents thought member-only supermarket pricing was unfair.","prompt":"Which concern about member-only pricing do the notes raise?","options":["It lowers prices too much for retailers to profit","It disadvantages people without a smartphone or fixed address and reduces price transparency","It breaches the advertising code on under-16s","It forces supermarkets to stop collecting data"],"answer":1,"explanation":"Member-only pricing excludes some shoppers and makes true prices harder to compare.","lvl":2},{"type":"mc","prompt":"Which statement gives the balanced view of marketing that the notes recommend?","options":["Marketing can be used well or badly, and also does good through anti-smoking and anti-gambling campaigns","Marketing criticisms are all unfounded","Marketing is harmless because consumers can always choose","Marketing only sells people things they do not need"],"answer":0,"explanation":"Marketing is fundamentally about changing behaviour and creating value, which is why ethics and law matter.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When a product shrinks while its price holds or rises, it is called ___.","answers":["shrinkflation"],"explanation":"Shrinkflation is listed under the high prices criticism.","lvl":2},{"type":"case","passage":"Professor Jana Bowden notes that loyalty programs like Flybuys and Everyday Rewards change how members shop.","prompt":"Which behavioural effect does she describe?","options":["Members switch between supermarkets more","Members stop caring about price entirely","Increased purchase frequency and basket size, even paying a premium for points","Members shop less often and spend less"],"answer":2,"explanation":"Despite 9 million+ members each, experts argue the programs do not save money overall.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The real trade in supermarket loyalty programs is customers' time.","wrong":"time","correct":"data","explanation":"Member data is shared with subsidiaries and partners under vague consent buried in long privacy policies."}]},{"id":"MMK101-11.4","name":"Distinguish ethics, consumer rights and compliance areas","summary":"You can separate ethics from law, identify genuine consumer rights, and assign cases to the four compliance areas.","questions":[{"type":"mc","prompt":"Which of these is NOT a consumer right according to the notes?","options":["The right to expect a safe product","The right not to buy","The right to expect the product to perform as claimed","The right to a product that is better than a competitor's"],"answer":3,"explanation":"Perceived value is subjective and firms deliberately differentiate, so there is no common yardstick for 'better'.","lvl":1},{"type":"match","prompt":"Match each compliance area to its case.","pairs":[["Competition law","Colgate fined about $18m for price fixing"],["Consumer law and product liability","Pressure-selling vacuums to the elderly"],["Marketing communications","Skechers Shape-Ups' unsupported weight-loss claim"],["Intellectual property","Cadbury versus Darrell Lea over the colour purple"]],"explanation":"Marketers must understand all four areas to avoid major repercussions."},{"type":"case","passage":"Bega took action against Kraft over the use of the peanut butter jar's distinctive yellow lid.","prompt":"Which compliance area does this fall under?","options":["Competition law","Intellectual property","Marketing communications","Consumer law and product liability"],"answer":1,"explanation":"IP protects brand equity; copying that would mislead the average consumer is actionable.","lvl":2},{"type":"sort","prompt":"Sort each example into the right category.","categories":["Ethics","Law"],"items":[{"text":"Price fixing is prohibited","cat":1},{"text":"Black and white rules","cat":1},{"text":"What you think is right may differ from a colleague","cat":0},{"text":"Should sit in the mission and vision","cat":0},{"text":"Products must be safe to use","cat":1},{"text":"A subjective grey area","cat":0}],"explanation":"Ethics is about moral right and wrong and is partly subjective; the law is black and white."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The Ad Standards test for a misleading ad is whether the average ___ would be misled.","answers":["consumer"],"explanation":"Ad Standards is a voluntary, marketer-run code that handles offensive or misleading ads.","lvl":2},{"type":"case","passage":"A paper-industry account manager received a call from a competitor wanting to discuss pricing. She hung up and reported it immediately.","prompt":"Why was this the right response?","options":["Discussing prices with rivals is legal if informal","Resale price maintenance requires a written contract","Collusion can start with a single call, and competition law prohibits price fixing","Only the legal team must worry about compliance"],"answer":2,"explanation":"Compliance is everyone's job, which is why most firms run annual legal and ethics training.","lvl":1}]}]}]};
window.LAMPLIGHT_UNITS["HPS104"] = {"code":"HPS104","name":"Foundations of Psychological Science","term":"T1 2026","weeks":10,"weekList":[{"week":1,"topic":"Evidence in Psychology","summary":"The philosophical foundations of scientific psychology: ontology and epistemology, the canons of science, operationalisation, the scientist-practitioner model and OLIA.","skills":[{"id":"HPS104-1.1","name":"Distinguish ontological from epistemological claims","summary":"You can tell whether a claim is about what exists or about how we know, and explain why determinism motivates empiricism.","questions":[{"type":"mc","prompt":"Which statement is an epistemological claim?","options":["Reality includes both physical and mental substances.","Knowledge is best gained through systematic observation of the world.","The universe is made of matter and energy following physical laws.","All events have systematic, orderly causes."],"answer":1,"explanation":"Epistemology concerns how we know things. Claims about what reality is made of (materialism, dualism, determinism) are ontological.","lvl":3},{"type":"sort","prompt":"Sort each position into the right category.","categories":["Ontological position","Epistemological position"],"items":[{"text":"Determinism","cat":0},{"text":"Empiricism","cat":1},{"text":"Dualism","cat":0},{"text":"Rationalism","cat":1},{"text":"Indeterminism","cat":0},{"text":"Knowledge through religious revelation","cat":1}],"explanation":"Ontology asks 'what is?' (determinism, dualism, indeterminism). Epistemology asks 'how do we know?' (empiricism, rationalism, revelation)."},{"type":"order","prompt":"Put the steps of the argument from determinism to empiricism in logical order.","items":["Assume reality is deterministic, so all events have systematic causes","Systematic causes leave evidence in the form of regularities and patterns","Patterns are best discovered by observing the world systematically","Therefore, determinism motivates an empirical epistemology"],"explanation":"The argument moves from an ontological assumption (causal order) to its evidence (patterns) to the method best suited to finding them (observation)."},{"type":"case","passage":"A student argues: 'If human behaviour were completely random and had no causes, it would make no sense to run experiments on it.' Her tutor says she has just explained why science pairs a particular view of reality with a particular method.","prompt":"Which pairing is the tutor referring to?","options":["Dualism and intuition","Rationalism and indeterminism","Ontological determinism and empirical epistemology","Materialism and authority"],"answer":2,"explanation":"If behaviour has systematic causes (determinism), there is something to find, and observation (empiricism) is the way to find it. Random behaviour would leave nothing to discover.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The branch of philosophy that asks 'what is real?' is called ___.","answers":["ontology"],"explanation":"Ontology is the study of being and the nature of reality. Epistemology is the study of knowledge.","lvl":2},{"type":"analogy","prompt":"Ontology is to 'what is?' as epistemology is to ___","options":["'what is beautiful?'","'how do we know?'","'what should we do?'","'what causes what?'"],"answer":1,"explanation":"Ontology concerns the nature of reality, while epistemology concerns how we come to know things and justify beliefs.","lvl":1}]},{"id":"HPS104-1.2","name":"Apply the four canons of science to examples","summary":"You can recognise determinism, empiricism, parsimony and testability in scenarios, including Morgan's Canon and falsifiability.","questions":[{"type":"case","passage":"A cat learns to open a door by pressing a latch. One researcher says the cat reasoned about the problem and worked out the solution. Another says the cat pressed the latch by accident, the door opened, and the behaviour was reinforced.","prompt":"Which canon supports preferring the second explanation?","options":["Empiricism","Parsimony","Falsifiability","Determinism"],"answer":1,"explanation":"Parsimony (here, Morgan's Canon) favours the simpler explanation that needs fewer assumptions about the cat's mental life, unless there is evidence for the more complex one.","lvl":2},{"type":"match","prompt":"Match each canon to the thinker most linked to it.","pairs":[["Parsimony","William of Occam"],["Falsifiability","Karl Popper"],["Empiricism","Bacon, Locke and Hume"],["Parsimony in animal behaviour","Lloyd Morgan"]],"explanation":"Occam's Razor and Morgan's Canon express parsimony, Popper championed falsifiability, and the British empiricists are linked to empiricism."},{"type":"mc","prompt":"Critics say Freudian psychoanalysis can explain any behaviour a patient shows, including its opposite. Which canon does this criticism mainly target?","options":["Empiricism","Testability and falsifiability","Parsimony","Determinism"],"answer":1,"explanation":"A theory that explains everything explains nothing. If no observation could contradict it, it is not falsifiable.","lvl":2},{"type":"type_answer","prompt":"What name is given to Lloyd Morgan's 1894 rule that we should not attribute higher mental faculties to animals when lower ones explain the behaviour?","answers":["Morgan's Canon","Morgans Canon","Morgan's law"],"explanation":"Morgan's Canon is psychology's application of parsimony to comparative (animal) research.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Popper argued that scientists should actively seek tests that could prove their theories right.","wrong":"right","correct":"wrong","explanation":"Falsifiability means seeking out tests that could disconfirm a theory, as Einstein did when he named predictions that would make relativity untenable."},{"type":"case","passage":"Researchers argue about how many teeth a horse should have. One reasons from its biological family, another from religious law. Finally someone suggests opening a horse's mouth and counting.","prompt":"Which canon does the final suggestion illustrate?","options":["Determinism","Parsimony","Empiricism","Testability"],"answer":2,"explanation":"Empiricism says knowledge comes from systematic observation of the world, not from authority or reasoning from first principles.","lvl":2}]},{"id":"HPS104-1.3","name":"Distinguish constructs from variables and operationalise them","summary":"You can tell an abstract construct from a measurable variable, and explain why operationalisation is necessary but imperfect.","questions":[{"type":"sort","prompt":"Sort each example into the right category.","categories":["Construct","Variable"],"items":[{"text":"Self-esteem","cat":0},{"text":"Score on the Rosenberg Self-Esteem Scale","cat":1},{"text":"Aggression","cat":0},{"text":"Number of loud noise blasts given to a confederate","cat":1},{"text":"Hunger","cat":0},{"text":"Hours since last meal","cat":1}],"explanation":"Constructs are abstract, unobservable concepts. Variables are concrete, measurable quantities used to capture them."},{"type":"case","passage":"In AT1, researchers want to know whether GPs hold 'diagnostic weight bias'. They measure it using a score on a vignette task in which patient weight is varied.","prompt":"What is the DWB score in this study?","options":["A construct","A canon of science","An operationalisation of the construct as a variable","A postulate"],"answer":2,"explanation":"Diagnostic weight bias is the construct. The DWB score is the variable that operationalises it.","lvl":3},{"type":"mc","prompt":"Two studies test the same theory of aggression. One measures noise blasts in the lab, the other uses questionnaire reports of past behaviour. They reach different conclusions. Which problem of operationalisation does this show?","options":["Variables are always constructs","Constructs are directly observable","Different operationalisations can give different answers","Operationalisation is only a problem in physics"],"answer":2,"explanation":"The construct is the same but the variables differ, so results can differ. This is one of the three reasons operationalisation is hard.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The process of translating an abstract construct into one or more measurable variables is called ___.","answers":["operationalisation","operationalization"],"explanation":"Operationalisation makes the unobservable observable so that theories about constructs can be tested.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A construct is a concrete, measurable quantity that varies on a dimension.","wrong":"construct","correct":"variable","explanation":"This is the definition of a variable. A construct is an abstract, theoretical concept that is not directly observable."},{"type":"mc","prompt":"Why can no single measure fully capture the construct 'depression'?","options":["Only physiological measures are valid","Depression is not a real phenomenon","Depression has many components and any variable is only an indirect proxy","Questionnaires cannot be scored reliably"],"answer":2,"explanation":"Constructs are complex (low mood, sleep, anhedonia, fatigue) and every measure is an indirect proxy, which is why the BDI and Hamilton scale capture different features.","lvl":2}]},{"id":"HPS104-1.4","name":"Identify the three roles of the scientist-practitioner model","summary":"You can recognise the consumer, evaluator and researcher roles in practice and explain the Boulder model and the scientist-practitioner gap.","questions":[{"type":"case","passage":"A therapist records every client's depression score at intake and again at discharge. She reviews the numbers each year to check whether her CBT sessions are actually working.","prompt":"Which scientist-practitioner role is she performing?","options":["Evaluator","Consumer","Researcher","Authority"],"answer":0,"explanation":"Using empirical outcome measures to evaluate one's own interventions, for accountability, is the evaluator role.","lvl":2},{"type":"match","prompt":"Match each practice to its scientist-practitioner role.","pairs":[["Updating a treatment protocol after reading a new RCT","Consumer"],["Tracking outcomes of your own program for accountability","Evaluator"],["Publishing a case series from your clinic","Researcher"]],"explanation":"Hayes, Barlow and Nelson-Gray describe three interrelated roles: consumer, evaluator and researcher."},{"type":"type_answer","prompt":"The 1949 conference that established the scientist-practitioner model was held in which US city?","answers":["Boulder","Boulder, Colorado"],"explanation":"The Boulder conference (1949), sponsored by NIMH and the APA, recommended training clinical psychologists equally in research and practice.","lvl":4},{"type":"mc","prompt":"According to Hayes and colleagues, which factor helped push practitioners back toward the scientist-practitioner ideal in the 1980s and 1990s?","options":["Managed care demanding evidence of effectiveness","A decline in clinical trials","The Boulder conference","The rise of psychoanalysis"],"answer":0,"explanation":"Managed care created economic pressure for empirical accountability, as insurers and governments demanded evidence that treatments work.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The scientist-practitioner gap refers to many clinicians who read, evaluate and contribute to research in their everyday practice.","wrong":"read","correct":"ignore","explanation":"The gap describes clinicians who do NOT read research, evaluate outcomes or contribute data, despite being trained to."},{"type":"case","passage":"A clinic's psychologists read the latest research carefully and apply it, but never measure their own clients' outcomes or share any data.","prompt":"What is the main weakness of relying on this single role?","options":["They are acting as researchers only","They have rejected the consumer role","Reading research is not part of the model","Individual practice is never evaluated and the field gains no new data"],"answer":3,"explanation":"Consumer alone is not enough: without evaluation, practice is not accountable, and without research the gap between research and practice widens.","lvl":3}]},{"id":"HPS104-1.5","name":"Apply the OLIA ordering of sources of knowledge","summary":"You can rank sources of knowledge in science, compare belief systems, and explain the implications of OLIA.","questions":[{"type":"order","prompt":"Put the sources of knowledge in order from most to least important in science.","items":["Observation","Logic","Intuition","Authority"],"explanation":"OLIA: Observation, Logic, Intuition, Authority. Observation is king and authority comes last."},{"type":"match","prompt":"Match each belief system to the source of knowledge it ranks first.","pairs":[["Science","Observation"],["Philosophy","Logic"],["Religion","Authority"]],"explanation":"Religion and government rank authority first, philosophy ranks logic first, and science ranks observation first."},{"type":"case","passage":"A well-known professor insists that a therapy works because of her decades of experience. A new, well-run study finds the therapy has no effect.","prompt":"According to OLIA, what should a scientific psychologist conclude?","options":["Trust the professor because of her status","Average the two views","Rely on intuition to decide","The observations outweigh the authority, so the study wins"],"answer":3,"explanation":"Authority is at the bottom of OLIA. If a famous researcher's claims contradict the observations, the observations win.","lvl":1},{"type":"mc","prompt":"The US Declaration of Independence states 'we hold these truths to be self-evident'. Which source of knowledge is this?","options":["Intuition","Logic","Observation","Authority"],"answer":0,"explanation":"Claims accepted as self-evident rely on intuition, immediate insight or what 'seems obvious'.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In philosophy, observation ranks first and logic ranks second.","wrong":"philosophy","correct":"science","explanation":"Science ranks observation first and logic second. Philosophy reverses this, ranking logic first and observation second."},{"type":"analogy","prompt":"Science is to observation as government is to ___","options":["authority","observation","logic","intuition"],"answer":0,"explanation":"Government, like religion, ranks authority first, followed by intuition, logic and observation.","lvl":2}]}]},{"week":2,"topic":"The Scientific Method","summary":"How laws, theories and models differ, how induction and deduction build and test theories, criteria for comparing theories, and types of explanation.","skills":[{"id":"HPS104-2.1","name":"Distinguish laws, theories, models and related terms","summary":"You can classify a scientific statement as a law, theory, model, hypothesis or postulate and explain how they differ.","questions":[{"type":"match","prompt":"Match each term to its description.","pairs":[["Law","Universal, deterministic statement of regular relations"],["Theory","Provisional explanation with boundary conditions"],["Model","Analogy that is useful rather than true"],["Postulate","Assumption within a theory that is not itself tested"]],"explanation":"Laws are universal and scarce in psychology, theories are truths with context, models are heuristic analogies, and postulates are untested assumptions."},{"type":"case","passage":"A researcher proposes that stressors lead to rumination, which in turn leads to anxiety (Stressor, Rumination, Anxiety). She uses it to generate study ideas rather than to claim a universal truth.","prompt":"This is best described as a:","options":["Law","System","Model","Protocol statement"],"answer":2,"explanation":"The lecture's example of a model is Stressor, Rumination, Anxiety: a 'mini theory' used as a heuristic tool.","lvl":4},{"type":"mc","prompt":"How do models differ from theories in their response to disconfirming evidence?","options":["Theories cannot be disconfirmed","Neither is affected by evidence","Models are more damaged by disconfirming evidence","Models can survive disconfirming evidence, while theories are more vulnerable"],"answer":3,"explanation":"Models are heuristic and less data-sensitive, so disconfirming evidence damages a theory but not necessarily a model.","lvl":4},{"type":"order","prompt":"Put these in order from broadest to narrowest scope (Valentine).","items":["System","Theory","Model"],"explanation":"A system is a general theory plus methodological recommendations (like behaviourism), a theory is narrower, and a model is narrower still."},{"type":"type_answer","prompt":"What term describes a tentative law: a testable prediction derived from a theory?","answers":["hypothesis","a hypothesis"],"explanation":"A hypothesis is a tentative law derived from a theory so it can be tested.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Laws are notably plentiful in psychology.","wrong":"plentiful","correct":"scarce","explanation":"Laws, which hold without qualification, are notably scarce in psychology. Most psychological explanation is in the form of theories."}]},{"id":"HPS104-2.2","name":"Identify valid and fallacious forms of conditional reasoning","summary":"You can classify IF THEN arguments as modus ponens, modus tollens, affirming the consequent or denying the antecedent.","questions":[{"type":"case","passage":"Premise: If a bird is a swan, then it is white. A student sees something white on the lake and concludes: 'It must be a swan.'","prompt":"What reasoning pattern has the student used?","options":["Denying the antecedent","Affirming the antecedent","Affirming the consequent","Denying the consequent"],"answer":2,"explanation":"If A then B; B is true; therefore A. This is the fallacy of affirming the consequent, because many white things are not swans.","lvl":3},{"type":"sort","prompt":"Sort each reasoning pattern into the right category.","categories":["Valid","Fallacy"],"items":[{"text":"Modus ponens","cat":0},{"text":"Modus tollens","cat":0},{"text":"Affirming the consequent","cat":1},{"text":"Denying the antecedent","cat":1}],"explanation":"Only affirming the antecedent (modus ponens) and denying the consequent (modus tollens) are valid."},{"type":"mc","prompt":"Which reasoning pattern is the logical basis of falsification?","options":["Denying the consequent (modus tollens)","Denying the antecedent","Affirming the antecedent","Affirming the consequent"],"answer":0,"explanation":"If the theory predicts B and B does not occur, the theory is rejected. Modus tollens underpins Popper's falsification.","lvl":4},{"type":"case","passage":"Premise: If a person receives CBT, their depression scores will fall. A clinician observes that a client did not receive CBT and concludes the client's depression scores will not fall.","prompt":"Which pattern is this, and is it valid?","options":["Modus ponens, valid","Modus tollens, valid","Affirming the consequent, a fallacy","Denying the antecedent, a fallacy"],"answer":3,"explanation":"If A then B; not A; therefore not B. Scores could fall for other reasons, so denying the antecedent is a fallacy.","lvl":4},{"type":"analogy","prompt":"Modus ponens is to affirming the antecedent as modus tollens is to ___","options":["denying the antecedent","the conjunction fallacy","affirming the consequent","denying the consequent"],"answer":3,"explanation":"Modus ponens is affirming the antecedent and modus tollens is denying the consequent. Both are valid forms.","lvl":3},{"type":"case","passage":"Linda is 31, outspoken and bright, and majored in philosophy with a strong interest in social justice. Most people judge 'Linda is a bank teller and an active feminist' as more likely than 'Linda is a bank teller'.","prompt":"What error are they making?","options":["The nominalist fallacy","The conjunction fallacy","Affirming the consequent","Denying the antecedent"],"answer":1,"explanation":"A compound event (A and B) can never be more likely than one of its components. Kahneman and Tversky called this the conjunction fallacy.","lvl":3}]},{"id":"HPS104-2.3","name":"Explain induction, deduction and falsification in science","summary":"You can explain the limits of induction, the hypothetico-deductive cycle, null and alternative hypotheses, and confirmatory bias.","questions":[{"type":"order","prompt":"Put the stages of the hypothetico-deductive cycle in order, starting from observation.","items":["Observe the world and interpret observations","Develop a tentative theory","Derive a specific, operationalised hypothesis","Test the hypothesis with new observations"],"explanation":"Induction builds theory from observation (bottom-up), then deduction derives testable predictions (top-down), and new data feed back into the theory."},{"type":"mc","prompt":"Why can induction never prove that 'all swans are white'?","options":["No number of confirming cases is logically sufficient, but one counterexample disproves it","Deduction is always inductive","Swans are not a valid construct","Swans are too hard to observe"],"answer":0,"explanation":"Confirmation of a universal claim is impossible, but falsification is possible. This asymmetry is the core of Popper's philosophy.","lvl":2},{"type":"case","passage":"A researcher hypothesises that GPs who watch an ED psychoeducational video will show lower diagnostic weight bias than GPs who watch a general mental health video.","prompt":"What is the null hypothesis?","options":["GPs have no weight bias","The general video will reduce weight bias","The ED video will increase weight bias","There will be no difference in diagnostic weight bias between the two groups"],"answer":3,"explanation":"The null hypothesis predicts no treatment effect. The decision is whether there is enough evidence to reject it.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In statistical testing we aim to prove the alternative hypothesis rather than reject the null.","wrong":"prove","correct":"support","explanation":"We never prove a hypothesis. We decide whether there is sufficient evidence to reject the null in favour of the alternative, reflecting Popper's insight."},{"type":"match","prompt":"Match each use of hypotheses to its description.","pairs":[["Validation","Testing a theory by confirmation"],["Falsification","Testing a theory by disconfirmation"],["Qualification","Identifying a theory's boundary conditions"]],"explanation":"Validation is the weakest use because of confirmatory bias; falsification is Popper's preferred approach; qualification finds where a theory holds."},{"type":"type_answer","prompt":"What bias describes the tendency to seek evidence that supports existing beliefs and ignore evidence against them (also called positive test bias)?","answers":["confirmatory bias","confirmation bias"],"explanation":"The fix for confirmatory bias is building procedures into research that force a search for disconfirmation, looking for black swans.","lvl":2}]},{"id":"HPS104-2.4","name":"Evaluate rival theories using external criteria","summary":"You can apply parsimony, testability, empirical support and fruitfulness (plus scope and clarity) to compare theories.","questions":[{"type":"case","passage":"Theory A explains a finding with three constructs. Theory B explains the same data equally well but adds a fourth construct and an unseen 'energy'.","prompt":"Which criterion most directly favours Theory A?","options":["Fruitfulness","Parsimony","Scope","Empirical support"],"answer":1,"explanation":"Parsimony (Occam's Razor) prefers maximum data explained with minimum theoretical assumptions.","lvl":1},{"type":"match","prompt":"Match each criterion to what it asks.","pairs":[["Fruitfulness","Does it stimulate new research and discoveries?"],["Empirical support","Is it backed by varied, replicable findings?"],["Testability","Does it make unambiguous, falsifiable predictions?"],["Scope","How much data does it cover?"]],"explanation":"The lecture's four core criteria are parsimony, testability, empirical support and fruitfulness; Valentine adds scope and clarity."},{"type":"mc","prompt":"Why is internal consistency not enough to compare rival theories?","options":["A circular argument can be internally consistent, so external, independent criteria are needed","Internally consistent theories are always false","Consistency is only relevant to models","External criteria cannot be applied to psychology"],"answer":0,"explanation":"Arguments like 'democracy is superior because everyone gets a say' are internally consistent but circular. You must step outside the theory to evaluate it.","lvl":3},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A theory can be partly wrong but still hugely valuable if it rates highly on ___, the criterion that may be most important long-term.","answers":["fruitfulness"],"explanation":"Fruitfulness concerns whether a theory stimulates research, explains unresolved phenomena and unifies theories.","lvl":4},{"type":"mc","prompt":"Popper stressed that empirical support depends on:","options":["The fame of the researcher","One dramatic study","Both the variety and quantity of corroboration","Internal logic alone"],"answer":2,"explanation":"A theory backed by many different lines of evidence from different groups is stronger than one backed by a single study.","lvl":3},{"type":"analogy","prompt":"Parsimony is to Occam's Razor as falsifiability is to ___","options":["Kuhn","Skinner","Popper","Morgan"],"answer":2,"explanation":"Parsimony is associated with William of Occam, and falsifiability with Karl Popper.","lvl":3}]},{"id":"HPS104-2.5","name":"Classify types of explanation in psychology","summary":"You can identify Valentine's seven types of explanation and spot the nominalist fallacy.","questions":[{"type":"case","passage":"A psychologist explains that Jones crossed the road in order to buy tobacco.","prompt":"Which type of explanation is this?","options":["Correlational","Deductive-nomological","Teleological (purposive)","Neurophysiological"],"answer":2,"explanation":"Teleological explanations refer to a future goal rather than a past cause, like Aristotle's final cause.","lvl":3},{"type":"match","prompt":"Match each explanation type to its example.","pairs":[["Neurophysiological","Depression explained by brain chemistry"],["Functional (mechanistic)","A flow chart model of reading"],["Correlational","Smoking is associated with cancer"],["Mentalistic (reasons)","Behaviour explained by the agent's beliefs and desires"]],"explanation":"Valentine's types differ in what they appeal to: brain, processes, associations or reasons."},{"type":"case","passage":"A doctor claims that opium makes people sleep because it has a 'soporific power'.","prompt":"What error is this?","options":["Nominalist fallacy","Confirmatory bias","Conjunction fallacy","Affirming the consequent"],"answer":0,"explanation":"The nominalist fallacy is thinking that naming something explains it. 'Soporific power' just renames the effect.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The deductive-nomological model explains an event as an instance of a general law plus consequent conditions.","wrong":"consequent","correct":"antecedent","explanation":"Hempel and Oppenheim's D-N model combines a general law with antecedent conditions (e.g. copper expands when heated, and this bar was copper and heated)."},{"type":"sort","prompt":"Sort each explanation of a road death into the right perspective.","categories":["Physician","Barrister","Civic planner"],"items":[{"text":"Multiple haemorrhage","cat":0},{"text":"Negligence by the driver","cat":1},{"text":"Tall shrubbery at the turning","cat":2},{"text":"Loss of blood from internal injuries","cat":0}],"explanation":"All the explanations are correct but focus on different aspects: explanation is pragmatic and shaped by the explainer's purpose."},{"type":"type_answer","prompt":"What is the German term for the tradition that psychology should pursue empathic understanding rather than causal prediction?","answers":["Verstehen"],"explanation":"Verstehen, along with hermeneutics and rationalisation, belongs to the mentalistic or reasons type of explanation.","lvl":5}]}]},{"week":3,"topic":"The Validity of Research","summary":"Variables, Mill's requirements for causality, types of confounds, the four validity types, GAGES and OOPS!, and measurement scales.","skills":[{"id":"HPS104-3.1","name":"Identify IVs, DVs, levels and conditions in a study","summary":"You can pick out the independent and dependent variables, count levels and conditions, and tell extraneous variables from confounds.","questions":[{"type":"case","passage":"Researchers randomly assign adults to receive CBT or no treatment, and also group them as young, middle-aged or old. Depression symptom scores are measured after eight weeks.","prompt":"How many conditions does this study have?","options":["5","2","3","6"],"answer":3,"explanation":"Multiple IVs multiply: treatment (2 levels) crossed with age (3 levels) gives 2 x 3 = 6 conditions.","lvl":3},{"type":"case","passage":"In AT1, GPs are randomly assigned to watch either an ED psychoeducational video or a general mental health video. They then complete a vignette task producing a Diagnostic Weight Bias (DWB) score.","prompt":"What is the dependent variable?","options":["DWB score","The GP's age","Random assignment","Type of psychoeducation video"],"answer":0,"explanation":"The DV is the outcome measured after the manipulation. The video type is the IV and the DWB score is the DV.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"An extraneous variable becomes a confound only when it is related to either the IV or the DV.","wrong":"either","correct":"both","explanation":"A confound must be related to BOTH the IV and the DV. If it relates to only one, it just adds noise rather than an alternative explanation."},{"type":"sort","prompt":"Sort each variable into the right category.","categories":["Continuous","Discrete or categorical"],"items":[{"text":"Height in cm","cat":0},{"text":"Treatment vs control","cat":1},{"text":"Type of therapy","cat":1},{"text":"Reaction time in ms","cat":0},{"text":"Male vs female","cat":1}],"explanation":"Continuous variables can take any value along a dimension. Discrete variables take distinct, separate values by definition."},{"type":"type_answer","prompt":"What term describes the discrete groups or conditions that define the values an independent variable takes?","answers":["levels","level"],"explanation":"An IV's levels define the groups. Treatment vs no treatment is an IV with two levels.","lvl":3},{"type":"mc","prompt":"Which kind of extraneous variable does the lecture describe as the most dangerous?","options":["Variables held constant across the study","Ones related only to the DV","Unknown variables the researcher does not know are there","Ones that are measured and controlled statistically"],"answer":2,"explanation":"The 'unknown unknowns' cannot be measured, controlled or accounted for, which makes hidden confounds the most dangerous.","lvl":2}]},{"id":"HPS104-3.2","name":"Apply Mill's three requirements for establishing causality","summary":"You can judge whether a claim meets covariation, temporal order and elimination of alternatives, and spot reverse causality and third variables.","questions":[{"type":"order","prompt":"Put Mill's requirements in the order they are presented, from most basic to hardest to satisfy.","items":["Covariation","Temporal order","Elimination of alternative explanations"],"explanation":"First the variables must covary, then the cause must precede the effect, and finally alternative explanations (confounds) must be ruled out, which is the hardest step."},{"type":"case","passage":"National ice cream sales correlate with national homicide rates. A commentator suggests banning ice cream to reduce murder.","prompt":"What best explains the correlation?","options":["A third variable (hot weather) causing both","An operational confound","Regression to the mean","Reverse causality"],"answer":0,"explanation":"Heat drives both ice cream buying and frustration, which predicts violence. This is the third-variable problem.","lvl":1},{"type":"case","passage":"A cross-sectional survey finds that divorced people report more distress than married people. The author concludes that distress causes divorce.","prompt":"Which of Mill's requirements is most clearly not established?","options":["Temporal order","Construct validity","Random sampling","Covariation"],"answer":0,"explanation":"Divorce and distress covary, but either could come first. Without longitudinal data the temporal order, and thus causal direction, cannot be determined.","lvl":3},{"type":"mc","prompt":"Pelham and Carvallo found men named Baker or Carpenter were more likely to work in those occupations. Why can temporal order be inferred here?","options":["Only one sequence is plausible: the surname came before the job","They used random assignment","It was a longitudinal RCT","The sample was WEIRD"],"answer":0,"explanation":"Men did not become carpenters and then change their name to Carpenter, so passive observational data can sometimes establish temporal order.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A farmer who invests more water in orchards that are already thriving illustrates the problem of forward causality.","wrong":"forward","correct":"reverse","explanation":"Here the apparent IV (watering) is caused by the DV (growth). This is reverse causality, which cross-sectional designs cannot resolve."},{"type":"case","passage":"Many people believe testosterone causes aggression, but studies that raise testosterone levels show little reliable increase in aggressive behaviour.","prompt":"What does this imply for the causal claim?","options":["It is supported because the belief is common","Temporal order is the only issue","The claim is proven by biological sex differences","Without covariation, there is no basis for a causal claim"],"answer":3,"explanation":"If the variables do not reliably covary, the first requirement fails. No covariation, no causal claim.","lvl":3}]},{"id":"HPS104-3.3","name":"Classify threats to internal validity by confound type","summary":"You can classify a threat as a person, environmental, experimental or operational confound and name the specific threat.","questions":[{"type":"case","passage":"In a therapy study, clients who are not improving tend to drop out of the treatment group, while dropout in the control group is low and random. At follow-up the treatment group looks very successful.","prompt":"Which threat is most responsible?","options":["Evaluation apprehension","Maturation","Homogeneous attrition","Heterogeneous attrition"],"answer":3,"explanation":"When dropout differs between groups and is not random, the remaining treatment group consists mostly of responders, making the treatment look more effective than it is.","lvl":4},{"type":"sort","prompt":"Sort each threat into the right confound category.","categories":["Experimental or procedural","Operational"],"items":[{"text":"Demand characteristics","cat":0},{"text":"Regression to the mean","cat":1},{"text":"Hawthorne effect","cat":0},{"text":"Maturation","cat":1},{"text":"Experimenter bias","cat":0},{"text":"Learning effects from repeated testing","cat":1}],"explanation":"Experimental confounds come from the way the study is run. Operational confounds come from how constructs are measured and natural changes over time."},{"type":"case","passage":"Participants are recruited for a depression trial because they scored extremely high on a depression scale. Six weeks later, both the treatment and waitlist groups score noticeably lower.","prompt":"Which threat could explain improvement in both groups?","options":["Selection bias","Participant reactance","Social desirability bias","Regression to the mean"],"answer":3,"explanation":"Extreme scores contain a random component unlikely to be extreme again, so scores drift toward the average regardless of treatment.","lvl":3},{"type":"match","prompt":"Match each threat to its description.","pairs":[["Participant reactance","Deliberately doing the opposite of what the researcher wants"],["Evaluation apprehension","Anxiety about being judged harms performance"],["Social desirability bias","Under-reporting undesirable behaviours"],["Hawthorne effect","Behaviour changes because of attention from being studied"]],"explanation":"These are all experimental or procedural confounds introduced by participant reactions to the study."},{"type":"case","passage":"A researcher recruits non-smokers from a university campus and smokers from a low-income suburb, then compares their lung health.","prompt":"What type of threat is this primarily?","options":["Participant reactance","Operational confound","Regression to the mean","Selection bias creating groups that differ from the outset"],"answer":3,"explanation":"Recruiting groups through different methods from different populations bakes in pre-existing differences, including environmental factors like air pollution.","lvl":2},{"type":"analogy","prompt":"Comparing watered oranges with unwatered apples is to a person confound as one orchard getting more sunlight is to ___","options":["an artefact","an operational confound","an experimental confound","an environmental confound"],"answer":3,"explanation":"In the orchard analogy, different fruit types are a pre-existing (person) difference, while different sunlight is an environmental or third-variable confound.","lvl":4}]},{"id":"HPS104-3.4","name":"Distinguish internal, external, construct and conceptual validity","summary":"You can identify which validity type a problem threatens, tell artefacts from confounds, and apply GAGES and OOPS!.","questions":[{"type":"case","passage":"To avoid hormonal variation, a researcher recruits only male participants. The study is well controlled with random assignment.","prompt":"Sex of participants in this study is best described as:","options":["An artefact limiting external validity","A person confound threatening internal validity","An operational confound","A demand characteristic"],"answer":0,"explanation":"An artefact is something held constant that would vary in the real world. It does not threaten internal validity but limits generalisation, here to men only.","lvl":4},{"type":"match","prompt":"Match each validity type to its core question.","pairs":[["Internal","Did my IV truly cause the change in my DV?"],["External","Can I generalise beyond this study?"],["Construct","Does my measure measure what I intend?"],["Conceptual","Is my study relevant to the research question?"]],"explanation":"The four validity types address causality, generalisability, measurement quality and relevance respectively."},{"type":"case","passage":"A researcher tests whether mindfulness reduces stress in clinical populations. She runs a rigorous RCT with a validated stress measure, but uses healthy undergraduates stressed by a timed maths test.","prompt":"Which validity type is most in question?","options":["Conceptual validity","Internal validity","Discriminant validity","Construct validity"],"answer":0,"explanation":"The study is well designed but may not answer the question about clinical populations under real-world stress: 'Nice study, but is it relevant?'","lvl":4},{"type":"mc","prompt":"A new depression questionnaire correlates just as strongly with an anxiety measure as with a clinician's depression diagnosis. Which aspect of construct validity is weak?","options":["Predictive validity","Discriminant validity","Convergent validity","External validity"],"answer":1,"explanation":"Discriminant validity requires the measure to distinguish depression from related but distinct constructs like anxiety.","lvl":4},{"type":"sort","prompt":"Sort each item into the heuristic it belongs to.","categories":["GAGES (confounds)","OOPS! (external validity)"],"items":[{"text":"Geography","cat":0},{"text":"Occasions","cat":1},{"text":"Socioeconomic status","cat":0},{"text":"Populations","cat":1},{"text":"Age","cat":0},{"text":"Situations","cat":1}],"explanation":"GAGES is Geography, Age, Gender, Ethnicity, SES. OOPS! is Operationalisations, Occasions, Populations, Situations."},{"type":"case","passage":"A widely reported finding says orchestra conductors live longer than people in other jobs. A critic notes that people only become conductors once they are already quite old.","prompt":"Which GAGES variable is the critic pointing to?","options":["Gender","Geography","Ethnicity","Age"],"answer":3,"explanation":"Age is strongly confounded with longevity: like great-grandmothers, you can only become a conductor if you have already lived a long time.","lvl":3}]},{"id":"HPS104-3.5","name":"Classify variables by measurement scale","summary":"You can classify data as nominal, ordinal, interval or ratio and state which operations are valid for each.","questions":[{"type":"sort","prompt":"Sort each variable into its measurement scale.","categories":["Nominal","Ordinal","Ratio"],"items":[{"text":"Hair colour","cat":0},{"text":"Olympic medal position","cat":1},{"text":"Reaction time in ms","cat":2},{"text":"Diagnostic category","cat":0},{"text":"Academic grade (HD, D, C, P, F)","cat":1},{"text":"Number of correct answers","cat":2}],"explanation":"Nominal: unordered categories. Ordinal: ordered with unequal intervals. Ratio: equal intervals and a true zero."},{"type":"mc","prompt":"Why can't we say an IQ of 120 is 'twice as intelligent' as an IQ of 60?","options":["IQ is an interval scale with no true zero","IQ is ordinal","IQ is nominal","IQ is a ratio scale"],"answer":0,"explanation":"Interval scales have equal intervals but no true zero, so ratios are not meaningful. Zero IQ does not mean zero intelligence.","lvl":2},{"type":"order","prompt":"Put the measurement scales in order from least to most informative.","items":["Nominal","Ordinal","Interval","Ratio"],"explanation":"Each level adds a property: order (ordinal), equal intervals (interval), then a true zero (ratio)."},{"type":"case","passage":"An athlete wins one gold and one bronze medal. A commentator says her average result is a silver.","prompt":"Why is this reasoning flawed?","options":["Medals are interval data without a true zero","Medals are continuous","Medal positions are ordinal, so intervals are not equal and a mean is not meaningful","Medals are ratio data"],"answer":2,"explanation":"Ordinal data can be ranked, but the gap between gold and silver is not necessarily the same as between silver and bronze.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Temperature in Celsius is a ratio scale because it has equal intervals.","wrong":"ratio","correct":"interval","explanation":"Celsius has equal intervals but 0 degrees is an arbitrary point, not an absence of temperature, so it is interval."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Likert scales are technically ___ data, although many researchers treat them as interval.","answers":["ordinal"],"explanation":"The intervals between Likert response options are not guaranteed to be equal, so they are technically ordinal: 'scale meaning trumps numerical anchors'.","lvl":2}]}]},{"week":4,"topic":"Experimental Research","summary":"True experiments, control groups and blinding, quasi and natural experiments, the limits of experiments, realism, and reliability.","skills":[{"id":"HPS104-4.1","name":"Explain how true experiments control confounds","summary":"You can explain random assignment, keeping everything else constant, control group types, blinding and why matching falls short.","questions":[{"type":"mc","prompt":"Why is random assignment preferred over matching groups on age and gender?","options":["Random assignment guarantees identical groups with any sample size","Matching can only equate a few known variables, while random assignment balances known and unknown variables","Matching is illegal in clinical trials","Matching removes the need for a control group"],"answer":1,"explanation":"You can only match on a few variables you have thought of. Random assignment distributes all person variables, including unmeasured ones, across conditions.","lvl":2},{"type":"case","passage":"In a trial, the treatment group receives daily phone calls from researchers, while the control group receives monthly calls. The treatment group improves more.","prompt":"What kind of confound is this?","options":["Third variable confound","Person confound","Procedural confound","Reverse causality"],"answer":2,"explanation":"The groups were treated differently in ways unrelated to the treatment, so 'everything else' was not kept constant.","lvl":3},{"type":"match","prompt":"Match each control group type to its description.","pairs":[["No-treatment control","Receives nothing, so expectations differ between groups"],["Placebo control","Receives an identical-seeming but inactive version of the treatment"],["Active control","Receives the existing standard treatment"]],"explanation":"Placebo controls equalise expectations, and active controls ask whether a new treatment beats what already exists."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When neither the participant nor the experimenter administering the treatment knows the condition, the study is ___.","answers":["double blinded","double-blinded","double blind","double-blind"],"explanation":"Double blinding prevents both expectancy effects in participants and experimenter bias.","lvl":2},{"type":"case","passage":"A researcher lets participants choose whether to receive a COVID vaccine. People with weddings and parties coming up choose the vaccine, while people staying home do not.","prompt":"What is the main problem with this design?","options":["The vaccine is a placebo","Everything else is kept constant","There is too much blinding","Selection creates a person confound because the groups differ in exposure risk"],"answer":3,"explanation":"Self-selection means groups differ systematically before the study begins. Random assignment prevents this.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Random assignment works best with small samples, such as four people per group.","wrong":"small","correct":"large","explanation":"With four per group you may by chance put all the healthy people in one group. With hundreds per group, systematic biases are very unlikely."}]},{"id":"HPS104-4.2","name":"Classify a study as true, quasi or natural experiment","summary":"You can read a study description and decide if it is a true experiment, person-by-treatment quasi-experiment, natural experiment or observational study.","questions":[{"type":"case","passage":"Twenty volunteers (10 men, 10 women) are randomly assigned to a resilience workshop or a resilience brochure. Hardiness is measured before and after, and the researcher compares how men and women respond.","prompt":"What is the design?","options":["Person-by-treatment quasi-experiment","Observational study","Natural experiment","True experiment"],"answer":0,"explanation":"The treatment is randomly assigned, but gender is a measured person variable, so at least one IV is not manipulated.","lvl":4},{"type":"case","passage":"Caregivers are randomly handed a baby dressed in either blue or pink, and their behaviour toward the baby is rated. The baby's actual sex is hidden and not analysed.","prompt":"What is the design?","options":["Person-by-treatment quasi-experiment","True experiment","Natural experiment","Pseudo-experiment"],"answer":1,"explanation":"The only IV (outfit colour) is randomly assigned and everything else is held constant, so it is a true experiment.","lvl":4},{"type":"case","passage":"A researcher uses hospital records to count admissions for depression in the month before and after an earthquake, comparing a city that was hit with a similar city on the same fault line that was not.","prompt":"What is the design?","options":["Cross-sectional survey","True experiment","Natural experiment","Person-by-treatment quasi-experiment"],"answer":2,"explanation":"Nature created the conditions, there was no researcher manipulation, and a comparable city serves as the comparison group.","lvl":3},{"type":"sort","prompt":"Sort each study into its design.","categories":["True experiment","Quasi-experiment","Natural experiment"],"items":[{"text":"Random assignment to vaccine or placebo only","cat":0},{"text":"Random assignment to vaccine or placebo, analysed by age group","cat":1},{"text":"Firefighters' weight before and after a compulsory boot camp policy, compared with police","cat":2},{"text":"Life insurance records before and after a major fire, compared with an adjacent state","cat":2},{"text":"Random assignment to boot camp or control, then compared by gender","cat":1}],"explanation":"True: all IVs randomly assigned. Quasi: at least one person variable. Natural: an external event creates the groups."},{"type":"mc","prompt":"A boot camp study finds weight loss overall, but splitting by gender shows it worked for men and not women. What has the quasi-experimental design revealed?","options":["A procedural confound","A placebo effect","An interaction effect","Regression to the mean"],"answer":2,"explanation":"An interaction effect occurs when the effect of one IV (treatment) depends on the level of another (gender). A true experiment alone would not reveal it.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A natural experiment comparing quake victims in a country town to residents of metropolitan Sydney has a highly meaningful comparison group.","wrong":"meaningful","correct":"flawed","explanation":"The groups differ on many demographic and cultural factors. The comparison should be a similar nearby town at equal risk that was not hit."}]},{"id":"HPS104-4.3","name":"Evaluate the limits of experiments and ways to add realism","summary":"You can explain feasibility, ethical and external validity limits of experiments, and distinguish mundane from psychological realism.","questions":[{"type":"case","passage":"A researcher wants to know whether age affects voting behaviour and plans to randomly assign participants to be young or old.","prompt":"What limitation of experiments does this illustrate?","options":["Feasibility: person variables cannot be manipulated","Double blinding","Mundane realism","Ethics"],"answer":0,"explanation":"Person variables such as age, gender and personality are intrinsic to participants and cannot be assigned.","lvl":2},{"type":"match","prompt":"Match each term to its description.","pairs":[["Mundane realism","The setting physically resembles the real world"],["Psychological realism","The study feels real and engaging to participants"],["Pseudo-experiment","Exposes people to a variable with no control group"]],"explanation":"Mundane realism is about physical similarity (e.g. running studies in real classrooms); psychological realism is about genuine emotional engagement, like playing Monopoly. A pseudo-experiment lacks the control group that experiments need."},{"type":"case","passage":"A study is run in a plain laboratory cubicle, but participants believe their performance will be shared with peers and report feeling genuinely nervous and invested.","prompt":"Which kind of realism does this study achieve?","options":["Neither","Ecological sampling","Mundane realism","Psychological (experimental) realism"],"answer":3,"explanation":"Although the setting is artificial, participants are psychologically engaged, which is experimental or psychological realism.","lvl":4},{"type":"mc","prompt":"Why might forcing participants to smoke fail to tell us about the effects of normal smoking?","options":["It improves internal validity too much","It requires a placebo cigarette","Forced smoking causes anger and resentment, changing the psychological meaning of the variable","Smoking cannot be measured"],"answer":2,"explanation":"Making people do something they don't want to do creates a different psychological situation from chosen smoking, as well as raising ethical problems.","lvl":3},{"type":"type_answer","prompt":"What term describes a study that exposes people to a variable without any control group, leaving it open to maturation and regression effects?","answers":["pseudo-experiment","pseudo experiment","pseudoexperiment"],"explanation":"Without a meaningful control group, a pseudo-experiment is susceptible to regression toward the mean, maturation, history and testing effects.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Ethics committees may require a trial to continue if the treatment is clearly working, so the control group keeps missing out.","wrong":"continue","correct":"stop","explanation":"Continuing to withhold a clearly beneficial treatment is ethically indefensible, so trials may be stopped early even at a cost to statistical power."}]},{"id":"HPS104-4.4","name":"Distinguish types of reliability and link them to validity","summary":"You can identify test-retest, internal consistency and interrater reliability, and explain that reliability is necessary but not sufficient for validity.","questions":[{"type":"match","prompt":"Match each reliability type to its usual statistic or method.","pairs":[["Internal consistency","Cronbach's alpha"],["Interrater reliability (categorical)","Cohen's kappa"],["Test-retest reliability","Correlation between two time points"]],"explanation":"Each type of reliability has a typical index: alpha for item agreement, kappa for rater agreement, and r for stability over time."},{"type":"case","passage":"A researcher gives a self-esteem scale to 200 students and gives the same scale to the same students three weeks later. Scores at both times correlate strongly.","prompt":"Which type of reliability has been demonstrated?","options":["Interrater reliability","Construct validity","Internal consistency","Test-retest reliability"],"answer":3,"explanation":"Assessing the same people on the same measure at two time points (typically two to four weeks apart) tests temporal consistency.","lvl":1},{"type":"case","passage":"Classifying people as 'partiers' based on whether they wear belts or suspenders gives the same answer day after day.","prompt":"What does this example show?","options":["Reliability and validity are the same thing","A reliable measure need not be valid","A valid measure need not be reliable","The measure has high construct validity"],"answer":1,"explanation":"The measure is consistent but has no validity for social behaviour. Reliability is necessary for validity but not sufficient.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Judges rating diving performances should discuss their ratings during the actual coding to improve interrater reliability.","wrong":"during","correct":"before","explanation":"Discussion is fine during training, but during actual coding it inflates apparent reliability without increasing validity. Judges must rate independently."},{"type":"mc","prompt":"According to the 'more is better' rule (the LeBron James analogy), why do more items improve reliability?","options":["Each item is perfectly reliable","More items guarantee a ratio scale","More items reduce the need for validity","Idiosyncratic noise in individual items tends to cancel out across many items"],"answer":3,"explanation":"Just as luck is unlikely to hold over a 20-basket game, random noise in single items averages out over many observations.","lvl":2},{"type":"case","passage":"On Test X (proud, confident, capable, secure, competent), people who score high on one item score high on all the others. On Test Z (proud, happy, lucky, strong, funny), item scores do not line up.","prompt":"Which conclusion is correct?","options":["Both have equal test-retest reliability","Test X has low construct validity","Test X has higher internal consistency","Test Z has higher internal consistency"],"answer":2,"explanation":"Test X's items hang together as measures of self-esteem, giving high internal consistency and a wider, more useful score range.","lvl":3}]}]},{"week":5,"topic":"Observational Research","summary":"Cross-sectional, longitudinal and case-control designs, sampling, mediators and moderators, and threats from people differing, changing and reacting to being studied.","skills":[{"id":"HPS104-5.1","name":"Classify observational designs by their use of time","summary":"You can tell cross-sectional differential, cross-sectional correlational, longitudinal and case-control designs apart and match them to research questions.","questions":[{"type":"case","passage":"Researchers select patients who already have lung cancer and matched controls without it, then compare the two groups' smoking histories.","prompt":"What is the design?","options":["Case-control","Cross-sectional differential","Cross-sectional correlational","Longitudinal"],"answer":0,"explanation":"Case-control designs are retrospective: they start with the outcome (cases) and look back at prior exposure, like a detective working back from the crime.","lvl":2},{"type":"match","prompt":"Match each research question to the appropriate design.","pairs":[["Is impulsivity level related to gambling frequency?","Cross-sectional correlational"],["Do high- and low-impulsivity groups differ in gambling problems?","Cross-sectional differential"],["Does impulsivity predict the development of gambling problems over time?","Longitudinal"],["Are problem gamblers more likely than matched controls to have been impulsive?","Case-control"]],"explanation":"Correlational uses continuous variables, differential forms groups, longitudinal tracks forward, and case-control starts with the outcome."},{"type":"sort","prompt":"Sort each design by the direction of time.","categories":["Past (retrospective)","Now (snapshot)","Future (prospective)"],"items":[{"text":"Case-control","cat":0},{"text":"Cross-sectional differential","cat":1},{"text":"Cross-sectional correlational","cat":1},{"text":"Longitudinal","cat":2}],"explanation":"Case-control looks back, cross-sectional takes a single snapshot, and longitudinal tracks the same cohort forward."},{"type":"mc","prompt":"Which observational design is best placed to establish temporal ordering?","options":["Cross-sectional differential","Case-control","Cross-sectional correlational","Longitudinal"],"answer":3,"explanation":"Tracking the same cohort over time allows the IV to be measured before the DV emerges, a key criterion for causality.","lvl":1},{"type":"case","passage":"A researcher tracks the same soldiers before and after deployment. Over time, several of the most distressed participants stop responding to follow-up surveys.","prompt":"Which weakness of this design does this illustrate?","options":["Cohort effects from a snapshot","Retrospective recall bias","Selective attrition","Artificial cutoffs"],"answer":2,"explanation":"Longitudinal designs are vulnerable to selective attrition, where sicker participants drop out, as well as being costly and slow.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Case-control designs are especially efficient for studying common conditions.","wrong":"common","correct":"rare","explanation":"Because they start with people who already have the outcome, case-control designs are highly efficient for rare conditions."}]},{"id":"HPS104-5.2","name":"Evaluate sampling methods and sampling biases","summary":"You can identify convenience, simple random, cluster and stratified sampling and explain selection and nonresponse bias.","questions":[{"type":"case","passage":"A researcher divides the population by SES. Since 10% of the population is high SES, she randomly selects participants so that 10% of her sample is high SES, and does the same for other SES levels.","prompt":"Which sampling method is this?","options":["Stratified sampling","Simple random sampling","Cluster sampling","Convenience sampling"],"answer":0,"explanation":"Stratified sampling divides the population into strata and draws proportional random samples from each.","lvl":2},{"type":"case","passage":"A national study randomly selects 40 schools, then surveys every student within each chosen school.","prompt":"Which sampling method is this?","options":["Convenience sampling","Snowball sampling","Cluster sampling","Stratified sampling"],"answer":2,"explanation":"In cluster sampling, clusters (schools, hospitals) are randomly selected and then sampled intensively.","lvl":2},{"type":"mc","prompt":"The 1936 Literary Digest poll received 2.4 million responses but wrongly predicted Roosevelt would lose. What is the main lesson?","options":["Larger samples are always more accurate","Response rates do not matter","Phone directories are representative","Sample size cannot compensate for sample bias"],"answer":3,"explanation":"Sampling from phone directories and car registrations in the Depression era favoured wealthy voters. Gallup's much smaller random sample predicted correctly.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When the people who return a survey differ systematically from those who don't, the result is ___ bias.","answers":["nonresponse","non-response"],"explanation":"Only 24% of the Literary Digest postcards came back, and responders were likely more politically engaged, worsening the selection bias.","lvl":2},{"type":"order","prompt":"Put these sampling methods in order from lowest to highest representativeness.","items":["Convenience","Cluster","Stratified"],"explanation":"Convenience samples are weakest, cluster samples are moderate, and stratified samples are high because subgroups are represented proportionally."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Selection bias mainly threatens internal validity, so an experiment with college students cannot establish causality.","wrong":"internal","correct":"external","explanation":"Selection bias limits generalisation. A well-run experiment with college students can still have strong internal validity."}]},{"id":"HPS104-5.3","name":"Distinguish mediators from moderators","summary":"You can decide whether a third variable explains how an effect occurs (mediator) or changes it for some people (moderator), and explain covariance control.","questions":[{"type":"case","passage":"Stress leads people to ruminate more, and rumination in turn leads to depression.","prompt":"What role does rumination play?","options":["Mediator","Moderator","Artefact","Confound"],"answer":0,"explanation":"A mediator is part of the causal chain: caused by the IV and in turn causing the DV. It answers 'why' or 'how'.","lvl":2},{"type":"case","passage":"Stress leads to more rumination, but only among people who are socially isolated. For well-connected people, stress barely affects rumination.","prompt":"What role does social isolation play?","options":["Operational confound","Dependent variable","Mediator","Moderator"],"answer":3,"explanation":"A moderator changes the strength or direction of an IV to DV relationship without being part of the causal chain. It answers 'for whom' or 'under what conditions'.","lvl":3},{"type":"match","prompt":"Match each concept to the question it answers.","pairs":[["Mediator","Why or how does the effect occur?"],["Moderator","For whom or under what conditions?"],["Direct relationship","The IV influences the DV with no intermediary"]],"explanation":"Mediators explain the mechanism; moderators specify when the effect holds."},{"type":"sort","prompt":"Sort each variable by its likely role.","categories":["Mediator","Moderator"],"items":[{"text":"Accepting worse gambling odds, linking impulsivity to problem gambling","cat":0},{"text":"A protective factor that weakens the stress to depression link","cat":1},{"text":"Rumination between stress and depression","cat":0},{"text":"A vulnerability factor that strengthens the effect of stress","cat":1}],"explanation":"Vulnerability and protective factors typically act as moderators, whereas mediators transmit the effect."},{"type":"mc","prompt":"A researcher measures SES and statistically removes its influence to see whether impulsivity still predicts gambling. What is the main limitation?","options":["It can only control confounds that are known and measured","It only works in true experiments","It turns the study into a case-control design","It increases reverse causality"],"answer":0,"explanation":"Covariance control removes variance linked to a measured confound, but unmeasured confounds remain a permanent threat.","lvl":3},{"type":"case","passage":"A researcher splits a continuous impulsivity score at the median into 'high' and 'low' groups, so people scoring just above and just below the cutoff are treated as very different.","prompt":"What problem does this create?","options":["A history effect","Regression to the mean","An artificial boundaries problem that loses information and power","A mediation effect"],"answer":2,"explanation":"Arbitrary cutoffs (like BMI 18.5 vs 19) treat nearly identical people as different, reduce statistical power, and act as an operational confound.","lvl":3}]},{"id":"HPS104-5.4","name":"Identify threats arising when people change over time","summary":"You can recognise history, maturation, regression toward the mean, testing effects and the mere measurement effect in pretest-posttest studies.","questions":[{"type":"case","passage":"Adolescent ballet dancers complete a 12-week mental imagery program alongside their normal classes. Their dance quality improves, and the program is declared a success. There was no control group.","prompt":"Which threat most plausibly explains the improvement?","options":["Maturation","Nonresponse bias","History","Mere measurement effect"],"answer":0,"explanation":"Adolescents naturally improve with 12 weeks of classes and physical development. Without a control group, this cannot be separated from the imagery training.","lvl":3},{"type":"case","passage":"Flight trainers noticed that pilots who were criticised after a very poor landing usually did better next time, while pilots praised after an excellent landing usually did worse.","prompt":"What best explains this pattern?","options":["Participant reactance","Testing effects","Regression toward the mean","Punishment is more effective than praise"],"answer":2,"explanation":"Extreme performances include unusual luck, so they tend to be followed by more average ones, regardless of praise or punishment.","lvl":3},{"type":"match","prompt":"Match each threat to its example.","pairs":[["History","Attitudes to war shifting after September 11, 2001"],["Mere measurement effect","Asking about intention to buy a car raises car purchases"],["Testing effects","Scoring higher on an alternate form of a test the second time"],["Short-term maturation","A headache resolving on its own after a pain reliever"]],"explanation":"History is broad societal change, the mere measurement effect is change caused by asking, testing effects come from prior exposure to the test, and maturation is natural change within the person."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"An observed score reflects both a person's stable ___ score and random error.","answers":["true"],"explanation":"Because extreme observed scores include unusual luck, they drift back toward the true score on retesting.","lvl":2},{"type":"mc","prompt":"What is the best protection against regression toward the mean in a therapy study?","options":["Removing the posttest","Using a longer questionnaire","Recruiting only people at their worst","A randomly assigned control group, since both groups should regress equally"],"answer":3,"explanation":"If the treatment group improves significantly more than a randomised control group, regression cannot explain the difference.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Testing effects are primarily a threat to external validity in pretest-posttest designs with no control group.","wrong":"external","correct":"internal","explanation":"Improvement from having taken the test before can masquerade as a treatment effect, which threatens internal validity. The mere measurement effect is the one described as mainly an external validity threat."}]},{"id":"HPS104-5.5","name":"Distinguish confounds from artifacts and reduce reaction biases","summary":"You can classify threats as confounds or artifacts, identify experimenter bias and participant reaction biases, and choose solutions.","questions":[{"type":"sort","prompt":"Sort each threat into the right category.","categories":["Confound (internal validity)","Artifact (external validity)"],"items":[{"text":"Heterogeneous attrition","cat":0},{"text":"Homogeneous attrition","cat":1},{"text":"Experimenter bias","cat":0},{"text":"Nonresponse bias","cat":1},{"text":"Maturation in a no-control pretest-posttest study","cat":0},{"text":"Selection bias","cat":1}],"explanation":"A confound should have been held constant but varied with the IV. An artifact should have been varied but was held constant."},{"type":"case","passage":"Experimenters were told some rats were 'maze-bright' and others 'maze-dull', although the rats were identical. The 'bright' rats performed better, partly because experimenters handled them more gently and made coding errors in their favour.","prompt":"Which threat does this study (Rosenthal and Fode, 1963) demonstrate?","options":["Experimenter bias","Demand characteristics","Participant reactance","Evaluation apprehension"],"answer":0,"explanation":"Experimenters' expectations shaped both their observations and their treatment of the rats, without conscious dishonesty.","lvl":2},{"type":"match","prompt":"Match each solution to the bias it mainly addresses.","pairs":[["Implicit Association Test","Faking responses on attitude measures"],["Double-blind procedure","Experimenter bias"],["Guaranteed anonymity","Social desirability from evaluation apprehension"],["Cover story given to all groups","Participant expectancies"]],"explanation":"Different techniques target different reaction biases: making responses hard to fake, hiding conditions, protecting identity, or equalising expectations."},{"type":"case","passage":"In a study with a very boring control condition, many more people drop out of the control group than the experimental group. The few who stay in the control group are unusually persistent.","prompt":"Which validity is threatened?","options":["Internal validity only","External validity only","Neither, because random assignment was used","Both internal and external validity"],"answer":3,"explanation":"Heterogeneous attrition makes the groups non-equivalent, erasing the benefits of random assignment and limiting generalisation.","lvl":4},{"type":"analogy","prompt":"Participant expectancies are to behaving as the experimenter expects as participant reactance is to ___","options":["reporting honestly","worrying about being judged","dropping out of the study","behaving against what the experimenter expects"],"answer":3,"explanation":"Reactance is the opposite of demand characteristics: participants resist the expected behaviour to assert autonomy.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"An artifact is a variable that should have been held constant but was accidentally allowed to vary.","wrong":"artifact","correct":"confound","explanation":"That is a confound. An artifact is the reverse: something that should have been varied but was held constant."}]}]},{"week":6,"topic":"Factorial Designs","summary":"One-way and factorial designs, cell and marginal means, main effects and interactions, within-subjects threats and counterbalancing, and writing good self-report measures.","skills":[{"id":"HPS104-6.1","name":"Calculate conditions, cell means and marginal means","summary":"You can count the conditions in a factorial design and calculate marginal means correctly from a table of cell means.","questions":[{"type":"mc","prompt":"A study crosses dosage (5 levels) with age group (3 levels). How many conditions are there?","options":["5","30","8","15"],"answer":3,"explanation":"Number of conditions = levels of IV1 x levels of IV2, so 5 x 3 = 15.","lvl":1},{"type":"case","passage":"Cell means for a 2x2 design: Young Women = 7, Old Women = 11, Young Men = 7, Old Men = 7.","prompt":"What is the marginal mean for Women?","options":["9","7","8","11"],"answer":0,"explanation":"Average across all levels of age for women: (7 + 11) / 2 = 9.","lvl":2},{"type":"case","passage":"Cell means for a 3x3 design. A1: 1, 2, 3. A2: 1, 2, 3. A3: 3, 3, 3 (for B1, B2, B3 respectively).","prompt":"What is the marginal mean for B1?","options":["3","1","2","1.67"],"answer":3,"explanation":"Average B1 across all levels of A: (1 + 1 + 3) / 3 = 1.67.","lvl":3},{"type":"match","prompt":"Match each term to its definition.","pairs":[["Level","One discrete value of an IV"],["Condition","A specific combination of levels across all IVs"],["Cell mean","The average DV score for one condition"],["Marginal mean","The average for one level of one IV, ignoring the other IVs"]],"explanation":"These building blocks are needed before main effects and interactions can be judged."},{"type":"type_answer","prompt":"In a three-way design of Gender (2) x Age (2) x Nationality (2), how many conditions are there? Give a number.","answers":["8","eight"],"explanation":"2 x 2 x 2 = 8 conditions.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Marginal means are used to test interaction effects.","wrong":"interaction","correct":"main","explanation":"Marginal means test main effects. Interactions must be judged from the pattern of cell means (simple main effects)."}]},{"id":"HPS104-6.2","name":"Identify main effects and interactions from cell means","summary":"You can decide from a table or graph whether there are main effects and an interaction, and describe the simple main effects.","questions":[{"type":"case","passage":"Cell means for a 3x3 design. A1: 10, 5, 0. A2: 5, 5, 5. A3: 0, 5, 10 (for B1, B2, B3). All row and column marginal means equal 5.","prompt":"What does this pattern show?","options":["Both main effects and an interaction","Main effect of A only","No main effects, but a strong interaction","No main effects and no interaction"],"answer":2,"explanation":"The effect of B runs in opposite directions for A1 and A3, cancelling out in the marginals. An interaction can exist with no main effects at all.","lvl":4},{"type":"case","passage":"Cell means for a 3x3 design. A1: 1, 2, 3. A2: 2, 3, 4. A3: 3, 4, 5 (for B1, B2, B3).","prompt":"What does this pattern show?","options":["Both main effects, no interaction","Interaction only","Main effect of B only","Main effect of A and an interaction"],"answer":0,"explanation":"Row marginals (2, 3, 4) and column marginals (2, 3, 4) both differ, but every row rises by exactly 1 across B, so the lines are parallel.","lvl":3},{"type":"sort","prompt":"Sort each graph pattern by whether it indicates an interaction.","categories":["Interaction","No interaction"],"items":[{"text":"Lines converging","cat":0},{"text":"Lines perfectly parallel","cat":1},{"text":"Lines crossing","cat":0},{"text":"Lines diverging","cat":0},{"text":"Lines look roughly parallel but simple main effects differ","cat":0}],"explanation":"Any non-parallel pattern is an interaction, and the formal test (whether simple main effects differ) overrides the visual impression."},{"type":"case","passage":"Young Women = 7, Old Women = 11, Young Men = 7, Old Men = 7.","prompt":"Which statement correctly describes the simple main effects of age?","options":["There is no main effect of age","Age has the same effect for women and men","Age increases scores for women but has no effect for men","Age decreases scores for women"],"answer":2,"explanation":"Age matters for women (7 to 11) but not men (7 to 7). Because the simple main effects differ, there is a Gender x Age interaction.","lvl":3},{"type":"order","prompt":"Put the steps for analysing a factorial table in order.","items":["Calculate all row and column marginal means","Compare marginal means to decide main effects","Examine the cell means for an interaction pattern","Describe the simple main effects"],"explanation":"Marginal means give main effects, cell means reveal interactions, and simple main effects explain what an interaction means."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Lines on a graph must physically cross to show an interaction.","wrong":"must","correct":"need not","explanation":"Converging or diverging lines also show an interaction. The lines only need to be non-parallel."}]},{"id":"HPS104-6.3","name":"Distinguish between, within and mixed designs and their threats","summary":"You can classify IVs as between- or within-subjects, identify mixed designs, and recognise sequence and carryover effects.","questions":[{"type":"case","passage":"Men and women each complete an easy, a medium and a hard version of a puzzle task, and their accuracy is recorded.","prompt":"What type of design is this?","options":["Mixed-model design","Fully between-subjects","Fully within-subjects","One-way design"],"answer":0,"explanation":"Gender is a person variable and must be between-subjects, while difficulty is within-subjects, so the design is mixed.","lvl":3},{"type":"match","prompt":"Match each carryover effect to its example.","pairs":[["Order effect","Rating life satisfaction after first being asked about income"],["Practice effect","Getting faster at a cognitive task through repetition"],["Interference effect","Saying 'stop' at a green light after answering 'opposite of bottom'"]],"explanation":"Carryover effects are specific contamination from earlier conditions: ordering, learning, or disruption."},{"type":"sort","prompt":"Sort each IV by whether it must be between-subjects or can be within-subjects.","categories":["Must be between-subjects","Can be within-subjects"],"items":[{"text":"Diagnosis","cat":0},{"text":"Task difficulty","cat":1},{"text":"Nationality","cat":0},{"text":"Stimulus set","cat":1},{"text":"Gender","cat":0},{"text":"Time point","cat":1}],"explanation":"Person variables cannot be experienced by the same person at multiple levels, while task features can."},{"type":"mc","prompt":"What is the key threat specific to within-subjects designs?","options":["Needing many more participants","Person confounds between groups","Sequence and carryover effects","Inability to use random assignment"],"answer":2,"explanation":"Because each person does every condition, fatigue, boredom, practice and interference from earlier conditions can bias later ones.","lvl":2},{"type":"analogy","prompt":"Between-subjects design is to person confounds as within-subjects design is to ___","options":["regression to the mean","sequence and carryover effects","selection bias","artefacts"],"answer":1,"explanation":"Between-subjects designs risk person differences between groups; within-subjects designs remove these but introduce order-based threats.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A ___ interaction occurs when the two-way interaction between two variables differs across levels of a third variable.","answers":["three-way","three way","3-way"],"explanation":"In a Gender x Age x Nationality design, if the Gender x Nationality pattern differs by age, there is a three-way interaction.","lvl":3}]},{"id":"HPS104-6.4","name":"Select a counterbalancing method for a within-subjects design","summary":"You can calculate orders for complete counterbalancing and choose between reverse, partial and Latin square approaches.","questions":[{"type":"mc","prompt":"How many orders are needed for complete counterbalancing of 4 conditions?","options":["8","4","24","16"],"answer":2,"explanation":"Complete counterbalancing requires n! orders: 4 x 3 x 2 x 1 = 24.","lvl":3},{"type":"case","passage":"A researcher has three conditions (A, B, C) and presents half the participants with ABC and half with CBA.","prompt":"Which counterbalancing method is this?","options":["Latin square","Partial counterbalancing","Reverse counterbalancing","Complete counterbalancing"],"answer":2,"explanation":"Reverse counterbalancing uses only the original and reversed sequences. It controls average serial position but not all order effects.","lvl":3},{"type":"case","passage":"Four participants receive conditions in these orders: ABCD, BADC, CDAB, DCBA.","prompt":"Which method is being used?","options":["Reverse counterbalancing","Complete counterbalancing","Latin square","Randomised block"],"answer":2,"explanation":"Each condition appears in each serial position exactly once across participants, the defining feature of a Latin square.","lvl":3},{"type":"match","prompt":"Match each method to its description.","pairs":[["Complete counterbalancing","Every possible order is used"],["Partial counterbalancing","A random subset of all possible orders is used"],["Latin square","Each condition appears once in each position and equally often before and after each other"]],"explanation":"The methods trade off full control of order effects against practicality."},{"type":"type_answer","prompt":"How many orders does complete counterbalancing require for 3 conditions? Give a number.","answers":["6","six"],"explanation":"3! = 3 x 2 x 1 = 6 orders: ABC, ACB, BAC, BCA, CAB, CBA.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Complete counterbalancing is practical for studies with more than four conditions.","wrong":"practical","correct":"impractical","explanation":"Orders grow factorially (5 conditions needs 120), so complete counterbalancing becomes impractical beyond about four conditions."}]},{"id":"HPS104-6.5","name":"Apply rules for writing self-report items and scales","summary":"You can spot flawed survey questions, choose anchors and scale formats, and explain reverse coding and scale development.","questions":[{"type":"case","passage":"A survey item reads: 'I am a lovable and capable person.' Participants respond on a 0 to 6 scale.","prompt":"What is the main problem with this item?","options":["It is double-barreled","It is a loaded question","It has too many scale points","It uses a negation"],"answer":0,"explanation":"It asks two things with one response. Someone might feel lovable but not capable, so it should be split into two items.","lvl":2},{"type":"match","prompt":"Match each flawed item to its problem.","pairs":[["How much do you trust the police who protect and serve our city?","Loaded question"],["Are puppies cute?","No variance (ceiling effect)"],["I am not without friends.","Negation"],["Do you prefer apples or oranges?","Forced choice"]],"explanation":"Good items are neutral, produce variance, avoid negations and let people rate each option separately."},{"type":"mc","prompt":"Why do scales like the Rosenberg include negatively worded items that are reverse-coded?","options":["To create a ceiling effect","To make it a Guttman scale","To control for yea-saying and nay-saying response biases","To make the scale shorter"],"answer":2,"explanation":"Acquiescence inflates positive and negative items alike, so once negative items are reverse-coded the inflation cancels out.","lvl":2},{"type":"sort","prompt":"Sort each construct by the scale type that best fits it.","categories":["Unipolar","Bipolar"],"items":[{"text":"How much do you like this song? (none to extreme)","cat":0},{"text":"Satisfaction from extremely dissatisfied to extremely satisfied","cat":1},{"text":"How often do you feel tired? (never to always)","cat":0},{"text":"Attitude from strongly negative to strongly positive, neutral in the middle","cat":1}],"explanation":"Unipolar scales run from none to maximum; bipolar scales have a meaningful neutral midpoint with opposite poles."},{"type":"order","prompt":"Put the steps of developing a new multi-item scale in order.","items":["Define exactly what you want to measure and review existing scales","Write a large item pool (for example 40 to 50 items)","Administer to a large sample and use factor analysis and reliability checks","Select the best items"],"explanation":"Scale development moves from careful definition, to generating many items, to empirical analysis and selection, often cycling back."},{"type":"case","passage":"A researcher builds an attitude scale in which items increase in extremity. Anyone who agrees with a strong item is assumed to also agree with all the milder items before it, and people are scored by the highest item they endorse.","prompt":"What type of scale is this?","options":["Thurstone scale","Guttman scale","Semantic differential","EGWA scale"],"answer":1,"explanation":"Guttman scales are hierarchical: endorsing a strong item implies endorsing all less extreme ones, and scoring identifies the threshold.","lvl":4}]}]},{"week":7,"topic":"Qualitative Research","summary":"How qualitative research differs from quantitative, its philosophical roots, the medical and social models, qualitative approaches and methods, and thematic analysis.","skills":[{"id":"HPS104-7.1","name":"Distinguish quantitative from qualitative research questions","summary":"You can tell nomothetic from idiographic aims and decide whether a research question calls for a qualitative or quantitative approach.","questions":[{"type":"sort","prompt":"Sort each research question by the approach it best suits.","categories":["Quantitative","Qualitative"],"items":[{"text":"How strongly does sleep loss predict exam scores?","cat":0},{"text":"What is it like to return to work after the loss of a child?","cat":1},{"text":"How often do teenagers check their phones in class?","cat":0},{"text":"How do refugees perceive the Australian medical system?","cat":1},{"text":"Does CBT reduce depression scores more than a waitlist?","cat":0},{"text":"What matters most to carers of people with dementia?","cat":1}],"explanation":"'How much, how many, how often, how strong' signals quantitative. 'Why, how, what is it like, what does it mean' signals qualitative."},{"type":"match","prompt":"Match each term to its meaning.","pairs":[["Nomothetic","Seeking general laws true for most people"],["Idiographic","Focusing on the specific and individual"],["Theory-driven","Testing hypotheses derived from theory"],["Question-driven","Starting with a topic and letting participants reveal what matters"]],"explanation":"Quantitative research is nomothetic and theory-driven; qualitative research is idiographic and question-driven."},{"type":"mc","prompt":"Which feature is characteristic of qualitative rather than quantitative research?","options":["Constructs are operationalised and measured","Variables are manipulated and confounds controlled","Data are expressed as probabilities","Complexity is explored in natural settings"],"answer":3,"explanation":"Qualitative research explores complexity with little or no manipulation, while quantitative research reduces complexity through control.","lvl":2},{"type":"analogy","prompt":"Quantitative is to nomothetic as qualitative is to ___","options":["hypothetico-deductive","experimental","positivist","idiographic"],"answer":3,"explanation":"Nomothetic (think 'norm') seeks general laws; idiographic (think 'idiosyncratic') focuses on the specific.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A key strength of qualitative research is that it provides prevalence, frequency and effect sizes.","wrong":"strength","correct":"weakness","explanation":"Not providing prevalence, frequency or effect sizes is a limitation of qualitative research, along with difficulty generalising."},{"type":"case","passage":"A researcher is interested in a new online subculture that has not been studied before. She is not sure what the key issues are and wants participants to show her what questions are worth asking.","prompt":"Which approach is most suitable and why?","options":["Qualitative, because the issue is complex and cannot be defined upfront","Quantitative, because it can test existing theory","Neither, because the topic is too new","Quantitative, because large samples are needed"],"answer":0,"explanation":"Qualitative research suits complex issues where you do not yet know the right question. Sometimes the goal is to find the question itself.","lvl":2}]},{"id":"HPS104-7.2","name":"Compare the philosophical positions and models behind research","summary":"You can distinguish positivism, post-positivism and social constructionism, and the medical model from the social model.","questions":[{"type":"match","prompt":"Match each position to its central claim.","pairs":[["Positivism","Neutral observation reveals objective, universal truths"],["Post-positivism","Reality exists but can only be known imperfectly and probabilistically"],["Social constructionism","Social reality is constructed through interaction and shared meaning"]],"explanation":"Positivism is largely rejected; post-positivism underpins modern quantitative psych; social constructionism underpins most qualitative research."},{"type":"case","passage":"A researcher studies 'beauty' by examining how it is discussed in media and conversation, and argues it has no fixed meaning outside human culture and changes across time and place.","prompt":"Which position does she hold?","options":["Determinism","Positivism","Post-positivism","Social constructionism"],"answer":3,"explanation":"Social constructionists see concepts like beauty as constructed through culture, rather than as facts to be operationalised through, say, symmetry ratings.","lvl":3},{"type":"sort","prompt":"Sort each feature into the right model.","categories":["Medical model","Social model"],"items":[{"text":"Focus on the sufferer","cat":0},{"text":"Focus on history and context","cat":1},{"text":"Diagnose and treat the individual","cat":0},{"text":"Reduce injustice and intolerance","cat":1},{"text":"Reduce symptom severity","cat":0},{"text":"Explain without pathologising or blaming","cat":1}],"explanation":"The medical model locates the problem in the individual; the social model locates it in disadvantage, stigma and context."},{"type":"case","passage":"An advocate argues that a wheelchair user is disabled mainly by missing ramps, inaccessible toilets and social exclusion, rather than by their body.","prompt":"Which model is the advocate using?","options":["Positivist model","Medical model","Deductive-nomological model","Social model"],"answer":3,"explanation":"The social model says barriers created by society produce much of the disability, so changing the environment removes much of it.","lvl":1},{"type":"mc","prompt":"Most modern quantitative psychology is best described as:","options":["Social constructionist","Post-positivist","Hermeneutic","Positivist"],"answer":1,"explanation":"Post-positivists accept researchers have biases but still pursue objective knowledge and general laws, with humility about limits.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Social constructionists treat the researcher's subjectivity as a flaw to be eliminated.","wrong":"flaw","correct":"feature","explanation":"Social constructionists accept that researchers are part of the process and see their values and perspective as a feature, not a bug."}]},{"id":"HPS104-7.3","name":"Select a qualitative approach for a research question","summary":"You can match a question to ethnography, grounded theory, discourse analysis or content analysis, including manifest and latent levels.","questions":[{"type":"case","passage":"A researcher wants to know whether news reports of sexual assault use active verbs that name the perpetrator ('the man assaulted her') or passive verbs that hide him ('she was assaulted').","prompt":"Which approach fits best?","options":["Discourse analysis","Case-control design","Ethnography","Grounded theory"],"answer":0,"explanation":"Discourse analysis studies how language is used and framed, and how that shapes beliefs about blame and power.","lvl":3},{"type":"match","prompt":"Match each approach to its purpose.","pairs":[["Ethnography","UNDERSTAND a group through immersion"],["Grounded theory","DISCOVER emergent theory when little is known"],["Discourse analysis","ANALYSE how language shapes beliefs"],["Content analysis","DOCUMENT the frequency or presence of content"]],"explanation":"The four approaches differ in why the research is done: understand, discover, analyse or document."},{"type":"case","passage":"A team counts how many films in a year include at least two named women who talk to each other about something other than a man.","prompt":"Which approach is this?","options":["Ethnography","Discourse analysis","Grounded theory","Content analysis"],"answer":3,"explanation":"The Bechdel test is a content analysis tool, focused on counting concrete features across an industry.","lvl":2},{"type":"case","passage":"During COVID, researchers wanted to understand why many workers liked working from home and refused to return, an outcome existing theory had failed to predict. They interviewed workers and built a theory from what they heard.","prompt":"Which approach is this?","options":["Theoretical thematic analysis","Discourse analysis","Content analysis","Grounded theory"],"answer":3,"explanation":"Grounded theory builds theory from the data when little is known, like the grief stages theory built from bereaved people's accounts.","lvl":3},{"type":"type_answer","prompt":"In content analysis, what is the level called that gives an interpretative account of what was meant or implied beyond the literal words?","answers":["latent","latent level"],"explanation":"The manifest level describes what was literally said; the latent level interprets what was meant.","lvl":4},{"type":"fill_gap","prompt":"Complete the sentence.","text":"A researcher who spends a year working in a hospital ward to understand its unspoken rules from the inside is doing ___.","answers":["ethnography"],"explanation":"Ethnography relies on immersion in a group to produce a 'portrait of a people'.","lvl":1}]},{"id":"HPS104-7.4","name":"Choose a qualitative data collection method","summary":"You can choose between interviews, focus groups, observation, archival data and open-ended survey questions, and weigh their trade-offs.","questions":[{"type":"case","passage":"A researcher wants to understand the workplace culture at a supermarket: shared frustrations with management, gossip and inside jokes.","prompt":"Which method is likely to be most useful?","options":["Structured interviews","Unstructured individual interviews about grief","Archival records","Focus groups"],"answer":3,"explanation":"Focus groups tend to surface social and cultural material as people play off each other, whereas interviews bring out personal, psychological experiences.","lvl":2},{"type":"order","prompt":"Put the interview types in order from most to least structured.","items":["Structured","Semi-structured","Unstructured (in-depth)"],"explanation":"Structured interviews use the same questions in the same order; semi-structured allow follow-ups; unstructured interviews start with a topic or two and let conversation flow."},{"type":"match","prompt":"Match each method to its best use.","pairs":[["Individual interview","Sensitive, personal or psychological topics"],["Observation","When self-report may not match actual behaviour"],["Archival data","Analysing large amounts of existing material without recruiting"],["Open-ended survey questions","Efficiently collecting written responses from hundreds of people"]],"explanation":"Each method suits different questions and constraints."},{"type":"mc","prompt":"Which interview type is the most common in qualitative research?","options":["Semi-structured","Unstructured","Group structured","Structured"],"answer":0,"explanation":"Semi-structured interviews cover planned topics while allowing flexible follow-up on what the participant raises.","lvl":2},{"type":"case","passage":"A researcher wants to see how Australian newspaper coverage of immigration has changed across several decades.","prompt":"Which method is most appropriate?","options":["Archival data","Observation","Structured interviews","Focus groups with journalists"],"answer":0,"explanation":"Archival data uses material that already exists, such as newspaper archives, allowing large-scale analysis without recruitment.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"A drawback of video observation is that you will miss things while writing.","wrong":"video","correct":"note-taking","explanation":"Note-taking means missing things while writing. Video captures everything but people may act differently when filmed."}]},{"id":"HPS104-7.5","name":"Apply the phases of Braun and Clarke's thematic analysis","summary":"You can order the phases, cluster codes into themes, and distinguish inductive from theoretical thematic analysis.","questions":[{"type":"order","prompt":"Put the phases of thematic analysis in order.","items":["Familiarise yourself with the data","Generate initial codes","Search for themes","Review, refine and name themes"],"explanation":"You cannot code what you do not know well, codes are then clustered into themes, and themes are finally reviewed and named, often shown in a thematic map."},{"type":"sort","prompt":"Sort each code into the theme it best fits (Harden et al., 2009).","categories":["Dislike of school","Poor material circumstances and unhappy childhood"],"items":[{"text":"Bullying","cat":0},{"text":"Family breakdown","cat":1},{"text":"Boredom","cat":0},{"text":"Poor housing","cat":1},{"text":"Lack of relevance","cat":0},{"text":"Frequent moves","cat":1}],"explanation":"In the teen pregnancy study, codes clustered into interconnected themes including dislike of school and poor material circumstances."},{"type":"match","prompt":"Match each term to its description.","pairs":[["Inductive","Bottom-up, data-driven, themes emerge"],["Theoretical","Top-down, researcher-driven, looks for specific themes"],["Thematic map","A diagram showing themes, subthemes and how they connect"]],"explanation":"Inductive analysis is richer and broader and often paired with grounded theory; theoretical analysis is more detailed and suits an existing framework. The end product is often a thematic map."},{"type":"mc","prompt":"Which statement about themes is correct?","options":["A theme is whatever appears most often","A theme is a salient pattern of meaning relevant to the research question, even if not the most frequent","A theme is a single code","A theme must be mentioned by every participant"],"answer":1,"explanation":"Salience matters more than frequency. A powerful point made by one or two people can constitute a theme.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Short tags such as {family breakdown} that label features of a transcript are called ___.","answers":["codes","code"],"explanation":"Codes are applied across the data in Phase 2 and later clustered into themes.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The international body of qualitative researchers has officially endorsed the use of AI for qualitative analysis.","wrong":"endorsed","correct":"banned","explanation":"They banned it because the researcher is meant to resonate with the data, though in practice many researchers still use AI for tasks like transcription."}]}]},{"week":8,"topic":"Ethical Research","summary":"Why ethical fading happens, four philosophical frameworks for ethics, the National Statement principles, and how consent, coercion, confidentiality and debriefing apply to research.","skills":[{"id":"HPS104-8.1","name":"Explain how ethical fading occurs through its three enablers","summary":"You can identify euphemisms, slippery-slope decisions and errors in causation in scenarios and explain how they let ethics fade.","questions":[{"type":"case","passage":"A company announcing 300 job losses describes the move in a press release as 'restructuring to realise efficiencies'.","prompt":"Which enabler of ethical fading is this?","options":["Attribution error","Slippery-slope decision making","Lie of commission","Euphemism"],"answer":3,"explanation":"Euphemisms dress up harmful behaviour in socially approved language, shifting focus away from the consequences.","lvl":2},{"type":"case","passage":"A new lab member notices that data points are sometimes quietly dropped. At first it feels wrong, but everyone does it, and each week the exclusions get slightly bigger. A year later she is excluding data she would once have found unthinkable.","prompt":"Which enabler best describes this?","options":["Slippery-slope decision making","Limited cognitive resources","Euphemism","Lie of omission"],"answer":0,"explanation":"Psychological numbing and induction mean each small step seems like the last, so the ethical baseline drifts over time.","lvl":2},{"type":"match","prompt":"Match each concept to its description.","pairs":[["Psychological numbing","Repeated exposure dulls our reaction to ethical dilemmas"],["Induction","If yesterday was fine and today is only slightly different, today is fine too"],["Lie of omission","Leaving out something important"],["Lie of commission","Saying something untrue"]],"explanation":"Numbing and induction drive slippery slopes; omission and commission are forms of the errors in causation enabler."},{"type":"case","passage":"A car salesperson does not mention that a vehicle has a faulty transmission, though the buyer never asks. Afterwards he tells himself he did not actually lie.","prompt":"What is this an example of?","options":["Virtue ethics","Lie of commission","Euphemism","Lie of omission"],"answer":3,"explanation":"Leaving out something important is a lie of omission. We tend to feel less guilty about omissions even when the effect is the same.","lvl":2},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Tenbrunsel and Messick describe ___ as the process by which the moral side of a decision fades into the background through self-deception.","answers":["ethical fading"],"explanation":"People act self-interestedly while still believing they are ethical, not because they are evil but because of normal psychological biases.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Our ethical biases are inherently egocentric, so we apply ethical rules more strictly to ourselves than to other people.","wrong":"ourselves","correct":"others","explanation":"We apply rules more strictly to others than to ourselves. That is why ethics committees do not trust researchers to evaluate their own work."}]},{"id":"HPS104-8.2","name":"Compare virtue, deontological, utilitarian and principle-based ethics","summary":"You can identify each framework from a justification, name its key thinker, and state its main strength and weakness.","questions":[{"type":"sort","prompt":"Sort each justification into its ethical framework.","categories":["Virtue","Deontological","Utilitarian"],"items":[{"text":"I behave ethically because I am a person of integrity","cat":0},{"text":"I follow the code of conduct because it is my professional duty","cat":1},{"text":"It was right because it produced the greatest good for the most people","cat":2},{"text":"Good character guides me where rules cannot","cat":0},{"text":"The role comes first, regardless of how I feel today","cat":1},{"text":"Five lives saved outweighs one lost","cat":2}],"explanation":"Virtue ethics focuses on character, deontology on duty, and utilitarianism on consequences."},{"type":"match","prompt":"Match each framework to its key thinker.","pairs":[["Virtue ethics","Aristotle"],["Deontological ethics","Kant"],["Utilitarian ethics","Bentham and Mill"],["Principle-based ethics","Ross"]],"explanation":"These thinkers are associated with each of the four frameworks described by Knapp and VandeCreek."},{"type":"mc","prompt":"What is a key weakness of virtue ethics for training psychologists?","options":["It ignores intentions","It cannot be applied to new situations","It is hard to measure good character, and we all think we are one of the good ones","It is purely based on outcomes"],"answer":2,"explanation":"Selecting people for 'good character' is biased; people tend to pick those who look and sound like them.","lvl":3},{"type":"mc","prompt":"Which weakness belongs to utilitarian ethics?","options":["It cannot be codified or taught","Outcomes are hard to predict and people hide behind good intentions","It relies entirely on character","It can become a paperwork checklist"],"answer":1,"explanation":"Utilitarianism struggles with predicting consequences, deciding whose outcomes count, and people justifying actions after the fact.","lvl":3},{"type":"case","passage":"A lecturer complains that he spends more time filling in ethics forms, ticking off each principle, than doing the research, and that the audit has become the point rather than the thinking behind it.","prompt":"Which framework's weakness is he describing?","options":["Principle-based ethics","Virtue ethics","Utilitarian ethics","Deontological ethics"],"answer":0,"explanation":"Principlism can become so process-heavy that the morality drains out, with slippery accountability between researcher and committee.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Modern research ethics mostly blends virtue ethics and principle-based ethics.","wrong":"virtue","correct":"deontological","explanation":"Research ethics blends deontological ethics (professional duties) with principlism (the principles to apply)."}]},{"id":"HPS104-8.3","name":"Apply the four National Statement principles to research","summary":"You can identify which National Statement principle (respect, merit and integrity, justice, beneficence) is at stake in a scenario.","questions":[{"type":"case","passage":"A researcher runs a study with such a poor design that its results cannot answer the research question, although no participant is harmed.","prompt":"Which principle is breached?","options":["Respect","Research merit and integrity","Beneficence","Justice"],"answer":1,"explanation":"A poorly designed study is unethical because it wastes participants' time and public resources, even without harm.","lvl":3},{"type":"case","passage":"A study excludes older adults and people who do not speak English without any justification, simply because recruiting students is easier.","prompt":"Which principle is most at stake?","options":["Confidentiality","Justice","Research merit and integrity","Beneficence"],"answer":1,"explanation":"Justice requires justifiable inclusion and exclusion criteria, no unfair burden, and fair access to benefits. Convenience samples can breach this.","lvl":2},{"type":"match","prompt":"Match each principle to what it requires.","pairs":[["Respect","Valuing participants, including privacy and valid consent"],["Beneficence","Benefits outweigh risks, which are minimised and communicated"],["Justice","Fair and equitable recruitment with no exploitation"],["Research merit and integrity","The study is worth doing, well designed and properly resourced"]],"explanation":"These are the four core principles of the NHMRC National Statement."},{"type":"type_answer","prompt":"Which Australian body publishes the National Statement on Ethical Conduct in Human Research? Give the acronym.","answers":["NHMRC"],"explanation":"The National Health and Medical Research Council publishes the National Statement.","lvl":3},{"type":"mc","prompt":"According to the lecture, what is the correct order of priority in research?","options":["Publication first, ethics second","Ethics and the participant first, knowledge second","Truth and ethics are equal","Knowledge first, participants second"],"answer":1,"explanation":"Ethics comes first. Beneficence is what prevents 'the pursuit of knowledge' being used to justify harm, as in the Nazi medical experiments.","lvl":1},{"type":"fill_gap","prompt":"Complete the sentence.","text":"The principle that the benefits of research must outweigh its risks is called ___.","answers":["beneficence"],"explanation":"Beneficence also requires risks to be minimised and communicated clearly to participants upfront.","lvl":2}]},{"id":"HPS104-8.4","name":"Apply consent, coercion, confidentiality and debriefing","summary":"You can spot problems with informed consent, coercion, confidentiality and debriefing in a research plan and suggest fixes.","questions":[{"type":"case","passage":"A lecturer invites her own first-year students to take part in her study during class, telling them it is voluntary.","prompt":"Which ethical issue is most important here?","options":["Freedom from coercion due to a power imbalance","Research merit","Confidentiality","Debriefing"],"answer":0,"explanation":"Students may feel refusing will affect their grades, even if it won't. Coercion can be a perception more than a reality.","lvl":1},{"type":"case","passage":"A small clinical study of eight clients from one regional clinic reports each participant's age, gender, occupation and postcode in a results table.","prompt":"What is the main ethical risk?","options":["Re-identification breaching confidentiality","Lack of beneficence","Lack of debriefing","Coercion"],"answer":0,"explanation":"With small samples, demographic details can let someone (such as a therapist) recognise a specific person. Each piece of information must be justified.","lvl":2},{"type":"sort","prompt":"Sort each activity into the ethical practice it belongs to.","categories":["Informed consent","Debriefing"],"items":[{"text":"Explaining the purpose, methods and risks before the study","cat":0},{"text":"Revealing the true hypothesis after limited disclosure","cat":1},{"text":"Telling participants they can withdraw at any time","cat":0},{"text":"Offering a list of support services after a sensitive study","cat":1}],"explanation":"Consent happens before participation; debriefing fills in what was held back and provides support afterwards."},{"type":"mc","prompt":"Under the National Statement, when is limited disclosure (holding back the hypothesis) allowed?","options":["Only with children","Whenever it improves the results","Never","Only if there is no better alternative, the risk is low, and participants are fully debriefed"],"answer":3,"explanation":"Sections 2.3.1 and 2.3.2 allow limited disclosure only when justified, low-risk and followed by full debriefing.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"The aim of debriefing is to leave participants in at least as bad a state as they entered the study.","wrong":"bad","correct":"good","explanation":"Participants should leave in at least as good a state as they entered, with the same mood, wellbeing and self-understanding."},{"type":"case","passage":"A researcher wants to collect participants' sexuality, postcode, income and religion 'just in case they are useful', although the study is about study habits.","prompt":"How is an ethics committee likely to respond?","options":["Approve, because more data is always better","Ask the researcher to justify each piece of information or remove it","Require a larger sample","Require deception"],"answer":1,"explanation":"Confidentiality includes limiting what is collected. The 'greedy researcher' temptation to collect everything will be challenged.","lvl":1}]}]},{"week":9,"topic":"Survey Methods","summary":"How survey items work, the judgment and response translation phases, scale types, judgmental context, and checking construct validity, reliability and measurement invariance.","skills":[{"id":"HPS104-9.1","name":"Diagnose whether a survey item fails at judgment or translation","summary":"You can identify the flaw in a survey item and say whether the respondent would struggle to interpret it or to convert their answer to a number.","questions":[{"type":"case","passage":"An item asks: 'Is your lecturer in this unit confusing?' The anchors are Never, Sometimes, Often, Extremely.","prompt":"Which statement best describes the problems with this item?","options":["It fails at judgment ('confusing' is vague) and at translation (anchors mix frequency and magnitude)","It is double-barrelled only","It fails only at translation because of the anchors","It has no problems"],"answer":0,"explanation":"'Confusing' could refer to speech, slides or assessments, and nobody knows what lies between 'often' and 'extremely', so the scale is not unidimensional.","lvl":4},{"type":"sort","prompt":"Sort each problem by the phase in which the item fails.","categories":["Judgment phase","Response translation phase"],"items":[{"text":"The question is vague about what is meant","cat":0},{"text":"Anchors mix frequency words with intensity words","cat":1},{"text":"The item asks about two things at once","cat":0},{"text":"The gaps between anchors are psychologically unequal","cat":1},{"text":"The question embeds an assumption","cat":0}],"explanation":"If the respondent cannot tell what you are asking, it fails at judgment. If they know but cannot pick a number, it fails at translation."},{"type":"case","passage":"An item asks: 'To what extent do you agree with the border protection laws that protect each of us from threats from abroad?'","prompt":"What is the main flaw?","options":["Loaded question","Floor effect","Double-barrelled","Negation"],"answer":0,"explanation":"The wording assumes the laws protect people, so respondents cannot disagree without rejecting the framing.","lvl":2},{"type":"match","prompt":"Match each flawed item to its problem.","pairs":[["How would you rate the love and respect you feel for your partner?","Double-barrelled"],["How often do you not think you're unhappy?","Double negative"],["Asking adults whether they can read","Ceiling effect"],["When did you first stop cheating on tests?","Loaded question"]],"explanation":"Each breaks a rule of thumb for writing good survey items."},{"type":"case","passage":"An item asks 'How depressed do you feel?' with anchors starting at 'Not very depressed' and ending at 'Extremely depressed'.","prompt":"Why does starting at 'Not very depressed' create a problem?","options":["It makes the scale bipolar","It makes the item loaded","It risks a floor effect because people who are genuinely fine have nowhere to go","It creates a ceiling effect"],"answer":2,"explanation":"Without 'not at all depressed', the bottom end of the scale is lost. A single item also cannot capture a complex construct like depression.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Anchors should avoid repeating the key word from the question, so a satisfaction item should not use 'satisfied' in its anchors.","wrong":"avoid","correct":"repeat","explanation":"Anchors should reinforce the question. A satisfaction item should use anchors like 'not at all satisfied' and 'quite satisfied'."}]},{"id":"HPS104-9.2","name":"Choose a suitable scale type for a construct","summary":"You can choose between absolute, frequency and bipolar scales and recognise bi-directional constructs.","questions":[{"type":"case","passage":"A researcher asks students what mark they expect to receive in HPS104, and lets them answer as a percentage.","prompt":"What type of scale is this?","options":["Likert agreement scale","Absolute (objective) scale","Bipolar scale","Frequency scale"],"answer":1,"explanation":"When a construct has a natural number scale, such as marks reported as percentages, an absolute scale removes translation guesswork.","lvl":3},{"type":"mc","prompt":"Why are frequency scales so common in clinical psychology?","options":["They prevent social desirability bias","They are always bipolar","They remove the need for anchors","They line up with diagnostic checklists and people are reasonably good at counting events"],"answer":3,"explanation":"Most diagnostic criteria ask how often symptoms occurred in a time period, which matches how people notice symptoms (for example, crying twice this week).","lvl":3},{"type":"case","passage":"A migrant can strongly identify with mainstream Australian culture and also strongly identify with her heritage culture at the same time.","prompt":"Why would a single bipolar scale be a poor choice here?","options":["The constructs are bi-directional, so a bipolar scale would lose information","The constructs have a ceiling effect","Cultural identity cannot be measured","Bipolar scales cannot have anchors"],"answer":0,"explanation":"Bipolar scales only suit genuinely one-dimensional constructs. When both can be high at once, the construct is bi-directional.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"'Not satisfied' and 'dissatisfied' mean identical things, so they can sit at one point on a bipolar scale.","wrong":"identical","correct":"different","explanation":"'Not satisfied' means you didn't get what you expected, while 'dissatisfied' means you got something actively bad. Treating them as the same can distort the scale."},{"type":"match","prompt":"Match each part of a survey item to its role.","pairs":[["Question","What you are actually asking"],["Numerical scale","Turns a subjective response into something you can analyse"],["Anchors","Words that tell respondents what the numbers mean"]],"explanation":"Every survey item has these three parts, and all three need to work."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"When researchers tested where people place the anchor '___' between 'not at all' and 'extremely', it consistently sat around 60 to 75 percent.","answers":["quite"],"explanation":"Although 'quite' is vague in everyday English, it performs reliably as an anchor. Psychology is pragmatic and uses what works.","lvl":5}]},{"id":"HPS104-9.3","name":"Use item order and context to shape survey responses","summary":"You can explain how instructions, preceding items and ordering set the judgmental context, and explain that a survey is a method not a design.","questions":[{"type":"case","passage":"The Personal Wellbeing Index asks about satisfaction with seven life domains (standard of living, health, relationships and so on) and then asks about satisfaction with 'life as a whole'.","prompt":"Why is the general item placed last?","options":["It is the least important item","The domain items prime everyone with the same definition of 'life', and they can be correlated with the general item","To reduce test-retest reliability","To create a ceiling effect"],"answer":1,"explanation":"If the general item came first, people would define 'life' differently (money, health), so answers would not be comparable.","lvl":4},{"type":"order","prompt":"Put the steps of the cat survey experiment in order.","items":["Ask about cat ownership and current behaviour","Ask what owners think cats kill","Randomly split respondents so one group sees kill statistics first and the other sees them later","Compare willingness to change behaviour between groups"],"explanation":"The order of information became the experimental manipulation, showing that experiments can be run inside surveys."},{"type":"mc","prompt":"Which statement about surveys is correct?","options":["A survey is a method of data collection that can be used within many designs","Surveys cannot include qualitative questions","Surveys can only be cross-sectional","A survey is a type of research design"],"answer":0,"explanation":"A survey is a method. The design can be experimental, quasi-experimental, cross-sectional or longitudinal.","lvl":2},{"type":"match","prompt":"Match each strategy for setting judgmental context to its description.","pairs":[["Clear instructions with a reference frame","Stating a time period such as 'in the last seven days'"],["Preceding questions","Earlier items prime the domain before the key question"],["Careful ordering","Deciding whether the general item comes first or last"]],"explanation":"These three strategies help respondents interpret questions the way the researcher intends."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Trying out a scale on a small group first to catch wording problems and ceiling or floor effects is called ___ testing.","answers":["pilot"],"explanation":"Pilot testing catches problems before the real data collection, when it is too late to fix them.","lvl":1},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Placing the general life satisfaction question first ensures everyone defines 'life as a whole' in the same way.","wrong":"first","correct":"last","explanation":"When it comes first, people define life by whatever is salient to them. Placing it last, after the domain items, standardises the definition."}]},{"id":"HPS104-9.4","name":"Evaluate a scale's validity, reliability and invariance","summary":"You can identify face, convergent, discriminant and predictive evidence, explain latent variables, and recognise measurement invariance issues.","questions":[{"type":"case","passage":"People who score high on a new depression risk screen at age 16 are much more likely to receive a depression diagnosis by age 20.","prompt":"What kind of validity evidence is this?","options":["Predictive validity","Face validity","Discriminant validity","Test-retest reliability"],"answer":0,"explanation":"Predictive validity shows a scale predicts future outcomes, which is valuable for early intervention.","lvl":2},{"type":"match","prompt":"Match each type of evidence to its question.","pairs":[["Face validity","Does the item look like it belongs?"],["Convergent evidence","Does it agree with other measures of the same construct?"],["Discriminant evidence","Does it distinguish the construct from related ones, like sadness?"],["Internal consistency","Do the items correlate with each other?"]],"explanation":"Construct validity draws on several types of evidence, while internal consistency is a form of reliability."},{"type":"case","passage":"An attachment scale includes an item about how often a child hugs their parents. Securely attached Japanese children score lower on this item than Australian children, although within Japan the most attached children still hug the most.","prompt":"Which concept must be checked before comparing Japanese and Australian scores?","options":["Measurement invariance","Test-retest reliability","Face validity","Ceiling effects"],"answer":0,"explanation":"Measurement invariance checks that a scale works the same way across groups before scores are directly compared.","lvl":4},{"type":"type_answer","prompt":"What term describes an unobservable construct inferred from observable signs, like a crocodile under the water?","answers":["latent variable","a latent variable","latent"],"explanation":"You infer the whole crocodile from its eyes and snout, just as you infer depression from sleep, appetite and mood items.","lvl":3},{"type":"mc","prompt":"A scale includes the item 'I have never lied'. Why?","options":["As a catch item to detect social desirability bias","To create a floor effect","To test predictive validity","To increase face validity"],"answer":0,"explanation":"Nearly everyone has lied, so answering 'never' suggests the respondent is presenting themselves unrealistically well.","lvl":2},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"High test-retest reliability is evidence that a latent variable is real and that the scale's items are all tapping it.","wrong":"test-retest","correct":"internal-consistency","explanation":"Internal consistency (items correlating with each other across people) is the evidence that items tap a single underlying latent variable."}]}]},{"week":10,"topic":"Introduction to Statistics","summary":"Descriptive statistics: mean, median and mode, choosing a measure for skewed data, variance and standard deviation, z scores and outliers.","skills":[{"id":"HPS104-10.1","name":"Calculate the mean, median and mode of a data set","summary":"You can calculate each measure of central tendency correctly, including the median for even-sized sets and major and minor modes.","questions":[{"type":"mc","prompt":"What is the median of the scores 3, 3, 4, 5, 7, 8?","options":["4","5.25","4.5","5"],"answer":2,"explanation":"With an even number of scores, the median is the mean of the two middle scores: (4 + 5) / 2 = 4.5.","lvl":2},{"type":"type_answer","prompt":"What is the mean of the sample 3, 5, 7, 2, 8? Give a number.","answers":["5","5.0"],"explanation":"Sum the scores (25) and divide by n (5): M = 5.","lvl":1},{"type":"case","passage":"Scores: 2, 1, 6, 4, 2, 2, 3, 4, 1.","prompt":"Which statement is correct?","options":["The mode is 4","The major mode is 1","There is no mode","The major mode is 2 and the minor modes are 1 and 4"],"answer":3,"explanation":"2 appears three times (major mode), while 1 and 4 each appear twice (minor modes).","lvl":3},{"type":"match","prompt":"Match each symbol to its meaning.","pairs":[["M","Sample mean"],["μ (mu)","Population mean"],["Σ (capital sigma)","Sum of"],["n","Sample size"]],"explanation":"Samples use Roman letters (M, s, n) and populations use Greek letters (μ, σ) with N for size."},{"type":"order","prompt":"Put the steps for finding the median in order.","items":["Arrange the scores from smallest to largest","Check whether the number of scores is odd or even","Take the middle score, or the mean of the two middle scores"],"explanation":"The median depends only on rank position, so the scores must be ordered first."},{"type":"case","passage":"Set 1: 1, 2, 10, 1000, 10000. Set 2: 8, 9, 10, 11, 12.","prompt":"What does comparing these sets show about the median?","options":["The median is strongly affected by outliers","The sets have different medians","Both sets have a median of 10, because the median ignores actual values beyond rank","The median equals the mean in both"],"answer":2,"explanation":"The median is robust to outliers but loses interval and ratio information, so very different distributions can share a median.","lvl":2}]},{"id":"HPS104-10.2","name":"Choose the best measure of central tendency for the data","summary":"You can pick the mean, median or mode based on distribution shape, outliers and measurement scale, and order them in skewed distributions.","questions":[{"type":"case","passage":"A unit's mean final mark is 65, but the mode is 0 because many students submitted nothing.","prompt":"Which measure best describes how a typical submitting student performed?","options":["Mean","Range","Median","Mode"],"answer":2,"explanation":"The median is less affected by the cluster of zero scores from non-submitters, which are not really performance.","lvl":2},{"type":"sort","prompt":"Sort each situation into the best measure of central tendency.","categories":["Mean","Median","Mode"],"items":[{"text":"Normally distributed reaction times with no outliers","cat":0},{"text":"Household income in Australia","cat":1},{"text":"Most common phone brand among students","cat":2},{"text":"Which shoe sizes to reorder","cat":2},{"text":"Ordinal rankings on a waiting list","cat":1}],"explanation":"The mean suits normal interval or ratio data, the median suits skewed data, outliers and ordinal data, and the mode suits nominal and discrete data."},{"type":"order","prompt":"In a positively skewed distribution, put the measures in order from lowest to highest value.","items":["Mode","Median","Mean"],"explanation":"The mode sticks to the peak, the mean follows the tail to the right, and the median falls in between."},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In a negatively skewed distribution, the mean is greater than the median.","wrong":"greater","correct":"less","explanation":"With a tail to the left, the mean is pulled toward low values: mean < median < mode."},{"type":"mc","prompt":"Why is median income reported instead of mean income?","options":["Income has a floor at zero but no upper limit, so a few very high earners pull the mean up","The mean cannot be calculated for money","Income is nominal data","The median uses every score's value"],"answer":0,"explanation":"Income is positively skewed, and a single extreme earner can drag the mean far above the typical person's income.","lvl":2},{"type":"analogy","prompt":"Mean is to interval and ratio data as mode is to ___","options":["skewed data","nominal data","normal data","ordinal data"],"answer":1,"explanation":"The mode is the only meaningful measure of central tendency for nominal (categorical) data.","lvl":2}]},{"id":"HPS104-10.3","name":"Calculate variance and standard deviation","summary":"You can compute deviations, sum of squares, population and sample variance, and standard deviation, and explain dividing by n minus 1.","questions":[{"type":"order","prompt":"Put the steps for calculating a standard deviation in order.","items":["Calculate each score's deviation from the mean","Square the deviations and sum them (sum of squares)","Divide to get the variance","Take the square root"],"explanation":"Squaring prevents positive and negative deviations cancelling out; the square root returns to the original units."},{"type":"case","passage":"Mean = 100. Scores: 103, 97, 96, 105, 99. The sum of squares is 60.","prompt":"If these five scores are a sample, what is the sample variance?","options":["15","12","3.87","60"],"answer":0,"explanation":"Sample variance divides by n-1: 60 / 4 = 15. As a population it would be 60 / 5 = 12.","lvl":3},{"type":"type_answer","prompt":"Scores 16, 10, 14, 8 and 12 have a mean of 12. What is their sum of squares? Give a number.","answers":["40"],"explanation":"Squared deviations are 16, 4, 4, 16 and 0, which sum to 40.","lvl":3},{"type":"mc","prompt":"A student keeps getting a standard deviation of 0 for data that clearly vary. What is the most likely mistake?","options":["Using the median instead of the mean","Taking the square root","Forgetting to square the deviations before summing","Dividing by n instead of n-1"],"answer":2,"explanation":"Unsquared deviations from the mean sum to zero because positives and negatives cancel.","lvl":3},{"type":"case","passage":"A 10-piece jigsaw puzzle only requires 9 real decisions, because once 9 pieces are placed, the last must go where it goes.","prompt":"What does this analogy explain?","options":["Why the median ignores outliers","Why variance is in squared units","Why sample variance divides by n-1 (degrees of freedom)","Why z scores are standardised"],"answer":2,"explanation":"Once the mean is fixed, the last deviation is determined by the others, so only n-1 deviations are free to vary.","lvl":3},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"Samples tend to overestimate the population variance, so we divide by n-1 to make the estimate smaller.","wrong":"overestimate","correct":"underestimate","explanation":"Samples tend to underestimate population variance, so the smaller denominator makes the sample variance bigger and a better estimate."}]},{"id":"HPS104-10.4","name":"Calculate and interpret z scores and outlier cutoffs","summary":"You can compute z scores, compare scores across different distributions, apply the 95% rule, and set outlier cutoffs.","questions":[{"type":"type_answer","prompt":"IQ has a mean of 100 and a standard deviation of 15. What is the z score for an IQ of 130? Give a number.","answers":["2","+2","2.0"],"explanation":"z = (130 − 100) / 15 = 30 / 15 = 2, placing the person about in the top 2.5%.","lvl":2},{"type":"case","passage":"Jen's orange weighs 550g (oranges: mean 500g, SD 50g). Greg's apple weighs 350g (apples: mean 300g, SD 10g).","prompt":"Whose fruit is more exceptional for its type?","options":["Cannot be compared","They are equal, since both are 50g above average","Jen's, because it is heavier","Greg's, with z = 5 compared with Jen's z = 1"],"answer":3,"explanation":"Standardising shows Greg's apple is 5 SDs above average, while Jen's orange is only 1 SD above, because apple weights vary much less.","lvl":3},{"type":"case","passage":"A researcher removes scores more than 2 standard deviations from the mean. The mean is 30 and the SD is 5.","prompt":"What are the cutoffs?","options":["Below 25 or above 35","Below 28 or above 32","Below 15 or above 45","Below 20 or above 40"],"answer":3,"explanation":"Two SDs is 10 points, so the cutoffs are 30 − 10 = 20 and 30 + 10 = 40.","lvl":2},{"type":"match","prompt":"Match each z score to its interpretation.","pairs":[["z = 0","Exactly at the mean"],["z = +1","Better than about 84% of scores"],["z = +2","Better than about 97.5% of scores"],["z = -1","One standard deviation below the mean"]],"explanation":"A z score expresses a deviation in standard deviation units."},{"type":"fill_gap","prompt":"Complete the sentence.","text":"Rescaling an outlier to equal the cutoff value, instead of deleting it, is called ___.","answers":["winsorising","winsorizing","winsorisation"],"explanation":"Winsorising keeps the outlier's rank as highest (or lowest) while limiting its influence on the distribution.","lvl":4},{"type":"fix_error","prompt":"One word is wrong. Find it.","sentence":"In a normal distribution, about 95% of scores fall within 3 standard deviations of the mean.","wrong":"3","correct":"2","explanation":"The 95% rule says about 95% of scores fall within plus or minus 2 SDs, the basis of the common alpha = .05 threshold."}]}]}]};
